#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_LINE_LENGTH 1024

typedef struct {
    char *input_file;
    char *output_file;
    int case_sensitive;
} Options;

void display_help() {
    printf("Usage: program_name [options] input_file\n");
    printf("Options:\n");
    printf("  -h, --help          Display this help message and exit.\n");
    printf("  -v, --version       Display the version information and exit.\n");
    printf("  --manpage           Print the man page documentation.\n");
    printf("  -cs                 Enable case-sensitive mode for line counting.\n");
    printf("  -o <output_file>   Redirect output to a specified file instead of the standard output.\n");
}

void display_version() {
    printf("Version: 1.0\n");
    printf("Copyright (c) 2023 Example Company\n");
}

void *count_lines(void *arg) {
    Options *options = (Options *)arg;
    FILE *file = fopen(options->input_file, options->case_sensitive ? "r" : "r");
    if (!file) {
        perror("Error opening file");
        pthread_exit(NULL);
    }

    char line[MAX_LINE_LENGTH];
    int total_lines = 0, processed_lines = 0;

    while (fgets(line, MAX_LINE_LENGTH, file)) {
        total_lines++;
        processed_lines++;
        if (processed_lines % (total_lines / 10) == 0) {
            printf("Processing: %d%% complete\n", processed_lines * 100 / total_lines);
        }
    }

    fclose(file);

    FILE *output = options->output_file ? fopen(options->output_file, "w") : stdout;
    fprintf(output, "Total lines: %d\n", total_lines);
    if (output != stdout) {
        fclose(output);
    }

    pthread_exit(NULL);
}

int main(int argc, char *argv[]) {
    Options options = {NULL, NULL, 0};
    int opt;

    while ((opt = getopt(argc, argv, ":h:v:o:cs")) != -1) {
        switch (opt) {
            case 'h':
                display_help();
                return 0;
            case 'v':
                display_version();
                return 0;
            case 'o':
                options.output_file = optarg;
                break;
            case 'cs':
                options.case_sensitive = 1;
                break;
            case '?':
                fprintf(stderr, "Invalid option: -%c\n", optopt);
                return 1;
            default:
                display_help();
                return 1;
        }
    }

    if (optind >= argc) {
        display_help();
        return 1;
    }

    options.input_file = argv[optind];

    pthread_t thread;
    if (pthread_create(&thread, NULL, count_lines, &options) != 0) {
        perror("Error creating thread");
        return 1;
    }

    pthread_join(thread, NULL);

    return 0;
}
