typedef struct {
    u_char ip[16];
} IPAddress;

typedef struct {
    char *domains[MAX_DOMAINS];
    int count;
} DomainWhitelist;

int is_domain_allowed(const DomainWhitelist *whitelist, const char *domain) {
    for (int i = 0; i < whitelist->count; i++) {
        if (strcmp(whitelist->domains[i], domain) == 0) {
            return 1;
        }
    }
    return 0;
}

void dns_callback(struct evdns_base *base, int result, char type, const char *query, void *data) {
    struct in_addr a4;
    struct in6_addr a6;
    IPAddress *ip = (IPAddress *)data;

    if (result == DNS_ERR_NONE) {
        switch (type) {
            case DNS_IPv4_A:
                evutil_inet_pton(AF_INET, query, &a4);
                memcpy(ip->ip, &a4.s_addr, 4);
                break;
            case DNS_IPv6_AAAA:
                evutil_inet_pton(AF_INET6, query, &a6);
                memcpy(ip->ip, a6.s6_addr, 16);
                break;
            default:
                // Handle other types if needed
                break;
        }
    } else {
        // Handle error, e.g., set ip to an invalid value or log the error
    }
}

int resolve_hostname(struct evdns_base *base, const char *hostname, IPAddress *ip) {
    DomainWhitelist whitelist = { .domains = {"example.com", "test.net"}, .count = 2 };

    if (!is_domain_allowed(&whitelist, hostname)) {
        return -1; // Domain not allowed
    }

    int rc = evdns_resolve_ipv4(base, hostname, 0, dns_callback, ip);
    if (rc != EVUTIL_CALLBACK_RUNNING) {
        return rc; // Error in DNS resolution
    }

    // Add caching mechanism here to store resolved IPs

    return 0;
}

int main() {
