    if (!base) {
        fprintf(stderr, "Could not initialize libevent\n");
        return 1;
    }

    struct evdns_base *dns_base = evdns_base_new(base, 1);
    if (!dns_base) {
        fprintf(stderr, "Could not initialize libevent DNS\n");
        event_base_free(base);
        return 1;
