// Helper function to find the largest integer in an array
int findLargest(int *array, int size) {
    int max = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

// Function to read integers from standard input and find the largest one
void processInput() {
    int *array = NULL;
    int size = 0;
    int capacity = 16; // Initial capacity

    array = (int *)malloc(capacity * sizeof(int));
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    while (scanf("%d", &array[size]) == 1) {
        size++;
        if (size >= capacity) {
            capacity *= 2; // Double the capacity
            int *temp = realloc(array, capacity * sizeof(int));
            if (temp == NULL) {
                fprintf(stderr, "Memory reallocation failed\n");
                free(array);
                return;
            }
            array = temp;
        }
    }

    if (size > 0) {
        printf("Largest integer: %d\n", findLargest(array, size));
    } else {
        printf("No integers provided.\n");
    }

    free(array);
}

int main() {
    processInput();
    return 0;
}
