#include <stdio.h>
#include <stdarg.h>
#include <time.h>
#include <pthread.h>

#define MAX_LOG_SIZE 1024 * 1024 // 1MB

typedef enum {
    INFO,
    DEBUG,
    WARNING,
    ERROR
} LogLevel;

typedef struct LogEntry {
    LogLevel level;
    char message[256];
    time_t timestamp;
    struct LogEntry* next;
} LogEntry;

LogEntry* log_head = NULL;
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
int log_size = 0;

void log_message(LogLevel level, const char* format, ...) {
    pthread_mutex_lock(&log_mutex);

    if (log_size >= MAX_LOG_SIZE) {
        // Remove the oldest log entry
        LogEntry* temp = log_head;
        log_head = log_head->next;
        free(temp);
        log_size -= sizeof(LogEntry);
    }

    LogEntry* new_entry = (LogEntry*)malloc(sizeof(LogEntry));
    snprintf(new_entry->message, 256, format, va_list args);

    time_t now = time(NULL);
    new_entry->timestamp = now;
    new_entry->level = level;

    new_entry->next = log_head;
    log_head = new_entry;
    log_size += sizeof(LogEntry);

    pthread_mutex_unlock(&log_mutex);

    // Asynchronous logging to remote server code here
}

void* async_log_thread(void* arg) {
    while (1) {
        pthread_mutex_lock(&log_mutex);
        LogEntry* entry = log_head;
        if (entry != NULL) {
            log_head = entry->next;
            // Code to send log message to remote server
            free(entry);
            log_size -= sizeof(LogEntry);
        }
        pthread_mutex_unlock(&log_mutex);

        // Sleep for a while before next log check
        sleep(1);
    }

    return NULL;
}

int main() {
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, async_log_thread, NULL);

    log_message(INFO, "This is an info message.");
    log_message(ERROR, "This is an error message.");

    pthread_join(thread_id, NULL);
    return 0;
}
