#include <iostream>
#include <fstream>
#include <mutex>
#include <string>
#include <map>

namespace Logging {
    enum class Level { DEBUG, INFO, WARN, ERROR, FATAL };

    class Logger {
    public:
        static Logger& getInstance() {
            static Logger instance;
            return instance;
        }

        void setLevel(Level level) {
            std::lock_guard<std::mutex> lock(mutex_);
            logLevel_ = level;
        }

        void setOutputFormat(const std::string& format) {
            std::lock_guard<std::mutex> lock(mutex_);
            outputFormat_ = format;
        }

        void addSink(const std::string& name, std::ostream* sink) {
            std::lock_guard<std::mutex> lock(mutex_);
            sinks_[name] = sink;
        }

        void log(Level level, const std::string& message) {
            if (level >= logLevel_) {
                std::string formattedMessage = formatMessage(level, message);
                for (auto& [_, sink] : sinks_) {
                    (*sink) << formattedMessage << std::endl;
                }
            }
        }

    private:
        Logger() : logLevel_(Level::INFO) {}
        ~Logger() {}

        std::string formatMessage(Level level, const std::string& message) {
            // Simple formatting logic
            return "[" + getLevelString(level) + "] " + message;
        }

        std::string getLevelString(Level level) {
            switch (level) {
                case Level::DEBUG: return "DEBUG";
                case Level::INFO: return "INFO";
                case Level::WARN: return "WARN";
                case Level::ERROR: return "ERROR";
                case Level::FATAL: return "FATAL";
                default: return "UNKNOWN";
            }
        }

        std::mutex mutex_;
        Level logLevel_;
        std::string outputFormat_;
        std::map<std::string, std::ostream*> sinks_;
    };

    void initLogger() {
        Logger& logger = Logger::getInstance();
        logger.addSink("console", &std::cout);
        logger.setLogLevel(Logger::INFO);
    }

    void logInfo(const std::string& message) {
        Logger::getInstance().log(Logger::INFO, message);
    }
}
```

This code snippet provides a basic implementation of a logging framework in C++. It includes a `Logger` class with methods to set the log level, output format, and add sinks. The `log` method outputs messages to all configured sinks if they meet or exceed the current log level. The `initLogger` function initializes the logger with a console sink and sets the default log level to INFO. The `logInfo` function is a convenience wrapper for logging informational messages.

To use this framework, you would call `Logging::initLogger()` in your main program before using any of the logging functions. You can add additional sinks by calling `Logger::getInstance().addSink()`, and configure the log level and format as needed.']

