using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;

public class HttpBatchProcessor
{
    private readonly HttpClient _httpClient;

    public HttpBatchProcessor()
    {
        _httpClient = new HttpClient();
    }

    public async Task<List<string>> ProcessHttpRequestsAsync(List<string> urls, CancellationToken cancellationToken, int maxConcurrency)
    {
        var tasks = new List<Task<string>>();
        var semaphoreSlim = new SemaphoreSlim(maxConcurrency);

        foreach (var url in urls)
        {
            await semaphoreSlim.WaitAsync(cancellationToken);
            tasks.Add(FetchDataAsync(url, cancellationToken, semaphoreSlim));
        }

        return await Task.WhenAll(tasks);
    }

    private async Task<string> FetchDataAsync(string url, CancellationToken cancellationToken, SemaphoreSlim semaphoreSlim)
    {
        try
        {
            using (cancellationToken.Register(() => semaphoreSlim.Release()))
            {
                var response = await _httpClient.GetAsync(url, HttpCompletionOption.ResponseHeadersRead, cancellationToken);
                response.EnsureSuccessStatusCode();
                return await response.Content.ReadAsStringAsync();
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error fetching {url}: {ex.Message}");
            return null;
        }
    }
}
