    {
        _cpuLoad = newLoad;
        AdjustFrameRate();
    }

    private void AdjustFrameRate()
    {
        // Simplified logic to adjust frame rate based on CPU load
        if (_cpuLoad > 0.8f)
        {
            _frameRate = 30;
        }
        else
        {
            _frameRate = 60;
        }
        Console.WriteLine($"Adjusted frame rate to {_frameRate}");
    }

