        {
            if (_resources.ContainsKey(id))
            {
                _resources[id] = updatedData;
                return Ok(new { message = "Resource updated successfully" });
            }
            else
            {
                return NotFound();
            }
        }
    }

    [HttpDelete("{id}")]
    public IActionResult DeleteResource(string id)
    {
        lock (_lock)
        {
            if (_resources.ContainsKey(id))
            {
                _resources.Remove(id);
                return Ok(new { message = "Resource deleted successfully", deletedCount = 1 });
            }
            else
            {
                return NotFound();
            }
        }
    }

    public class Resource
    {
        public string Id { get; set; }
        public string Data { get; set; }
    }
}
