import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class StringMd5Hasher {

    private static final MessageDigest md5Digest = getMD5Digest();

    public Map<String, String> computeMd5Hashes(List<String> inputStrings) {
        Map<String, String> result = new ConcurrentHashMap<>();
        for (String str : inputStrings) {
            try {
                byte[] hashBytes = md5Digest.digest(str.getBytes());
                String md5Hash = bytesToHex(hashBytes);
                result.put(str, md5Hash);
                System.out.println("Computed MD5 for: " + str + ", Hash: " + md5Hash);
            } catch (Exception e) {
                // Handle exception appropriately
                System.err.println("Error computing MD5 for: " + str);
            }
        }
        return result;
    }

    private static MessageDigest getMD5Digest() {
        try {
            return MessageDigest.getInstance("MD5");
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("MD5 algorithm not available", e);
        }
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
