class UserService {
    private $db;
    private $cache;
    private $logger;

    public function __construct($db, $cache, $logger) {
        $this->db = $db;
        $this->cache = $cache;
        $this->logger = $logger;
    }

    public function handleRequest($_REQUEST) {
        $ip = $_SERVER['REMOTE_ADDR'];
        if ($this->isRateLimited($ip)) {
            return json_encode(['message' => 'error']);
        }

        try {
            switch ($_REQUEST['sub_action'] ?? '') {
                case 'delete':
                    if (isset($_REQUEST['id'])) {
                        $this->deleteUser((int)$_REQUEST['id']);
                        break;
                    }
                    // Fall through to create/update
                default:
                    $user = [
                        'name' => $_REQUEST['name'],
                        'email' => $_REQUEST['email'],
                        'password' => password_hash($_REQUEST['password'], PASSWORD_DEFAULT)
                    ];
                    if (isset($_REQUEST['id'])) {
                        $this->updateUser((int)$_REQUEST['id'], $user);
                    } else {
                        $this->createUser($user);
                    }
                    break;
            }
        } catch (\Exception $e) {
            $this->logger->logError('Error handling request: ' . $e->getMessage());
            return json_encode(['message' => 'error']);
        }

        return json_encode(['message' => 'success']);
    }

    private function isRateLimited($ip) {
        // Implement rate limiting logic
    }

    private function createUser(array $user) {
        if ($this->isEmailUnique($user['email'])) {
            $this->db->insert('users', $user);
            $this->cache->set($user['email'], $user, 3600); // Cache for 1 hour
        } else {
            throw new \Exception('Email already exists');
        }
    }

    private function updateUser(int $id, array $user) {
        if ($this->isEmailUnique($user['email']) || $this->getUserByEmail($user['email']) === null) {
            $this->db->update('users', $user, ['id' => $id]);
            $this->cache->set($user['email'], $user, 3600); // Update cache
        } else {
            throw new \Exception('Email already exists');
        }
    }

    private function deleteUser(int $id) {
        $user = $this->getUserById($id);
        if ($user !== null) {
            $this->db->delete('users', ['id' => $id]);
            $this->cache->delete($user['email']); // Remove from cache
        } else {
            throw new \Exception('User not found');
        }
    }

    private function isEmailUnique(string $email): bool {
        return $this->db->count('users', ['email' => $email]) === 0;
    }

    private function getUserById(int $id) {
        return $this->cache->get($id) ?? $this->db->select('users', ['id' => $id]);
    }

    private function getUserByEmail(string $email) {
        return $this->cache->get($email) ?? $this->db->select('users', ['email' => $email]);
    }
}

// Usage example:
$db = new PDO('mysql:host=localhost;dbname=your_db', 'username', 'password');
$cache = new Cache(); // Custom cache implementation
$logger = new Logger(); // Custom logger implementation
$userService = new UserService($db, $cache, $logger);
echo $userService->handleRequest($_REQUEST);
