const fs = require('fs').promises;
const path = require('path');
const csv = require('csv-parser');

async function readFilesInDirectory(directoryPath, filterPattern) {
  const files = await fs.readdir(directoryPath);
  const processedResults = [];
  let activeReads = 0;
  const maxConcurrentReads = 10;

  for (let file of files) {
    if (filterPattern.test(file)) {
      if (activeReads >= maxConcurrentReads) {
        await new Promise(resolve => setTimeout(resolve, 100)); // Throttle
      }
      activeReads++;
      const filePath = path.join(directoryPath, file);
      processedResults.push(processFile(filePath));
      activeReads--;
    }
  }

  return Promise.all(processedResults);
}

async function processFile(filePath) {
  try {
    const extname = path.extname(filePath).toLowerCase();
    let content;

    if (extname === '.json') {
      content = await fs.readFile(filePath, 'utf8');
      content = JSON.parse(content);
    } else if (extname === '.csv') {
      content = [];
      await fs.createReadStream(filePath)
        .pipe(csv())
        .on('data', row => content.push(row));
    } else if (extname === '.txt') {
      content = await fs.readFile(filePath, 'utf8');
      // Add custom processing logic for plain text here
    } else {
      throw new Error(`Unsupported file type: ${extname}`);
    }

    return { filePath, content };
  } catch (error) {
    console.error(`Error processing file ${filePath}:`, error);
    return { filePath, content: null, error };
  }
}

// Example usage:
const directoryPath = '/path/to/your/directory';
const filterPattern = /\.json$/i;

readFilesInDirectory(directoryPath, filterPattern)
  .then(results => {
    console.log('Processed results:', results);
  })
  .catch(error => {
    console.error('Error in reading files:', error);
  });
```

This code provides a basic structure for reading multiple files from a specified directory, processing their contents based on file type, and handling various constraints. It uses asynchronous operations to ensure the function can handle large numbers of files efficiently and gracefully handles errors. The solution includes mechanisms for throttling concurrent reads and is modular, allowing easy extension for additional file types and processing logic."]

