async function runTests(modulePath, testCases, config) {
    const { retries = 3, timeout = 5000, skip } = config;
    let module;

    for (const testCase of testCases) {
        if (typeof skip === 'function' && skip(testCase)) {
            console.log(`Skipping test case: ${testCase.label}`);
            continue;
        }

        for (let attempt = 1; attempt <= retries + 1; attempt++) {
            try {
                if (!module) {
                    module = await import(modulePath);
                }
                const result = await Promise.race([
                    new Promise((resolve, reject) => {
                        setTimeout(() => reject(new Error('Test timed out')), timeout);
                    }),
                    testCase.testFunction(module)
                ]);
                console.log(`Test case passed: ${testCase.label}`);
            } catch (error) {
                if (attempt < retries + 1) {
                    console.warn(`Test case failed, retrying (${attempt}/${retries}): ${testCase.label}`);
                } else {
                    console.error(`Test case failed after retries: ${testCase.label}`);
                }
            }
        }
    }
}
