function generateSidebarMenu(config) {
    function renderItem(item, depth = 1) {
        if (!item.label || !item.iconClass) return '';
        const indent = ' '.repeat(depth * 2);
        let itemHtml = `<li class="menu-item ${depth > 1 ? 'dropdown' : ''}">\n`;
        itemHtml += `${indent}<a href="${item.route}" class="${item.iconClass}">${item.label}</a>\n`;

        if (item.submenu && item.submenu.length > 0) {
            itemHtml += `${indent}<ul class="submenu">\n`;
            item.submenu.forEach(subItem => {
                itemHtml += renderItem(subItem, depth + 1);
            });
            itemHtml += `${indent}</ul>\n`;
        }

        itemHtml += `${indent}</li>\n`;
        return itemHtml;
    }

    let sidebarHtml = '<ul class="sidebar-menu">\n';
    config.forEach(item => {
        sidebarHtml += renderItem(item);
    });
    sidebarHtml += '</ul>';
    return sidebarHtml;
}
