class GraphDatabase {
  constructor() {
    this.vertices = [];
    this.edges = [];
  }

  addVertex(properties) {
    const vertex = { id: Date.now(), ...properties };
    this.vertices.push(vertex);
    return vertex;
  }

 .addEdge(properties) {
    const edge = { id: Date.now(), ...properties };
    this.edges.push(edge);
    return edge;
  }
}

class StreamProcessor {
  constructor() {
    this.graphDB = new GraphDatabase();
    this.paused = false;
    this.streamData = [];
  }

  pause() {
    this.paused = true;
  }

  resume() {
    this.paused = false;
    this.processStreamData();
  }

  async processStreamData() {
    while (this.streamData.length > 0 && !this.paused) {
      const dataChunk = this.streamData.shift();
      await new Promise(resolve => setTimeout(resolve, 1)); // Simulate processing time
      this.graphDB.addVertex(dataChunk.vertex);
      this.graphDB.addEdge(dataChunk.edge);
    }
  }

  addStreamData(vertexProperties, edgeProperties) {
    if (!this.paused) {
      const vertex = this.graphDB.addVertex(vertexProperties);
      const edge = this.graphDB.addEdge(edgeProperties);
      this.streamData.push({ vertex, edge });
      process.nextTick(() => this.processStreamData());
    }
  }

  simulateGraphOperations(numVertices, numEdges) {
    for (let i = 0; i < numVertices; i++) {
      this.addStreamData(
        { type: 'vertex', properties: { value: Math.random() } },
        {}
      );
    }
    for (let i = 0; i < numEdges; i++) {
      const fromVertex = this.graphDB.vertices[Math.floor(Math.random() * this.graphDB.vertices.length)];
      const toVertex = this.graphDB.vertices[Math.floor(Math.random() * this.graphDB.vertices.length)];
      this.addStreamData(
        {},
        { type: 'edge', properties: { weight: Math.random(), from: fromVertex.id, to: toVertex.id } }
      );
    }
  }
}

// Example usage:
const processor = new StreamProcessor();
processor.simulateGraphOperations(100, 200);
setTimeout(() => {
  processor.pause();
  setTimeout(() => processor.resume(), 5000);
}, 3000);
