function traverseDOM(node, callback, summary = {}) {
  if (node.nodeType === Node.ELEMENT_NODE) {
    const attrs = node.attributes;
    for (let i = 0; i < attrs.length; i++) {
      const attr = attrs[i];
      if (callback(node, attr)) {
        if (!summary[attr.name]) summary[attr.name] = [];
        summary[attr.name].push(attr.value);
      }
    }
    for (let child of node.childNodes) {
      traverseDOM(child, callback, summary);
    }
  }
  return summary;
}
