const jsModuleLoader = (() => {
  let scriptsQueue = [];
  let isExecuting = false;

  function loadScript(url) {
    return new Promise((resolve, reject) => {
      const script = document.createElement('script');
      script.src = url;
      script.onload = () => resolve();
      script.onerror = (error) => reject(error);
      document.head.appendChild(script);
    });
  }

  async function executeScripts() {
    if (!scriptsQueue.length || isExecuting) return;

    isExecuting = true;
    const currentScriptUrl = scriptsQueue.shift();

    try {
      await loadScript(currentScriptUrl);
      console.log(`Script loaded successfully: ${currentScriptUrl}`);
    } catch (error) {
      console.error(`Failed to load script: ${currentScriptUrl}`, error);
      // Implement graceful degradation logic here
    }

    isExecuting = false;
    executeScripts();
  }

  return {
    addScript(url) {
      scriptsQueue.push(url);
      executeScripts();
    },
  };
})();

