import java.util.*;
import org.apache.commons.math3.stat.clustering.Cluster;
import org.apache.commons.math3.stat.clustering.DoublePoint;
import org.apache.commons.math3.stat.clustering.KMeansPlusPlusClusterer;

public class TransactionClustering {

    public static List<Cluster<DoublePoint>> clusterTransactions(List<Transaction> transactions) {
        long startTime = System.currentTimeMillis();

        List<DoublePoint> points = new ArrayList<>();
        for (Transaction transaction : transactions) {
            if (transaction.isValidGeographicalData()) {
                points.add(new DoublePoint(transaction.getCoordinates()));
            }
        }

        KMeansPlusPlusClusterer<DoublePoint> clusterer = new KMeansPlusPlusClusterer<>(3);
        List<Cluster<DoublePoint>> clusters = clusterer.cluster(points);

        long endTime = System.currentTimeMillis();
        System.out.println("Clustering took: " + (endTime - startTime) + " ms");

        return clusters;
    }
}

class Transaction {
    private double timestamp;
    private double amount;
    private double[] coordinates;

    public Transaction(double timestamp, double amount, double[] coordinates) {
        this.timestamp = timestamp;
        this.amount = amount;
        this.coordinates = coordinates;
    }

    public double[] getCoordinates() {
        return coordinates;
    }

    public boolean isValidGeographicalData() {
        return coordinates != null && coordinates.length == 2;
    }
}
