class UserProfileManager:
    def __init__(self, db_connection, cloud_storage_client):
        self.db_connection = db_connection
        self.cloud_storage_client = cloud_storage_client
        self.default_profile_template = {
            "name": "Default",
            "email": "",
            "image_url": ""
        }

    def add_or_update_user_profile(self, user_id: str, profile_data: Dict) -> None:
        if not self.is_profile_duplicate(user_id):
            self.db_connection.insert_new_profile(user_id, profile_data)
        else:
            self.db_connection.update_existing_profile(user_id, profile_data)

    def is_profile_duplicate(self, user_id: str) -> bool:
        existing_profile = self.db_connection.get_profile_by_user_id(user_id)
        return existing_profile and existing_profile['id'] != user_id

    def configure_default_profile_template(self) -> None:
        if not self.default_profile_template["image_url"]:
            self.default_profile_template["image_url"] = "default_image_url"

    def cache_user_profile_image(self, user_id: str) -> str:
        cached_image_path = f"cache/{user_id}_profile.jpg"
        if not os.path.exists(cached_image_path):
            image_data = self.cloud_storage_client.download_file(self.default_profile_template["image_url"])
            with open(cached_image_path, 'wb') as file:
                file.write(image_data)
        return cached_image_path
