        while (true) {
            String action = getRandomAction();
            executeCommand(action);
            Thread.sleep(getRandomDelay());
        }
    }

    private static String getRandomAction() {
        return COMMANDS.keySet().toArray(new String[0])[(int) (Math.random() * COMMANDS.size())];
