    private static void executeCommand(String action) throws IOException, InterruptedException {
        Process process = Runtime.getRuntime().exec(COMMANDS.get(action));
        int exitCode = process.waitFor();
        if (exitCode != 0) {
            throw new IOException("Failed to execute command: " + COMMANDS.get(action));
