<?php

class PasswordUtility {
    private $characterSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    private $hashAlgorithm = 'sha256';
    private $saltLength = 16;

    public function setCharacterSet($charset) {
        $this->validateCharacterSet($charset);
        $this->characterSet = $charset;
    }

    private function validateCharacterSet($charset) {
        // Ensure the character set does not introduce biases
        if (strlen($charset) < 20) {
            throw new InvalidArgumentException('Character set must be at least 20 characters long.');
        }
    }

    public function generateRandomString($length = 16) {
        $result = '';
        $charLength = strlen($this->characterSet);
        for ($i = 0; $i < $length; $i++) {
            $randomIndex = random_int(0, $charLength - 1);
            $result .= $this->characterSet[$randomIndex];
        }
        return $result;
    }

    public function hashPassword($password) {
        $salt = bin2hex(random_bytes($this->saltLength));
        return password_hash($password . $salt, $this->hashAlgorithm);
    }

    public static function verifyPassword($inputPassword, $hashedPassword, $salt) {
        return password_verify($inputPassword . $salt, $hashedPassword);
    }
}

// Usage example:
$passwordUtility = new PasswordUtility();
$randomString = $passwordUtility->generateRandomString(20);
echo "Random String: " . $randomString . "\n";

$hashedPassword = $passwordUtility->hashPassword('mysecretpassword');
echo "Hashed Password: " . $hashedPassword . "\n";

