<?php

class OAuthManager {
    private $client;
    private $db;

    public function __construct($clientId, $clientSecret, $redirectUri) {
        $this->client = new OAuth2\Client($clientId, $clientSecret, null, $redirectUri);
        $this->db = new PDO('sqlite:auth.db');
        $this->db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
    }

    public function authenticateUser($code) {
        $token = $this->client->getAccessToken('authorization_code', [
            'code' => $code,
        ]);
        $this->storeToken($token);
    }

    private function storeToken($token) {
        $stmt = $this->db->prepare("INSERT INTO tokens (access_token, expires_in) VALUES (:access_token, :expires_in)");
        $stmt->execute([
            ':access_token' => $token['access_token'],
            ':expires_in' => $token['expires_in'],
        ]);
    }

    public function getToken() {
        $now = time();
        $stmt = $this->db->prepare("SELECT * FROM tokens WHERE expires_at > :now");
        $stmt->execute([':now' => $now]);
        $token = $stmt->fetch(PDO::FETCH_ASSOC);

        if ($token) {
            return $token['access_token'];
        } else {
            return $this->refreshToken();
        }
    }

    private function refreshToken() {
        $stmt = $this->db->prepare("SELECT refresh_token FROM tokens ORDER BY id DESC LIMIT 1");
        $stmt->execute();
        $refreshToken = $stmt->fetch(PDO::FETCH_ASSOC)['refresh_token'];

        if ($refreshToken) {
            $newToken = $this->client->getAccessToken('refresh_token', [
                'refresh_token' => $refreshToken,
            ]);
            $this->storeToken($newToken);
            return $newToken['access_token'];
        } else {
            throw new Exception("No refresh token available");
        }
    }

    public function makeRequest($url) {
        try {
            $token = $this->getToken();
            $client = new \GuzzleHttp\Client();
            $response = $client->request('GET', $url, [
                'headers' => ['Authorization' => "Bearer {$token}"],
            ]);
            return $response->getBody()->getContents();
        } catch (\GuzzleHttp\Exception\RequestException $e) {
            if ($this->refreshToken()) {
                return $this->makeRequest($url);
            } else {
                throw $e;
            }
        }
    }
}

// Usage example:
$manager = new OAuthManager('your_client_id', 'your_client_secret', 'your_redirect_uri');
$manager->authenticateUser('authorization_code_from_user');
echo $manager->makeRequest('https://api.example.com/data');
?>
