    public void updatePassword(String userId, String newPassword) throws Exception {
        if (!isPasswordComplex(newPassword)) {
            throw new IllegalArgumentException("Password does not meet complexity requirements.");
        }

        boolean updated = false;
        int attempts = 0;

        while (!updated && attempts < 3) {
            try (Connection connection : getConnection(userId)) {
                updatePasswordInDataSource(connection, userId, newPassword);
                updated = true;
            } catch (SQLException e) {
                // Handle network delays and retry
                Thread.sleep(100 * ++attempts);
            }
        }

        if (!updated) {
            throw new Exception("Failed to update password after multiple attempts.");
        }
    }

    private boolean isPasswordComplex(String password) {
        // Implement complexity requirements check
        return true;
    }

    private Connection getConnection(String userId) throws SQLException {
        DataSource dataSource = dataSources.get(userId);
        if (dataSource == null) {
            throw new IllegalArgumentException("No data source found for user: " + userId);
        }
        return dataSource.getConnection();
    }

