#include <stdlib.h>

typedef struct {
    int* states;
    int num_states;
    // Other FSA metadata and transition tables
} FSA;

typedef struct StateNode {
    struct StateNode* next;
    // Additional state data
} StateNode;

StateNode* manageStateList(int* states, int num_states, FSA* fsa, StateNode* last_state) {
    if (states == NULL || num_states <= 0 || fsa == NULL || last_state == NULL) {
        return NULL;
    }

    StateNode* new_head = (StateNode*)malloc(sizeof(StateNode));
    if (new_head == NULL) {
        return NULL;
    }

    new_head->next = NULL;

    for (int i = 0; i < num_states; i++) {
        if (states[i] >= fsa->num_states || states[i] < 0) {
            free(new_head);
            return NULL;
        }

        StateNode* current = new_head;
        while (current->next != NULL) {
            current = current->next;
        }

        StateNode* new_node = (StateNode*)malloc(sizeof(StateNode));
        if (new_node == NULL) {
            free(new_head);
            return NULL;
        }

        new_node->next = NULL;
        current->next = new_node;
    }

    last_state->next = new_head;

    return new_head;
}
