['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define WINDOW_SIZE 10
#define MAX_TRANSACTIONS 1000

typedef struct {
    int id;
    time_t timestamp;
    double amount;
    char* tags;
} Transaction;

typedef struct {
    Transaction transactions[MAX_TRANSACTIONS];
    int front, rear;
    int size;
    int totalTransactions;
    double totalAmount;
} TransactionQueue;

void initQueue(TransactionQueue *queue) {
    queue->front = 0;
    queue->rear = -1;
    queue->size = 0;
    queue->totalTransactions = 0;
    queue->totalAmount = 0;
}

int isEmpty(TransactionQueue *queue) {
    return (queue->size == 0);
}

void enqueue(TransactionQueue *queue, Transaction transaction) {
    if (queue->rear == MAX_TRANSACTIONS - 1)
        return; // Queue is full
    queue->rear++;
    queue->transactions[queue->rear] = transaction;
    queue->size++;
    queue->totalTransactions++;
    queue->totalAmount += transaction.amount;
}

Transaction dequeue(TransactionQueue *queue) {
    if (isEmpty(queue))
        return (Transaction){0}; // Return a dummy transaction
    Transaction transaction = queue->transactions[queue->front];
    queue->front++;
    queue->size--;
    queue->totalTransactions--;
    queue->totalAmount -= transaction.amount;
    return transaction;
}

double getWeightedSum(TransactionQueue *queue, int currentTime) {
    double weightedSum = 0;
    int countInWindow = (currentTime - queue->front > WINDOW_SIZE) ? WINDOW_SIZE : currentTime - queue->front + 1;
    double weightFactor = countInWindow == 0 ? 1.0 : (double)(WINDOW_SIZE - countInWindow + 1) / WINDOW_SIZE;
    for (int i = queue->front; i <= queue->rear && i <= queue->front + countInWindow - 1; i++) {
        weightedSum += queue->transactions[i].amount * weightFactor;
    }
    return weightedSum;
}

Transaction processTransaction(TransactionQueue *queue, Transaction transaction, time_t currentTime) {
    static int blacklist[] = {1001, 2002}; // Example blacklist
    for (int i = 0; i < sizeof(blacklist) / sizeof(blacklist[0]); i++) {
        if (transaction.id == blacklist[i]) {
            return transaction; // Drop fraudulent transactions
        }
    }

    if (!isEmpty(queue) && currentTime - queue->front > 15) {
        dequeue(queue);
    }

    enqueue(queue, transaction);

    double maxWeightedSum = getWeightedSum(queue, currentTime);
    int maxId = transaction.id;

    for (int i = queue->front; i <= queue->rear; i++) {
        double currentWeightedSum = getWeightedSum(queue, currentTime) - queue->transactions[i].amount + transaction.amount;
        if (currentWeightedSum > maxWeightedSum) {
            maxWeightedSum = currentWeightedSum;
            maxId = queue->transactions[i].id;
        }
    }

    return (Transaction){maxId, 0, maxWeightedSum, NULL};
}

int main() {
    TransactionQueue queue;
    initQueue(&queue);

    // Example usage
    time_t currentTime = time(NULL);
    Transaction transaction1 = {1001, currentTime, 10.5, "Payment"};
    Transaction result = processTransaction(&queue, transaction1, currentTime);
    printf("Highest Weighted Sum ID: %d, Value: %.2f\n", result.id, result.amount);

    return 0;
}
