using System;

public class RandomValueGenerator
{
    private int _minValue;
    private int _maxValue;

    public RandomValueGenerator(int minValue, int maxValue)
    {
        SetRange(minValue, maxValue);
    }

    public void SetRange(int minValue, int maxValue)
    {
        if (minValue >= maxValue)
        {
            throw new ArgumentException("Maximum value must be greater than minimum value.");
        }
        _minValue = minValue;
        _maxValue = maxValue;
    }

    public int GenerateRandomInteger()
    {
        Random random = new Random();
        return random.Next(_minValue, _maxValue + 1);
    }

    public float GenerateRandomFloat()
    {
        Random random = new Random();
        return (float)random.NextDouble() * (_maxValue - _minValue) + _minValue;
    }

    public override string ToString()
    {
        return $"Range: {_minValue} to {_maxValue}";
    }
}
