#include <pthread.h>

#define SLASH "/"
#define LOG_CALLS

typedef struct {
    int call_count;
} StringProcessor;

StringProcessor processor = {0};
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

char* appendSlash(const char* input, size_t limit, char* buffer, size_t bufferSize, bool includeNullTerminator) {
    if (input == NULL) return NULL;

    size_t length = strlen(input);
    size_t requiredSize = includeNullTerminator ? length + 2 : length + 1;

    if (buffer != NULL && bufferSize >= requiredSize) {
        strcpy(buffer, input);
        strcat(buffer, SLASH);
        pthread_mutex_lock(&lock);
        processor.call_count++;
        pthread_mutex_unlock(&lock);
        return buffer;
    }

    char* result = (char*)malloc(requiredSize * sizeof(char));
    if (result == NULL) return NULL;

    strcpy(result, input);
    strcat(result, SLASH);

#ifdef LOG_CALLS
    pthread_mutex_lock(&lock);
    processor.call_count++;
    pthread_mutex_unlock(&lock);
#endif

    return result;
}

// Example usage:
// char* newString = appendSlash("example", 10, NULL, 0, true);
// printf("%s\n", newString);
