#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define CHUNK_SIZE 1024 * 1024 // 1MB
#define AVG_FIELD_COUNT 3

typedef struct {
    char **fields;
    int field_count;
} LineData;

void process_chunk(const char *chunk, size_t chunk_size) {
    FILE *output = fopen("processed_output.txt", "a");
    if (!output) {
        perror("Failed to open output file");
        return;
    }

    for (size_t i = 0; i < chunk_size;) {
        LineData line_data = {NULL, 0};
        char *line = NULL;
        size_t len = 0;

        // Read line from chunk
        if ((len = getline(&line, &len, (FILE *)chunk + i)) == -1) {
            free(line);
            break;
        }

        i += len;

        // Process line
        char *token = strtok(line, ",");
        while (token != NULL) {
            line_data.fields = realloc(line_data.fields, (line_data.field_count + 1) * sizeof(char *));
            line_data.fields[line_data.field_count++] = strdup(token);
            token = strtok(NULL, ",");
        }

        // Calculate average of the last three fields
        double sum = 0;
        for (int j = 0; j < line_data.field_count && j < AVG_FIELD_COUNT; j++) {
            sum += atof(line_data.fields[j]);
        }
        double avg = line_data.field_count >= AVG_FIELD_COUNT ? sum / AVG_FIELD_COUNT : 0;

        // Print output
        for (int j = 0; j < line_data.field_count; j++) {
            fprintf(output, "%s,", line_data.fields[j]);
        }
        fprintf(output, "%.2f\n", avg);

        // Free allocated memory
        for (int j = 0; j < line_data.field_count; j++) {
            free(line_data.fields[j]);
        }
        free(line_data.fields);
    }

    fclose(output);
}

void log_error(const char *message) {
    FILE *log_file = fopen("error_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "Error: %s\n", message);
        fclose(log_file);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <input_file> <output_file>\n", argv[0]);
        return 1;
    }

    FILE *input = fopen(argv[1], "r");
    if (!input) {
        perror("Failed to open input file");
        return 1;
    }

    char *chunk = malloc(CHUNK_SIZE);
    size_t chunk_size;

    while ((chunk_size = fread(chunk, 1, CHUNK_SIZE, input)) > 0) {
        process_chunk(chunk, chunk_size);
    }

    free(chunk);
    fclose(input);

    return 0;
}
