#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <tiffio.h>
#include <openssl/evp.h>

EVP_CIPHER_CTX *parse_tiff_and_encrypt(char *filename, char *operation) {
    TIFF *tiff = TIFFOpen(filename, "r");
    if (!tiff) {
        fprintf(stderr, "Error opening TIFF file\n");
        return NULL;
    }

    uint16 bitsPerSample, samplesPerPixel, extraSamples;
    TIFFGetField(tiff, TIFFTAG_BITSPERSAMPLE, &bitsPerSample);
    TIFFGetField(tiff, TIFFTAG_SAMPLESPERPIXEL, &samplesPerPixel);
    TIFFGetField(tiff, TIFFTAG_EXTRASAMPLES, &extraSamples);

    if (bitsPerSample != 1 && bitsPerSample != 2 && bitsPerSample != 4 && bitsPerSample != 8 && bitsPerSample != 16) {
        fprintf(stderr, "Error: Unsupported number of bits per sample\n");
        TIFFClose(tiff);
        return NULL;
    }

    if (extraSamples > 0) {
        printf("Extra samples: %u\n", extraSamples);
        uint16 *sampleInfo = (uint16 *)malloc(extraSamples * sizeof(uint16));
        TIFFGetField(tiff, TIFFTAG_EXTRASAMPLESINFO, sampleInfo);
        // Process sample information
        free(sampleInfo);
    }

    EVP_CIPHER_CTX *ctx = NULL;
    if (strcmp(operation, "encrypt") == 0) {
        ctx = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, NULL, NULL);
    } else if (strcmp(operation, "decrypt") == 0) {
        ctx = EVP_CIPHER_CTX_new();
        EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, NULL, NULL);
    }

    TIFFClose(tiff);

    return ctx;
}
