#define MAX_FILENAME_LENGTH 128

void generate_new_filename(const char *input_filename, const char *log_file) {
    FILE *log = fopen(log_file, "a");
    if (!log) {
        perror("Failed to open log file for writing");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[17];
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", tm_info);

    int random_number = rand() % 9999 + 1;

    const char *file_extension = strrchr(input_filename, '.');
    if (!file_extension) {
        file_extension = ".txt";
    } else {
        file_extension++;
    }

    size_t input_length = strlen(input_filename);
    char new_filename[MAX_FILENAME_LENGTH];
    snprintf(new_filename, sizeof(new_filename), "%.*s_%s_%d.%s",
             (int)(input_length - strlen(file_extension)), input_filename,
             timestamp, random_number, file_extension);

    // Replace spaces and special characters with underscores
    for (size_t i = 0; new_filename[i]; i++) {
        if (!isalnum(new_filename[i]) && new_filename[i] != '_') {
            new_filename[i] = '_';
        }
    }

    // Truncate filename if it exceeds the maximum length
    if (strlen(new_filename) > MAX_FILENAME_LENGTH - 1) {
        new_filename[MAX_FILENAME_LENGTH - 1] = '\0';
    }

    printf("New filename: %s\n", new_filename);

    fprintf(log, "Generated new filename: %s\n", new_filename);
    fclose(log);
}

int main() {
    generate_new_filename("example.txt", "log.txt");
    return 0;
}
