} AESCipher;

int init_cipher(AESCipher *cipher, const char *password, int password_len, const unsigned char *salt, size_t salt_len, size_t iv_size) {
    if (iv_size % EVP_CIPHER_block_size(EVP_aes_256_cbc()) != 0 || iv_size > EVP_CIPHER_iv_length(EVP_aes_256_cbc())) {
        fprintf(stderr, "Unsupported IV size\n");
        return -1;
    }

    cipher->ctx = EVP_CIPHER_CTX_new();
    if (!cipher->ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        return -1;
    }

    if (PBKDF2_HMAC((const unsigned char *)password, password_len, salt, salt_len, 100000, EVP_sha256(), sizeof(cipher->key), cipher->key) != 1) {
        fprintf(stderr, "Failed to derive key\n");
        EVP_CIPHER_CTX_free(cipher->ctx);
        return -1;
    }

    if (EVP_EncryptInit_ex(cipher->ctx, EVP_aes_256_cbc(), NULL, cipher->key, salt) != 1) {
        fprintf(stderr, "Failed to initialize cipher\n");
        EVP_CIPHER_CTX_free(cipher->ctx);
        return -1;
    }

    if (EVP_CIPHER_CTX_set_iv_length(cipher->ctx, iv_size) != 1) {
        fprintf(stderr, "Failed to set IV length\n");
        EVP_CIPHER_CTX_free(cipher->ctx);
        return -1;
    }

    return 0;
}

void cleanup_cipher(AESCipher *cipher) {
    if (cipher->ctx) {
        EVP_CIPHER_CTX_free(cipher->ctx);
        cipher->ctx = NULL;
    }
}
