#include <unistd.h>
#include <string.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <time.h>

#define MAX_CONCURRENT_PROCESSES 10

typedef struct {
    pid_t pid;
    int pipefd[2];
} ProcessInfo;

void log_message(const char *message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

int run_command_in_background(const char *command, const char **envp, FILE *input, FILE *output, FILE *error, int max_concurrent_processes, ProcessInfo processes[]) {
    if (max_concurrent_processes <= 0) {
        log_message("Invalid maximum concurrent processes");
        return -1;
    }

    for (int i = 0; i < MAX_CONCURRENT_PROCESSES; ++i) {
        if (processes[i].pid == 0) {
            pid_t pid = fork();
            if (pid == -1) {
                log_message("Fork failed");
                return -1;
            } else if (pid == 0) {
                // Child process
                close(processes[i].pipefd[0]);
                dup2(processes[i].pipefd[1], STDOUT_FILENO);
                close(processes[i].pipefd[1]);

                execlp(command, command, NULL);
                log_message("Command execution failed");
                _exit(EXIT_FAILURE);
            } else {
                // Parent process
                processes[i].pid = pid;
                close(processes[i].pipefd[1]);
                return i;
            }
        }
    }

    log_message("Max concurrent processes reached");
    return -1;
}

int main() {
    ProcessInfo processes[MAX_CONCURRENT_PROCESSES];

    for (int i = 0; i < MAX_CONCURRENT_PROCESSES; ++i) {
        if (pipe(processes[i].pipefd) == -1) {
            log_message("Pipe creation failed");
            return -1;
        }
    }

    const char *envp[] = { "VAR=value", NULL };
    FILE *input = fopen("input.txt", "r");
    FILE *output = fopen("output.txt", "w");
    FILE *error = fopen("error.txt", "w");

    if (!input || !output || !error) {
        log_message("File open failed");
        return -1;
    }

    int process_index = run_command_in_background("your_command_here", envp, input, output, error, MAX_CONCURRENT_PROCESSES, processes);

    if (process_index != -1) {
        waitpid(processes[process_index].pid, NULL, 0);
        log_message("Command execution completed");
    }

    for (int i = 0; i < MAX_CONCURRENT_PROCESSES; ++i) {
        close(processes[i].pipefd[0]);
        close(processes[i].pipefd[1]);
    }

    fclose(input);
    fclose(output);
    fclose(error);

    return 0;
}
