    public async Task<DirectoryInfo?> AddWebApplicationAsync(string siteName, string virtualPath, string physicalPath, AuthenticationMode authMode)
    {
        try
        {
            if (!Directory.Exists(physicalPath))
            {
                Directory.CreateDirectory(physicalPath);
            }

            var webConfigPath = Path.Combine(physicalPath, "web.config");
            if (!File.Exists(webConfigPath))
            {
                logger.Info("Missing web.config file in the directory. Operation aborted.");
                return null;
            }

            using (var serverManager = new ServerManager())
            {
                Site site = serverManager.Sites[siteName];
                if (site == null)
                {
                    logger.Error($"Site {siteName} not found.");
                    return null;
                }

                Application application = site.Applications[virtualPath];
                if (application != null)
                {
                    logger.Info("Application already exists at the specified path.");
                    return null;
                }

                await ValidateConfigAsync(physicalPath);

                application = site.Applications.Add(virtualPath, physicalPath);
                application.ApplicationPoolName = "DefaultAppPool";
                application.AuthenticationSection["windowsAuthentication"].Enabled = authMode == AuthenticationMode.Windows;
                application.AuthenticationSection["basicAuthentication"].Enabled = authMode == AuthenticationMode.Basic;

                serverManager.CommitChanges();
                logger.Info($"Web application added successfully at {virtualPath}");
                return new DirectoryInfo(physicalPath);
            }
        }
        catch (Exception ex)
        {
            logger.Error(ex, "Error occurred while adding web application.");
            return null;
        }
    }

    private static async Task ValidateConfigAsync(string physicalPath)
    {
        // Simulate external service integration
        await Task.Delay(1000); // Simulate latency
        logger.Info("Configuration validation completed successfully.");
    }
