import java.io.*;
import java.nio.file.*;
import java.util.concurrent.*;

public class ShellCommandExecutor {

    private static final String TEMP_DIR = "/path/to/temp/dir";
    private static final String LOG_FILE = "/path/to/log/file.log";

    public void executeCommands(String[] commands) {
        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

        for (String command : commands) {
            Future<?> future = executor.submit(() -> {
                try {
                    Path tempDirPath = Paths.get(TEMP_DIR);
                    if (Files.exists(tempDirPath)) {
                        Files.walkFileTree(tempDirPath, new SimpleFileVisitor<Path>() {
                            @Override
                            public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) throws IOException {
                                Files.delete(file);
                                return FileVisitResult.CONTINUE;
                            }

                            @Override
                            public FileVisitResult postVisitDirectory(Path dir, IOException exc) throws IOException {
                                Files.delete(dir);
                                return FileVisitResult.CONTINUE;
                            }
                        });
                    }

                    ProcessBuilder processBuilder = new ProcessBuilder("sh", "-c", command);
                    processBuilder.directory(new File("/path/to/working/dir"));
                    processBuilder.redirectErrorStream(true);
                    Process process = processBuilder.start();

                    try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
                        String line;
                        while ((line = reader.readLine()) != null) {
                            logToFile(line, LOG_FILE);
                        }
                    }

                    int exitCode = process.waitFor();
                    if (exitCode != 0) {
                        throw new IOException("Command execution failed with exit code: " + exitCode);
                    }
                } catch (IOException | InterruptedException e) {
                    e.printStackTrace();
                }
            });
        }

        executor.shutdown();
    }

    private void logToFile(String message, String filePath) throws IOException {
        try (BufferedWriter writer = Files.newBufferedWriter(Paths.get(filePath), StandardOpenOption.APPEND)) {
            writer.write(message);
            writer.newLine();
        }
    }

    public static void main(String[] args) {
        ShellCommandExecutor executor = new ShellCommandExecutor();
        String[] commands = {"ls -l", "echo 'Hello, World!'", "rm -rf /nonexistentdir"};
        executor.executeCommands(commands);
    }
}
