using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Microsoft.Azure.Storage;
using Microsoft.Azure.Storage.Blob;

public class CsvUploader
{
    public static async Task<UploadSummary> UploadCsvToBlob(string csvFilePath, string connectionString)
    {
        var summary = new UploadSummary();
        CloudStorageAccount account = CloudStorageAccount.Parse(connectionString);
        CloudBlobClient client = account.CreateCloudBlobClient();
        CloudBlobContainer container = client.GetContainerReference("your-container-name");

        await container.CreateIfNotExistsAsync();

        using (StreamReader reader = File.OpenText(csvFilePath))
        {
            string headerLine = reader.ReadLine();
            if (!string.IsNullOrEmpty(headerLine))
            {
                var headers = headerLine.Split(',');

                for (int i = 0; i < headers.Length; i++)
                {
                    summary.ColumnHeaders.Add(headers[i]);
                }
            }

            while (!reader.EndOfStream)
            {
                string[] row = reader.ReadLine().Split(',');
                summary.TotalRows++;

                if (row.Length != headers.Length)
                {
                    summary.Inconsistencies++;
                }
                else
                {
                    var dataRow = new Dictionary<string, string>();
                    for (int i = 0; i < headers.Length; i++)
                    {
                        dataRow[headers[i]] = row[i];
                    }

                    summary.DataRows.Add(dataRow);
                }
            }
        }

        CloudBlockBlob blob = container.GetBlockBlobReference(Path.GetFileName(csvFilePath));
        using (FileStream fileStream = File.OpenRead(csvFilePath))
        {
            await blob.UploadFromStreamAsync(fileStream);
        }

        return summary;
    }
}

public class UploadSummary
{
    public List<string> ColumnHeaders { get; set; } = new List<string>();
    public int TotalRows { get; set; }
    public int Inconsistencies { get; set; }
    public List<Dictionary<string, string>> DataRows { get; set; } = new List<Dictionary<string, string>>();
}
