public class TripleDESDecryptor
{
    public static string DecryptMessage(string base64EncryptedData, byte[] tripleDesKey, byte[] iv, bool cacheAlgorithms = true)
    {
        try
        {
            using (TripleDESCryptoServiceProvider des = new TripleDESCryptoServiceProvider())
            {
                if (cacheAlgorithms)
                {
                    // Dynamically retrieve and cache cryptographic algorithms
                    var configManager = new ConfigManager();
                    string algorithmName = configManager.GetAlgorithmName("TripleDES");
                    CryptoConfig.AddAlgorithm(typeof(TripleDESCryptoServiceProvider), algorithmName);
                }

                des.Key = tripleDesKey;
                des.IV = iv;
                des.Mode = CipherMode.CBC;
                des.Padding = PaddingMode.PKCS7;

                using (MemoryStream msDecrypt = new MemoryStream(Convert.FromBase64String(base64EncryptedData)))
                {
                    using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, des.CreateDecryptor(), CryptoStreamMode.Read))
                    {
                        using (StreamReader srDecrypt = new StreamReader(csDecrypt))
                        {
                            return srDecrypt.ReadToEnd();
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            // Handle potential errors gracefully
            throw new Exception("Decryption failed: " + ex.Message, ex);
        }
    }
}

public class ConfigManager
{
    public string GetAlgorithmName(string encryptionType)
    {
        // Simulate retrieval from configuration files and libraries
        switch (encryptionType)
        {
            case "TripleDES":
                return "TripleDESCryptoServiceProvider";
            default:
                throw new Exception("Unsupported encryption type");
        }
    }
}
