using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class StringHashProcessor
{
    private readonly IConfigService _configService;
    private readonly ConcurrentDictionary<string, string> _hashCache = new ConcurrentDictionary<string, string>();

    public StringHashProcessor(IConfigService configService)
    {
        _configService = configService;
    }

    public async Task ProcessStringsAsync(IEnumerable<string> strings)
    {
        var tasks = new List<Task>();

        foreach (var str in strings)
        {
            tasks.Add(ProcessStringAsync(str));
        }

        await Task.WhenAll(tasks);
    }

    private async Task ProcessStringAsync(string input)
    {
        string hash;
        if (!_hashCache.TryGetValue(input, out hash))
        {
            hash = MD5Hash(input);

            try
            {
                var config = await _configService.GetConfigAsync();
                if (config.EnableCaching && IsHashValid(config.ExpectedHash, hash))
                {
                    _hashCache.TryAdd(input, hash);
                }
            }
            catch
            {
                // Handle configuration fetch failure, e.g., log and skip caching
            }
        }

        Console.WriteLine($"String: {input}, MD5 Hash: {hash}");
    }

    private string MD5Hash(string input)
    {
        using (MD5 md5 = MD5.Create())
        {
            byte[] inputBytes = System.Text.Encoding.ASCII.GetBytes(input);
            byte[] hashBytes = md5.ComputeHash(inputBytes);
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
        }
    }

    private bool IsHashValid(string expectedHash, string actualHash)
    {
        return string.Equals(expectedHash, actualHash, StringComparison.OrdinalIgnoreCase);
    }
}

public interface IConfigService
{
    Task<Config> GetConfigAsync();
}

public class Config
{
    public bool EnableCaching { get; set; }
    public string ExpectedHash { get; set; }
}
```

