public class AESDecryptionHelper
{
    public static byte[] Decrypt(byte[] ciphertext, byte[] key, byte[] iv)
    {
        using (Aes aes = Aes.Create())
        {
            aes.Key = key;
            aes.IV = iv;
            aes.Mode = CipherMode.CBC;
            aes.Padding = PaddingMode.PKCS7;

            ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV);

            using (MemoryStream msDecrypt = new MemoryStream(ciphertext))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    byte[] plaintext = new byte[ciphertext.Length];
                    int decryptedByteCount = csDecrypt.Read(plaintext, 0, plaintext.Length);
                    Array.Resize(ref plaintext, decryptedByteCount);
                    return plaintext;
                }
            }
        }
    }

    public static void Main(string[] args)
    {
        try
        {
            // Example usage:
            byte[] key = Convert.FromBase64String("your-base-64-encoded-key");
            byte[] iv = Convert.FromBase64String("your-base-64-encoded-iv");
            byte[] ciphertext = Convert.FromBase64String("your-base-64-encoded-ciphertext");

            byte[] plaintext = Decrypt(ciphertext, key, iv);
            Console.WriteLine("Decrypted Text: " + Encoding.UTF8.GetString(plaintext));
        }
        catch (Exception ex)
        {
            Console.WriteLine("Decryption failed: " + ex.Message);
        }
    }
}
