use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::Duration;

use tokio;
use tokio::task;
use reqwest::Client;
use log::{info, error};

// Define a struct to hold task details
struct Task {
    id: String,
    details: HashMap<String, String>,
}

// Function to fetch task details from the external API
async fn fetch_task_details(client: &Client, task_id: &str) -> Result<Task, reqwest::Error> {
    let response = client.get(format!("https://api.example.com/tasks/{}", task_id)).send().await?;
    if response.status().is_success() {
        let task = response.json::<Task>().await?;
        Ok(task)
    } else {
        Err(reqwest::Error::new(reqwest::StatusCode::from_u16(response.status().as_u16()).unwrap(), "Failed to fetch task details"))
    }
}

// Function to process a single task
async fn process_task(client: &Client, task_id: String) -> Result<(), reqwest::Error> {
    let task = fetch_task_details(client, &task_id).await?;
    // Process the task (e.g., perform some operation)
    info!("Processing task {}", task.id);
    Ok(())
}

// Main function to handle command line arguments and process tasks
#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 {
        error!("Usage: {} <task_ids>", args[0]);
        return Err("Invalid arguments".into());
    }

    let client = Client::new();
    let task_ids = &args[1..];

    // Create a channel to communicate with the worker tasks
    let (tx, mut rx) = tokio::sync::mpsc::channel(task_ids.len());

    // Spawn worker tasks to process each task concurrently
    for task_id in task_ids {
        tx.send(task_id.to_string()).await?;
    }

    // Close the sender half of the channel
    drop(tx);

    // Process up to 10 concurrent tasks
    let mut handles = vec![];
    while let Some(task_id) = rx.recv().await {
        let client = client.clone();
        let handle = tokio::spawn(async move {
            match process_task(&client, task_id).await {
                Ok(_) => info!("Task {} completed successfully", task_id),
                Err(e) => error!("Failed to process task {}: {}", task_id, e),
            }
        });
        handles.push(handle);
        if handles.len() >= 10 {
            for handle in futures::future::join_all(handles).await {
                handle?;
            }
            handles.clear();
        }
    }

    // Wait for any remaining tasks to complete
    for handle in handles {
        handle.await?;
    }

    info!("All tasks processed");
    Ok(())
}
