use std::os::unix::fs::PermissionsExt;
use std::path::Path;

fn create_config_directory(app_name: &str) -> Result<(), Box<dyn std::error::Error>> {
    let config_dir = Path::new(env::var("HOME")?).join(app_name);

    if config_dir.exists() && config_dir.is_dir() {
        env::set_var(format!("{}_CONFIG_DIR", app_name), config_dir.display().to_string());
        return Ok(());
    }

    fs::create_dir_all(&config_dir)?;
    env::set_var(format!("{}_CONFIG_DIR", app_name), config_dir.display().to_string());

    let mut perms = fs::metadata(&config_dir)?.permissions();
    perms.set_mode(0o755); // Set permissions for user and group
    fs::set_permissions(&config_dir, perms)?;

    Ok(())
}
