from abc import ABC, abstractmethod

# Setup basic configuration for logging
logging.basicConfig(level=logging.DEBUG)

class Serializable(ABC):
    @abstractmethod
    def to_json(self) -> str:
        pass

    @staticmethod
    @abstractmethod
    def from_json(data: str) -> 'Serializable':
        pass

class Factory:
    _registry = {}

    @staticmethod
    def register(id_: str, cls_: type):
        if id_ in Factory._registry:
            logging.warning(f"ID '{id_}' already registered. Overwriting.")
        Factory._registry[id_] = cls_

    @staticmethod
    def create_instance(data: str) -> Serializable:
        data_dict = json.loads(data)
        cls_id = data_dict.get('type')
        if cls_id not in Factory._registry:
            raise ValueError(f"Unknown type '{cls_id}'")
        cls_ = Factory._registry[cls_id]
        return cls_.from_json(json.dumps(data_dict))

class CyclicReferenceHandler:
    def __init__(self, max_depth: int = 10):
        self.max_depth = max_depth
        self.depth = 0

    def handle(self, data: dict) -> dict:
        if 'id' in data and data['id'] in self._seen_ids:
            return {'$ref': f"#{data['id']}"}
        if self.depth >= self.max_depth:
            raise ValueError("Cyclic reference detected")
        self._seen_ids.add(data['id'])
        self.depth += 1
        result = {k: self.handle(v) for k, v in data.items()}
        self.depth -= 1
        return result

class JSONSerializer:
    def __init__(self, cyclic_ref_handler: CyclicReferenceHandler):
        self.cyclic_ref_handler = cyclic_ref_handler

    def serialize(self, obj: Serializable) -> str:
        return json.dumps(obj.to_json(), default=lambda o: o.to_json())

    def deserialize(self, data: str) -> Serializable:
        return Factory.create_instance(data)

class JSONSchemaValidator:
    @staticmethod
    def validate(data: str, schema):
        try:
            json.loads(data)
        except json.JSONDecodeError as e:
            raise ValueError(f"Invalid JSON string: {e}")
        # Add schema validation logic here

# Example usage
Factory.register('Person', type)

class Person(Serializable):
    def __init__(self, name, age):
        self.name = name
        self.age = age

    def to_json(self) -> str:
        return {'type': 'Person', 'name': self.name, 'age': self.age}

    @staticmethod
    def from_json(data: str) -> 'Person':
        data_dict = json.loads(data)
        return Person(name=data_dict['name'], age=data_dict['age'])

# Create serializer with cyclic reference handler
serializer = JSONSerializer(CyclicReferenceHandler(max_depth=5))

# Serialize and deserialize a Person object
person = Person("John Doe", 30)
serialized_data = serializer.serialize(person)
deserialized_person = serializer.deserialize(serialized_data)

print(deserialized_person.name, deserialized_person.age)  # Output: John Doe 30
