import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;

public class StringHashProcessor {

    private static final Map<String, String> hashCache = new HashMap<>();
    private static final Object lock = new Object();
    private static int logLevel = 0; // 0: Error, 1: Warning, 2: Info

    public static Map<String, String> processStrings(List<String> inputList, String regexPattern, boolean useSHA256) {
        Map<String, String> result = new HashMap<>();
        Pattern pattern = Pattern.compile(regexPattern);

        for (String str : inputList) {
            if (!pattern.matcher(str).matches()) {
                continue;
            }

            String hashFunction = useSHA256 ? "SHA-256" : "MD5";
            try {
                MessageDigest digest = MessageDigest.getInstance(hashFunction);
                byte[] hashBytes = digest.digest(str.getBytes());
                StringBuilder sb = new StringBuilder();
                for (byte b : hashBytes) {
                    sb.append(String.format("%02x", b));
                }
                String hash = sb.toString();

                synchronized (lock) {
                    if (!hashCache.containsKey(str)) {
                        hashCache.put(str, hash);
                        log("Computed " + hashFunction + " hash for: " + str, 2);
                    }
                }

                result.put(str, hash);
            } catch (NoSuchAlgorithmException e) {
                log("Error computing " + hashFunction + " hash for: " + str, 0);
            }
        }

        return result;
    }

    private static void log(String message, int level) {
        if (logLevel >= level) {
            System.out.println(message);
        }
    }

    public static void setLogLevel(int level) {
        logLevel = level;
    }
}
```

