public class RandomFileRenamer
{
    private int minValue;
    private int maxValue;

    public RandomFileRenamer(int min, int max)
    {
        minValue = min;
        maxValue = max;
    }

    public float GenerateRandomFloat()
    {
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    public int GenerateRandomInt()
    {
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    public void RenameFile(string filePath, string newExtension)
    {
        FileInfo fileInfo = new FileInfo(filePath);
        string directoryPath = fileInfo.DirectoryName;
        string fileNameWithoutExtension = fileInfo.Name.Substring(0, fileInfo.Name.LastIndexOf('.'));

        string newFileName = $"{fileNameWithoutExtension}_{GenerateRandomInt()}.{newExtension}";
        File.Move(filePath, Path.Combine(directoryPath, newFileName));
    }

    public override string ToString()
    {
        return $"Range: {minValue}-{maxValue}, New Extension: .{GenerateRandomInt()}";
    }
}
