void on_connection(uv_stream_t *server, int status) {
    if (status < 0) {
        fprintf(stderr, "New connection error %s\n", uv_strerror(status));
        return;
    }

    uv_tcp_t *client = (uv_tcp_t*)malloc(sizeof(uv_tcp_t));
    uv_tcp_init(server->loop, client);
    if (uv_accept(server, (uv_stream_t*)client) == 0) {
        // Handle the connection
    } else {
        uv_close((uv_handle_t*)client, NULL);
    }
}

void start_server(ServerConfig *config) {
    struct sockaddr_in addr;
    uv_tcp_init(config->server.loop, &config->server);

    if (config->protocol == 0) {
        // Bind to HTTP port
        uv_ip4_addr("0.0.0.0", config->port, &addr);
    } else {
        // Bind to HTTPS port
        uv_ip4_addr("0.0.0.0", config->port + 1, &addr);
    }

    int r = uv_tcp_bind(&config->server, (const struct sockaddr*)&addr, UV_TCP_IPV6ONLY);
    if (r) {
        fprintf(stderr, "Bind error %s\n", uv_strerror(r));
        return;
    }

    r = uv_listen((uv_stream_t*)&config->server, 128, on_connection);
    if (r) {
        fprintf(stderr, "Listen error %s\n", uv_strerror(r));
        return;
    }
}

void stop_server(ServerConfig *config) {
    uv_close((uv_handle_t*)&config->server, NULL);
}

int main() {
    uv_loop_t *loop = uv_default_loop();

    ServerConfig config1 = {.port = 8080, .protocol = 0, .timeout = 30, .keep_alive = 5};
    ServerConfig config2 = {.port = 8443, .protocol = 1, .timeout = 60, .keep_alive = 10};

    start_server(&config1);
    start_server(&config2);

    uv_run(loop, UV_RUN_DEFAULT);

    stop_server(&config1);
    stop_server(&config2);

    return 0;
}
