import hashlib
import os
from concurrent.futures import ThreadPoolExecutor, ProcessPoolExecutor, as_completed

def md5_hash_file(file_path, chunk_size=65536):
    hasher = hashlib.md5()
    with open(file_path, 'rb') as file:
        while True:
            data = file.read(chunk_size)
            if not data:
                break
            hasher.update(data)
    return hasher.hexdigest()

def md5_hash_files_concurrently(file_paths, chunk_size=65536, use_processes=False):
    if use_processes:
        executor = ProcessPoolExecutor()
    else:
        executor = ThreadPoolExecutor(max_workers=len(file_paths))

    futures = {executor.submit(md5_hash_file, file_path, chunk_size): file_path for file_path in file_paths}
    results = {}

    for future in as_completed(futures):
        file_path = futures[future]
        try:
            hash_value = future.result()
            results[file_path] = hash_value
        except Exception as e:
            results[file_path] = str(e)

    return results

# Example usage:
file_paths = ['path/to/file1', 'path/to/file2', 'path/to/file3']
hash_results = md5_hash_files_concurrently(file_paths, use_processes=True, chunk_size=8192)

for file_path, hash_value in hash_results.items():
    print(f"File: {file_path}, MD5 Hash: {hash_value}")
```

This code snippet defines a function `md5_hash_file` to compute the MD5 hash of a single file efficiently by reading it in fixed-size chunks. It also includes a function `md5_hash_files_concurrently` to handle multiple files concurrently using either threads or processes based on the `use_processes` parameter. The example usage demonstrates how to use these functions to compute MD5 hashes for a list of files.

