    static int attempts = 0;
    if (attempts < MAX_RETRIES) {
        attempts++;
        snprintf(nasPdu, sizeof(nasPdu), "NAS_PDU_%d", context);
        return 0; // Success
    }
    return -1; // Failure
}

int validateNasPdu(const char *nasPdu) {
    // Simulate EMM protocol validation
    return strlen(nasPdu) > 5 ? 0 : -1; // Basic check
}

LTE_NAS_EMM_MESSAGE* initDynamicList(int numMessages, int *count, clock_t deadline) {
    LTE_NAS_EMM_MESSAGE *list = malloc(numMessages * sizeof(LTE_NAS_EMM_MESSAGE));
    if (list == NULL) {
        perror("Failed to allocate memory for list");
        return NULL;
    }

    *count = 0;
    time_t start = time(NULL);
    for (int i = 0; i < numMessages; i++) {
        int context = i + 1;
        char nasPdu[1024];
        int retries = 0;

        while (retries < MAX_RETRIES) {
            if (fetchNasPdu(context, nasPdu) == 0) {
                if (validateNasPdu(nasPdu) == 0) {
                    list[i].epsMobilityContext = context;
                    strncpy(list[i].nasPdu, nasPdu, sizeof(list[i].nasPdu));
                    (*count)++;
                    break;
                } else {
                    fprintf(stderr, "Invalid NAS_PDU for context %d\n", context);
                }
            }
            retries++;
        }

        if (time(NULL) - start > 1) {
            fprintf(stderr, "Deadline exceeded. Only initialized %d messages.\n", *count);
            break;
        }
    }

    if (*count == 0) {
        free(list);
        list = NULL;
    }

    return list;
}

void cleanup(LTE_NAS_EMM_MESSAGE *list, int count) {
    free(list);
}
