using System;
using System.Threading.Tasks;

public class DynamicRangeGenerator<T> where T : IComparable<T>
{
    private T min;
    private T max;
    private bool isMaxInclusive;
    private Random random = new Random();

    public DynamicRangeGenerator(T min, T max, bool isMaxInclusive)
    {
        SetRange(min, max, isMaxInclusive);
    }

    public void SetRange(T newMin, T newMax, bool isMaxNewInclusive)
    {
        if (newMin.CompareTo(newMax) > 0 || (!isMaxNewInclusive && newMin.Equals(newMax)))
        {
            throw new ArgumentException("Invalid range parameters.");
        }
        min = newMin;
        max = newMax;
        isMaxInclusive = isMaxNewInclusive;
    }

    public T GenerateRandomValue()
    {
        if (min.CompareTo(max) == 0)
        {
            return min;
        }

        bool useMax = random.Next(2) == 1 && (isMaxInclusive || !min.Equals(max));
        T value = useMax ? max : min;

        if (!value.Equals(min) && !useMax)
        {
            value = GenerateRandomValue();
        }

        return value;
    }
}

public class Program
{
    public static async Task Main(string[] args)
    {
        DynamicRangeGenerator<int> intGenerator = new DynamicRangeGenerator<int>(1, 100, true);
        Console.WriteLine(intGenerator.GenerateRandomValue());

        DynamicRangeGenerator<float> floatGenerator = new DynamicRangeGenerator<float>(0.5f, 2.5f, false);
        Console.WriteLine(floatGenerator.GenerateRandomValue());
    }
}
```

