using System;
using System.IO;

public class AdvancedFileRenamer
{
    private int minValue;
    private int maxValue;
    private int seed;

    public AdvancedFileRenamer(int minValue, int maxValue, int seed)
    {
        this.minValue = minValue;
        this.maxValue = maxValue;
        this.seed = seed;
        RandomGenerator = new Random(seed);
    }

    private Random RandomGenerator { get; set; }

    public float GenerateRandomFloat()
    {
        return (float)RandomGenerator.NextDouble() * (maxValue - minValue) + minValue;
    }

    public int GenerateRandomInt()
    {
        return RandomGenerator.Next(minValue, maxValue);
    }

    public void RenameFile(string filePath)
    {
        if (string.IsNullOrEmpty(filePath))
            throw new ArgumentException("File path cannot be null or empty.");

        string directory = Path.GetDirectoryName(filePath);
        string fileNameWithoutExtension = Path.GetFileNameWithoutExtension(filePath);
        string originalExtension = Path.GetExtension(filePath);

        int extensionLength = GetExtensionLength(fileNameWithoutExtension);
        string newExtension = GenerateRandomDigits(extensionLength) + GetFileType(originalExtension);

        string newFilePath = Path.Combine(directory, $"{fileNameWithoutExtension}{newExtension}");
        File.Move(filePath, newFilePath);
    }

    private int GetExtensionLength(string fileName)
    {
        return fileName.Length % 5 == 0 ? 4 : 6;
    }

    private string GenerateRandomDigits(int length)
    {
        const string digits = "0123456789";
        char[] result = new char[length];
        for (int i = 0; i < length; i++)
            result[i] = digits[RandomGenerator.Next(digits.Length)];
        return new string(result);
    }

    private string GetFileType(string extension)
    {
        if (string.IsNullOrEmpty(extension))
            throw new ArgumentException("Extension cannot be null or empty.");

        switch (extension.ToLower())
        {
            case ".txt": return "TXT";
            case ".jpg": return "JPEG";
            case ".png": return "PNG";
            default: return "UNK";
        }
    }

    public override string ToString()
    {
        return $"Range: {minValue}-{maxValue}, Seed: {seed}";
    }
}
