    // Ensure adherence to EMM protocol standards and generate randomly

    pthread_mutex_t *mutex = (pthread_mutex_t*)malloc(sizeof(pthread_mutex_t));
    if (mutex == NULL) {
        perror("Failed to allocate memory for mutex");
        free(array->messages);
        free(array);
        return NULL;
    }

    if (pthread_mutex_init(mutex, NULL) != 0) {
        perror("Failed to initialize mutex");
        free(array->messages);
        free(array);
        free(mutex);
        return NULL;
    }

    array->mutex = mutex;

    return array;
}

void destroy_message_array(NAS_Message_Array *array) {
    if (array == NULL) {
        return;
    }

    pthread_mutex_destroy(array->mutex);
    free(array->messages);
    free(array->mutex);
    free(array);
}
