MoSTState* loadObjectFromFile(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        return NULL;
    }

    MoSTState* state = NULL;
    size_t bytesRead = fread(&state, sizeof(MoSTState), 1, file);
    fclose(file);

    if (bytesRead != 1) {
        free(state);
        return NULL;
    }

    return state;
}

const char* modifyFilenameWithTimestampAndRandomNumber(const char* originalFilename, const char* logFilename) {
    static char newFilename[MAX_FILENAME_LENGTH];
    time_t now = time(NULL);
    struct tm* timeinfo = localtime(&now);
    srand(time(NULL));
    int randomNumber = rand() % 9999 + 1;

    // Log the operation to the specified log file
    FILE* logFile = fopen(logFilename, "a");
    if (logFile != NULL) {
        fprintf(logFile, "Modifying filename: %s\n", originalFilename);
        fclose(logFile);
    }

    // Replace spaces and special characters with underscores
    for (int i = 0; i < strlen(originalFilename); i++) {
        char ch = originalFilename[i];
        if (ch == ' ' || !isalnum(ch)) {
            newFilename[i] = '_';
        } else {
            newFilename[i] = ch;
        }
    }

    // Add timestamp, random number, and file type to the filename
    sprintf(newFilename + strlen(newFilename), "_%04d_%02d%d_%s",
            timeinfo->tm_year + 1900, timeinfo->tm_mon + 1,
            timeinfo->tm_mday, timeinfo->tm_hour * 100 + timeinfo->tm_min,
            randomNumber, (strlen(newFilename) > 3 ? newFilename + strlen(newFilename) - 2 : "txt"));

    // Truncate the filename if it exceeds the maximum length
    if (strlen(newFilename) > MAX_FILENAME_LENGTH) {
        newFilename[MAX_FILENAME_LENGTH - 1] = '\0';
    }

    return newFilename;
}
