using System;
using System.Collections.Generic;
using System.Linq;
using Newtonsoft.Json;

public enum TaskStatus { Pending, InProgress, Completed }

public class Task
{
    public int Id { get; set; }
    public string Description { get; set; }
    public Priority Priority { get; set; }
    public DateTime Deadline { get; set; }
    public TaskStatus Status { get; set; }
}

public enum Priority { High, Medium, Low }

public class TaskManager
{
    private List<Task> tasks = new List<Task>();

    public void AddTask(Task task)
    {
        tasks.Add(task);
    }

    public void UpdateTask(int taskId, Action<Task> updateAction)
    {
        var task = tasks.FirstOrDefault(t => t.Id == taskId);
        if (task != null)
        {
            updateAction(task);
        }
    }

    public void RemoveTask(int taskId)
    {
        tasks.RemoveAll(t => t.Id == taskId);
    }

    public string GenerateSummaryReport()
    {
        return $"Total Tasks: {tasks.Count}, Pending: {tasks.Count(t => t.Status == TaskStatus.Pending)}, In-Progress: {tasks.Count(t => t.Status == TaskStatus.InProgress)}, Completed: {tasks.Count(t => t.Status == TaskStatus.Completed)}";
    }

    public List<Task> FilterTasks(DateTime startDate, DateTime endDate)
    {
        return tasks.Where(t => t.Deadline >= startDate && t.Deadline <= endDate).ToList();
    }

    public string SerializeToJson()
    {
        return JsonConvert.SerializeObject(tasks);
    }

    public void DeserializeFromJson(string json)
    {
        tasks = JsonConvert.DeserializeObject<List<Task>>(json);
    }

    public override string ToString()
    {
        return $"TaskManager with {tasks.Count} tasks";
    }
}
