#include <string.h>

typedef struct {
    char name[100];
    char email[100];
    char phone[20];
    char city[50];
} User;

User** filter_users_by_city(const char* filename, const char* city, int* count) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    User** users = NULL;
    *count = 0;

    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        if (strlen(buffer) > 1 && buffer[strlen(buffer) - 1] == '\n') {
            buffer[strlen(buffer) - 1] = '\0';
        }

        User* user = malloc(sizeof(User));
        if (!user) {
            perror("Memory allocation failed");
            fclose(file);
            for (int i = 0; i < *count; ++i) {
                free(users[i]);
            }
            free(users);
            return NULL;
        }

        sscanf(buffer, "%s %s %s %s", user->name, user->email, user->phone, user->city);

        if (strcmp(user->city, city) == 0) {
            users = realloc(users, (*count + 1) * sizeof(User*));
            if (!users) {
                perror("Memory reallocation failed");
                free(user);
                fclose(file);
                for (int i = 0; i < *count; ++i) {
                    free(users[i]);
                }
                return NULL;
            }
            users[*count] = user;
            (*count)++;
        } else {
            free(user);
        }
    }

    fclose(file);
    return users;
}

void free_users(User** users, int count) {
    for (int i = 0; i < count; ++i) {
        free(users[i]);
    }
    free(users);
}
