using json = nlohmann::json;

void insertAfterToken(std::forward_list<std::string>& tokens, const std::string& targetToken, const std::string& insertToken) {
    auto it = tokens.begin();
    bool found = false;
    while (it != tokens.end()) {
        try {
            json j = json::parse(*it);
            if (j.contains("access_token") && j.contains("expires_in") && j.contains("token_type")) {
                if (j["token_type"] == "Bearer" && j["expires_in"].is_number_unsigned() && j["expires_in"].get<unsigned>() > 0) {
                    if (*it == targetToken) {
                        found = true;
                        break;
                    }
                } else {
                    return;
                }
            } else {
                return;
            }
        } catch (json::parse_error& e) {
            return;
        }
        ++it;
    }
    if (found) {
        tokens.insert_after(it, insertToken);
    } else {
        tokens.push_back(insertToken);
    }
}
