LTE_NAS_EMM_MESSAGE* initialize_emm_messages(int numMessages, int** errorCount) {
    LTE_NAS_EMM_MESSAGE* messages = (LTE_NAS_EMM_MESSAGE*)calloc(numMessages, sizeof(LTE_NAS_EMM_MESSAGE));
    if (!messages) {
        *errorCount = 1;
        return NULL;
    }

    uint8_t memPool[MEM_POOL_SIZE];
    int poolIndex = 0;

    for (int i = 0; i < numMessages; i++) {
        int retries = 0;
        uint8_t nas_pdu[256];
        size_t pduSize;

        while (retries < MAX_RETRIES) {
            // Simulate data retrieval from external APIs with retry logic
            if (!retrieve_nas_pdu_from_api(nas_pdu, &pduSize)) {
                retries++;
                usleep((1 << retries) * 1000); // Exponential backoff
            } else {
                break;
            }
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to retrieve NAS_PDU after %d retries\n", retries);
            (*errorCount)++;
            continue;
        }

        // Validate NAS_PDU against EMM protocol standards
        if (!validate_emm_pdu(nas_pdu, pduSize)) {
            fprintf(stderr, "NAS_PDU validation failed for message %d\n", i);
            (*errorCount)++;
            continue;
        }

        memcpy(messages[i].EPSmobilityContext, generate_eps_mobility_context(), 16);
        memcpy(messages[i].NAS_PDU, nas_pdu, pduSize);

        // Simulate memory reuse from a pool
        if (poolIndex + pduSize <= MEM_POOL_SIZE) {
            memcpy(&memPool[poolIndex], nas_pdu, pduSize);
            poolIndex += pduSize;
        }
    }

    *errorCount = numMessages - (*errorCount);
    return messages;
}

int retrieve_nas_pdu_from_api(uint8_t* nas_pdu, size_t* pdu_size) {
    // Simulated function to retrieve NAS_PDU from an API
