    static int api_failures = 0;
    if (api_failures < MAX_RETRIES / 2) {
        *pdu_size = rand() % 256 + 1;
        memset(nas_pdu, 0x41, *pdu_size); // A's for demonstration
        api_failures++;
        return 1;
    } else {
        return 0;
    }
}

int validate_emm_pdu(uint8_t* nas_pdu, size_t pdu_size) {
