int generate_unique_session_id(TCP_CONNECTION_INFO *connections, int count) {
    srand(time(NULL));
    unsigned long id;
    do {
        id = rand() % 1000000; // Generate a simple unique ID
    } while (count > 0 && find_connection_with_id(connections, count, id) != -1);
    return id;
}

int find_connection_with_id(TCP_CONNECTION_INFO *connections, int count, unsigned long id) {
    for (int i = 0; i < count; i++) {
        if (connections[i].session_id == id) {
            return i;
        }
    }
    return -1;
}

TCP_CONNECTION_INFO* initialize_connection_list(int *count) {
    TCP_CONNECTION_INFO *connections = malloc(MAX_CONNECTIONS * sizeof(TCP_CONNECTION_INFO));
    if (!connections) {
        fprintf(stderr, "Memory allocation failed\n");
        *count = 0;
        return NULL;
    }

    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    int i = 0;
    while (i < MAX_CONNECTIONS && ((clock_gettime(CLOCK_MONOTONIC, &end), (end.tv_sec - start.tv_sec) * 1000 + (end.tv_nsec - start.tv_nsec) / 1000000)) <= DEADLINE_PER_CONNECTION) {
        // Simulate network metadata retrieval
        snprintf(connections[i].ip_address, sizeof(connections[i].ip_address), "192.168.%d.%d", rand() % 256, rand() % 256);
        connections[i].port = rand() % 65535;

        // Generate unique session ID
        connections[i].session_id = generate_unique_session_id(connections, i);

        // Simulate validation (e.g., check if port is within valid range)
        if (connections[i].port < 1024 || connections[i].port > 65535) {
            fprintf(stderr, "Invalid port number: %d\n", connections[i].port);
            continue;
        }

        i++;
    }

    *count = i;
    return connections;
}

void free_connection_list(TCP_CONNECTION_INFO *connections, int count) {
    free(connections);
}
