using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
using System.Security.Cryptography;

public class DynamicRangeValueGenerator<T> where T : IComparable, IEquatable<T>
{
    private ConcurrentDictionary<string, object> cache = new ConcurrentDictionary<string, object>();
    private Random random = new Random();
    private string kmsUrl = "https://your-kms-url.com";
    private bool isKmsInitialized = false;
    private ILogger logger;

    public T Min { get; set; }
    public T Max { get; set; }

    public DynamicRangeValueGenerator(T min, T max)
    {
        SetRange(min, max);
        InitializeKMS();
    }

    private void InitializeKMS()
    {
        // Simulate KMS initialization
        isKmsInitialized = true;
        logger.Log("KMS initialized");
    }

    public void SetRange(T min, T max)
    {
        if (min.CompareTo(max) > 0)
            throw new ArgumentException("Min cannot be greater than Max");

        Min = min;
        Max = max;

        logger.Log($"Range set to [{Min}, {Max}]");
    }

    public T GenerateRandomValue()
    {
        if (!isKmsInitialized)
            throw new InvalidOperationException("KMS is not initialized");

        // Simulate getting a secure value from KMS
        byte[] secureBytes = GetSecureBytesFromKMS();
        T randomValue;

        if (typeof(T) == typeof(int))
        {
            int intMin = Convert.ToInt32(Min);
            int intMax = Convert.ToInt32(Max);
            int intValue = BitConverter.ToInt32(secureBytes, 0);
            intValue = (intValue % (intMax - intMin + 1)) + intMin;
            randomValue = (T)Convert.ChangeType(intValue, typeof(T));
        }
        else if (typeof(T) == typeof(float))
        {
            float floatMin = Convert.ToSingle(Min);
            float floatMax = Convert.ToSingle(Max);
            float floatValue = BitConverter.ToSingle(secureBytes, 0);
            floatValue = ((floatValue % (floatMax - floatMin)) + floatMin);
            randomValue = (T)Convert.ChangeType(floatValue, typeof(T));
        }
        else
        {
            throw new NotSupportedException("Unsupported type");
        }

        logger.Log($"Generated value: {randomValue}");
        return randomValue;
    }

    private byte[] GetSecureBytesFromKMS()
    {
        // Simulate a call to KMS for secure bytes
        if (!isKmsInitialized)
            throw new InvalidOperationException("KMS is not initialized");

        try
        {
            using (HttpClient client = new HttpClient())
            {
                HttpResponseMessage response = client.GetAsync(kmsUrl).Result;
                response.EnsureSuccessStatusCode();
                byte[] responseBody = response.Content.ReadAsByteArrayAsync().Result;

                // Simulate caching the secure bytes for future use
                cache.TryAdd("secureBytes", responseBody);

                return responseBody;
            }
        }
        catch (Exception ex)
        {
            logger.LogError(ex, "Failed to get secure bytes from KMS");
            throw new InvalidOperationException("Failed to get secure bytes from KMS", ex);
        }
    }

    public override string ToString()
    {
        return $"Range: [{Min}, {Max}]";
    }
}

public interface ILogger
{
    void Log(string message);
    void LogError(Exception exception, string message);
}

public class ConsoleLogger : ILogger
{
    public void Log(string message)
    {
        Console.WriteLine(message);
    }

    public void LogError(Exception exception, string message)
    {
        Console.Error.WriteLine($"{message}: {exception}");
    }
}
