public enum TaskStatus { Pending, InProgress, Completed }

[Serializable]
public class TaskMetadata
{
    public Dictionary<string, object> Data { get; set; }
}

public class TaskManager : ICloneable
{
    private List<TaskItem> tasks = new List<TaskItem>();

    public void AddTask(TaskItem task)
    {
        tasks.Add(task);
    }

    public void UpdateTask(int taskId, Action<TaskItem> updateAction)
    {
        var task = tasks.FirstOrDefault(t => t.Id == taskId);
        if (task != null)
        {
            updateAction(task);
        }
    }

    public void RemoveTask(int taskId)
    {
        tasks.RemoveAll(t => t.Id == taskId);
    }

    public List<TaskItem> GetTasksBetweenDates(DateTime startDate, DateTime endDate, Dictionary<string, object> metadataCriteria = null)
    {
        return tasks
            .Where(t => t.Deadline >= startDate && t.Deadline <= endDate)
            .Where(metadataCriteria != null ? t => metadataCriteria.All(kv => t.Metadata.Data.ContainsKey(kv.Key) && t.Metadata.Data[kv.Key].Equals(kv.Value)) : true)
            .ToList();
    }

    public string GenerateReport()
    {
        return JsonConvert.SerializeObject(tasks, Formatting.Indented);
    }

    object ICloneable.Clone()
    {
        return new TaskManager
        {
            tasks = tasks.Select(t => (TaskItem)t.Clone()).ToList()
        };
    }
}

[Serializable]
public class TaskItem : ICloneable
{
    public int Id { get; set; }
    public string Description { get; set; }
    public TaskPriority Priority { get; set; }
    public DateTime Deadline { get; set; }
    public TaskStatus Status { get; set; }
    public TaskMetadata Metadata { get; set; }

