import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;
import java.util.regex.Pattern;
import javax.json.JsonObject;
import javax.json.JsonReader;

public class HashProcessor {

    public static Map<String, String> processStrings(List<String> inputList, String configHashType, String verbosityLevel, String regexPattern) {
        Map<String, String> hashMap = new HashMap<>();
        Pattern pattern = Pattern.compile(regexPattern);

        for (String str : inputList) {
            if (!pattern.matcher(str).matches()) {
                continue;
            }

            String hashValue = computeHash(str, configHashType);
            logStep("Computed " + configHashType + " hash for: " + str, verbosityLevel);
            hashMap.put(str, hashValue);
        }

        return hashMap;
    }

    private static String computeHash(String input, String hashType) {
        try {
            MessageDigest digest = MessageDigest.getInstance(hashType);
            byte[] encodedhash = digest.digest(input.getBytes());
            StringBuilder hexString = new StringBuilder();

            for (byte b : encodedhash) {
                String hex = Integer.toHexString(0xff & b);
                if(hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }

            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Hash algorithm not supported", e);
        }
    }

    private static void logStep(String message, String verbosityLevel) {
        if ("DEBUG".equalsIgnoreCase(verbosityLevel)) {
            System.out.println(message);
        } else if ("INFO".equalsIgnoreCase(verbosityLevel)) {
            System.out.println(message);
        } // Add more conditions for different verbosity levels
    }

    public static boolean verifyOAuth2Token(String tokenResponseJson) {
        JsonObject json = Json.createReader(new StringReader(tokenResponseJson)).readObject();

        if (json.containsKey("access_token") && json.containsKey("expires_in") &&
            json.containsKey("token_type")) {

            int expiresIn = json.getInt("expires_in");
            if (expiresIn > 0 && "Bearer".equals(json.getString("token_type"))) {
                return true;
            }
        }

        return false;
    }
}
