void executeComplexShellCommandInGameContext() {
    static std::mutex mtx;
    static std::condition_variable cv;
    static std::queue<std::function<void()>> requestQueue;
    static std::atomic<bool> running(true);
    static std::chrono::time_point<std::chrono::system_clock> lastActionTime;

    // Thread function to process requests
    auto worker = [&]() {
        while (running) {
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock, []{ return !requestQueue.empty() || !running; });

            if (!running) break;

            auto request = std::move(requestQueue.front());
            requestQueue.pop();
            lock.unlock();

            request();
        }
    };

    // Start the worker thread
    std::thread workerThread(worker);

    // Function to add a request to the queue
    auto enqueueRequest = [&](const std::function<void()>& request) {
        std::unique_lock<std::mutex> lock(mtx);
        requestQueue.push(request);
        cv.notify_one();
    };

    // Request handling function
    auto handleRequest = [&]() {
        if (std::chrono::system_clock::now() - lastActionTime < std::chrono::seconds(9)) {
            return;
        }

        int actionType = rand() % 3; // Weighted random selection

        switch (actionType) {
            case 0: // Execute shell command
                {
                    auto commandOutput = getWeatherData();
                    std::cout << "Executing shell command. Output: " << commandOutput << std::endl;
                    lastActionTime = std::chrono::system_clock::now();
                }
                break;
            case 1: // Perform in-game action
                std::cout << "Performing in-game action." << std::endl;
                lastActionTime = std::chrono::system_clock::now();
                break;
            case 2: // Trigger custom game event
                std::cout << "Triggering custom game event." << std::endl;
                lastActionTime = std::chrono::system_clock::now();
                break;
        }
    };

    // Main loop to enqueue requests
    while (running) {
        handleRequest();
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
    }

    workerThread.join();
}

int main() {
    srand(static_cast<unsigned int>(time(nullptr)));
    executeComplexShellCommandInGameContext();
    return 0;
}
