import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.security.*;
import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import org.apache.commons.codec.digest.DigestUtils;
import com.paramiko.*;
import org.json.JSONObject;

public class SecureDeviceConfigurator {
    private static final String KEY_ALGORITHM = "RSA";
    private static final String CIPHER_ALGORITHM = "AES/CBC/PKCS5Padding";
    private static final int RSA_KEY_SIZE = 2048;
    private static final int AES_KEY_SIZE = 128;

    public Object deserialize(byte[] encryptedData, byte[] key) throws RuntimeException {
        try {
            SecretKeySpec secretKey = new SecretKeySpec(key, "AES");
            Cipher cipher = Cipher.getInstance(CIPHER_ALGORITHM);
            cipher.init(Cipher.DECRYPT_MODE, secretKey);
            byte[] decryptedData = cipher.doFinal(encryptedData);

            ByteArrayInputStream bis = new ByteArrayInputStream(decryptedData);
            ObjectInputStream ois = new ObjectInputStream(bis);
            return ois.readObject();
        } catch (Exception e) {
            throw new RuntimeException("Deserialization failed", e);
        }
    }

    public byte[] encrypt(byte[] data, byte[] key) throws Exception {
        SecretKeySpec secretKey = new SecretKeySpec(key, "AES");
        Cipher cipher = Cipher.getInstance(CIPHER_ALGORITHM);
        cipher.init(Cipher.ENCRYPT_MODE, secretKey);
        return cipher.doFinal(data);
    }

    public PublicKey generateRSAKeyPair() throws NoSuchAlgorithmException {
        KeyPairGenerator keyGen = KeyPairGenerator.getInstance(KEY_ALGORITHM);
        keyGen.initialize(RSA_KEY_SIZE);
        return keyGen.generateKeyPair().getPublic();
    }

    public PrivateKey generateRSAKeyPair() throws NoSuchAlgorithmException {
        KeyPairGenerator keyGen = KeyPairGenerator.getInstance(KEY_ALGORITHM);
        keyGen.initialize(RSA_KEY_SIZE);
        return keyGen.generateKeyPair().getPrivate();
    }

    public byte[] signData(byte[] data, PrivateKey privateKey) throws Exception {
        Signature signature = Signature.getInstance("SHA256withRSA");
        signature.initSign(privateKey);
        signature.update(data);
        return signature.sign();
    }

    public boolean verifySignature(byte[] data, byte[] signature, PublicKey publicKey) throws Exception {
        Signature sig = Signature.getInstance("SHA256withRSA");
        sig.initVerify(publicKey);
        sig.update(data);
        return sig.verify(signature);
    }

    public JSONObject configureNetworkDevice(DeviceConfig config, String key) throws Exception {
        JSch jsch = new JSch();
        Session session = jsch.getSession(config.getUsername(), config.getHostname(), config.getPort());
        session.setPassword(key);

        KeyPair keyPair = jsch.getKeyPair("id_rsa", config.getPrivateKeyPath(), config.getPassphrase());
        if (keyPair != null) {
            session.setIdentityKey(keyPair);
        }

        session.connect();
        Channel channel = session.openChannel("shell");
        channel.connect();

        // Execute commands and read output
        BufferedReader in = new BufferedReader(new InputStreamReader(channel.getInputStream()));
        StringBuilder output = new StringBuilder();
        String line;
        while ((line = in.readLine()) != null) {
            output.append(line).append("\n");
        }

        JSONObject status = new JSONObject();
        status.put("status", "success");
        status.put("output", output.toString());
        session.disconnect();

        return status;
    }
}

