#define AES_BLOCK_SIZE 16
#define MIN_ITERATIONS 10000

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char *key;
    unsigned int key_len;
    unsigned char *iv;
    unsigned int iv_len;
} AESCipher;

AESCipher* init_aescbc(const char *password, size_t password_len,
                       const unsigned char *salt, size_t salt_len,
                       const unsigned char *user_iv, size_t user_iv_len) {
    AESCipher *cipher = (AESCipher*)malloc(sizeof(AESCipher));
    if (!cipher) {
        fprintf(stderr, "Failed to allocate memory for cipher context.\n");
        return NULL;
    }

    // Adjust IV length
    if (user_iv_len < AES_BLOCK_SIZE || user_iv_len % AES_BLOCK_SIZE != 0) {
        fprintf(stderr, "Invalid IV size. Must be a multiple of the block size (%d).\n", AES_BLOCK_SIZE);
        free(cipher);
        return NULL;
    }
    cipher->iv_len = user_iv_len;

    // Derive key using PBKDF2 with SHA-256
    unsigned char *derived_key = (unsigned char*)malloc(32);
    if (!derived_key) {
        fprintf(stderr, "Failed to allocate memory for derived key.\n");
        free(cipher);
        return NULL;
    }
    int iter = MIN_ITERATIONS;
    while (iter < 100000 && !PKCS5_PBKDF2_HMAC(password, password_len, salt, salt_len, iter, EVP_sha256(), 32, derived_key)) {
        if (!RAND_bytes((unsigned char*)&iter, sizeof(iter))) {
            fprintf(stderr, "Failed to generate random number for PBKDF2.\n");
            free(derived_key);
            free(cipher);
            return NULL;
        }
    }
    cipher->key_len = 32;
    cipher->key = derived_key;

    // Initialize EVP_CIPHER_CTX
    if (!(cipher->ctx = EVP_CIPHER_CTX_new())) {
        fprintf(stderr, "Failed to create EVP_CIPHER_CTX.\n");
        free(derived_key);
        free(cipher);
        return NULL;
    }

    if (1 != EVP_EncryptInit_ex(cipher->ctx, EVP_aes_256_cbc(), NULL, derived_key, user_iv)) {
        fprintf(stderr, "Failed to initialize AES-256-CBC cipher.\n");
        EVP_CIPHER_CTX_free(cipher->ctx);
        free(derived_key);
        free(cipher);
        return NULL;
    }

    return cipher;
}

void cleanup_cipher(AESCipher *cipher) {
    if (cipher) {
        EVP_CIPHER_CTX_free(cipher->ctx);
        free(cipher->key);
        free(cipher);
    }
}

// Additional functions for key material regeneration, custom KDF implementation,
// and periodic key regeneration can be added here.
