#include <libuv.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int port;
    const char *cert_file;
    const char *key_file;
    int keep_alive_timeout;
} ServerConfig;

void log_message(uv_handle_t *handle, const char *format, ...) {
    va_list args;
    char buffer[1024];
    va_start(args, format);
    vsnprintf(buffer, sizeof(buffer), format, args);
    va_end(args);

    // Log the message to an error log
    fprintf(stderr, "%s\n", buffer);
}

void on_connection(uv_stream_t *server, int status) {
    if (status < 0) {
        log_message(server, "New connection failed: %s", uv_strerror(status));
        return;
    }

    // Handle the new connection
}

void initialize_and_run_server(const ServerConfig *config) {
    uv_loop_t *loop = uv_default_loop();
    uv_tcp_t server[config->num_ports];

    for (int i = 0; i < config->num_ports; ++i) {
        uv_tcp_init(loop, &server[i]);
        struct sockaddr_in addr;
        uv_ip4_addr("0.0.0.0", config->port + i, &addr);
        int rc = uv_tcp_bind(&server[i], (const struct sockaddr *)&addr, 0);
        if (rc != 0) {
            log_message(NULL, "Bind failed: %s", uv_strerror(rc));
            continue;
        }

        rc = uv_listen((uv_stream_t *)&server[i], config->max_connections, on_connection);
        if (rc != 0) {
            log_message(NULL, "Listen failed: %s", uv_strerror(rc));
            continue;
        }
    }

    uv_run(loop, UV_RUN_DEFAULT);

    // Cleanup
    for (int i = 0; i < config->num_ports; ++i) {
        uv_close((uv_handle_t *)&server[i], NULL);
    }
}
