#include <iostream>
#include <memory>

class PersistentStorage {
public:
    int* indexTable;
    char* dataBuffer;
    size_t capacity;
    bool useCompression;
    bool useEncryption;

    PersistentStorage(size_t cap, bool comp, bool enc)
        : capacity(cap), useCompression(comp), useEncryption(enc) {
        indexTable = new (std::nothrow) int[capacity];
        dataBuffer = new (std::nothrow) char[capacity];

        if (!indexTable || !dataBuffer) {
            delete[] indexTable;
            delete[] dataBuffer;
            throw std::bad_alloc();
        }
    }

    ~PersistentStorage() {
        delete[] indexTable;
        delete[] dataBuffer;
    }
};

extern "C" void* configurePersistentStoreWithCapacity(size_t capacity, bool useCompression, bool useEncryption, int optionalFlag = 0) {
    try {
        static int callCount = 0;
        ++callCount;

        if (capacity == 0 || !useCompression && !useEncryption) {
            std::cerr << "Invalid input parameters." << std::endl;
            return nullptr;
        }

        PersistentStorage* storage = new PersistentStorage(capacity, useCompression, useEncryption);

        // Log call count for analysis
        std::cout << "configurePersistentStoreWithCapacity called " << callCount << " times." << std::endl;

        return storage;
    } catch (const std::bad_alloc& e) {
        std::cerr << "Memory allocation failed: " << e.what() << std::endl;
        return nullptr;
    }
}
```

