using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.Json;

public class ConfigSettingsRepository
{
    private Dictionary<string, (string Value, DateTime LastUpdated)> _settings;
    private Dictionary<string, DateTime> _cache;
    private Action<string, string, string> _logAction;
    private TimeSpan _cacheEvictionPolicy;

    public ConfigSettingsRepository(TimeSpan cacheEvictionPolicy)
    {
        _settings = new Dictionary<string, (string Value, DateTime LastUpdated)>();
        _cache = new Dictionary<string, DateTime>();
        _logAction = (_, _, _) => { };
        _cacheEvictionPolicy = cacheEvictionPolicy;
    }

    public void SetLogAction(Action<string, string, string> logAction)
    {
        _logAction = logAction;
    }

    public void AddOrUpdateSetting(string key, string value)
    {
        _settings[key] = (value, DateTime.Now);
        CacheSetting(key, DateTime.Now);
        LogChange("Update", key, value);
    }

    public string GetSetting(string key)
    {
        if (_cache.TryGetValue(key, out var cacheEntry) && DateTime.Now - cacheEntry <= _cacheEvictionPolicy)
        {
            return _settings[key].Value;
        }
        else
        {
            CacheSetting(key, DateTime.Now);
            return _settings[key].Value;
        }
    }

    public void DeleteSetting(string key)
    {
        if (_settings.ContainsKey(key))
        {
            _settings.Remove(key);
            _cache.Remove(key);
            LogChange("Delete", key, null);
        }
    }

    public void BatchUpdateSettings(Dictionary<string, string> updates)
    {
        foreach (var update in updates)
        {
            AddOrUpdateSetting(update.Key, update.Value);
        }
    }

    public string ExportSettings()
    {
        try
        {
            return JsonSerializer.Serialize(_settings.Select(kv => new { Key = kv.Key, Value = kv.Value.Item1 }));
        }
        catch (JsonException ex)
        {
            LogChange("ExportError", ex.Message, null);
            return null;
        }
    }

    private void CacheSetting(string key, DateTime timestamp)
    {
        _cache[key] = timestamp;
    }

    private void LogChange(string action, string key, string value)
    {
        _logAction(action, key, value);
    }

    public override string ToString()
    {
        return JsonSerializer.Serialize(_settings.Select(kv => new { Key = kv.Key, Value = kv.Value.Item1 }));
    }
}
