#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct record {
    int key;
    long offset;
    struct record *next;
} Record;

typedef struct dynamic_collection {
    Record **records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicCollection;

DynamicCollection* create_dynamic_collection(size_t initial_capacity) {
    DynamicCollection *collection = (DynamicCollection*)malloc(sizeof(DynamicCollection));
    collection->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void destroy_dynamic_collection(DynamicCollection *collection) {
    for (size_t i = 0; i < collection->size; ++i) {
        Record *current = collection->records[i];
        while (current != NULL) {
            Record *temp = current;
            current = current->next;
            free(temp);
        }
    }
    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int add_record(DynamicCollection *collection, int key, long offset) {
    if (collection->size >= collection->capacity) {
        // Resize the array
        Record **new_records = (Record**)realloc(collection->records, collection->capacity * 2 * sizeof(Record*));
        if (new_records == NULL) return -1; // Memory allocation failed
        collection->records = new_records;
        collection->capacity *= 2;
    }

    Record *new_record = (Record*)malloc(sizeof(Record));
    if (new_record == NULL) return -1; // Memory allocation failed

    new_record->key = key;
    new_record->offset = offset;
    new_record->next = NULL;

    collection->records[collection->size++] = new_record;
    return 0;
}

// Serialize and deserialize functions would be implemented here
// Considering memory usage, cache locality, and concurrent access

int main() {
    srand(time(NULL));
    DynamicCollection *collection = create_dynamic_collection(10);

    for (int i = 0; i < 20; ++i) {
        int key;
        do {
            key = rand() % 1000;
        } while (find_record(collection, key) != NULL);
        add_record(collection, key, i * 8);
    }

    destroy_dynamic_collection(collection);
    return 0;
}
