    pthread_mutex_init(&ds->lock, NULL);
    for (int i = 0; i < MAX_RECORDS; ++i) {
        ds->records[i].key = -1;
        ds->records[i].node = NULL;
    }
}

int insert_record(DataStructure* ds, int key) {
    pthread_mutex_lock(&ds->lock);
    for (int i = 0; i < MAX_RECORDS; ++i) {
        if (ds->records[i].key == -1) {
            ds->records[i].key = key;
            ds->records[i].node = NULL; // Initialize node pointer to NULL
            pthread_mutex_unlock(&ds->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&ds->lock);
    return -1;
}

int lookup_record(DataStructure* ds, int key) {
    pthread_mutex_lock(&ds->lock);
    for (int i = 0; i < MAX_RECORDS; ++i) {
        if (ds->records[i].key == key) {
            pthread_mutex_unlock(&ds->lock);
            return i;
        }
    }
    pthread_mutex_unlock(&ds->lock);
    return -1;
}

void delete_record(DataStructure* ds, int key) {
    pthread_mutex_lock(&ds->lock);
    for (int i = 0; i < MAX_RECORDS; ++i) {
        if (ds->records[i].key == key) {
            ds->records[i].key = -1;
            ds->records[i].node = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&ds->lock);
}

void serialize_data_structure(DataStructure* ds, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) return;

    for (int i = 0; i < MAX_RECORDS; ++i) {
        fwrite(&ds->records[i], sizeof(Record), 1, file);
    }

    fclose(file);
}

void deserialize_data_structure(DataStructure* ds, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) return;

    for (int i = 0; i < MAX_RECORDS; ++i) {
        fread(&ds->records[i], sizeof(Record), 1, file);
    }

    fclose(file);
}

void monitor_access(DataStructure* ds) {
    // Implement monitoring and logging logic here
}

// Example usage:
int main() {
    DataStructure ds;
    init_data_structure(&ds);

    insert_record(&ds, 42);
    int index = lookup_record(&ds, 42);
    if (index != -1) {
        printf("Record found at index: %d\n", index);
    }

    delete_record(&ds, 42);

    serialize_data_structure(&ds, "data.bin");
    deserialize_data_structure(&ds, "data.bin");

    monitor_access(&ds);

    return 0;
}
