#define MAX_PDU_SIZE 512

typedef struct {
    LTE_NAS_EMM_MESSAGE message;
    time_t last_updated;
    pthread_mutex_t lock;
} NAS_MESSAGE;

NAS_MESSAGE* init_nas_messages(int num_messages) {
    NAS_MESSAGE *messages = (NAS_MESSAGE*) malloc(num_messages * sizeof(NAS_MESSAGE));
    if (!messages) return NULL;

    for (int i = 0; i < num_messages; ++i) {
        pthread_mutex_init(&messages[i].lock, NULL);
    }

    srand(time(NULL));
    for (int i = 0; i < num_messages; ++i) {
        messages[i].message.nas_pdu_size = rand() % MAX_PDU_SIZE + 1;
        messages[i].message.nas_pdu = (char*) malloc(messages[i].message.nas_pdu_size);
        if (!messages[i].message.nas_pdu) {
            for (int j = 0; j < i; ++j) {
                free(messages[j].message.nas_pdu);
                pthread_mutex_destroy(&messages[j].lock);
            }
            free(messages);
            return NULL;
        }
        // Populate NAS_PDU content with a unique value
        snprintf(messages[i].message.nas_pdu, messages[i].message.nas_pdu_size, "PDU_%d", i);
    }

    return messages;
}

void destroy_nas_messages(NAS_MESSAGE *messages, int num_messages) {
    for (int i = 0; i < num_messages; ++i) {
        free(messages[i].message.nas_pdu);
        pthread_mutex_destroy(&messages[i].lock);
    }
    free(messages);
}
