require 'vendor/autoload.php';

use League\OAuth2\Client\Provider\GenericProvider;

function authenticate_user($client_id, $client_secret, $redirect_uri) {
    $provider = new GenericProvider([
        'clientId'                => $client_id,
        'clientSecret'            => $client_secret,
        'redirectUri'             => $redirect_uri,
        'urlAuthorize'          => 'https://example.com/oauth/authorize',
        'urlAccessToken'          => 'https://example.com/oauth/access_token',
        'urlResourceOwnerDetails' => 'https://example.com/api/userinfo'
    ]);

    if (!isset($_GET['code'])) {
        // Direct user to authorization URL
        $authUrl = $provider->getAuthorizationUrl();
        $_SESSION['oauth2state'] = $provider->getState();
        header('Location: ' . $authUrl);
        exit;
    }

    // Check given state against previously stored one to mitigate CSRF attack
    if (empty($_GET['state']) || ($_GET['state'] !== $_SESSION['oauth2state'])) {
        unset($_SESSION['oauth2state']);
        exit('Invalid state');
    } else {
        unset($_SESSION['oauth2state']);
    }

    try {
        $token = $provider->getAccessToken('authorization_code', [
            'code' => $_GET['code']
        ]);

        // Store access token in session
        $_SESSION['access_token'] = (string) $token;

        // Get user information using access token
        $user_info = $provider->getResourceOwner($token);
        return $user_info;
    } catch (\League\OAuth2\Client\Exception\IdentityProviderException $e) {
        echo 'Error: ' . $e->getMessage();
        exit;
    }
}
