    u_char ip[16];
    time_t last_accessed;
} DNSCacheEntry;

DNSCacheEntry dns_cache[CACHE_SIZE];

int is_whitelisted(const char *domain) {
    // Check if the domain is in the whitelist
    // Implement logic to check against a dynamic list of allowed domains
    return 1; // Placeholder
}

int resolve_hostname(const char *hostname, u_char *ip, size_t ip_size) {
    int err = 0;

    if (!is_whitelisted(hostname)) {
        fprintf(stderr, "Hostname not whitelisted\n");
        return -1;
    }

    for (int i = 0; i < CACHE_SIZE; i++) {
        if (strcmp(dns_cache[i].domain, hostname) == 0 && time(NULL) - dns_cache[i].last_accessed < 3600) {
            memcpy(ip, dns_cache[i].ip, ip_size);
            return 0;
        }
    }

    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allows both IPv4 and IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "DNS resolution failed: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        if (p->ai_family == AF_INET6 && ip_size >= sizeof(struct in6_addr)) {
            memcpy(ip, &((struct sockaddr_in6 *)p->ai_addr)->sin6_addr, sizeof(struct in6_addr));
            err = 0;
            break;
        } else if (p->ai_family == AF_INET && ip_size >= sizeof(struct in_addr)) {
            memcpy(ip, &((struct sockaddr_in *)p->ai_addr)->sin_addr, sizeof(struct in_addr));
            err = 0;
            break;
        }
    }

    freeaddrinfo(res);

    if (!err) {
        for (int i = 0; i < CACHE_SIZE; i++) {
            if (dns_cache[i].last_accessed == 0) {
                strcpy(dns_cache[i].domain, hostname);
                memcpy(dns_cache[i].ip, ip, sizeof(u_char));
                dns_cache[i].last_accessed = time(NULL);
                break;
            }
        }
    }

    return err;
}

int main() {
    u_char ip[16];
    if (resolve_hostname("example.com", ip, sizeof(ip)) == 0) {
        printf("IP: %s\n", inet_ntop(AF_INET6, ip, NULL, 0));
    } else {
        printf("Failed to resolve hostname\n");
    }
    return 0;
}
