#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ENTRIES 10000
#define MAX_CONCURRENT_UPDATES 100

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU;

typedef struct Entry {
    NFAPI_CRC_INDICATION_PDU pdu;
    struct Entry* next;
} Entry;

typedef struct {
    Entry** entries;
    pthread_mutex_t lock;
    int count;
    int crc_count;
} NFAPICRCList;

NFAPICRCList* createNFAPICRCList() {
    NFAPICRCList* list = (NFAPICRCList*)malloc(sizeof(NFAPICRCList));
    list->entries = (Entry**)calloc(MAX_ENTRIES, sizeof(Entry*));
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    list->crc_count = 0;
    return list;
}

void addOrUpdateNFAPICRC(NFAPICRCList* list, NFAPI_CRC_INDICATION_PDU pdu) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < MAX_ENTRIES; i++) {
        if (list->entries[i] != NULL && list->entries[i]->pdu.RNTI == pdu.RNTI) {
            // Update existing entry
            list->entries[i]->pdu = pdu;
            pthread_mutex_unlock(&list->lock);
            return;
        }
    }

    // Add new entry
    Entry* newEntry = (Entry*)malloc(sizeof(Entry));
    newEntry->pdu = pdu;
    newEntry->next = NULL;

    int index = list->count % MAX_ENTRIES;
    if (list->entries[index] != NULL) {
        newEntry->next = list->entries[index];
    }
    list->entries[index] = newEntry;
    list->count++;
    if (pdu.CRC_INDICATION_REL8_TAG) {
        list->crc_count++;
    }
    pthread_mutex_unlock(&list->lock);
}

void removeNFAPICRC(NFAPICRCList* list, int RNTI) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < MAX_ENTRIES; i++) {
        if (list->entries[i] != NULL && list->entries[i]->pdu.RNTI == RNTI) {
            Entry* temp = list->entries[i];
            if (temp->next != NULL) {
                list->entries[i] = temp->next;
            } else {
                list->entries[i] = NULL;
            }
            free(temp);
            list->count--;
            if (list->entries[i] != NULL && list->entries[i]->pdu.CRC_INDICATION_REL8_TAG) {
                list->crc_count--;
            }
            pthread_mutex_unlock(&list->lock);
            return;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

int getEntryCount(NFAPICRCList* list) {
    pthread_mutex_lock(&list->lock);
    int count = list->count;
    pthread_mutex_unlock(&list->lock);
    return count;
}

int getCRCCount(NFAPICRCList* list) {
    pthread_mutex_lock(&list->lock);
    int crc_count = list->crc_count;
    pthread_mutex_unlock(&list->lock);
    return crc_count;
}

void destroyNFAPICRCList(NFAPICRCList* list) {
    for (int i = 0; i < MAX_ENTRIES; i++) {
        Entry* current = list->entries[i];
        while (current != NULL) {
            Entry* next = current->next;
            free(current);
            current = next;
        }
    }
    pthread_mutex_destroy(&list->lock);
    free(list->entries);
    free(list);
}
