#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ENTRIES 10000
#define CONCURRENT_UPDATES 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    bool CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} DynamicList;

void initDynamicList(DynamicList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void addEntry(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T newEntry) {
    pthread_mutex_lock(&list->lock);
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    newNode->data = newEntry;
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
}

bool updateEntry(DynamicList* list, unsigned short RNTI, NFAPI_CRC_INDICATION_PDU_T updatedEntry) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            current->data = updatedEntry;
            pthread_mutex_unlock(&list->lock);
            return true;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return false;
}

void removeEntry(DynamicList* list, unsigned short RNTI) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* prev = NULL;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            pthread_mutex_unlock(&list->lock);
            return;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

int getTotalEntries(DynamicList* list) {
    int count = 0;
    Node* current = list->head;
    while (current != NULL) {
        count++;
        current = current->next;
    }
    return count;
}

int getEntriesWithCRCFlag(DynamicList* list) {
    int count = 0;
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.CRC_INDICATION_REL8_TAG) {
            count++;
        }
        current = current->next;
    }
    return count;
}

void destroyDynamicList(DynamicList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Example usage
int main() {
    DynamicList myList;
    initDynamicList(&myList);

    NFAPI_CRC_INDICATION_PDU_T entry1 = {1, 100, true};
    addEntry(&myList, entry1);

    NFAPI_CRC_INDICATION_PDU_T updatedEntry = {2, 100, false};
    updateEntry(&myList, 100, updatedEntry);

    removeEntry(&myList, 100);

    printf("Total entries: %d\n", getTotalEntries(&myList));
    printf("Entries with CRC flag set: %d\n", getEntriesWithCRCFlag(&myList));

    destroyDynamicList(&myList);
    return 0;
}
```

This code provides a basic implementation of a dynamic list using linked nodes, protected by a mutex for thread safety. It includes functions to add, update, remove, and retrieve statistics about entries in the list. The use of a mutex ensures that operations on the list are performed atomically, preventing concurrent modifications from causing data inconsistencies.']

