    struct tm *tm_info = localtime(&now);

    pthread_mutex_lock(&log_mutex);

    if (log_count >= MAX_LOG_SIZE / sizeof(LogEntry)) {
        // Handle buffer overflow
    }

    snprintf(log_buffer[log_count].message, sizeof(log_buffer[log_count].message), "%s [%s] ", format, level == INFO ? "INFO" : level == DEBUG ? "DEBUG" : level == WARNING ? "WARNING" : "ERROR");
    vsnprintf(log_buffer[log_count].message + 14, sizeof(log_buffer[log_count].message) - 14, format, args);
    log_buffer[log_count].level = level;
    log_count++;

    pthread_mutex_unlock(&log_mutex);

    va_end(args);
}

