#include <iostream>
#include <string>
#include <mutex>
#include <unordered_map>
#include <memory>

// Configuration Interface
class IConfiguration {
public:
    virtual ~IConfiguration() = default;
    virtual std::string getSetting(const std::string& key) const = 0;
    virtual void setSetting(const std::string& key, const std::string& value) = 0;
};

// In-Memory Configuration Implementation
class MemoryConfig : public IConfiguration {
public:
    std::string getSetting(const std::string& key) const override {
        std::lock_guard<std::mutex> lock(mutex_);
        return config_.get(key, "");
    }

    void setSetting(const std::string& key, const std::string& value) override {
        std::lock_guard<std::mutex> lock(mutex_);
        config_[key] = value;
    }

private:
    mutable std::mutex mutex_;
    std::unordered_map<std::string, std::string> config_;
};

// Configuration Loader Interface
class IConfigurationLoader {
public:
    virtual ~IConfigurationLoader() = default;
    virtual IConfiguration* loadConfigurations() const = 0;
};

// File-Based Configuration Loader
class FileConfigLoader : public IConfigurationLoader {
public:
    IConfiguration* loadConfigurations() const override {
        // Load configurations from a file and return an instance of MemoryConfig
        return new MemoryConfig();
    }
};

// Environment Variable Configuration Loader
class EnvVarConfigLoader : public IConfigurationLoader {
public:
    IConfiguration* loadConfigurations() const override {
        // Load configurations from environment variables and return an instance of MemoryConfig
        return new MemoryConfig();
    }
};

// Command-Line Argument Configuration Loader
class CmdLineConfigLoader : public IConfigurationLoader {
public:
    IConfiguration* loadConfigurations() const override {
        // Load configurations from command-line arguments and return an instance of MemoryConfig
        return new MemoryConfig();
    }
};

// Config Manager with Support for Multiple Sources
class ConfigManager {
public:
    ConfigManager(std::vector<std::unique_ptr<IConfigurationLoader>> loaders)
        : loaders_(std::move(loaders)) {}

    void loadConfigurations() const {
        for (const auto& loader : loaders_) {
            IConfiguration* config = loader->loadConfigurations();
            mergeConfig(config);
            delete config;
        }
    }

    std::string getSetting(const std::string& key) const {
        std::lock_guard<std::mutex> lock(mutex_);
        return config_.get(key, "");
    }

    void setSetting(const std::string& key, const std::string& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        config_[key] = value;
    }

private:
    mutable std::mutex mutex_;
    IConfiguration* config_ = new MemoryConfig();

    void mergeConfig(IConfiguration* sourceConfig) {
        for (const auto& pair : sourceConfig->config_) {
            config_->setSetting(pair.first, pair.second);
        }
    }
};

// Example Usage
int main() {
    ConfigManager manager({
        std::make_unique<FileConfigLoader>(),
        std::make_unique<EnvVarConfigLoader>(),
        std::make_unique<CmdLineConfigLoader>()
    });

    manager.loadConfigurations();

    std::cout << "Setting 'example': " << manager.getSetting("example") << std::endl;

    return 0;
}
