using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;
using System.Xml.XPath;

public class XmlParserService
{
    private readonly HttpClient _httpClient;

    public XmlParserService(HttpClient httpClient)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
    }

    public async Task<List<XElement>> ParseXmlAndFindElementsAsync(string xmlUrl, string xpathPattern, int maxRetries = 3, int backoffMilliseconds = 500)
    {
        if (string.IsNullOrEmpty(xmlUrl))
            return new List<XElement>();

        for (int attempt = 1; attempt <= maxRetries; attempt++)
        {
            try
            {
                var xmlContent = await FetchXmlAsync(xmlUrl);
                var document = XPathDocument.Parse(xmlContent);

                using (var navigator = document.CreateNavigator())
                {
                    var nodes = navigator.Select(xpathPattern);
                    return nodes.Cast<XNode>().Select(n => n as XElement).ToList();
                }
            }
            catch (Exception ex) when (attempt < maxRetries)
            {
                // Log the exception for debugging purposes
                Console.WriteLine($"Attempt {attempt} failed. Retrying in {backoffMilliseconds}ms.");
                await Task.Delay(backoffMilliseconds);
            }
        }

        throw new Exception("Failed to fetch or parse XML after multiple retries.");
    }

    private async Task<string> FetchXmlAsync(string url)
    {
        using (var response = await _httpClient.GetAsync(url, HttpCompletionOption.ResponseHeadersRead))
        {
            response.EnsureSuccessStatusCode();
            return await response.Content.ReadAsStringAsync();
        }
    }
}
