// Include necessary libraries
require_once 'RateLimiter.php';
require_once 'AuthenticationService.php';
require_once 'UserManager.php';
require_once 'CacheManager.php';

function manageUserAccount($_REQUEST) {
    $rateLimiter = new RateLimiter();
    $authenticationService = new AuthenticationService(API_KEY);
    $userManager = new UserManager();
    $cacheManager = new CacheManager();

    $ip = $_SERVER['REMOTE_ADDR'];

    if (!$rateLimiter->allowRequest($ip, RATE_LIMIT_IP, RATE_LIMIT_TIMEFRAME)) {
        http_response_code(429); // Too Many Requests
        echo json_encode(['error' => 'Too many requests. Please try again later.']);
        return;
    }

    $id = isset($_REQUEST['id']) ? $_REQUEST['id'] : null;
    $name = isset($_REQUEST['name']) ? $_REQUEST['name'] : null;
    $email = isset($_REQUEST['email']) ? $_REQUEST['email'] : null;
    $password = isset($_REQUEST['password']) ? $_REQUEST['password'] : null;
    $sub_action = isset($_REQUEST['sub_action']) ? $_REQUEST['sub_action'] : null;

    try {
        switch ($sub_action) {
            case 'create':
                if (!$authenticationService->verifyUser($email)) {
                    echo json_encode(['error' => 'Invalid user']);
                    return;
                }

                if (!$userManager->isEmailUnique($email)) {
                    echo json_encode(['error' => 'Email already exists']);
                    return;
                }

                $newUser = [
                    'name' => $name,
                    'email' => $email,
                    'password' => password_hash($password, PASSWORD_DEFAULT)
                ];

                $userId = $userManager->createUser($newUser);
                echo json_encode(['message' => 'User created successfully', 'id' => $userId]);
                break;

            case 'update':
                if (!$authenticationService->verifyUser($email)) {
                    echo json_encode(['error' => 'Invalid user']);
                    return;
                }

                $updatedUser = [
                    'name' => $name,
                    'password' => password_hash($password, PASSWORD_DEFAULT)
                ];

                $result = $userManager->updateUser($id, $updatedUser);
                if ($result) {
                    echo json_encode(['message' => 'User updated successfully']);
                } else {
                    echo json_encode(['error' => 'Failed to update user']);
                }
                break;

            case 'delete':
                if (!$authenticationService->verifyUser($email)) {
                    echo json_encode(['error' => 'Invalid user']);
                    return;
                }

                $confirmationToken = generateConfirmationToken();
                sendDeletionEmail($email, $confirmationToken);

                // Store token for confirmation
                $cacheManager->storeToken($id, $confirmationToken, CACHE_EXPIRY);
                echo json_encode(['message' => 'Deletion request sent. Please check your email for confirmation']);
                break;

            case 'retrieve':
                $user = $userManager->getUserById($id);
                if ($user) {
                    echo json_encode(['user' => $user]);
                } else {
                    echo json_encode(['error' => 'User not found']);
                }
                break;

            default:
                echo json_encode(['error' => 'Invalid sub_action']);
        }
    } catch (Exception $e) {
        error_log($e->getMessage());
        http_response_code(500);
        echo json_encode(['error' => 'Internal server error']);
    }
}

