    public LTE_NAS_EMM_MESSAGE[] initializeMessages(int count) {
        LTE_NAS_EMM_MESSAGE[] messages = new LTE_NAS_EMM_MESSAGE[count];
        Random random = new Random();
        for (int i = 0; i < count; i++) {
            EPS_Mobility epsMobilityContext = new EPS_Mobility();
            byte[] nasPduContent = generateRandomNasPdu(random);
            messages[i] = new LTE_NAS_EMM_MESSAGE(epsMobilityContext, nasPduContent);
        }
        return messages;
    }

    private byte[] generateRandomNasPdu(Random random) {
        // Generate a random NAS PDU content
        int length = random.nextInt(1024) + 1; // Random length between 1 and 1024 bytes
        return new byte[length];
    }

    public Object loadStateObject() throws IOException, ClassNotFoundException {
        String filePath = System.getenv("STATE_OBJECT_PATH");
        if (filePath == null || filePath.isEmpty()) {
            throw new IllegalArgumentException("Environment variable STATE_OBJECT_PATH is not set.");
        }
        CachedObject cachedObject = cache.get(filePath);
        if (cachedObject != null && !isExpired(cachedObject)) {
            return cachedObject.object;
        }
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath))) {
            Object obj = ois.readObject();
            if (obj instanceof MoSTState) {
                CachedObject newCachedObject = new CachedObject(obj);
                cache.put(filePath, newCachedObject);
                pruneCache();
                return obj;
            }
        }
        return null;
    }

    private boolean isExpired(CachedObject cachedObject) {
        long currentTime = System.currentTimeMillis();
        return (currentTime - cachedObject.timestamp) > CACHE_EXPIRY_TIME;
    }

    private void pruneCache() {
        if (cache.size() > MAX_CACHE_SIZE) {
            cache.values().stream()
                    .sorted(Comparator.comparingLong(c -> c.timestamp))
                    .limit(cache.size() - MAX_CACHE_SIZE)
                    .forEach(cache::remove);
        }
    }

    private static class CachedObject {
        Object object;
