// Import necessary modules
const fs = require('fs').promises;
const path = require('path');
const { pipeline } = require('stream/promises');
const { Readable } = require('stream');

// Define the function to read and process files
async function processFiles(directory, pattern = '', options = {}) {
  const { maxConcurrentReads = 100, timeout = 5000, maxSizeLimit = 10 * 1024 * 1024 } = options;
  let fileQueue = [];
  let currentReaders = 0;

  // Create a stream to process files
  const directoryStream = Readable.from(fs.opendir(directory));

  // Function to start reading the next file
  async function readNextFile() {
    if (currentReaders >= maxConcurrentReads) return;
    try {
      const entry = await directoryStream.read();
      if (!entry) return;
      const filePath = path.join(directory, entry.name);
      if ((pattern && entry.name.includes(pattern)) || !pattern) {
        currentReaders++;
        processFile(filePath).finally(() => {
          currentReaders--;
          readNextFile();
        });
      }
    } catch (error) {
      console.error('Error reading file:', error);
      readNextFile();
    }
  }

  // Function to process a single file
  async function processFile(filePath) {
    try {
      const fileStats = await fs.stat(filePath);
      if (fileStats.size > maxSizeLimit) return;
      const data = await fs.readFile(filePath, { encoding: 'utf8' });
      let result;
      if (path.extname(filePath).toLowerCase() === '.json') {
        result = JSON.parse(data);
      } else if (path.extname(filePath).toLowerCase() === '.csv') {
        result = parseCSV(data);
      } else {
        result = data; // Handle plain text
      }
      fileQueue.push(result);
    } catch (error) {
      console.error('Error processing file:', error);
    }
  }

  // Start reading files
  for (let i = 0; i < maxConcurrentReads; i++) {
    readNextFile();
  }

  // Return the aggregated result
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (currentReaders === 0) {
        resolve(fileQueue);
      } else {
        const interval = setInterval(() => {
          if (currentReaders === 0) {
            clearInterval(interval);
            resolve(fileQueue);
          }
        }, 100);
      }
    }, timeout).unref();
  });
}

// Example usage
const directoryPath = '/path/to/directory';
const pattern = 'data';
processFiles(directoryPath, pattern, { maxConcurrentReads: 50, maxSizeLimit: 5 * 1024 * 1024 })
  .then((result) => {
    console.log('Processed files:', result);
  })
  .catch((error) => {
    console.error('Error processing files:', error);
  });
```

