async function manageTests(modulePath, options = {}) {
  const { concurrencyLimit = Infinity, retryAttempts = 3, timeout = 5000 } = options;
  let retriesLeft = retryAttempts;

  while (retriesLeft > 0) {
    try {
      const module = await import(modulePath);
      if (!module.default || !Array.isArray(module.default.tests)) {
        throw new Error('Module does not contain a default object with tests array');
      }

      for (const test of module.default.tests) {
        console.log(`Testing ${test.name} in ${modulePath}`);
        const result = await Promise.race([
          new Promise((resolve, reject) => {
            setTimeout(() => reject(new Error('Test timed out')), timeout);
          }),
          test.fn(blueslip)
        ]);

        if (result) {
          console.log(`${test.name} passed`);
        } else {
          throw new Error(`${test.name} failed`);
        }
      }

      break; // All tests passed, exit the retry loop
    } catch (error) {
      retriesLeft--;
      if (retriesLeft > 0) {
        const backoff = Math.pow(2, retryAttempts - retriesLeft);
        console.log(`Test failed. Retrying in ${backoff}ms...`);
        await new Promise(resolve => setTimeout(resolve, backoff));
      } else {
        throw error;
      }
    }
  }

  blueslip.reset(); // Reset mocking library after all tests
}

// Example usage:
manageTests('./path/to/module', { concurrencyLimit: 2, timeout: 7000 });
