function processOldTestamentReferences(text) {
    // Regular expression to match whole word occurrences of Old Testament books, ignoring case and punctuation
    const oldTestamentBooksRegex = /\b(?:Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Ruth|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiah|Jeremiah|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)\b/gi;

    // Create a set of Old Testament book names for efficient lookups
    const oldTestamentBooks = new Set([
        "Genesis", "Exodus", "Leviticus", "Numbers", "Deuteronomy", "Ruth",
        "Ezra", "Nehemiah", "Esther", "Job", "Psalms", "Proverbs", "Ecclesiastes",
        "Song of Solomon", "Isaiah", "Jeremiah", "Ezekiel", "Daniel", "Hosea",
        "Joel", "Amos", "Obadiah", "Jonah", "Micah", "Nahum", "Habakkuk",
        "Zephaniah", "Haggai", "Zechariah", "Malachi"
    ]);

    // Create a map to store the frequency of each book reference
    const bookFrequency = new Map();

    // Match all Old Testament book references in the text using regular expression
    let match;
    while ((match = oldTestamentBooksRegex.exec(text)) !== null) {
        // Get the matched book name and convert it to lowercase for case-insensitive comparison
        const bookName = match[0].toLowerCase();

        // If the book is an Old Testament book, increment its frequency in the map
        if (oldTestamentBooks.has(bookName)) {
            bookFrequency.set(bookName, (bookFrequency.get(bookName) || 0) + 1);
        }
    }

    return bookFrequency;
}
