function generateSidebar(config) {
    const createMenuItem = (item, level = 0) => {
        if (!item.children || item.children.length === 0) {
            return `
                <li class="sidebar-item" data-id="${item.id}">
                    <a href="${item.route}" tabindex="0">
                        <i class="${item.icon}"></i> ${item.label}
                    </a>
                </li>
            `;
        } else {
            const childrenHtml = item.children.map(child => createMenuItem(child, level + 1)).join('');
            return `
                <li class="sidebar-item sidebar-dropdown" data-id="${item.id}">
                    <div tabindex="0">
                        <i class="${item.icon}"></i> ${item.label}
                        <i class="dropdown-icon fa fa-angle-down"></i>
                    </div>
                    <ul class="dropdown-menu">
                        ${childrenHtml}
                    </ul>
                </li>
            `;
        }
    };

    const sidebarHtml = `
        <nav role="navigation" aria-label="Site Navigation" class="sidebar">
            <ul class="sidebar-list">
                ${config.map(item => createMenuItem(item)).join('')}
            </ul>
        </nav>
    `;

    return sidebarHtml;
}

// Example usage:
