["```javascript
class ModuleLoader {
    constructor(basePath) {
        this.basePath = basePath;
        this.modules = {};
        this.queue = [];
        this.loading = false;
        this.errorHandler = (error, modulePath) => console.error(`Failed to load module ${modulePath}:`, error);
        this.performanceMetrics = [];
    }

    addModule(moduleName, dependencies = [], callback) {
        this.modules[moduleName] = { dependencies, callback };
        if (!this.loading) {
            this.loadNext();
        }
    }

    async loadNext() {
        if (this.loading || !Object.keys(this.modules).length) return;

        this.loading = true;
        const moduleName = Object.keys(this.modules)[0];
        const module = this.modules[moduleName];

        try {
            for (const dep of module.dependencies) {
                await this.loadModule(dep);
            }

            const script = document.createElement('script');
            script.src = `${this.basePath}/${moduleName}.js`;
            script.onload = () => {
                delete this.modules[moduleName];
                if (module.callback) module.callback();
                this.loading = false;
                this.loadNext();
            };
            script.onerror = (error) => {
                this.errorHandler(error, moduleName);
                delete this.modules[moduleName];
                this.loading = false;
                this.loadNext();
            };

            document.head.appendChild(script);
        } catch (error) {
            this.errorHandler(error, moduleName);
            delete this.modules[moduleName];
            this.loading = false;
            this.loadNext();
        }
    }

    loadModule(moduleName) {
        return new Promise((resolve, reject) => {
            if (this.modules[moduleName].dependencies.length === 0) {
                resolve();
            } else {
                for (const dep of this.modules[moduleName].dependencies) {
                    if (!this.modules[dep]) {
                        reject(new Error(`Dependency ${dep} not found`));
                        return;
                    }
                }
                resolve();
            }
        });
    }

    setErrorHandler(handler) {
        this.errorHandler = handler;
    }

    addPerformanceMetric(metric) {
        this.performanceMetrics.push(metric);
    }
}

// Usage
const loader = new ModuleLoader('path/to/modules');
loader.addModule('moduleA', [], () => console.log('moduleA loaded'));
loader.addModule('moduleB', ['moduleA'], () => console.log('moduleB loaded'));
