public class TransactionClusteringService {

    private Clusterer<DoublePoint> clusterer;
    private long lastClusterTime;

    public TransactionClusteringService(Clusterer<DoublePoint> clusterer) {
        this.clusterer = clusterer;
    }

    public List<org.apache.commons.math3.stat.clustering.Cluster<DoublePoint>> clusterTransactions(List<Transaction> transactions) {
        List<DoublePoint> points = new ArrayList<>();
        for (Transaction transaction : transactions) {
            Optional<DoublePoint> point = enrichAndValidateTransaction(transaction);
            if (point.isPresent()) {
                points.add(point.get());
            }
        }

        lastClusterTime = System.currentTimeMillis();
        return clusterer.cluster(points);
    }

    private Optional<DoublePoint> enrichAndValidateTransaction(Transaction transaction) {
        // Validate and enrich the transaction data
        if (!isValidTransaction(transaction)) {
            return Optional.empty();
        }

        // Enrich the transaction with additional data if necessary

        return Optional.of(new DoublePoint(transaction.getLatitude(), transaction.getLongitude()));
    }

    private boolean isValidTransaction(Transaction transaction) {
        // Implement validation logic for transactions
        return transaction != null && transaction.getLatitude() != null && transaction.getLongitude() != null;
    }

    public long getLastClusterTime() {
        return lastClusterTime;
    }

    public void setClusterer(Clusterer<DoublePoint> clusterer) {
        this.clusterer = clusterer;
    }

