['```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.*;
import java.util.*;
import java.util.concurrent.*;

public class ConnectionPool {

    private final Map<String, Channel> channelMap = new ConcurrentHashMap<>();
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private final int maxConnections;
    private final int minConnections;
    private final long connectTimeout;
    private final long idleTimeout;

    public ConnectionPool(int maxConnections, int minConnections, long connectTimeout, long idleTimeout) {
        this.maxConnections = maxConnections;
        this.minConnections = minConnections;
        this.connectTimeout = connectTimeout;
        this.idleTimeout = idleTimeout;
        initConnectionPool();
    }

    private void initConnectionPool() {
        // Initialize minimum connections
        for (int i = 0; i < minConnections; i++) {
            createNewChannel("tcp", new InetSocketAddress("example.com", 80));
        }
        scheduleIdleCheck();
    }

    public Channel getChannel(String protocol, InetSocketAddress address) {
        String key = protocol + ":" + address.toString();
        return channelMap.computeIfAbsent(key, k -> createNewChannel(protocol, address));
    }

    private Channel createNewChannel(String protocol, InetSocketAddress address) {
        try {
            if ("tcp".equalsIgnoreCase(protocol)) {
                SocketChannel channel = SocketChannel.open();
                channel.connect(address);
                channel.configureBlocking(false);
                return channel;
            } else if ("udp".equalsIgnoreCase(protocol)) {
                DatagramChannel channel = DatagramChannel.open();
                channel.bind(null);
                return channel;
            }
        } catch (IOException e) {
            handleConnectionFailure(e);
        }
        return null;
    }

    private void scheduleIdleCheck() {
        scheduler.scheduleAtFixedRate(() -> {
            long currentTime = System.currentTimeMillis();
            List<String> keysToRemove = new ArrayList<>();
            for (Map.Entry<String, Channel> entry : channelMap.entrySet()) {
                if ((currentTime - getLastUsed(entry.getValue())) > idleTimeout && !entry.getValue().isOpen()) {
                    keysToRemove.add(entry.getKey());
                }
            }
            for (String key : keysToRemove) {
                closeChannel(channelMap.remove(key));
            }
        }, 0, idleTimeout, TimeUnit.MILLISECONDS);
    }

    private long getLastUsed(Channel channel) {
        // Implement logic to get last used timestamp
        return System.currentTimeMillis();
    }

    private void closeChannel(Channel channel) {
        try {
            channel.close();
        } catch (IOException e) {
            // Handle exception
        }
    }

    private void handleConnectionFailure(Throwable e) {
        // Implement retry logic with exponential backoff
        scheduler.schedule(() -> initConnectionPool(), connectTimeout, TimeUnit.MILLISECONDS);
    }

    public void shutdown() {
        scheduler.shutdown();
        for (Channel channel : channelMap.values()) {
            closeChannel(channel);
        }
    }
}
