                // Update existing profile
                userProfiles[userId] = profileData;
            } else {
                // Insert new profile
                userProfiles.insert({userId, profileData});
            }
        }

        bool isDefaultProfileInitialized() const {
            return defaultProfileInitialized;
        }

        void initializeDefaultProfile(const std::string& templateData) {
            if (!isDefaultProfileInitialized()) {
                userProfiles["default"] = templateData;
                defaultProfileInitialized = true;
            }
        }

