            // Simulate downloading image from cloud and saving locally
            std::ofstream file("local_cache/" + userId + ".jpg", std::ios::binary);
            // Assume cloudUrl provides the image data for simplicity
            file.write(cloudUrl.data(), cloudUrl.size());
        }

        int generateRandomNumber() {
            return distribution(generator);
        }

