spl_autoload_register(function ($class) {
    $prefixes = [
        'NamespaceA\\' => __DIR__ . '/vendor/namespacea/src/',
        'NamespaceB\\' => __DIR__ . '/vendor/namespaceb/src/'
    ];

    foreach ($prefixes as $namespace => $base_dir) {
        $len = strlen($namespace);
        if (strncmp($class, $namespace, $len) === 0) {
            $relative_class = substr($class, $len);
            require $base_dir . str_replace('\\', '/', $relative_class) . '.php';
            return;
        }
    }
});

// Configure the services using a hierarchical configuration system
$config = include __DIR__ . '/config/config.php';

// Handle dynamic service discovery and fallback mechanisms efficiently
$serviceDiscovery = new ServiceDiscovery();
$service = $serviceDiscovery->get('my-service', $config);

if ($service === null) {
    $service = $serviceDiscovery->fallback('my-service');
}

// Implement a caching layer to reduce database load during service discovery
$cachingLayer = new CachingLayer($config['cache']);
$cachedService = $cachingLayer->get('my-service');

if ($cachedService !== null) {
    $service = $cachedService;
} else {
    $service = $serviceDiscovery->fetch('my-service');
    $cachingLayer->set('my-service', $service);
}

// Support hot-reloading of configuration files on file changes
