fn measure_compilation_time_and_rss() -> i32 {
    let start_time = Instant::now();
    let before_rss = get_resident_set_size();

    // Install ice hook using SyncLazy
    static ICE_HOOK: SyncLazy<IceHook> = SyncLazy::new(|| IceHook::new());

    // Catch errors during compilation and report them
    catch_with_exit_code(|| {
        if let Err(e) = rustc_driver::main() {
            early_error(ice::ErrorGuaranteed {}, e);
        }
    });

    let end_time = Instant::now();
    let after_rss = get_resident_set_size();

    let execution_time = end_time.duration_since(start_time).as_secs_f64();
    let rss_increase = (after_rss - before_rss) as f64 / 1024.0; // Convert bytes to MB

    // Log warnings and attempt to free memory if RSS exceeds threshold
    const RSS_THRESHOLD_MB: f64 = 512.0;
    if rss_increase > RSS_THRESHOLD_MB {
        log::warn!("RSS increase exceeded threshold: {:.2} MB", rss_increase);
        for _ in 0..3 {
            // Drop unnecessary references and reduce large data structures
            drop_large_data_structures();
            let new_after_rss = get_resident_set_size();
            if (new_after_rss - before_rss) as f64 / 1024.0 < RSS_THRESHOLD_MB {
                break;
            }
        }
    }

    // Integrate with external logging service asynchronously
    log_to_external_service(execution_time, rss_increase);

    // Handle signal interruptions gracefully
    handle_signal_interruption();

    // Return exit code of subprocess
    rustc_driver::exit_code()
}

