    let mut signal = Signal::new(&[SignalKind::interrupt(), SignalKind::terminate()]);
    while signal.recv().await.is_some() {
        log::info!("Received SIGINT or SIGTERM");
        // Clean up resources and flush logs
        break;
    }
}
