    public void updateUserStatus(int userId, String newStatus, String lastModifiedIP, Date lastModifiedDate) {
        Connection conn = null;
        PreparedStatement updateStmt = null;
        PreparedStatement auditStmt = null;
        try {
            conn = getConnection(); // Assume this method establishes a database connection
            conn.setAutoCommit(false); // Start transaction

            String md5Hash = hashMD5(lastModifiedIP);
            if (md5Hash == null) throw new Exception("Failed to hash IP address");

            updateStmt = conn.prepareStatement(
                "UPDATE users SET status = ?, last_modified_ip = ?, last_modified_date = ? WHERE id = ?");
            updateStmt.setString(1, newStatus);
            updateStmt.setString(2, md5Hash);
            updateStmt.setTimestamp(3, new java.sql.Timestamp(lastModifiedDate.getTime()));
            updateStmt.setInt(4, userId);

            int rowsUpdated = updateStmt.executeUpdate();
            if (rowsUpdated == 0) {
                throw new Exception("No rows were updated for user ID: " + userId);
            }

            auditStmt = conn.prepareStatement(
                "INSERT INTO audit_log (user_id, action, ip_hash, timestamp) VALUES (?, ?, ?, ?)");
            auditStmt.setInt(1, userId);
            auditStmt.setString(2, "STATUS_UPDATE");
            auditStmt.setString(3, md5Hash);
            auditStmt.setTimestamp(4, new java.sql.Timestamp(lastModifiedDate.getTime()));

            auditStmt.executeUpdate();

            conn.commit(); // Commit transaction
            sendNotificationEmail(userId, newStatus); // Assume this method sends an email

        } catch (SQLException | NoSuchAlgorithmException e) {
            try {
                if (conn != null) conn.rollback(); // Rollback on exception
            } catch (SQLException ex) {
                ex.printStackTrace();
            }
            e.printStackTrace();
        } finally {
            closeResources(conn, updateStmt, auditStmt); // Assume this method closes resources
        }
    }

    private String hashMD5(String input) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] messageDigest = md.digest(input.getBytes());
        StringBuilder hexString = new StringBuilder();
        for (byte b : messageDigest) {
            String hex = Integer.toHexString(0xff & b);
            if(hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

