#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ENTRIES 1000
#define RNTI_RANGE 65536

typedef struct {
    int rx_ue_information_tag;
    int rnti;
    bool crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node** hash_table;
    size_t table_size;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* create_dynamic_list(size_t initial_size) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->hash_table = (Node**)calloc(initial_size, sizeof(Node*));
    if (!list->hash_table) {
        free(list);
        return NULL;
    }

    list->table_size = initial_size;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_dynamic_list(DynamicList* list) {
    if (!list) return;

    for (size_t i = 0; i < list->table_size; ++i) {
        Node* node = list->hash_table[i];
        while (node) {
            Node* next = node->next;
            free(node);
            node = next;
        }
    }

    free(list->hash_table);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

size_t hash_function(int rnti, size_t table_size) {
    return rnti % table_size;
}

bool add_entry(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    if (!list || !entry.rnti) return false;

    pthread_mutex_lock(&list->lock);

    size_t index = hash_function(entry.rnti, list->table_size);
    Node* node = list->hash_table[index];

    while (node) {
        if (node->data.rnti == entry.rnti) {
            pthread_mutex_unlock(&list->lock);
            return false; // Duplicate RNTI not allowed
        }
        node = node->next;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    new_node->data = entry;
    new_node->next = list->hash_table[index];
    list->hash_table[index] = new_node;

    pthread_mutex_unlock(&list->lock);
    return true;
}

bool update_entry(DynamicList* list, int rnti, NFAPI_CRC_INDICATION_PDU_T new_data) {
    if (!list || !rnti) return false;

    pthread_mutex_lock(&list->lock);

    size_t index = hash_function(rnti, list->table_size);
    Node* node = list->hash_table[index];

    while (node) {
        if (node->data.rnti == rnti) {
            node->data = new_data;
            pthread_mutex_unlock(&list->lock);
            return true;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&list->lock);
    return false; // Entry not found
}

bool remove_entry(DynamicList* list, int rnti) {
    if (!list || !rnti) return false;

    pthread_mutex_lock(&list->lock);

    size_t index = hash_function(rnti, list->table_size);
    Node** prev_node = &list->hash_table[index];
    Node* node = *prev_node;

    while (node) {
        if (node->data.rnti == rnti) {
            *prev_node = node->next;
            free(node);
            pthread_mutex_unlock(&list->lock);
            return true;
        }
        prev_node = &node->next;
        node = *prev_node;
    }

    pthread_mutex_unlock(&list->lock);
    return false; // Entry not found
}

size_t get_total_entries(DynamicList* list) {
    if (!list) return 0;

    size_t count = 0;
    for (size_t i = 0; i < list->table_size; ++i) {
        Node* node = list->hash_table[i];
        while (node) {
            ++count;
            node = node->next;
        }
    }

    return count;
}

size_t get_entries_with_crc_flag(DynamicList* list) {
    if (!list) return 0;

    size_t count = 0;
    for (size_t i = 0; i < list->table_size; ++i) {
        Node* node = list->hash_table[i];
        while (node) {
            if (node->data.crc_indication_rel8_tag) {
                ++count;
            }
            node = node->next;
        }
    }

    return count;
}

