<?php

class UserAccountManager {
    private $config;
    private $cache;

    public function __construct($config, $cache) {
        $this->config = $config;
        $this->cache = $cache;
    }

    public function generateSecureString($length = 32, $charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789') {
        return substr(str_shuffle(str_repeat($charset, ceil($length / strlen($charset)))), 1, $length);
    }

    public function createUserAccount($username, $password) {
        // Hash password
        $hashedPassword = password_hash($password, PASSWORD_DEFAULT);

        // Store user data in database or cache
        $userId = $this->cache->set("user:{$username}", [
            'username' => $username,
            'password' => $hashedPassword,
            'session_token' => null,
            'profile' => []
        ]);

        return $userId;
    }

    public function updateProfile($userId, $updates) {
        // Update user profile in database or cache
        if ($this->cache->exists("user:{$userId}")) {
            $userData = $this->cache->get("user:{$userId}");
            $userData['profile'] = array_merge($userData['profile'], $updates);
            $this->cache->set("user:{$userId}", $userData);
        }
    }

    public function generateSessionToken($userId) {
        // Generate a secure session token
        $sessionToken = $this->generateSecureString();

        // Store the session token in database or cache with expiration time
        $expirationTime = time() + $this->config['session_ttl'];
        $this->cache->set("user:{$userId}:token", $sessionToken, ['ttl' => $expirationTime]);

        return $sessionToken;
    }

    public function validateSessionToken($userId, $sessionToken) {
        // Validate the session token
        if ($this->cache->exists("user:{$userId}:token")) {
            $storedToken = $this->cache->get("user:{$userId}:token");
            return $storedToken === $sessionToken;
        }

        return false;
    }

    public function logoutUser($userId) {
        // Logout user by invalidating the session token
        if ($this->cache->exists("user:{$userId}:token")) {
            $this->cache->delete("user:{$userId}:token");
        }
    }
}

// Usage example
$config = [
    'session_ttl' => 3600, // 1 hour
];

$cache = new Memcached();
$cache->addServer('127.0.0.1', 11211);

$userManager = new UserAccountManager($config, $cache);
$userId = $userManager->createUserAccount('john_doe', 'password123');
$userManager->updateProfile($userId, ['email' => 'john@example.com']);
$sessionToken = $userManager->generateSessionToken($userId);
$isValidToken = $userManager->validateSessionToken($userId, $sessionToken);
$userManager->logoutUser($userId);

?>
