import java.net.HttpURLConnection;
import java.net.URL;
import java.io.OutputStream;
import org.json.JSONObject;

public class PaymentProcessor {

    public static String processTransaction(String paymentData) {
        try {
            URL url = new URL("https://api.thirdpartygateway.com/transaction");
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();
            conn.setRequestMethod("POST");
            conn.setRequestProperty("Content-Type", "application/json; utf-8");
            conn.setRequestProperty("Authorization", "Bearer YOUR_API_KEY");
            conn.setDoOutput(true);

            try(OutputStream os = conn.getOutputStream()) {
                byte[] input = paymentData.getBytes("utf-8");
                os.write(input, 0, input.length);           
            }

            int responseCode = conn.getResponseCode();
            if (responseCode == HttpURLConnection.HTTP_OK) {
                // Read the response and return it
                return "Transaction successful";
            } else {
                return "Transaction failed with HTTP error code: " + responseCode;
            }
        } catch (Exception e) {
            return "Transaction failed due to an exception: " + e.getMessage();
        }
    }

    public static void main(String[] args) {
        String paymentData = "{\"amount\":100, \"currency\":\"USD\", \"cardNumber\":\"4111111111111111\"}";
        String result = processTransaction(paymentData);
        System.out.println(result);
    }
}
