#include <stdlib.h>

typedef struct {
    int *states;
    int num_states;
    // Other metadata and transition tables
} FSA;

int* manage_state_list(int **state_list, int current_index, FSA *fsa, int last_state) {
    if (state_list == NULL || fsa == NULL) {
        return NULL; // Handle null pointers gracefully
    }

    if (current_index < 0 || current_index >= fsa->num_states) {
        return NULL; // Handle invalid indices
    }

    int new_state = fsa->states[current_index];
    if (new_state == -1) { // Assuming -1 represents an invalid or terminal state
        return *state_list;
    }

    int *new_state_list = realloc(*state_list, (last_state + 2) * sizeof(int));
    if (new_state_list == NULL) {
        return NULL; // Handle memory allocation failure
    }

    new_state_list[last_state] = new_state;
    new_state_list[last_state + 1] = -1; // Sentinel value to indicate end of list

    *state_list = new_state_list;
    if (last_state > 0) {
        (*state_list)[last_state - 1] = current_index; // Update the previous state's next pointer
    }

    return *state_list;
}
