#include <atomic>
#include <mutex>

class Graph {
private:
    struct Node {
        std::unordered_set<int> edges;
        std::mutex edge_mutex;
    };

    std::vector<Node> nodes;
    std::mutex graph_mutex;

public:
    Graph(int num_nodes) : nodes(num_nodes) {}

    void add_node() {
        std::lock_guard<std::mutex> lock(graph_mutex);
        nodes.push_back(Node());
    }

    void remove_node(int node_id) {
        std::lock_guard<std::mutex> lock(graph_mutex);
        if (node_id < 0 || node_id >= nodes.size()) return;

        for (auto& node : nodes) {
            node.edges.erase(node_id);
        }
        nodes.erase(nodes.begin() + node_id);
    }

    void add_edge(int from, int to) {
        std::lock_guard<std::mutex> lock(graph_mutex);
        if (from < 0 || from >= nodes.size() || to < 0 || to >= nodes.size()) return;

        std::lock_guard<std::mutex> from_lock(nodes[from].edge_mutex);
        std::lock_guard<std::mutex> to_lock(nodes[to].edge_mutex);

        nodes[from].edges.insert(to);
    }

    void remove_edge(int from, int to) {
        std::lock_guard<std::mutex> lock(graph_mutex);
        if (from < 0 || from >= nodes.size() || to < 0 || to >= nodes.size()) return;

        std::lock_guard<std::mutex> from_lock(nodes[from].edge_mutex);
        std::lock_guard<std::mutex> to_lock(nodes[to].edge_mutex);

        nodes[from].edges.erase(to);
    }

    bool edge_exists(int from, int to) {
        if (from < 0 || from >= nodes.size() || to < 0 || to >= nodes.size()) return false;

        std::lock_guard<std::mutex> lock(graph_mutex);
        std::lock_guard<std::mutex> from_lock(nodes[from].edge_mutex);

        return nodes[from].edges.find(to) != nodes[from].edges.end();
    }
};
