    Event events[MAX_EVENTS];
    int count;
    time_t window_start;
    int *id_counts;
    int total_events;
    int window_event_count;
    float avg_priority;
} EventManager;

void init_manager(EventManager *manager) {
    manager->count = 0;
    manager->window_start = time(NULL);
    manager->id_counts = (int *)calloc(100, sizeof(int)); // Assuming max 100 unique IDs
    manager->total_events = 0;
    manager->window_event_count = 0;
    manager->avg_priority = 0.0;
}

int validate_id(EventManager *manager, int id) {
    return (id >= 0 && id < 100); // Simplified whitelist
}

int is_overloaded(EventManager *manager, int priority) {
    time_t now = time(NULL);
    if (difftime(now, manager->window_start) > 60) {
        // Reset counts for the new minute
        for (int i = 0; i < manager->id_counts[0]; i++) {
            manager->id_counts[i] = 0;
        }
        manager->window_start = now;
    }
    return manager->id_counts[id] >= priority;
}

float calculate_relevance(EventManager *manager, Event event) {
    float frequency_score = 1.0 / (manager->id_counts[event.id] + 1);
    float diversity_score = strnlen(event.metadata, sizeof(event.metadata)) / sizeof(event.metadata);
    return frequency_score * diversity_score * event.priority;
}

void update_manager(EventManager *manager, Event event) {
    time_t now = time(NULL);
    if (difftime(now, manager->window_start) > 300) {
        // Reset counts for the new window
        manager->count = 0;
        manager->window_event_count = 0;
        manager->avg_priority = 0.0;
    }

    if (validate_id(manager, event.id)) {
        manager->events[manager->count++] = event;
        manager->id_counts[event.id]++;

        manager->total_events++;
        manager->window_event_count++;
        manager->avg_priority = ((manager->total_events - 1) * manager->avg_priority + event.priority) / manager->total_events;

        if (!is_overloaded(manager, event.priority)) {
            // Update internal metrics
            // ...
        }
    }
}

Event* get_highest_relevance_event(EventManager *manager) {
    float highest_score = -1.0;
    Event *highest_event = NULL;
    for (int i = 0; i < manager->count; i++) {
        float score = calculate_relevance(manager, manager->events[i]);
        if (score > highest_score) {
            highest_score = score;
            highest_event = &manager->events[i];
        }
    }
    return highest_event;
}
