// Import necessary libraries
const async = require('async');

// Define the asynchronous reduction function
function modularAsyncReduce(initialAccumulator, reducerCallback, options = {}) {
  const {
    concurrencyLimit = 1,
    timeoutThreshold = Infinity,
    errorHandler = (err) => { throw err; },
    transformArray = (arr) => arr,
    transformAccumulator = (acc) => acc,
    logPerformance = () => {}
  } = options;

  let accumulatedValue = initialAccumulator;
  const workerPool = async.pool(concurrencyLimit, async (element, callback) => {
    try {
      let transformedElement = element;
      if (typeof transformArray === 'function') {
        transformedElement = transformArray(element);
      }

      let result = await reducerCallback(accumulatedValue, transformedElement);
      accumulatedValue = result;

      logPerformance();
      callback(null, result);
    } catch (err) {
      errorHandler(err);
      callback(err);
    }
  }, (err, results) => {
    if (err) return;
    let finalAccumulatedValue = accumulatedValue;
    if (typeof transformAccumulator === 'function') {
      finalAccumulatedValue = transformAccumulator(accumulatedValue);
    }
    console.log('Final Accumulated Value:', finalAccumulatedValue);
  });

  const array = transformArray(transformArray([])); // Transform the array
  async.eachLimit(array, concurrencyLimit, (element, callback) => {
    workerPool.push(element, callback);
  });
}

// Example usage and test suite
const reducerCallback = async (acc, element) => {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      resolve(acc + element);
    }, Math.random() * 100); // Simulate asynchronous operation with random delay
  });
};

modularAsyncReduce(0, reducerCallback, {
  concurrencyLimit: 5,
  timeoutThreshold: 1000,
  errorHandler: (err) => { console.error('Error:', err); },
  transformArray: (arr) => arr.map(x => x * 2), // Transform elements
  transformAccumulator: (acc) => acc / 10, // Transform accumulator
  logPerformance: () => {
    console.log('Current Accumulated Value:', accumulatedValue);
  }
});
