#include <stdio.h>
#include <stdlib.h>
#include <dirent.h>
#include <string.h>

#define MAX_RESOURCE_TYPES 3
#define CACHE_SIZE 10

typedef enum {
    TEXT,
    BINARY,
    METADATA
} ResourceType;

typedef struct {
    char* filename;
    ResourceType type;
    void* data;
    size_t size;
} Resource;

typedef struct {
    Resource** items;
    int count;
} ResourceBundle;

ResourceBundle* loadResourceBundle(const char* directory, char* cache[CACHE_SIZE], int* cacheSize) {
    ResourceBundle* bundle = (ResourceBundle*)malloc(sizeof(ResourceBundle));
    if (!bundle) {
        perror("Failed to allocate memory for resource bundle");
        return NULL;
    }
    bundle->items = NULL;
    bundle->count = 0;

    DIR* dir = opendir(directory);
    if (!dir) {
        perror("Failed to open directory");
        free(bundle);
        return NULL;
    }

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        char path[1024];
        snprintf(path, sizeof(path), "%s/%s", directory, entry->d_name);

        FILE* file = fopen(path, "rb");
        if (!file) {
            perror("Failed to open file");
            continue;
        }

        ResourceType type;
        if (strstr(entry->d_name, ".txt")) type = TEXT;
        else if (strstr(entry->d_name, ".bin")) type = BINARY;
        else if (strstr(entry->d_name, ".meta")) type = METADATA;
        else {
            fprintf(stderr, "Unsupported file format: %s\n", entry->d_name);
            fclose(file);
            continue;
        }

        fseek(file, 0, SEEK_END);
        size_t size = ftell(file);
        fseek(file, 0, SEEK_SET);

        void* data = malloc(size);
        if (!data) {
            perror("Failed to allocate memory for resource data");
            fclose(file);
            continue;
        }

        fread(data, 1, size, file);
        fclose(file);

        Resource* resource = (Resource*)malloc(sizeof(Resource));
        if (!resource) {
            perror("Failed to allocate memory for resource");
            free(data);
            continue;
        }
        resource->filename = strdup(entry->d_name);
        resource->type = type;
        resource->data = data;
        resource->size = size;

        bundle->count++;
        bundle->items = realloc(bundle->items, bundle->count * sizeof(Resource*));
        if (!bundle->items) {
            perror("Failed to reallocate memory for resource items");
            free(resource->filename);
            free(resource->data);
            free(resource);
            continue;
        }
        bundle->items[bundle->count - 1] = resource;

        // Check cache and add to it if necessary
        if (*cacheSize < CACHE_SIZE) {
            cache[*cacheSize++] = strdup(entry->d_name);
        }
    }

    closedir(dir);
    return bundle;
}

int main() {
    char* directory = "resources";
    char* cache[CACHE_SIZE] = {0};
    int cacheSize = 0;

    ResourceBundle* bundle = loadResourceBundle(directory, cache, &cacheSize);
    if (bundle) {
        printf("Total items in resource bundle: %d\n", bundle->count);

        // Free resources
        for (int i = 0; i < bundle->count; i++) {
            free(bundle->items[i]->filename);
            free(bundle->items[i]->data);
            free(bundle->items[i]);
        }
        free(bundle->items);
        free(bundle);
    }

    // Free cache
    for (int i = 0; i < cacheSize; i++) {
        free(cache[i]);
    }

    return 0;
}
