#include <time.h>

#define MAX_CONCURRENT_PROCESSES 10

typedef struct {
    int EPS_context;
    char NAS_PDU[1024];
} LTE_NAS_EMM_MESSAGE;

void handle_signal(int signum) {
    // Handle signal gracefully
}

int execute_command(char* command, char** envp, FILE* stdout_file, FILE* stderr_file, int pipefd[2]) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return -1;
    } else if (pid == 0) {
        // Child process
        dup2(pipefd[1], STDOUT_FILENO);
        dup2(pipefd[1], STDERR_FILENO);
        close(pipefd[0]);
        close(pipefd[1]);

        execve("/bin/sh", (char* const[]){"sh", "-c", command, NULL}, envp);
        perror("execve");
        exit(EXIT_FAILURE);
    } else {
        // Parent process
        close(pipefd[1]);
        return pid;
    }
}

int main() {
    LTE_NAS_EMM_MESSAGE messages[] = {
        {1, "EMM message 1"},
        {2, "EMM message 2"},
        {3, "EMM message 3"}
    };

    int num_messages = sizeof(messages) / sizeof(messages[0]);
    pid_t child_pids[MAX_CONCURRENT_PROCESSES] = {0};
    FILE* stdout_files[MAX_CONCURRENT_PROCESSES];
    FILE* stderr_files[MAX_CONCURRENT_PROCESSES];
    int pipefds[MAX_CONCURRENT_PROCESSES][2];

    // Initialize signal handler
    signal(SIGCHLD, handle_signal);

    for (int i = 0; i < num_messages; i++) {
        if (i < MAX_CONCURRENT_PROCESSES) {
            char command[1024];
            sprintf(command, "process_message %d %s", messages[i].EPS_context, messages[i].NAS_PDU);
            pipe(pipefds[i]);

            child_pids[i] = execute_command(command, environ, stdout_files[i], stderr_files[i], pipefds[i]);
        } else {
            // Wait for a slot in the concurrent processes array
            int j;
            for (j = 0; j < MAX_CONCURRENT_PROCESSES; j++) {
                if (child_pids[j] != 0) {
                    waitpid(child_pids[j], NULL, 0);
                    child_pids[j] = 0;
                }
            }

            // Retry if slot is found
            i--;
        }
    }

    // Wait for all child processes to complete
    for (int i = 0; i < MAX_CONCURRENT_PROCESSES; i++) {
        if (child_pids[i] != 0) {
            waitpid(child_pids[i], NULL, 0);
        }
    }

    return 0;
}
