// Thread-safe function to execute complex shell command in game context
void* executeComplexShellCommandInGameContext(void* arg) {
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);
    pthread_mutex_lock(&mutex);

    // Check if the cooldown period has passed
    time_t currentTime = time(nullptr);
    static time_t lastExecutionTime = 0;
    if (currentTime - lastExecutionTime < COOLDOWN_PERIOD) {
        pthread_mutex_unlock(&mutex);
        return nullptr;
    }
    lastExecutionTime = currentTime;

    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&mutex);

    // Weighted random selection for action
    int randomNumber = rand() % 100;
    if (randomNumber < 30) {
        checkAndProcessDirectory();
    } else if (randomNumber < 75) {
        applyInGameAction();
    } else {
        triggerCustomEvent();
    }

    // Release the mutex
    pthread_mutex_unlock(&mutex);

    // Log the executed action and its outcome
    std::ofstream logFile("execution_log.txt", std::ios::app);
    if (logFile.is_open()) {
        logFile << "Action executed at: " << currentTime << std::endl;
        // Add details about the executed action here
        logFile.close();
    }

    return nullptr;
}

// Main function to demonstrate the use of the thread-safe function
int main() {
    pthread_t thread1, thread2;

    // Create threads to execute the shell command in game context concurrently
    pthread_create(&thread1, NULL, executeComplexShellCommandInGameContext, NULL);
    pthread_create(&thread2, NULL, executeComplexShellCommandInGameContext, NULL);

    // Wait for both threads to complete
    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    return 0;
}
