['```java
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class StreamingDataAggregator {
    private final ConcurrentHashMap<String, SensorData> sensorDataMap = new ConcurrentHashMap<>();
    private AtomicInteger configVersion = new AtomicInteger(0);

    public void processSensorReading(String sensorId, double reading) {
        sensorDataMap.computeIfAbsent(sensorId, k -> new SensorData()).add(reading);
    }

    public synchronized void updateConfiguration(int newVersion) {
        if (newVersion > configVersion.get()) {
            configVersion.set(newVersion);
            // Apply configuration updates here
            System.out.println("Updating configuration to version: " + newVersion);
        }
    }

    public double getMean(String sensorId) {
        SensorData data = sensorDataMap.get(sensorId);
        return data == null ? 0.0 : data.calculateMean();
    }

    public double getVariance(String sensorId) {
        SensorData data = sensorDataMap.get(sensorId);
        return data == null ? 0.0 : data.calculateVariance();
    }

    private static class SensorData {
        private final AtomicInteger count = new AtomicInteger(0);
        private final AtomicLong sum = new AtomicLong(0);
        private final AtomicLong sumOfSquares = new AtomicLong(0);

        public void add(double reading) {
            count.incrementAndGet();
            sum.addAndGet((long) reading);
            sumOfSquares.addAndGet((long) (reading * reading));
        }

        public double calculateMean() {
            int currentCount = count.get();
            return currentCount == 0 ? 0.0 : (double) sum.get() / currentCount;
        }

        public double calculateVariance() {
            int currentCount = count.get();
            if (currentCount <= 1) {
                return 0.0;
            }
            long meanSum = sum.get();
            long meanOfSquaresSum = sumOfSquares.get();
            return ((double) meanOfSquaresSum - ((meanSum * meanSum) / currentCount)) / (currentCount - 1);
        }
    }

    public static void main(String[] args) {
        StreamingDataAggregator aggregator = new StreamingDataAggregator();

        // Simulate sensor readings
        for (int i = 0; i < 100; i++) {
            aggregator.processSensorReading("sensor" + i % 5, Math.random() * 100);
        }

        // Simulate configuration update
        aggregator.updateConfiguration(2);

        // Output results
        System.out.println("Mean of sensor1: " + aggregator.getMean("sensor1"));
        System.out.println("Variance of sensor2: " + aggregator.getVariance("sensor2"));
    }
}
```

This code provides a basic structure for an efficient streaming data processor in Java. It includes methods to process sensor readings, update configurations, and calculate mean and variance. The use of `ConcurrentHashMap` ensures thread safety for concurrent access, while `AtomicInteger` and `AtomicLong` provide atomic operations for updating counters and sums. The `SensorData` inner class efficiently accumulates data in a thread-safe manner and calculates statistical metrics.']

