    private readonly IKeyProvider _keyProvider;
    private readonly ICryptoTransformFactory _cryptoTransformFactory;

    public AesCbcDecryptor(IKeyProvider keyProvider, ICryptoTransformFactory cryptoTransformFactory)
    {
        _keyProvider = keyProvider ?? throw new ArgumentNullException(nameof(keyProvider));
        _cryptoTransformFactory = cryptoTransformFactory ?? throw new ArgumentNullException(nameof(cryptoTransformFactory));
    }

    public async Task<byte[]> DecryptAsync(string ciphertext, string keyId)
    {
        if (string.IsNullOrEmpty(ciphertext))
            throw new ArgumentException("Ciphertext cannot be null or empty", nameof(ciphertext));

        if (string.IsNullOrEmpty(keyId))
            throw new ArgumentException("KeyId cannot be null or empty", nameof(keyId));

        var (key, iv) = await GetKeyAndIVAsync(keyId);

        using (var aesAlg = Aes.Create())
        {
            aesAlg.Key = key;
            aesAlg.IV = iv;

            using (var decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV))
            using (var memoryStream = new System.IO.MemoryStream(ciphertext))
            using (var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read))
            {
                return await Task.Run(() => cryptoStream.ToArray());
            }
        }
    }

    private async Task<Tuple<byte[], byte[]>> GetKeyAndIVAsync(string keyId)
    {
        return _keyCache.GetOrAdd(keyId, async k =>
        {
            try
