                var (key, iv) = await _keyProvider.GetKeyAndIVAsync(k);
                return Tuple.Create(key, iv);
            }
            catch (Exception ex)
            {
                // Log the exception and retry logic here
                throw new Exception("Failed to fetch key or IV from external data source", ex);
            }
        });
    }

    public void Dispose()
    {
        _keyCache.Clear();
    }
}

