import json

class JsonSerializer:
    _registry = {}
    _factory_priority = {}

    @staticmethod
    def register(data_type, id):
        JsonSerializer._registry[id] = data_type

    @staticmethod
    def factory(id, *args, **kwargs):
        priority = JsonSerializer._factory_priority.get(id, 0)
        for factory_method in sorted(JsonSerializer._registry[id].__subclasses__, key=lambda x: getattr(x, '_priority', 0) == priority, reverse=True):
            instance = factory_method(*args, **kwargs)
            if instance is not None:
                return instance
        return JsonSerializer._registry[id](*args, **kwargs)

    @staticmethod
    def serialize(data, depth=10):
        if depth <= 0:
            raise ValueError("Maximum recursion depth reached")
        if isinstance(data, dict):
            return {k: JsonSerializer.serialize(v, depth - 1) for k, v in data.items()}
        elif isinstance(data, list):
            return [JsonSerializer.serialize(i, depth - 1) for i in data]
        else:
            return data

    @staticmethod
    def deserialize(json_str, type_id, schema=None):
        try:
            data = json.loads(json_str)
            if schema is not None and not jsonschema.validate(data, schema):
                raise ValueError("JSON does not match schema")
            return JsonSerializer.factory(type_id, **data)
        except (json.JSONDecodeError, jsonschema.exceptions.ValidationError) as e:
            raise ValueError(f"Invalid JSON or schema: {e}")

# Usage example
class User(JsonSerializer):
    _priority = 1

    def __init__(self, name, age):
        self.name = name
        self.age = age

JsonSerializer.register(User, "user")
user_json = '{"name": "John", "age": 30}'
user = JsonSerializer.deserialize(user_json, "user")
print(user.name, user.age)
