#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>

// Define a structure for HTTP request parameters
typedef struct {
    char *url;
    CURL *handle;
} HttpRequest;

// Function to initialize an asynchronous HTTP request
HttpRequest* init_http_request(const char *url) {
    HttpRequest *request = (HttpRequest *)malloc(sizeof(HttpRequest));
    if (!request) return NULL;

    request->url = strdup(url);
    request->handle = curl_easy_init();
    if (!request->handle) {
        free(request->url);
        free(request);
        return NULL;
    }

    // Set common options for HTTP requests
    curl_easy_setopt(request->handle, CURLOPT_URL, request->url);
    curl_easy_setopt(request->handle, CURLOPT_NOSIGNAL, 1L); // Handle network errors gracefully

    return request;
}

// Function to perform the actual HTTP request asynchronously
int perform_async_http_request(HttpRequest *request) {
    CURLcode res = curl_easy_perform(request->handle);
    if (res != CURLE_OK) {
        fprintf(stderr, "HTTP Request failed: %s\n", curl_easy_strerror(res));
        return -1;
    }
    return 0;
}

// Function to clean up an HTTP request
void cleanup_http_request(HttpRequest *request) {
    if (request->handle) {
        curl_easy_cleanup(request->handle);
    }
    free(request->url);
    free(request);
}

// Example usage of the above functions
int main() {
    HttpRequest *req = init_http_request("https://example.com");
    if (!req) {
        fprintf(stderr, "Failed to initialize HTTP request\n");
        return 1;
    }

    int result = perform_async_http_request(req);
    if (result != 0) {
        fprintf(stderr, "HTTP Request failed\n");
    } else {
        printf("HTTP Request successful\n");
    }

    cleanup_http_request(req);
    return 0;
}
```

