#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>

typedef struct {
    void** items;
    int front;
    int rear;
    int capacity;
    pthread_mutex_t mutex;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} ThreadSafeQueue;

ThreadSafeQueue* create_queue(int max_capacity) {
    ThreadSafeQueue* queue = (ThreadSafeQueue*)malloc(sizeof(ThreadSafeQueue));
    queue->items = (void**)malloc(max_capacity * sizeof(void*));
    queue->front = 0;
    queue->rear = -1;
    queue->capacity = max_capacity;
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->not_full, NULL);
    pthread_cond_init(&queue->not_empty, NULL);
    return queue;
}

void destroy_queue(ThreadSafeQueue* queue) {
    pthread_mutex_lock(&queue->mutex);
    while (queue->front != (queue->rear + 1) % queue->capacity) {
        free(queue->items[queue->front]);
        queue->front = (queue->front + 1) % queue->capacity;
    }
    pthread_mutex_unlock(&queue->mutex);
    pthread_mutex_destroy(&queue->mutex);
    pthread_cond_destroy(&queue->not_full);
    pthread_cond_destroy(&queue->not_empty);
    free(queue->items);
    free(queue);
}

void enqueue(ThreadSafeQueue* queue, void* item) {
    pthread_mutex_lock(&queue->mutex);
    while ((queue->rear + 1) % queue->capacity == queue->front) {
        pthread_cond_wait(&queue->not_full, &queue->mutex);
    }
    queue->items[queue->rear] = item;
    queue->rear = (queue->rear + 1) % queue->capacity;
    pthread_cond_signal(&queue->not_empty);
    pthread_mutex_unlock(&queue->mutex);
}

void* dequeue(ThreadSafeQueue* queue) {
    void* item = NULL;
    pthread_mutex_lock(&queue->mutex);
    while (queue->front == (queue->rear + 1) % queue->capacity) {
        pthread_cond_wait(&queue->not_empty, &queue->mutex);
    }
    item = queue->items[queue->front];
    queue->front = (queue->front + 1) % queue->capacity;
    pthread_cond_signal(&queue->not_full);
    pthread_mutex_unlock(&queue->mutex);
    return item;
}

