#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <ctype.h>
#include <time.h>

#define MAX_LINE_LENGTH 1024
#define MAX_RULES 10
#define TRANSFORM_FUNCTION_LIMIT 500

typedef struct {
    char *key;
    char *value;
} KeyValue;

typedef struct {
    KeyValue *rules[MAX_RULES];
    int rule_count;
} TransformationRules;

void* mem_pool = NULL;
size_t pool_size = 0;
size_t pool_used = 0;

void* allocate_memory(size_t size) {
    if (pool_used + size > pool_size) {
        // Reallocate memory pool
        pool_size = pool_used + size + 1024; // Add some extra space
        mem_pool = realloc(mem_pool, pool_size);
    }
    void *ptr = mem_pool + pool_used;
    pool_used += size;
    return ptr;
}

void free_memory(void) {
    if (mem_pool != NULL) {
        free(mem_pool);
        mem_pool = NULL;
        pool_size = 0;
        pool_used = 0;
    }
}

TransformationRules parse_transformation_rules(char *rules_str) {
    TransformationRules rules;
    rules.rule_count = 0;

    char *token = strtok(rules_str, ";");
    while (token != NULL && rules.rule_count < MAX_RULES) {
        KeyValue *kv = (KeyValue*)allocate_memory(sizeof(KeyValue));
        kv->key = strtok(token, "=");
        kv->value = strtok(NULL, "=");
        if (kv->key == NULL || kv->value == NULL) {
            fprintf(stderr, "Invalid rule syntax: %s\n", token);
        } else {
            rules.rules[rules.rule_count++] = kv;
        }
        token = strtok(NULL, ";");
    }

    return rules;
}

void transform_user_activity(char *input_file, char *output_file, TransformationRules rules, bool detailed_logs) {
    FILE *in_file = fopen(input_file, "r");
    if (in_file == NULL) {
        perror("Failed to open input file");
        return;
    }

    FILE *out_file = fopen(output_file, "w");
    if (out_file == NULL) {
        fclose(in_file);
        perror("Failed to open output file");
        return;
    }

    char line[MAX_LINE_LENGTH];
    int processed_records = 0;

    struct timespec start_time, end_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (fgets(line, sizeof(line), in_file) != NULL && processed_records < TRANSFORM_FUNCTION_LIMIT) {
        if (detailed_logs) fprintf(stderr, "Processing line: %s", line);

        // Apply transformation rules
        for (int i = 0; i < rules.rule_count; i++) {
            char *key = rules.rules[i]->key;
            char *value = rules.rules[i]->value;

            if (strstr(line, key) != NULL) {
                char *new_line = str_replace(line, key, value);
                if (new_line == NULL) {
                    fprintf(stderr, "Memory allocation failed for transformation\n");
                    continue;
                }
                strcpy(line, new_line);
                free(new_line);

                if (detailed_logs) fprintf(stderr, "Transformed line: %s", line);
            }
        }

        // Write transformed line to output file
        fputs(line, out_file);
        processed_records++;

        clock_gettime(CLOCK_MONOTONIC, &end_time);
        if ((end_time.tv_sec - start_time.tv_sec) * 1000 + (end_time.tv_nsec - start_time.tv_nsec) / 1000000 > 500) {
            fprintf(stderr, "Timeout limit reached. Processed %d records.\n", processed_records);
            break;
        }
    }

    fclose(in_file);
    fclose(out_file);

    // Free memory pool
    free_memory();
}

char* str_replace(const char *old_string, const char *old_substring, const char *new_substring) {
    size_t old_len = strlen(old_substring);
    size_t new_len = strlen(new_substring);
    size_t count = 0;

    // Count occurrences of old substring
    const char *p = old_string;
    while ((p = strstr(p, old_substring)) != NULL) {
        p += old_len;
        count++;
    }

    // Allocate memory for new string
    size_t len = strlen(old_string) - count * old_len + count * new_len + 1;
    char *new_string = (char*)allocate_memory(len);
    if (new_string == NULL) return NULL;

    p = old_string;
    char *q = new_string;
    while ((p = strstr(p, old_substring)) != NULL) {
        size_t pos = p - old_string;
        memcpy(q, old_string, pos);
        q += pos;
        strcpy(q, new_substring);
        q += new_len;
        p += old_len;
    }
    strcpy(q, p);

    return new_string;
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <input_file> <output_file> <rules_str> <detailed_logs>\n", argv[0]);
        return 1;
    }

    bool detailed_logs = (strcmp(argv[4], "true") == 0);
    TransformationRules rules = parse_transformation_rules(argv[3]);

    transform_user_activity(argv[1], argv[2], rules, detailed_logs);

    return 0;
}
