    srand(time(NULL));
    int count = 0;
    while (count < MAX_CONNECTIONS && count < *num_connections) {
        TCP_CONNECTION_INFO conn_info;
        strcpy(conn_info.ip, "192.168.1." + rand() % 255);
        conn_info.port = 1024 + rand() % 1023;
        generate_session_id(conn_info.session_id);

        if (validate_connection_metadata(&conn_info)) {
            (*conn_list)[count] = conn_info;
            count++;
        } else {
            log_event("Invalid connection metadata", &conn_info, 0);
        }
    }

    *num_connections = count;
    return 0;
}

int main() {
