    int num_connections;

    if (initialize_connection_list(&connection_list, &num_connections) == 0) {
        printf("Successfully initialized %d connections.\n", num_connections);
    } else {
        printf("Failed to initialize connection list.\n");
    }

    free(connection_list); // Clean up allocated memory
