#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>

#define QUEUE_INIT_SIZE 10

typedef struct {
    int *data;
    size_t head;
    size_t tail;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} ThreadSafeQueue;

ThreadSafeQueue* ts_queue_create() {
    ThreadSafeQueue *queue = (ThreadSafeQueue*)malloc(sizeof(ThreadSafeQueue));
    queue->data = (int*)calloc(QUEUE_INIT_SIZE, sizeof(int));
    queue->head = 0;
    queue->tail = 0;
    queue->count = 0;
    queue->capacity = QUEUE_INIT_SIZE;
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->not_full, NULL);
    pthread_cond_init(&queue->not_empty, NULL);
    return queue;
}

void ts_queue_destroy(ThreadSafeQueue *queue) {
    free(queue->data);
    pthread_mutex_destroy(&queue->lock);
    pthread_cond_destroy(&queue->not_full);
    pthread_cond_destroy(&queue->not_empty);
    free(queue);
}

bool ts_queue_enqueue(ThreadSafeQueue *queue, int item) {
    pthread_mutex_lock(&queue->lock);
    while (queue->count == queue->capacity) {
        pthread_cond_wait(&queue->not_full, &queue->lock);
    }
    queue->data[queue->tail] = item;
    queue->tail = (queue->tail + 1) % queue->capacity;
    queue->count++;
    pthread_cond_signal(&queue->not_empty);
    pthread_mutex_unlock(&queue->lock);
    return true;
}

bool ts_queue_dequeue(ThreadSafeQueue *queue, int *item) {
    pthread_mutex_lock(&queue->lock);
    while (queue->count == 0) {
        pthread_cond_wait(&queue->not_empty, &queue->lock);
    }
    *item = queue->data[queue->head];
    queue->head = (queue->head + 1) % queue->capacity;
    queue->count--;
    pthread_cond_signal(&queue->not_full);
    pthread_mutex_unlock(&queue->lock);
    return true;
}
