    std::this_thread::sleep_for(std::chrono::milliseconds(rand() % 51));

    // Randomly select an attack
    int selectedAttack = rand() % 4 + 1;
    while (selectedAttack == attackHistory[historyIndex]) {
        selectedAttack = rand() % 4 + 1;
    }
    attackHistory[historyIndex] = selectedAttack;
    historyIndex = (historyIndex + 1) % 10;

    // Calculate damage
    int damage;
    switch (selectedAttack) {
        case 1: damage = 40; break;
        case 2: damage = 60; break;
        case 3: damage = 80; break;
        case 4: damage = 120; break;
        default: return; // Invalid attack
    }

    // Print selected attack and damage
    std::cout << "Executing Attack " << selectedAttack << " with " << damage << " damage." << std::endl;

    // Log damage to file
    try {
        damageLog << damage << std::endl;
        damageLog.flush();
    } catch (const std::ios_base& e) {
        std::cerr << "Error writing to damage log file: " << e.what() << std::endl;
    }

    // Rotate log file every hour if it exceeds 100 lines
    static int lineCount = 0;
    ++lineCount;
    if (lineCount >= 100) {
        time_t now = time(nullptr);
        char buffer[80];
        strftime(buffer, sizeof(buffer), "%Y%m%d%H%M%S", localtime(&now));
        damageLog.close();
        std::string newFileName = "damage_log_" + std::string(buffer) + ".txt";
        rename("damage_log.txt", newFileName.c_str());
        damageLog.open("damage_log.txt", std::ios::app);
        if (!damageLog) {
            std::cerr << "Failed to open rotated damage log file." << std::endl;
            return;
        }
        lineCount = 0;
    }

    // Cool down for 10 seconds
    std::this_thread::sleep_for(std::chrono::seconds(10));
}
