void executeRandomAttack() {
    static int lastAttack = 0;
    static std::string history[10] = {};
    static int historyIndex = 0;

    srand(time(0));
    int attack;
    do {
        attack = rand() % 4 + 1;
    } while (attack == lastAttack);
    lastAttack = attack;

    history[historyIndex++] = std::to_string(attack);
    if (historyIndex >= 10) historyIndex = 0;

    int damage;
    switch (attack) {
        case 1: damage = 40; break;
        case 2: damage = 60; break;
        case 3: damage = 80; break;
        case 4: damage = 120; break;
        default: damage = 0; break;
    }

    std::cout << "Attack " << attack << ": " << damage << " damage" << std::endl;

    usleep(rand() % 50 * 1000); // Random delay between 0 and 50 milliseconds

    pid_t pid = fork();
    if (pid == -1) {
        std::cerr << "Error: forking failed." << std::endl;
        return;
    } else if (pid == 0) {
        execl("/bin/sh", "sh", "-c", "echo 'Result of Attack " + std::to_string(attack) + ": " + std::to_string(damage) + " damage'", NULL);
        exit(EXIT_FAILURE);
    } else {
        int status;
        waitpid(pid, &status, 0);
    }

    static time_t lastLogTime = 0;
    static int totalDamage = 0;
    if (time(0) - lastLogTime >= 60) {
        std::ofstream logFile("damage_log.txt", std::ios::app | std::ios::out | std::ios::binary);
        if (!logFile.is_open()) {
            std::cerr << "Error: cannot open log file." << std::endl;
            return;
        }
        logFile << totalDamage << std::endl;
        logFile.close();
        lastLogTime = time(0);
        totalDamage = 0;
    } else {
        totalDamage += damage;
    }

    // Rotate the log file every hour
    static time_t lastRotationTime = 0;
    if (time(0) - lastRotationTime >= 3600) {
        std::ofstream newFile("damage_log_" + std::to_string(time(0)) + ".txt");
        if (!newFile.is_open()) {
            std::cerr << "Error: cannot open log file for rotation." << std::endl;
            return;
        }
        newFile.close();
        rename("damage_log.txt", "damage_log_old.txt");
        rename("damage_log_old.txt", ("damage_log_" + std::to_string(lastRotationTime) + ".txt").c_str());
        lastRotationTime = time(0);
    }
}
