use std::fs::{File, OpenOptions};
use std::io::{self, Write};
use std::process::{Command, Stdio};
use rand::Rng;
use tokio::task;
use tokio::time::{sleep, Duration};

const ATTACKS: [(u8, u32); 4] = [(1, 40), (2, 60), (3, 80), (4, 120)];
const COOLDOWN: Duration = Duration::from_secs(10);
const FILE_SIZE_LIMIT: u64 = 10 * 1024 * 1024;
const MAX_ATTACKS: usize = 50_000;

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: {} command", args[0]);
        return;
    }

    match args[1].as_str() {
        "executeRandomAttack" => executeRandomAttack(),
        _ => eprintln!("Unknown command: {}", args[1]),
    }
}

fn executeRandomAttack() {
    let mut rng = rand::thread_rng();
    let mut last_attacks = [0; 10];
    let mut total_damage = 0;
    let mut file = OpenOptions::new()
        .append(true)
        .create(true)
        .open("damage_log.txt")
        .expect("Failed to open damage log file");

    for _ in 0..MAX_ATTACKS {
        loop {
            let attack = rng.gen_range(0, ATTACKS.len());
            if last_attacks.iter().rev().take(2).all(|&a| a != attack) {
                last_attacks[attack % 10] = attack;
                break;
            }
        }

        let damage = ATTACKS[last_attacks.last().unwrap()][1];
        total_damage += damage;

        println!("Executing Attack {} for {} damage", last_attacks.last().unwrap() + 1, damage);

        let delay = Duration::from_millis(rng.gen_range(0..=50));
        sleep(delay).await;

        let output = execute_child_process(&last_attacks.last().unwrap());
        print!("{}", output);
    }

    if total_damage > FILE_SIZE_LIMIT {
        let _ = file.set_len(0); // Truncate the file
    }

    writeln!(file, "Total Damage: {}", total_damage)
        .expect("Failed to write to damage log file");
}

fn execute_child_process(attack: &u8) -> String {
    let output = Command::new("echo")
        .arg(format!("Attack {} executed", attack + 1))
        .stdout(Stdio::piped())
        .spawn()
        .expect("Failed to spawn child process")
        .wait_with_output()
        .expect("Failed to wait for child process");

    String::from_utf8_lossy(&output.stdout).to_string()
}
