const bookRegex = /(?:Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Moses|Joshua|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk/Zephaniah/Haggai/Zechariah/Malachi)/i;
const pduRegex = /.*?NAS_PDU=(.*?)$/;

function initializeLTE_NAS_EMM_MESSAGES(numMessages) {
  const messages = [];

  for (let i = 0; i < numMessages; i++) {
    const NAS_EPS_mobility = `Context${i}`;
    let NAS_PDU;

    do {
      NAS_PDU = generateRandomPDU();
    } while (!isValidNAS_PDU(NAS_PDU));

    messages.push({
      NAS_EMM_TYPE: 'EMM_MESSAGE',
      NAS_EPS_mobility,
      NAS_PDU
    });

    simulateNetworkLatency();
  }

  return {
    messages,
    getBookFrequency() {
      const frequency = {};

      for (const message of messages) {
        const matches = message.NAS_PDU.match(bookRegex);

        if (matches && matches[1]) {
          const bookName = matches[1].replace(/[^a-zA-Z\s]/g, '').trim();

          if (isOldTestamentBook(bookName)) {
            frequency[bookName] = (frequency[bookName] || 0) + 1;
          }
        }
      }

      return frequency;
    }
  };
