    let attack_strategies = vec![
        ("Attack A", 40, Duration::from_secs(2)),
        ("Attack B", 60, Duration::from_secs(3)),
        ("Attack C", 80, Duration::from_secs(5)),
        ("Attack D", 120, Duration::from_secs(7)),
    ];

    // Simulate concurrent attack requests
    let mut tasks = Vec::new();
    for _ in 0..100 {
        let strategy = attack_strategies.choose(&mut rand::thread_rng()).unwrap();
        let task = tokio::spawn(async move {
            execute_attack(strategy);
        });
        tasks.push(task);
    }

    // Wait for all tasks to complete
    futures::future::join_all(tasks).await;

    // Log total damage dealt over 60 seconds
    log_damage_to_file("combat_log.csv");
}

fn execute_attack((name, damage, cooldown): (&str, i32, Duration)) {
