    tokio::time::sleep(Duration::from_millis(rand::thread_rng().gen_range(0..51))).await;
    if rand::thread_rng().gen_bool(0.8) {
        println!("Executing {} for {} damage", name, damage);
    } else {
        println!("Attack {} failed", name);
    }
}

