#include <stdio.h>
#include <stdlib.h>
#include <dirent.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_FILENAME_LENGTH 255
#define THREAD_POOL_SIZE 16
#define BATCH_SIZE 100
#define MAX_LOG_LENGTH 256

typedef struct {
    char *filename;
    size_t file_size;
} FileEntry;

typedef struct {
    FileEntry **entries;
    int count;
    sem_t entry_count_lock;
} TaskQueue;

void* worker_thread(void *arg) {
    TaskQueue *queue = (TaskQueue*) arg;
    while (1) {
        sem_wait(&queue->entry_count_lock);
        if (queue->count == 0) {
            pthread_exit(NULL);
        }
        int index = queue->count - 1;
        FileEntry *entry = queue->entries[index];
        // Process file here
        printf("Processing file: %s\n", entry->filename);
        queue->count--;
        sem_post(&queue->entry_count_lock);
    }
}

void processDirectoryContent(const char *directory_path, const char *log_file_path, size_t max_file_size) {
    DIR *dir;
    struct dirent *ent;
    TaskQueue task_queue = { .entries = NULL, .count = 0 };
    sem_init(&task_queue.entry_count_lock, 0, 1);

    if ((dir = opendir(directory_path)) != NULL) {
        while ((ent = readdir(dir)) != NULL) {
            char full_path[MAX_FILENAME_LENGTH + 1];
            snprintf(full_path, sizeof(full_path), "%s/%s", directory_path, ent->d_name);
            struct stat file_stat;
            if (lstat(full_path, &file_stat) == 0 && S_ISREG(file_stat.st_mode)) {
                FileEntry *entry = malloc(sizeof(FileEntry));
                entry->filename = strdup(ent->d_name);
                entry->file_size = file_stat.st_size;
                if (entry->file_size > max_file_size) {
                    printf("Skipping large file: %s\n", ent->d_name);
                    free(entry->filename);
                    free(entry);
                    continue;
                }
                sem_wait(&task_queue.entry_count_lock);
                task_queue.entries = realloc(task_queue.entries, (task_queue.count + 1) * sizeof(FileEntry*));
                task_queue.entries[task_queue.count++] = entry;
                sem_post(&task_queue.entry_count_lock);

                if (task_queue.count % BATCH_SIZE == 0) {
                    // Move batch to new directory
                }
            }
        }
        closedir(dir);
    } else {
        fprintf(stderr, "Failed to open directory: %s\n", directory_path);
    }

    pthread_t threads[THREAD_POOL_SIZE];
    for (int i = 0; i < THREAD_POOL_SIZE; i++) {
        pthread_create(&threads[i], NULL, worker_thread, &task_queue);
    }
    for (int i = 0; i < THREAD_POOL_SIZE; i++) {
        pthread_join(threads[i], NULL);
    }

    sem_destroy(&task_queue.entry_count_lock);

    FILE *log_file = fopen(log_file_path, "a");
    if (log_file != NULL) {
        // Log errors and warnings here
        fclose(log_file);
    }
}
