#include <stdlib.h>
#include <pthread.h>

#define MAX_ENTRIES 50000
#define CONFIG_REFRESH_INTERVAL 60

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pthread_mutex_t mutex;
} ListEntry;

typedef struct {
    ListEntry entries[MAX_ENTRIES];
    int count;
    pthread_mutex_t lock;
} DynamicList;

void init_list(DynamicList *list) {
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

int add_entry(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T new_pdu) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->count; i++) {
        pthread_mutex_lock(&list->entries[i].mutex);
        if (list->entries[i].pdu.RNTI == new_pdu.RNTI) {
            pthread_mutex_unlock(&list->entries[i].mutex);
            pthread_mutex_unlock(&list->lock);
            return -1; // Duplicate RNTI
        }
        pthread_mutex_unlock(&list->entries[i].mutex);
    }
    if (list->count < MAX_ENTRIES) {
        list->entries[list->count++] = (ListEntry){new_pdu, PTHREAD_MUTEX_INITIALIZER};
        pthread_mutex_unlock(&list->lock);
        return 0;
    } else {
        pthread_mutex_unlock(&list->lock);
        return -2; // List full
    }
}

int update_entry(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T updated_pdu) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->count; i++) {
        if (pthread_mutex_trylock(&list->entries[i].mutex) == 0) {
            if (list->entries[i].pdu.RNTI == updated_pdu.RNTI) {
                list->entries[i].pdu = updated_pdu;
                pthread_mutex_unlock(&list->entries[i].mutex);
                pthread_mutex_unlock(&list->lock);
                return 0;
            }
            pthread_mutex_unlock(&list->entries[i].mutex);
        }
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // RNTI not found
}

int remove_entry(DynamicList *list, int rnti) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->count; i++) {
        if (pthread_mutex_trylock(&list->entries[i].mutex) == 0) {
            if (list->entries[i].pdu.RNTI == rnti) {
                pthread_mutex_unlock(&list->entries[i].mutex);
                for (; i < list->count - 1; i++) {
                    pthread_mutex_lock(&list->entries[i + 1].mutex);
                    list->entries[i] = list->entries[i + 1];
                    pthread_mutex_unlock(&list->entries[i + 1].mutex);
                }
                pthread_mutex_destroy(&list->entries[list->count - 1].mutex);
                list->count--;
                pthread_mutex_unlock(&list->lock);
                return 0;
            }
            pthread_mutex_unlock(&list->entries[i].mutex);
        }
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // RNTI not found
}

int get_stats(DynamicList *list, int *total_entries, int *crc_flag_set) {
    pthread_mutex_lock(&list->lock);
    *total_entries = list->count;
    *crc_flag_set = 0;
    for (int i = 0; i < list->count; i++) {
        if (pthread_mutex_trylock(&list->entries[i].mutex) == 0) {
            if (list->entries[i].pdu.CRCFLAG) (*crc_flag_set)++;
            pthread_mutex_unlock(&list->entries[i].mutex);
        }
    }
    pthread_mutex_unlock(&list->lock);
    return 0;
}

