public class TaskManager
{
    private List<TaskItem> tasks = new List<TaskItem>();
    private readonly object lockObject = new object();

    public void AddTask(TaskItem task)
    {
        lock (lockObject)
        {
            tasks.Add(task);
        }
    }

    public void UpdateTask(string taskId, Action<TaskItem> updateAction)
    {
        lock (lockObject)
        {
            var task = tasks.FirstOrDefault(t => t.Id == taskId);
            if (task != null)
                updateAction(task);
        }
    }

    public void RemoveTask(string taskId)
    {
        lock (lockObject)
        {
            tasks.RemoveAll(t => t.Id == taskId);
        }
    }

    public List<TaskItem> GetSummaryReport(Func<TaskItem, bool> criteria)
    {
        return tasks.Where(criteria).ToList();
    }

    public async Task<List<TaskItem>> FilterTasksAsync(DateTime startTime, DateTime endTime, Dictionary<string, object> metadataCriteria)
    {
        // Simulate API call with potential latency
        await Task.Delay(100);

        var filteredTasks = tasks
            .Where(t => t.Deadline >= startTime && t.Deadline <= endTime)
            .ToList();

        foreach (var criterion in metadataCriteria)
        {
            filteredTasks = filteredTasks
                .Where(t => t.Metadata.ContainsKey(criterion.Key) && t.Metadata[criterion.Key].Equals(criterion.Value))
                .ToList();
        }

        return filteredTasks;
    }

    public string SerializeToJson()
    {
        lock (lockObject)
        {
            return JsonConvert.SerializeObject(tasks);
        }
    }

    public void DeserializeFromJson(string json)
    {
        lock (lockObject)
        {
            tasks = JsonConvert.DeserializeObject<List<TaskItem>>(json);
        }
    }

    public async Task UpdateMetadataAsync(Func<Task> updateFunction)
    {
        try
        {
            await updateFunction();
        }
        catch (Exception ex)
        {
            // Log error and handle gracefully
        }
    }
}

