#include <pthread.h>
#include <syslog.h>

typedef struct {
    const char* filename;
    EVP_CIPHER_CTX *cipher_ctx;
} ImageTask;

int process_image(ImageTask* task) {
    TIFF* tif = TIFFOpen(task->filename, "r");
    if (!tif) {
        syslog(LOG_ERR, "Failed to open image file: %s", task->filename);
        return -1;
    }

    // Check bits per sample and handle unsupported cases
    uint16_t bits_per_sample;
    TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &bits_per_sample);
    if (bits_per_sample != 1 && bits_per_sample != 2 && bits_per_sample != 4 && bits_per_sample != 8 && bits_per_sample != 16) {
        syslog(LOG_ERR, "Unsupported bits per sample: %d", bits_per_sample);
        TIFFClose(tif);
        return -1;
    }

    // Initialize cipher context
    EVP_CIPHER_CTX *cipher_ctx = EVP_CIPHER_CTX_new();
    if (!cipher_ctx) {
        syslog(LOG_ERR, "Failed to create cipher context");
        TIFFClose(tif);
        return -1;
    }
    task->cipher_ctx = cipher_ctx;

    // Process image data in chunks
    uint32_t width, height, samples_per_pixel;
    TIFFGetField(tif, TIFFTAG_IMAGEWIDTH, &width);
    TIFFGetField(tif, TIFFTAG_IMAGELENGTH, &height);
    TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &samples_per_pixel);

    tdata_t buffer = _TIFFmalloc(TIFFTileSize(tif));
    uint64_t total_samples = width * height * samples_per_pixel;
    uint64_t processed_samples = 0;

    while (processed_samples < total_samples) {
        uint32_t tiles_across, tiles_down;
        TIFFComputeTileSize(tif, &tiles_across, &tiles_down);
        uint64_t remaining_samples = total_samples - processed_samples;
        uint32_t tile_width = width / tiles_across + (width % tiles_across ? 1 : 0);
        uint32_t tile_height = height / tiles_down + (height % tiles_down ? 1 : 0);

        for (uint32_t row = 0; row < tiles_down; row++) {
            for (uint32_t col = 0; col < tiles_across; col++) {
                uint64_t tile_samples = tile_width * tile_height * samples_per_pixel;
                if (tile_samples > remaining_samples) {
                    tile_samples = remaining_samples;
                }

                if (!TIFFReadTile(tif, buffer, col, row, 0, 0)) {
                    syslog(LOG_ERR, "Failed to read tile from image file: %s", task->filename);
                    EVP_CIPHER_CTX_free(cipher_ctx);
                    TIFFClose(tif);
                    _TIFFfree(buffer);
                    return -1;
                }

                // Apply cryptographic operation using OpenSSL
                if (!EVP_EncryptUpdate(cipher_ctx, (unsigned char*)buffer, &tile_samples)) {
                    syslog(LOG_ERR, "Failed to encrypt tile from image file: %s", task->filename);
                    EVP_CIPHER_CTX_free(cipher_ctx);
                    TIFFClose(tif);
                    _TIFFfree(buffer);
                    return -1;
                }

                processed_samples += tile_samples;
            }
        }
    }

    _TIFFfree(buffer);
    TIFFClose(tif);
    return 0;
}

void* thread_function(void* arg) {
    ImageTask* task = (ImageTask*)arg;
    if (process_image(task) != 0) {
        syslog(LOG_ERR, "Failed to process image: %s", task->filename);
    }
    free(task);
    return NULL;
}

int main(int argc, char** argv) {
    // Parse command-line options and set up logging
    // Create a thread pool and dispatch tasks

    pthread_t threads[10];
    ImageTask* tasks[10];

    // Populate tasks array with image filenames and cryptographic parameters
    for (int i = 0; i < 10; i++) {
        tasks[i] = malloc(sizeof(ImageTask));
        tasks[i]->filename = argv[i + 1];
        tasks[i]->cipher_ctx = NULL;
        pthread_create(&threads[i], NULL, thread_function, tasks[i]);
    }

    // Wait for all threads to complete
    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
