int findMax(int *nums, int count) {
    if (count == 0) {
        fprintf(stderr, "No valid integers found.\n");
        return -1; // Assuming -1 as an error code for no valid numbers
    }

    int max = nums[0];
    for (int i = 1; i < count; ++i) {
        if (nums[i] > max) {
            max = nums[i];
        }
    }

    return max;
}

void updateArray(int *nums, int count, int newNum, int minVal, int maxVal) {
    for (int i = 0; i < count; ++i) {
        if (nums[i] == newNum) {
            nums[i] = newNum;
            break;
        }
    }

    // If not found, append it and increase count
    if (count < MAX_NUMS && newNum >= minVal && newNum <= maxVal) {
        nums[count++] = newNum;
    } else {
        fprintf(stderr, "Cannot add %d to array or already in array.\n", newNum);
    }
}

