                    // Validate refresh token if needed
                }
                break;
            }
            ++it;
        }

        if (it != tokens.end()) {
            it = tokens.insert_after(it, insertToken);
        } else {
            tokens.push_back(insertToken);
        }
    }

    std::string computeMD5Hash(const std::string& input) {
        unsigned char digest[MD5_DIGEST_LENGTH];
        MD5((unsigned char*)input.c_str(), input.length(), (unsigned char*)&digest);    

        char mdString[33];
        for(int i = 0; i < 16 ; ++i)
            sprintf(&mdString[i*2], "%02x", (unsigned int)digest[i]);

        return std::string(mdString);
    }
