#include <semaphore.h>
#include <pthread.h>

typedef struct {
    sem_t *semaphores;
    int size;
    int min_wait_time;
    int max_wait_time;
} SemaphorePool;

SemaphorePool* semaphore_pool_create(int initial_size, int min_wait_time, int max_wait_time) {
    SemaphorePool *pool = (SemaphorePool*)malloc(sizeof(SemaphorePool));
    if (!pool) return NULL;

    pool->semaphores = (sem_t*)calloc(initial_size, sizeof(sem_t));
    if (!pool->semaphores) {
        free(pool);
        return NULL;
    }

    pool->size = initial_size;
    pool->min_wait_time = min_wait_time;
    pool->max_wait_time = max_wait_time;

    for (int i = 0; i < initial_size; i++) {
        sem_init(&pool->semaphores[i], 0, 1);
    }

    return pool;
}

void semaphore_pool_destroy(SemaphorePool *pool) {
    if (!pool) return;

    for (int i = 0; i < pool->size; i++) {
        sem_destroy(&pool->semaphores[i]);
    }
    free(pool->semaphores);
    free(pool);
}

int semaphore_pool_create_semaphore(SemaphorePool *pool) {
    if (!pool || pool->size >= 1000) return -1; // Assuming a max of 1000 semaphores

    sem_t *new_sem = &pool->semaphores[pool->size++];
    sem_init(new_sem, 0, 1);
    return pool->size - 1;
}

void semaphore_pool_delete_semaphore(SemaphorePool *pool, int index) {
    if (!pool || index < 0 || index >= pool->size) return;

    sem_t *sem_to_delete = &pool->semaphores[index];
    sem_destroy(sem_to_delete);
    pool->semaphores[index] = pool->semaphores[--pool->size];
}

int semaphore_pool_acquire(SemaphorePool *pool, int index, int timeout_ms) {
    if (!pool || index < 0 || index >= pool->size) return -1;

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += timeout_ms / 1000;
    ts.tv_nsec += (timeout_ms % 1000) * 1000000;

    if (ts.tv_nsec >= 1000000000) {
        ts.tv_sec++;
        ts.tv_nsec -= 1000000000;
    }

    return sem_timedwait(&pool->semaphores[index], &ts);
}

void semaphore_pool_release(SemaphorePool *pool, int index) {
    if (!pool || index < 0 || index >= pool->size) return;

    sem_post(&pool->semaphores[index]);
}
