import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.SQLException;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class UserStatusUpdater {
    private static final Lock lock = new ReentrantLock();
    private EmailService emailService;

    public UserStatusUpdater(EmailService emailService) {
        this.emailService = emailService;
    }

    public void updateUserStatus(int userId, String newStatus, String lastModifiedIP, String lastModifiedDate, boolean notificationPreference) {
        try {
            lock.lock();
            Connection connection = DatabaseConnection.getConnection();

            // Hash the IP address
            String hashedIP = hashIP(lastModifiedIP);

            // Update user status in main table
            String updateQuery = "UPDATE users SET status = ?, last_modified_ip = ?, last_modified_date = ? WHERE id = ?";
            try (PreparedStatement updateStmt = connection.prepareStatement(updateQuery)) {
                updateStmt.setString(1, newStatus);
                updateStmt.setString(2, hashedIP);
                updateStmt.setString(3, lastModifiedDate);
                updateStmt.setInt(4, userId);
                updateStmt.executeUpdate();
            }

            // Log the operation in audit table
            String auditLog = "User ID: " + userId + ", New Status: " + newStatus + ", Last Modified IP: " + hashedIP + ", Date: " + lastModifiedDate;
            logAudit(auditLog);

            // Send notification if enabled
            if (notificationPreference) {
                sendNotification(userId, newStatus);
            }
        } catch (SQLException | NoSuchAlgorithmException e) {
            handleError("Error updating user status", e);
        } finally {
            lock.unlock();
        }
    }

    private String hashIP(String ip) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] hashBytes = digest.digest(ip.getBytes());
        StringBuilder sb = new StringBuilder();
        for (byte b : hashBytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private void logAudit(String auditLog) {
        // Implement logging to an external service or file
        System.out.println("Audit Log: " + auditLog);
    }

    private void sendNotification(int userId, String newStatus) {
        try {
            emailService.sendEmail(userId, "Your status has been updated to: " + newStatus);
        } catch (Exception e) {
            handleError("Failed to send notification", e);
        }
    }

    private void handleError(String message, Exception e) {
        System.err.println(message + ": " + e.getMessage());
        // Log error details for further analysis
    }
}
