typedef struct {
    double value;
    double last_value;
    time_t last_recorded_time;
} Metric;

typedef enum {
    CPU_USAGE,
    MEMORY_CONSUMPTION,
    DISK_IO,
    NETWORK_BANDWIDTH
} MetricType;

typedef struct {
    Metric *metrics;
    size_t capacity;
    size_t count;
    FILE *log_file;
    pthread_mutex_t mutex;
} ResourceMonitor;

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

ResourceMonitor* initialize_resource_monitor(MetricType types[], int num_types, const char *log_destination, time_t interval, bool allow_duplicates) {
    // Initialize the resource monitor
    ResourceMonitor *rm = (ResourceMonitor*)malloc(sizeof(ResourceMonitor));
    if (!rm) {
        log_error("Failed to allocate memory for ResourceMonitor.");
        return NULL;
    }

    // Set up logging destination
    if (strcmp(log_destination, "file") == 0) {
        rm->log_file = fopen("monitor.log", "w");
        if (!rm->log_file) {
            log_error("Failed to open log file.");
            free(rm);
            return NULL;
        }
    } else if (strcmp(log_destination, "console") == 0) {
        rm->log_file = stdout;
    } else {
        log_error("Unsupported log destination.");
        free(rm);
        return NULL;
    }

    // Initialize metrics array
    rm->capacity = num_types * 2; // Start with twice the number of types to accommodate potential growth
    rm->count = 0;
    rm->metrics = (Metric*)malloc(rm->capacity * sizeof(Metric));
    if (!rm->metrics) {
        log_error("Failed to allocate memory for metrics array.");
        fclose(rm->log_file);
        free(rm);
        return NULL;
    }

    // Initialize mutex
    pthread_mutex_init(&rm->mutex, NULL);

    // Populate initial metric values (simplified example)
    for (int i = 0; i < num_types; i++) {
        Metric *metric = &rm->metrics[i];
        switch (types[i]) {
            case CPU_USAGE: metric->value = 5.0; break;
            case MEMORY_CONSUMPTION: metric->value = 1024.0; break;
            case DISK_IO: metric->value = 100.0; break;
            case NETWORK_BANDWIDTH: metric->value = 1000.0; break;
        }
        metric->last_value = -1.0; // Initialize to ensure first record always happens
        metric->last_recorded_time = time(NULL);
    }

    return rm;
}

void free_resource_monitor(ResourceMonitor *rm) {
    if (rm->log_file != stdout) {
        fclose(rm->log_file);
    }
    pthread_mutex_destroy(&rm->mutex);
    free(rm->metrics);
    free(rm);
}

void log_metrics(ResourceMonitor *rm, time_t interval) {
    pthread_mutex_lock(&rm->mutex);
    for (int i = 0; i < rm->count; i++) {
        Metric *metric = &rm->metrics[i];
        if (difftime(time(NULL), metric->last_recorded_time) >= interval) {
            if (!allow_duplicates && metric->value == metric->last_value) {
                continue;
            }
            fprintf(rm->log_file, "Type: %d, Value: %f\n", i, metric->value);
            metric->last_value = metric->value;
            metric->last_recorded_time = time(NULL);
        }
    }
    pthread_mutex_unlock(&rm->mutex);
}

// Example usage
int main() {
    MetricType types[] = {CPU_USAGE, MEMORY_CONSUMPTION};
    ResourceMonitor *monitor = initialize_resource_monitor(types, 2, "console", 5, false);
    if (monitor) {
        // Simulate logging metrics
        for (int i = 0; i < 10; i++) {
            log_metrics(monitor, 5);
            sleep(5);
        }
        free_resource_monitor(monitor);
    }
    return 0;
}
