from threading import Lock

class TransactionProcessor:
    def __init__(self):
        self.metrics_lock = Lock()
        self.transaction_metrics = {}

    def process_transactions(self, transactions, age_threshold, recent_window_size, weight_function):
        with self.metrics_lock:
            for transaction in transactions:
                if (time.time() - transaction['timestamp']) <= age_threshold:
                    weighted_sum = weight_function(transaction)
                    transaction_id = transaction['id']
                    if transaction_id not in self.transaction_metrics or weighted_sum > self.transaction_metrics[transaction_id][1]:
                        self.transaction_metrics[transaction_id] = (weighted_sum, time.time())
        return max(self.transaction_metrics.values(), key=lambda x: x[0])

def process_large_file_with_transactions(file_path, chunk_size=1024*1024):
    hasher = hashlib.md5()
    transaction_processor = TransactionProcessor()
