import hashlib
import os
import threading
from queue import Queue, Empty
import time
from xml.etree import ElementTree as ET
import concurrent.futures

def parse_and_hash_file(file_path, chunk_size=64*1024, num_threads=4):
    def read_in_chunks(file_obj, chunk_size):
        while True:
            data = file_obj.read(chunk_size)
            if not data:
                break
            yield data

    def hash_chunk(data):
        return hashlib.md5(data).hexdigest()

    def parse_xml_with_xpath(xml_data, element_name):
        root = ET.fromstring(xml_data)
        elements = root.findall(f".//{element_name}")
        if len(elements) != 1:
            raise ValueError(f"Expected exactly one '{element_name}' element")
        return elements[0]

    def handle_file(file_path):
        start_time = time.time()
        with open(file_path, 'rb') as f:
            chunk_hashes = [hash_chunk(chunk) for chunk in read_in_chunks(f, chunk_size)]
        file_hash = hashlib.md5(b''.join(chunk_hashes)).hexdigest()
        elapsed_time = time.time() - start_time
        print(f"File: {file_path}, Hash: {file_hash}, Time: {elapsed_time:.2f}s")

    def parse_and_process_file(file_path):
        try:
            with open(file_path, 'rb') as f:
                xml_data = f.read()
                element = parse_xml_with_xpath(xml_data, "desired_element_name")
                handle_file(element.text)
        except Exception as e:
            print(f"Error processing file {file_path}: {e}")

    def worker():
        while True:
            try:
                file_path = q.get(timeout=1)
                parse_and_process_file(file_path)
                q.task_done()
            except Empty:
                break

    if not os.path.isfile(file_path):
        raise FileNotFoundError(f"File not found: {file_path}")

    q = Queue()
    with concurrent.futures.ThreadPoolExecutor(max_workers=num_threads) as executor:
        for _ in range(num_threads):
            executor.submit(worker)

        # Example of adding files to the queue
        q.put("/path/to/file1")
        q.put("/path/to/file2")

        q.join()

# Example usage
parse_and_hash_file("/path/to/largefile", chunk_size=1024*1024, num_threads=8)
