    pthread_cond_init(&pipeline->not_full, NULL);
    pthread_cond_init(&pipeline->not_empty, NULL);

    pipeline->buffer = (DataRecord*)malloc(initial_buffer_size * sizeof(DataRecord));
    if (!pipeline->buffer) {
        free(pipeline);
        return NULL;
    }

    return pipeline;
}

void destroy_data_pipeline(DataPipeline* pipeline) {
    if (pipeline) {
        pthread_mutex_destroy(&pipeline->lock);
        pthread_cond_destroy(&pipeline->not_full);
        pthread_cond_destroy(&pipeline->not_empty);
        free(pipeline->buffer);
        free(pipeline);
