import requests
from concurrent.futures import ThreadPoolExecutor, as_completed
import logging
import os

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

def download_file(url, chunk_size=1024 * 1024, max_retries=3):
    response = requests.head(url)
    file_size = int(response.headers['content-length'])
    local_filename = url.split('/')[-1]

    with open(local_filename, 'wb') as f:
        for i in range(0, file_size, chunk_size):
            attempt = 0
            while attempt < max_retries:
                try:
                    response = requests.get(url, headers={'Range': f'bytes={i}-{i+chunk_size-1}'}, stream=True)
                    if response.status_code == 206:
                        f.write(response.content)
                        break
                    else:
                        raise Exception(f"Failed to download chunk {i}")
                except Exception as e:
                    logger.warning(f"Attempt {attempt+1} failed: {e}")
                    attempt += 1
                    if attempt >= max_retries:
                        raise

def download_file_concurrently(urls, chunk_size=1024 * 1024, max_retries=3, max_workers=5):
    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        futures = {executor.submit(download_file, url, chunk_size, max_retries): url for url in urls}
        for future in as_completed(futures):
            url = futures[future]
            try:
                future.result()
                logger.info(f"Downloaded {url} successfully")
            except Exception as e:
                logger.error(f"Failed to download {url}: {e}")

# Example usage
urls = [
    "http://example.com/largefile1",
    "http://example.com/largefile2",
    # Add more URLs here
]

download_file_concurrently(urls)
