    pthread_cond_init(&queue->not_empty, NULL);
}

int is_full(MessageQueue *queue) {
    return (queue->rear + 1) % MAX_TASKS == queue->front;
}

int is_empty(MessageQueue *queue) {
    return queue->front == -1;
}

void enqueue(MessageQueue *queue, Task task) {
    pthread_mutex_lock(&queue->mutex);
    while (is_full(queue)) {
        pthread_cond_wait(&queue->not_full, &queue->mutex);
    }
    if (queue->rear == -1)
        queue->front = 0;
    queue->rear = (queue->rear + 1) % MAX_TASKS;
    queue->tasks[queue->rear] = task;
    pthread_cond_signal(&queue->not_empty);
    pthread_mutex_unlock(&queue->mutex);
}

void dequeue(MessageQueue *queue, Task *task) {
    pthread_mutex_lock(&queue->mutex);
    while (is_empty(queue)) {
        pthread_cond_wait(&queue->not_empty, &queue->mutex);
    }
    *task = queue->tasks[queue->front];
    if (queue->front == queue->rear)
        queue->front = queue->rear = -1;
    else
        queue->front = (queue->front + 1) % MAX_TASKS;
    pthread_cond_signal(&queue->not_full);
    pthread_mutex_unlock(&queue->mutex);
}

void manage_dynamic_message_queue(MessageQueue *queue, int max_tasks) {
    // Implement task management logic here
}
