import hashlib
import os
import threading
from concurrent.futures import ThreadPoolExecutor, as_completed

def md5_hash_large_file(file_path):
    chunk_size = 8192  # Initial chunk size in bytes
    file_size = os.path.getsize(file_path)
    num_threads = min(32, os.cpu_count())  # Limit number of threads to avoid excessive resource usage

    def read_chunk(offset):
        with open(file_path, 'rb') as f:
            f.seek(offset)
            return f.read(chunk_size)

    def worker(start_offset):
        while start_offset < file_size:
            chunk = read_chunk(start_offset)
            if not chunk:
                break
            hash_obj.update(chunk)
            start_offset += chunk_size

    with ThreadPoolExecutor(max_workers=num_threads) as executor:
        futures = [executor.submit(worker, i * chunk_size) for i in range((file_size + chunk_size - 1) // chunk_size)]
        for future in as_completed(futures):
            try:
                future.result()
            except Exception as e:
                print(f"Error processing file: {e}")

    return hash_obj.hexdigest()

# Example usage
hash_result = md5_hash_large_file('large_file.txt')
print(hash_result)
```

