    for (int i = 0; i < num_packets; i++) {
        packets[i].protocol_id = i + 1;
        packets[i].timestamp = current_time + i;

        char* payload;
        PayloadGenerator generator = NULL;

        for (int j = 0; j < num_data_formats; j++) {
            if (strcmp(data_formats[j].name, data_format_name) == 0) {
                generator = data_formats[j].generator;
                break;
            }
        }

        if (!generator) {
            fprintf(stderr, "Unknown data format: %s\n", data_format_name);
            free(packets);
            return NULL;
        }

        generator(&payload);
        if (!payload) {
            free(packets);
            return NULL;
        }

        packets[i].payload = payload;
    }

    return packets;
}

