} Template;

// Global list of supported templates
Template *templates = NULL;
int num_templates = 0;

// Function to initialize the data store
Entry** initialize_data_store(const char *db_name, int num_entries, const char *template_name, size_t max_payload_size) {
    // Check for invalid parameters
    if (num_entries <= 0 || template_name == NULL || max_payload_size == 0) {
        return NULL;
    }

    // Find the specified template
    Template *selected_template = NULL;
    for (int i = 0; i < num_templates; i++) {
        if (strcmp(templates[i].name, template_name) == 0) {
            selected_template = &templates[i];
            break;
        }
    }

    if (selected_template == NULL) {
        fprintf(stderr, "Error: Invalid template name.\n");
        return NULL;
    }

    // Allocate memory for the data store
    Entry **data_store = malloc(num_entries * sizeof(Entry*));
    if (data_store == NULL) {
        perror("Failed to allocate memory for data store.");
        return NULL;
    }

    // Initialize each entry in the data store
    for (int i = 0; i < num_entries; i++) {
        data_store[i] = malloc(sizeof(Entry));
        if (data_store[i] == NULL) {
            perror("Failed to allocate memory for entry.");
            // Clean up previously allocated entries
            for (int j = 0; j < i; j++) {
                free(data_store[j]->payload);
                free(data_store[j]);
            }
            free(data_store);
            return NULL;
        }

        data_store[i]->id = i + 1;
        data_store[i]->timestamp = time(NULL);

        // Generate payload using the selected template's logic
        data_store[i]->payload = selected_template->generate_payload(max_payload_size);
        if (data_store[i]->payload == NULL) {
            fprintf(stderr, "Error: Failed to generate payload for entry %d.\n", i + 1);
            // Clean up previously allocated entries and payload
            for (int j = 0; j <= i; j++) {
                free(data_store[j]->payload);
                free(data_store[j]);
            }
            free(data_store);
            return NULL;
        }
    }

    return data_store;
}

// Example template registration function
