    if (data_store != NULL) {
        for (int i = 0; i < 5; i++) {
            printf("Entry %d: ID=%d, Payload=%s\n", i + 1, data_store[i]->id, data_store[i]->payload);
            free(data_store[i]->payload);
            free(data_store[i]);
        }
        free(data_store);
    }

    // Clean up global templates
    for (int i = 0; i < num_templates; i++) {
        free(templates[i].name);
    }
    free(templates);

    return 0;
}
