['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/time.h>

#define MAX_COMMAND_LENGTH 1024
#define MAX_DATA_SIZE 4096

typedef struct {
    char command[MAX_COMMAND_LENGTH];
    int success;
    char error_message[256];
} CommandResult;

typedef struct {
    char data[MAX_DATA_SIZE];
    int processed;
    char metadata[256];
} DataRecord;

typedef struct Node {
    union {
        CommandResult *command_result;
        DataRecord *data_record;
    } content;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    Node *tail;
    pthread_mutex_t lock;
} DynamicBuffer;

DynamicBuffer* create_buffer() {
    DynamicBuffer *buffer = (DynamicBuffer*)malloc(sizeof(DynamicBuffer));
    buffer->head = buffer->tail = NULL;
    pthread_mutex_init(&buffer->lock, NULL);
    return buffer;
}

void enqueue_command_result(DynamicBuffer *buffer, CommandResult *result) {
    Node *new_node = (Node*)malloc(sizeof(Node));
    new_node->content.command_result = result;
    new_node->next = NULL;
    pthread_mutex_lock(&buffer->lock);
    if (buffer->tail != NULL) {
        buffer->tail->next = new_node;
    } else {
        buffer->head = new_node;
    }
    buffer->tail = new_node;
    pthread_mutex_unlock(&buffer->lock);
}

void enqueue_data_record(DynamicBuffer *buffer, DataRecord *record) {
    Node *new_node = (Node*)malloc(sizeof(Node));
    new_node->content.data_record = record;
    new_node->next = NULL;
    pthread_mutex_lock(&buffer->lock);
    if (buffer->tail != NULL) {
        buffer->tail->next = new_node;
    } else {
        buffer->head = new_node;
    }
    buffer->tail = new_node;
    pthread_mutex_unlock(&buffer->lock);
}

void* process_commands_and_data(void *arg) {
    DynamicBuffer *buffer = (DynamicBuffer*)arg;
    while (1) {
        Node *current = NULL;
        pthread_mutex_lock(&buffer->lock);
        if (buffer->head != NULL) {
            current = buffer->head;
            buffer->head = buffer->head->next;
            if (buffer->head == NULL) {
                buffer->tail = NULL;
            }
        }
        pthread_mutex_unlock(&buffer->lock);

        if (current == NULL) {
            break; // No more commands or data records
        }

        if (current->content.command_result != NULL) {
            // Process command result
            printf("Processing command: %s\n", current->content.command_result->command);
            if (current->content.command_result->success) {
                printf("Command succeeded.\n");
            } else {
                printf("Command failed: %s\n", current->content.command_result->error_message);
            }
        } else if (current->content.data_record != NULL) {
            // Process data record
            printf("Processing data record: %s\n", current->content.data_record->data);
            if (current->content.data_record->processed) {
                printf("Data processed.\n");
            }
        }

        free(current); // Free the node after processing
    }
    return NULL;
}

void coordinate_file_and_data_management(DynamicBuffer *buffer, char **commands, int command_count, DataRecord *data_records, int data_count) {
    pthread_t thread;
    pthread_create(&thread, NULL, process_commands_and_data, buffer);

    for (int i = 0; i < command_count; i++) {
        CommandResult *result = (CommandResult*)malloc(sizeof(CommandResult));
        strcpy(result->command, commands[i]);
        result->success = rand() % 2 == 0 ? 1 : 0;
        if (!result->success) {
            sprintf(result->error_message, "Error processing command: %s", commands[i]);
        }
        enqueue_command_result(buffer, result);
    }

    for (int i = 0; i < data_count; i++) {
        enqueue_data_record(buffer, &data_records[i]);
    }

    pthread_join(thread, NULL);

    // Clean up
    while (buffer->head != NULL) {
        Node *current = buffer->head;
        buffer->head = buffer->head->next;
        free(current);
    }
    pthread_mutex_destroy(&buffer->lock);
}

int main() {
    DynamicBuffer *buffer = create_buffer();

    char *commands[] = {"create file", "read file", "update file", "delete file"};
    int command_count = sizeof(commands) / sizeof(commands[0]);

    DataRecord data_records[] = {
        {"record1", 1, "metadata1"},
        {"record2", 0, "metadata2"}
    };
    int data_count = sizeof(data_records) / sizeof(data_records[0]);

    coordinate_file_and_data_management(buffer, commands, command_count, data_records, data_count);

    free(buffer);
    return 0;
}
