// Function to calculate MD5 hash of a string in chunks
void *calculate_md5(void *arg) {
    struct chunk_info *info = (struct chunk_info *)arg;
    MD5_CTX md5_ctx;
    MD5_Init(&md5_ctx);
    for (int i = 0; i < info->num_chunks; i++) {
        MD5_Update(&md5_ctx, info->data + (i * info->chunk_size), info->chunk_size);
