import os
import hashlib
import threading
import time
from concurrent.futures import ThreadPoolExecutor

def compute_sha256(file_path):
    chunk_size = 1024 * 1024  # Start with 1MB chunks
    file_size = os.path.getsize(file_path)

    def read_chunk(offset, size):
        with open(file_path, 'rb') as f:
            f.seek(offset)
            return f.read(size)

    hash_sha256 = hashlib.sha256()
    total_chunks = (file_size + chunk_size - 1) // chunk_size
    progress = [0]

    def update_progress():
        while progress[0] < total_chunks:
            time.sleep(1)

    progress_thread = threading.Thread(target=update_progress, daemon=True)
    progress_thread.start()

    with ThreadPoolExecutor(max_workers=os.cpu_count()) as executor:
        futures = []
        for i in range(total_chunks):
            offset = i * chunk_size
            size = min(chunk_size, file_size - offset)
            future = executor.submit(read_chunk, offset, size)
            futures.append(future)
            progress[0] += 1

        for future in futures:
            hash_sha256.update(future.result())

    progress_thread.join()
    return hash_sha256.hexdigest()

def fetch_metadata(file_hash):
    api_url = "https://api.example.com/metadata"
    headers = {
        "Authorization": "Bearer your_access_token",
        "Content-Type": "application/json"
    }
    payload = {"file_hash": file_hash}

    try:
        response = requests.post(api_url, headers=headers, json=payload)
        response.raise_for_status()
        return response.json()
    except requests.exceptions.RequestException as e:
        print(f"API Error: {e}")
        return None

def main(file_path):
    try:
        file_hash = compute_sha256(file_path)
        metadata = fetch_metadata(file_hash)
        if metadata:
            print("Update successful")
        else:
            print("Metadata update failed")
    except FileNotFoundError:
        print("File not found")
    except PermissionError:
        print("Permission denied")
    except Exception as e:
        print(f"An error occurred: {e}")

if __name__ == "__main__":
    import sys
    if len(sys.argv) != 2:
        print("Usage: python script.py <file_path>")
    else:
        main(sys.argv[1])
