import hashlib
import threading
import logging
from queue import Queue
from concurrent.futures import ThreadPoolExecutor, as_completed

# Configure logging
logging.basicConfig(level=logging.INFO)

def md5_file(file_path):
    """Compute MD5 hash of a file."""
    hasher = hashlib.md5()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b""):
            hasher.update(chunk)
    return hasher.hexdigest()

def sha256_file(file_path):
    """Compute SHA-256 hash of a file."""
    hasher = hashlib.sha256()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b""):
            hasher.update(chunk)
    return hasher.hexdigest()

def compute_hash(file_path, algorithm='md5'):
    """Compute hash of a file using specified algorithm."""
    if algorithm == 'md5':
        return md5_file(file_path)
    elif algorithm == 'sha256':
        return sha256_file(file_path)
    else:
        raise ValueError("Unsupported algorithm")

def concurrent_hashing(file_paths, algorithm='md5', max_workers=4):
    """Compute hash of multiple files concurrently."""
    results = {}
    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        futures = {executor.submit(compute_hash, path, algorithm): path for path in file_paths}
        for future in as_completed(futures):
            try:
                result = future.result()
                path = futures[future]
                results[path] = result
            except Exception as e:
                logging.error(f"Error hashing file {futures[future]}: {e}")
    return results

# Example usage
file_paths = ['path/to/large/file1', 'path/to/large/file2']
hash_results = concurrent_hashing(file_paths, algorithm='sha256')
print(hash_results)
```

