import asyncio
import re
from datetime import datetime, timedelta

class USER_PROFILE:
    def __init__(self, user_id, profile_version, login_history):
        self.USER_ID = user_id
        self.PROFILE_VERSION = profile_version
        self.LOGIN_HISTORY = login_history

async def initialize_user_profiles(num_profiles):
    user_profiles = []
    login_history_set = set()

    keywords_regexes = {
        'login': re.compile(r'\blogin\b', re.IGNORECASE),
        'logout': re.compile(r'\blogout\b', re.IGNORECASE),
        'error': re.compile(r'\berror\b', re.IGNORECASE)
    }

    for i in range(num_profiles):
        user_id = f'U{i+1}'
        while True:
            login_history = generate_login_history()
            if login_history not in login_history_set and is_within_last_year(login_history):
                login_history_set.add(login_history)
                break
            await asyncio.sleep(0.1)  # Simulate network latency

        user_profiles.append(USER_PROFILE(user_id, 'v1', login_history))

    keyword_counts = {keyword: sum(keyword_regex.findall(' '.join(profile.LOGIN_HISTORY for profile in user_profiles))) for keyword, keyword_regex in keywords_regexes.items()}

    return keyword_counts

def generate_login_history():
    # Simulate generating a random login history
    return f'User logged in at {datetime.now()} and then logged out at {datetime.now() + timedelta(hours=1)}'

def is_within_last_year(entry):
    try:
        entry_datetime = datetime.strptime(entry, '%Y-%m-%d %H:%M:%S')
        return (datetime.now() - entry_datetime) <= timedelta(days=365)
    except ValueError:
        return False

# Example usage
async def main():
    result = await initialize_user_profiles(1000)
    print(result)

asyncio.run(main())
