        std::thread([this]() {
            std::this_thread::sleep_for(std::chrono::seconds(COOLDOWN_PERIOD));
            {
                std::lock_guard<std::mutex> lock(cooldownMutex);
                isOnCooldown = false;
                cooldownCV.notify_all();
            }
        }).detach();

        // Log ability execution
