        pthread_mutex_lock(&array->lock);
        while (array->count == 0 && array->memory_usage < MAX_MEMORY_USAGE) {
            pthread_cond_wait(&array->cond, &array->lock);
        }
        if (array->count == 0) break;
        pdu = array->messages[array->count - 1].pdu;
        result = validate_nas_pdu(pdu);
        // Handle validation result
        pthread_mutex_unlock(&array->lock);
    }

    return NULL;
}

void add_message(LTE_NAS_EMM_ARRAY *array, LTE_NAS_EMM_MESSAGE message) {
    pthread_mutex_lock(&array->lock);
    while (array->memory_usage + sizeof(message.pdu) > MAX_MEMORY_USAGE || array->count == array->capacity) {
        if (array->count == 0) break;
        pthread_cond_signal(&array->cond);
        pthread_cond_wait(&array->cond, &array->lock);
    }
    if (array->count < array->capacity) {
        memcpy(&array->messages[array->count], &message, sizeof(message));
        array->count++;
        array->memory_usage += sizeof(message.pdu);
        pthread_cond_signal(&array->cond);
    }
    pthread_mutex_unlock(&array->lock);
}

