#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define QUEUE_INIT_SIZE 10

typedef struct {
    int *data;
    int front;
    int rear;
    int size;
    int capacity;
    pthread_mutex_t lock;
} ThreadSafeQueue;

ThreadSafeQueue* queue_create() {
    ThreadSafeQueue *q = (ThreadSafeQueue*)malloc(sizeof(ThreadSafeQueue));
    q->data = (int*)malloc(QUEUE_INIT_SIZE * sizeof(int));
    q->front = 0;
    q->rear = -1;
    q->size = 0;
    q->capacity = QUEUE_INIT_SIZE;
    pthread_mutex_init(&q->lock, NULL);
    return q;
}

void queue_enqueue(ThreadSafeQueue *q, int value) {
    pthread_mutex_lock(&q->lock);
    if (q->size == q->capacity) {
        // Resize the queue
        q->capacity *= 2;
        q->data = realloc(q->data, q->capacity * sizeof(int));
    }
    q->rear = (q->rear + 1) % q->capacity;
    q->data[q->rear] = value;
    q->size++;
    pthread_mutex_unlock(&q->lock);
}

int queue_dequeue(ThreadSafeQueue *q) {
    int item;
    pthread_mutex_lock(&q->lock);
    if (q->size == 0) {
        // Handle empty queue
        return -1; // or throw an error
    }
    item = q->data[q->front];
    q->front = (q->front + 1) % q->capacity;
    q->size--;
    pthread_mutex_unlock(&q->lock);
    return item;
}

void queue_destroy(ThreadSafeQueue *q) {
    free(q->data);
    pthread_mutex_destroy(&q->lock);
    free(q);
}
