typedef struct {
    char protocol_id[10];
    time_t timestamp;
    char *payload;
} CustomPacket;

CustomPacket* update_system_config_with_custom_protocol(int num_packets, const char *data_format, size_t max_payload_size) {
    if (num_packets <= 0 || data_format == NULL || max_payload_size == 0) return NULL;

    CustomPacket *packets = malloc(num_packets * sizeof(CustomPacket));
    if (packets == NULL) return NULL;

    srand(time(NULL));

    for (int i = 0; i < num_packets; i++) {
        memset(packets[i].protocol_id, 0, sizeof(packets[i].protocol_id));
        memset(&packets[i].timestamp, 0, sizeof(packets[i].timestamp));
        packets[i].payload = malloc(max_payload_size);
        if (packets[i].payload == NULL) {
            for (int j = 0; j < i; j++) free(packets[j].payload);
            free(packets);
            return NULL;
        }

        // Generate unique protocol ID
        snprintf(packets[i].protocol_id, sizeof(packets[i].protocol_id), "proto%d", rand() % 1000);

        // Set timestamp
        packets[i].timestamp = time(NULL);

        // Generate payload based on data format
        size_t payload_size = rand() % max_payload_size + 1;
        snprintf(packets[i].payload, payload_size, "%s%d", data_format, rand());
    }

    return packets;
}

void free_packets(CustomPacket *packets, int num_packets) {
    for (int i = 0; i < num_packets; i++) {
        free(packets[i].payload);
    }
    free(packets);
}
