import os
import hashlib
import tempfile
from concurrent.futures import ThreadPoolExecutor, as_completed

def calculate_md5(file_path):
    # Calculate MD5 hash for a given file path
    hasher = hashlib.md5()
    with open(file_path, 'rb') as f:
        buf = f.read(4096)
        while len(buf) > 0:
            hasher.update(buf)
            buf = f.read(4096)
    return hasher.hexdigest()

def process_file(file_path):
    try:
        if os.path.islink(file_path):
            raise ValueError("Symlink detected")

        file_size = os.path.getsize(file_path)
        if file_size > 100 * 1024 * 1024:
            with tempfile.NamedTemporaryFile(delete=False) as tmp_file:
                # Handle large files by writing chunks to a temporary file
                pass

        md5_hash = calculate_md5(file_path)
        return file_path, md5_hash
    except Exception as e:
        return file_path, str(e)

def process_directory(directory):
    results = {}
    with ThreadPoolExecutor(max_workers=10) as executor:
        future_to_file = {executor.submit(process_file, os.path.join(directory, f)): f for f in os.listdir(directory)}
        for future in as_completed(future_to_file):
            file_path = future_to_file[future]
            try:
                file_path, md5_hash = future.result()
                results[file_path] = md5_hash
            except Exception as exc:
                print(f'File {file_path} generated an exception: {exc}')
    return results
