import os
import hashlib
import threading
from concurrent.futures import ThreadPoolExecutor, as_completed

def calculate_md5(file_path):
    md5_hash = hashlib.md5()
    with open(file_path, "rb") as f:
        for chunk in iter(lambda: f.read(4096), b""):
            md5_hash.update(chunk)
    return md5_hash.hexdigest()

def process_file(file_path, output_dict):
    try:
        if os.path.islink(file_path) or file_path.endswith(".enc"):
            return
        if os.stat(file_path).st_size > 1024 * 1024 * 100:  # 100 MB
            md5 = calculate_md5(file_path)
        else:
            with open(file_path, "rb") as f:
                md5 = hashlib.md5(f.read()).hexdigest()
        output_dict[file_path] = md5
    except Exception as e:
        print(f"Error processing {file_path}: {e}")

def process_directory(directory_path):
    output_dict = {}
    with ThreadPoolExecutor(max_workers=10) as executor:
        futures = {executor.submit(process_file, file_path, output_dict): file_path for file_path in os.listdir(directory_path)}
        for future in as_completed(futures):
            print(f"Processed {futures[future]}")
    return output_dict
```
