NFAPI_CRC_INDICATION_PDU_T* initialize_crc_indications(size_t N, uint8_t max_rx_ue_info_tag, uint16_t max_rnti, uint8_t max_crc_flag) {
    if (N == 0 || max_rx_ue_info_tag == 0 || max_rnti == 0 || max_crc_flag == 0) {
        return NULL; // Handle invalid input
    }

    NFAPI_CRC_INDICATION_PDU_T* array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array == NULL) {
        return NULL; // Handle memory allocation failure
    }

    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < N; ++i) {
        array[i].rx_ue_information_tag.RX_UE_INFORMATION_TAG = rand() % max_rx_ue_info_tag;
        array[i].rx_ue_information_tag.RNTI = rand() % max_rnti;
        array[i].crc_indication_rel8_tag.CRCFLAG = rand() % (max_crc_flag + 1);
    }

    // Validate the integrity of the structures
    for (size_t i = 0; i < N; ++i) {
        if (array[i].rx_ue_information_tag.RX_UE_INFORMATION_TAG >= max_rx_ue_info_tag ||
            array[i].rx_ue_information_tag.RNTI >= max_rnti ||
            array[i].crc_indication_rel8_tag.CRCFLAG > max_crc_flag) {
                free(array);
