#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_TRANSACTIONS 1000

typedef enum {
    TRANSACTION_PENDING,
    TRANSACTION_SUCCESS,
    TRANSACTION_FAILURE
} TRANSACTION_STATUS;

typedef struct {
    int TRANSACTION_ID;
    int SEQUENCE_NUMBER;
    int PAYLOAD_SIZE;
    TRANSACTION_STATUS STATUS;
} MAC_TRANSACTION_T;

typedef struct {
    MAC_TRANSACTION_T *transactions;
    int size;
    int capacity;
    pthread_mutex_t log_mutex;
} MAC_TRANSACTIONS_MANAGER_T;

void mac_transactions_manager_init(MAC_TRANSACTIONS_MANAGER_T *manager) {
    manager->transactions = NULL;
    manager->size = 0;
    manager->capacity = 0;
    pthread_mutex_init(&manager->log_mutex, NULL);
}

int mac_transactions_manager_add_transaction(MAC_TRANSACTIONS_MANAGER_T *manager, int sequence_number, int payload_size) {
    if (sequence_number <= 0 || payload_size <= 0) {
        fprintf(stderr, "Invalid input parameters.\n");
        return -1;
    }

    if (manager->size > 0 && manager->transactions[manager->size - 1].SEQUENCE_NUMBER == sequence_number) {
        fprintf(stderr, "Sequence number must be unique and not consecutive.\n");
        return -1;
    }

    if (manager->size >= manager->capacity) {
        int new_capacity = (manager->capacity == 0) ? 8 : manager->capacity * 2;
        MAC_TRANSACTION_T *new_transactions = realloc(manager->transactions, new_capacity * sizeof(MAC_TRANSACTION_T));
        if (!new_transactions) {
            fprintf(stderr, "Memory allocation failed.\n");
            return -1;
        }
        manager->transactions = new_transactions;
        manager->capacity = new_capacity;
    }

    MAC_TRANSACTION_T *new_transaction = &manager->transactions[manager->size++];
    new_transaction->TRANSACTION_ID = manager->size;
    new_transaction->SEQUENCE_NUMBER = sequence_number;
    new_transaction->PAYLOAD_SIZE = payload_size;
    new_transaction->STATUS = TRANSACTION_PENDING;

    return 0;
}

void mac_transactions_manager_log_status_change(MAC_TRANSACTIONS_MANAGER_T *manager, int transaction_id, TRANSACTION_STATUS new_status) {
    pthread_mutex_lock(&manager->log_mutex);
    for (int i = 0; i < manager->size; ++i) {
        if (manager->transactions[i].TRANSACTION_ID == transaction_id) {
            manager->transactions[i].STATUS = new_status;
