void mac_transactions_manager_free(MAC_TRANSACTIONS_MANAGER_T *manager) {
    free(manager->transactions);
    manager->transactions = NULL;
    manager->size = 0;
    manager->capacity = 0;
    pthread_mutex_destroy(&manager->log_mutex);
}
