    if (!array) {
        return NULL; // Handle allocation failure
    }

    for (int i = 0; i < size; i++) {
        array[i].RX_UE_INFORMATION_TAG = i;
        array[i].RNTI = rand() % 1024;
        array[i].CRC_INDICATION_REL8_TAG = (rand() % 2) == 0 ? true : false;
    }

    return array;
}

void freeNfaapiArray(NFAPI_CRC_INDICATION_PDU_T* array, int size) {
    if (array) {
        free(array);
    }
}

bool validateNfaapiArray(NFAPI_CRC_INDICATION_PDU_T* array, int size) {
    for (int i = 0; i < size; i++) {
        if (array[i].RX_UE_INFORMATION_TAG == -1 || array[i].RNTI > 1023) {
            return false;
        }
    }
    return true;
}

EVP_CIPHER_CTX* initializeAesCbcCipher(const char* password, int keyLength, int ivLength, const EVP_MD* hashFunc) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        return NULL; // Handle allocation failure
    }

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, NULL, NULL)) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL; // Handle initialization failure
    }

    if (keyLength != 32 || ivLength != 16) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL; // Handle invalid key or IV length
    }

    if (1 != EVP_EncryptInit_ex(ctx, NULL, hashFunc, (unsigned char*)password, NULL)) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL; // Handle password derivation failure
    }

    return ctx;
}

void cleanupAesCbcCipher(EVP_CIPHER_CTX* ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx);
    }
}
