import os
import hashlib
import tempfile
from cryptography.fernet import Fernet, InvalidToken

def process_directory(directory_path):
    file_hashes = {}
    fernet_key = Fernet.generate_key()
    cipher_suite = Fernet(fernet_key)

    def calculate_md5(file_path):
        md5_hash = hashlib.md5()
        with open(file_path, "rb") as file:
            for chunk in iter(lambda: file.read(4096), b""):
                md5_hash.update(chunk)
        return md5_hash.hexdigest()

    def process_large_file(large_file_path):
        temp_dir = tempfile.mkdtemp()
        temp_file_path = os.path.join(temp_dir, "large_file")
        with open(large_file_path, 'rb') as original_file:
            with open(temp_file_path, 'wb') as temp_file:
                for chunk in iter(lambda: original_file.read(4096), b""):
                    temp_file.write(chunk)
        file_hashes[large_file_path] = calculate_md5(temp_file_path)
        os.rmdir(temp_dir)

    for root, _, files in os.walk(directory_path):
        for file_name in files:
            file_path = os.path.join(root, file_name)
            if not os.path.islink(file_path) and file_name != "encrypted.txt":
                try:
                    with open(file_path, 'rb') as file:
                        file_data = file.read()
                        if file_data.startswith(b'gAAAAAB'):  # Assuming encrypted files start with this prefix
                            decrypted_data = cipher_suite.decrypt(file_data)
                            file_hashes[file_path] = calculate_md5(decrypted_data)
                        else:
                            file_hashes[file_path] = calculate_md5(file_data)
                except InvalidToken:
                    print(f"Failed to decrypt {file_path}")
                except Exception as e:
                    print(f"Error processing {file_path}: {e}")
            elif os.path.getsize(file_path) > 100 * 1024 * 1024:  # 100 MB
                process_large_file(file_path)

    return file_hashes
```

