#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct MLBD {
    unsigned char macAddress[6];
    int sequenceNumber;
    int sessionId;
    struct MLBD* next;
} MLBD;

typedef struct {
    MLBD** cache;
    size_t cacheSize;
    size_t cacheCapacity;
    pthread_mutex_t mutex;
    int totalCreated;
    int totalReleased;
} MlbManager;

MlbManager* mlbManagerCreate() {
    MlbManager* manager = (MlbManager*)malloc(sizeof(MlbManager));
    if (!manager) return NULL;
    manager->cache = NULL;
    manager->cacheSize = 0;
    manager->cacheCapacity = 16;
    manager->mutex = PTHREAD_MUTEX_INITIALIZER;
    manager->totalCreated = 0;
    manager->totalReleased = 0;

    manager->cache = (MLBD**)malloc(manager->cacheCapacity * sizeof(MLBD*));
    if (!manager->cache) {
        free(manager);
        return NULL;
    }

    for (size_t i = 0; i < manager->cacheCapacity; ++i) {
        manager->cache[i] = NULL;
    }

    return manager;
}

void mlbManagerDestroy(MlbManager* manager) {
    pthread_mutex_lock(&manager->mutex);
    while (manager->cacheSize > 0) {
        free(manager->cache[--manager->cacheSize]);
    }
    free(manager->cache);
    pthread_mutex_unlock(&manager->mutex);

    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

MLBD* mlbManagerAllocate(MlbManager* manager, unsigned char macAddress[6], int sessionId) {
    MLBD* newMlbd = (MLBD*)malloc(sizeof(MLBD));
    if (!newMlbd) return NULL;

    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->cacheSize; ++i) {
        if (!manager->cache[i]) {
            manager->cache[i] = newMlbd;
            break;
        }
    }

    if (manager->cacheSize == manager->cacheCapacity) {
        size_t newCapacity = manager->cacheCapacity * 2;
        MLBD** newCache = (MLBD**)realloc(manager->cache, newCapacity * sizeof(MLBD*));
        if (!newCache) {
            pthread_mutex_unlock(&manager->mutex);
            free(newMlbd);
            return NULL;
        }
        manager->cache = newCache;
        for (size_t i = manager->cacheSize; i < newCapacity; ++i) {
            manager->cache[i] = NULL;
        }
        manager->cacheCapacity = newCapacity;
    }

    newMlbd->next = NULL;
    newMlbd->sequenceNumber = 0; // Initialize sequence number
    memcpy(newMlbd->macAddress, macAddress, sizeof(macAddress));
    newMlbd->sessionId = sessionId;

    manager->totalCreated++;
    pthread_mutex_unlock(&manager->mutex);

    return newMlbd;
}

void mlbManagerRelease(MlbManager* manager, MLBD* mlbd) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->cacheSize; ++i) {
        if (manager->cache[i] == mlbd) {
            manager->cache[i] = NULL;
            break;
        }
    }

    free(mlbd);

    manager->totalReleased++;
    pthread_mutex_unlock(&manager->mutex);
}

void logMessage(const char* level, const char* message) {
    // Implement logging logic here
    printf("[%s] %s\n", level, message);
}
