void initialize_and_run_server(int num_connections, int *ports, int num_ports, int use_tls, char *tls_cert_path, char *tls_key_path,
                               int timeout_seconds, int keep_alive_enabled, int *log_condition) {
    uv_loop_t* loop = uv_default_loop();
    struct sockaddr_in bind_addr;
    memset(&bind_addr, 0, sizeof(bind_addr));
    bind_addr.sin_family = AF_INET;

    for (int i = 0; i < num_ports; ++i) {
        bind_addr.sin_port = htons(ports[i]);

        uv_tcp_t* server = (uv_tcp_t*)malloc(sizeof(uv_tcp_t));
        uv_tcp_init(loop, server);

        int r = uv_tcp_bind(server, (const struct sockaddr*)&bind_addr, 0);
        if (r < 0) {
            log_message("Cannot bind to port %d", ports[i]);
            continue;
        }

        r = uv_listen((uv_stream_t*)server, num_connections, [](uv_stream_t* server, int status) {
            if (status < 0) {
                // Handle connection error
                return;
            }
            // Handle new connection
        });

        if (r < 0) {
            log_message("Cannot listen on port %d", ports[i]);
            continue;
        }

        if (*log_condition == 1) {
            log_message("Server started on port %d", ports[i]);
        }
    }

    uv_run(loop, UV_RUN_DEFAULT);
}

int main() {
    int num_connections = 100;
    int ports[] = {8080, 8443};
    int num_ports = sizeof(ports) / sizeof(ports[0]);
    int use_tls = 1;
    char *tls_cert_path = "path/to/cert.pem";
    char *tls_key_path = "path/to/key.pem";
    int timeout_seconds = 60;
    int keep_alive_enabled = 1;
    int log_condition = 1;

    initialize_and_run_server(num_connections, ports, num_ports, use_tls, tls_cert_path, tls_key_path,
                               timeout_seconds, keep_alive_enabled, &log_condition);

    return 0;
}
