#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_CAPACITY 100000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} ArrayManager;

void init_array(ArrayManager *manager, size_t N, unsigned int seed) {
    pthread_mutex_lock(&manager->mutex);
    manager->capacity = MAX_CAPACITY < N ? MAX_CAPACITY : N;
    manager->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(manager->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        perror("Memory allocation failed");
        return;
    }
    for (size_t i = 0; i < N; ++i) {
        manager->array[i].RX_UE_INFORMATION_TAG = seed + i * 100;
        manager->array[i].RNTI = seed + i * 200;
        manager->array[i].CRCFLAG = rand_r(&seed) % 256;
    }
    manager->size = N;
    pthread_mutex_unlock(&manager->mutex);
}

int add_element(ArrayManager *manager, unsigned int RX_UE_INFORMATION_TAG, unsigned short RNTI, unsigned char CRCFLAG) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->size >= manager->capacity) {
        perror("Array is full");
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }
    manager->array[manager->size].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    manager->array[manager->size].RNTI = RNTI;
    manager->array[manager->size].CRCFLAG = CRCFLAG;
    ++manager->size;
    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

void free_array(ArrayManager *manager) {
    pthread_mutex_lock(&manager->mutex);
    free(manager->array);
    manager->array = NULL;
    manager->capacity = 0;
    manager->size = 0;
    pthread_mutex_unlock(&manager->mutex);
}

// Example usage
int main() {
    ArrayManager manager;
    pthread_mutex_init(&manager.mutex, NULL);

    init_array(&manager, 1000, time(NULL));
    add_element(&manager, 123456789, 5678, 1);

    free_array(&manager);
    pthread_mutex_destroy(&manager.mutex);
    return 0;
}
