#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_CAPACITY 10000
#define LOAD_FACTOR_THRESHOLD 0.75

typedef struct NFAPI_LTE_RX_UE_CONTEXT_T {
    int UE_ID;
    int PCI;
    int RRC_STATE;
} UE_CONTEXT;

typedef struct HashEntry {
    UE_CONTEXT ue_context;
    struct HashEntry *next;
} HashEntry;

typedef struct HashTable {
    HashEntry **buckets;
    int num_buckets;
    int size;
    pthread_mutex_t mutex;
} HashTable;

unsigned int hash_function(int key, int buckets) {
    return abs(key % buckets);
}

HashTable* create_hash_table(int num_buckets) {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    table->buckets = (HashEntry**)calloc(num_buckets, sizeof(HashEntry*));
    table->num_buckets = num_buckets;
    table->size = 0;
    pthread_mutex_init(&table->mutex, NULL);
    return table;
}

void insert_entry(HashTable *table, int UE_ID) {
    pthread_mutex_lock(&table->mutex);
    if (table->size / (double)table->num_buckets >= LOAD_FACTOR_THRESHOLD) {
        resize_hash_table(table, table->num_buckets * 2);
    }
    unsigned int index = hash_function(UE_ID, table->num_buckets);
    HashEntry *entry = (HashEntry*)malloc(sizeof(HashEntry));
    entry->ue_context.UE_ID = UE_ID;
    entry->ue_context.PCI = UE_ID % 100; // Example mapping
    entry->ue_context.RRC_STATE = UE_ID % 5 + 1; // Example mapping
    entry->next = table->buckets[index];
    table->buckets[index] = entry;
    table->size++;
    pthread_mutex_unlock(&table->mutex);
}

void resize_hash_table(HashTable *table, int new_num_buckets) {
    HashEntry **new_buckets = (HashEntry**)calloc(new_num_buckets, sizeof(HashEntry*));
    for (int i = 0; i < table->num_buckets; i++) {
        HashEntry *entry = table->buckets[i];
        while (entry != NULL) {
            unsigned int new_index = hash_function(entry->ue_context.UE_ID, new_num_buckets);
            HashEntry *next_entry = entry->next;
            entry->next = new_buckets[new_index];
            new_buckets[new_index] = entry;
            entry = next_entry;
        }
    }
    free(table->buckets);
    table->buckets = new_buckets;
    table->num_buckets = new_num_buckets;
}

void destroy_hash_table(HashTable *table) {
    for (int i = 0; i < table->num_buckets; i++) {
        HashEntry *entry = table->buckets[i];
        while (entry != NULL) {
            HashEntry *next_entry = entry->next;
            free(entry);
            entry = next_entry;
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->mutex);
    free(table);
}

int main() {
    HashTable *table = create_hash_table(10);

    for (int i = 0; i < 5000; i++) {
        insert_entry(table, i);
    }

    destroy_hash_table(table);
    return 0;
}
