import os
import hashlib
from multiprocessing import Pool
from concurrent.futures import ThreadPoolExecutor

def process_file(file_path):
    try:
        if not os.path.islink(file_path) and not is_encrypted(file_path):
            file_size = os.path.getsize(file_path)
            if file_size > 100 * 1024 * 1024:
                return {file_path: md5_hash_large_file(file_path)}
            else:
                return {file_path: md5_hash_small_file(file_path)}
    except Exception as e:
        print(f"Error processing {file_path}: {e}")
    return {}

def md5_hash_small_file(file_path):
    hasher = hashlib.md5()
    with open(file_path, 'rb') as f:
        while chunk := f.read(8192):
            hasher.update(chunk)
    return hasher.hexdigest()

def md5_hash_large_file(file_path):
    hasher = hashlib.md5()
    temp_file = tempfile.NamedTemporaryFile(delete=False)
    try:
        with open(file_path, 'rb') as large_file, open(temp_file.name, 'wb') as temp:
            while chunk := large_file.read(8192 * 1024):  # 8MB chunks
                hasher.update(chunk)
                temp.write(chunk)
        return hasher.hexdigest()
    finally:
        os.unlink(temp_file.name)

def is_encrypted(file_path):
    with open(file_path, 'rb') as f:
        header = f.read(16)  # Check the first 16 bytes for encryption header
        return b'encryption_header' in header

def process_directory(directory, num_processes=4):
    files_to_process = [os.path.join(root, file) for root, _, files in os.walk(directory) for file in files]
    with ThreadPoolExecutor(max_workers=num_processes) as executor:
        results = list(executor.map(process_file, files_to_process))
    return {key: value for result_dict in results for key, value in result_dict.items()}
