void selectAndCooldownAttack() {
    auto now = std::chrono::system_clock::now();

    if (lastAttack == 0 || now - lastAttackTime >= std::chrono::seconds(9)) {
        int selectedAttack;
        do {
            selectedAttack = dist(rng);
        } while (selectedAttack == lastAttack);

        lastAttack = selectedAttack;
        lastAttackTime = now;

        std::cout << "Selected Attack: " << selectedAttack << std::endl;
    }
}
