#define MAX_RECORDS 1000

typedef struct {
    int key;
    time_t timestamp;
} record;

long offset_array[MAX_RECORDS];
int key_array[MAX_RECORDS];
record records[MAX_RECORDS];

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_data_structure() {
    srand(time(NULL));
    for (int i = 0; i < MAX_RECORDS; i++) {
        key_array[i] = rand();
        offset_array[i] = i * sizeof(record);
        records[i].key = key_array[i];
        records[i].timestamp = time(NULL);
    }
}

void* insert_record(void* arg) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (records[i].key == 0) {
            records[i].key = rand();
            records[i].timestamp = time(NULL);
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void* delete_record(void* arg) {
    int key_to_delete = *(int*)arg;
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (records[i].key == key_to_delete) {
            records[i].key = 0;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void* lookup_record(void* arg) {
    int key_to_find = *(int*)arg;
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (records[i].key == key_to_find) {
            records[i].timestamp = time(NULL);
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void serialize_data_structure(const char* filename) {
    FILE* file = fopen(filename, "wb");
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (records[i].key != 0) {
            fwrite(&offset_array[i], sizeof(long), 1, file);
            fwrite(&records[i], sizeof(record), 1, file);
        }
    }
    fclose(file);
}

void deserialize_data_structure(const char* filename) {
    FILE* file = fopen(filename, "rb");
    int offset;
    while (fread(&offset, sizeof(long), 1, file)) {
        record new_record;
        fread(&new_record, sizeof(record), 1, file);
        records[offset / sizeof(record)] = new_record;
    }
    fclose(file);
}

