#include <stdlib.h>
#include <pthread.h>
#include <stdio.h>

typedef struct {
    uint8_t mac_address[6];
    uint16_t sequence_number;
} MAC_PDU;

typedef struct MLBD {
    MAC_PDU pdu;
    int session_id;
    struct MLBD *next;
} MLBD;

typedef struct {
    MLBD *head;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
    size_t cache_size;
    size_t max_sessions;
    size_t current_sessions;
    void (*log_message)(const char*, ...);
} MLBD_Manager;

MLBD_Manager* mlbd_manager_init(size_t initial_size, size_t max_sessions, void (*log_func)(const char*, ...)) {
    MLBD_Manager *manager = (MLBD_Manager*)malloc(sizeof(MLBD_Manager));
    if (!manager) {
        log_func("Failed to allocate memory for MLBD manager");
        return NULL;
    }

    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->cond_var, NULL);
    manager->cache_size = initial_size;
    manager->max_sessions = max_sessions;
    manager->current_sessions = 0;
    manager->log_message = log_func;

    return manager;
}

void mlbd_manager_release(MLBD_Manager *manager) {
    MLBD *mlbd, *tmp;
    pthread_mutex_lock(&manager->lock);
    mlbd = manager->head;
    while (mlbd) {
        tmp = mlbd;
        mlbd = mlbd->next;
        free(tmp);
    }
    manager->head = NULL;
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    pthread_cond_destroy(&manager->cond_var);
    free(manager);
}

MLBD* mlbd_manager_get(MLBD_Manager *manager, int session_id) {
    MLBD *mlbd, *prev = NULL;
    pthread_mutex_lock(&manager->lock);

    // Search for an existing MLBD with the given session ID
    for (mlbd = manager->head; mlbd != NULL; prev = mlbd, mlbd = mlbd->next) {
        if (mlbd->session_id == session_id && mlbd->session_id != -1) {
            // Move this MLBD to the front of the list for quick access
            if (prev) {
                prev->next = mlbd->next;
                mlbd->next = manager->head;
                manager->head = mlbd;
            }
            pthread_mutex_unlock(&manager->lock);
            return mlbd;
        }
    }

    // Check if we need to allocate a new MLBD
    if (manager->current_sessions < manager->max_sessions) {
        mlbd = (MLBD*)malloc(sizeof(MLBD));
        if (!mlbd) {
            manager->log_message("Failed to allocate memory for new MLBD");
            pthread_mutex_unlock(&manager->lock);
            return NULL;
        }

        // Initialize the new MLBD
        mlbd->session_id = session_id;
        mlbd->next = manager->head;
        manager->head = mlbd;
        manager->current_sessions++;

        pthread_mutex_unlock(&manager->lock);
        return mlbd;
    } else {
        manager->log_message("Session limit reached");
        pthread_mutex_unlock(&manager->lock);
        return NULL;
    }
}

void mlbd_manager_release_mlbd(MLBD_Manager *manager, MLBD *mlbd) {
    pthread_mutex_lock(&manager->lock);
    // Mark the MLBD as released (session ID -1)
    mlbd->session_id = -1;
    manager->log_message("Releasing MLBD for session %d", mlbd->session_id);

    // Move the MLBD to the end of the list for potential reuse
    MLBD *prev, *current = manager->head;
    while (current != mlbd) {
        prev = current;
        current = current->next;
    }
    if (prev)
        prev->next = mlbd->next;
    else
        manager->head = mlbd->next;
    mlbd->next = NULL;

    pthread_mutex_unlock(&manager->lock);
}

void mlbd_manager_log(const char* format, ...) {
    va_list args;
    va_start(args, format);
    vprintf(format, args);
    va_end(args);
}
```

