// Function to initialize the AES-256-CBC cipher
EVP_CIPHER_CTX* initCipher(const std::string& password, unsigned char* iv) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return nullptr;

    // Derive key using SHA-256
    unsigned char derivedKey[32];
    SHA256((unsigned char*)password.c_str(), password.size(), derivedKey);

    // Set up the cipher context
    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, derivedKey, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return nullptr;
    }

    return ctx;
}

// Function to execute a random attack with cooldown and logging
void executeRandomAttack(EVP_CIPHER_CTX* ctx, const std::vector<Attack>& attacks, 
                         unsigned char* iv, std::atomic<int>* damageLogIndex,
                         int& lastDamage, int& consecutiveSame) {
    static std::mutex mtx;
    std::lock_guard<std::mutex> lock(mtx);

    // Simulate random attack selection
    int attackId = rand() % attacks.size();
    if (attackId == consecutiveSame) {
        consecutiveSame = (consecutiveSame + 1) % attacks.size();
        if (consecutiveSame == attackId) consecutiveSame++;
    }
    Attack selectedAttack = attacks[attackId];

    // Simulate random delay
    std::this_thread::sleep_for(std::chrono::milliseconds(rand() % 101));

    // Log the damage
    int damage = selectedAttack.damage;
    *damageLogIndex += damage;

    // Print attack details
    std::cout << "Attacking with Attack " << selectedAttack.id << " for " << damage << " damage.\n";

    consecutiveSame = (consecutiveSame == attackId) ? (attackId + 1) % attacks.size() : consecutiveSame;
}

// Function to log total damage to file
void logDamageToFile(const std::string& filename, int* damageLogIndex) {
    static std::mutex mtx;
    std::lock_guard<std::mutex> lock(mtx);

    // Open the file for appending or create if it doesn't exist
    std::ofstream out(filename, std::ios_base::app | std::ios_base::ate);
    if (!out.is_open()) {
        std::cerr << "Failed to open damage log file.\n";
        return;
    }

    // Log the current damage and reset the index
    int totalDamage = *damageLogIndex;
    out << "Total Damage Logged: " << totalDamage << "\n";
    *damageLogIndex = 0;

    // Rotate the file every hour
    time_t now = time(nullptr);
    struct tm* timeinfo = localtime(&now);
    char filenameBuffer[256];
    snprintf(filenameBuffer, sizeof(filenameBuffer), "%s_%d-%m-%Y.log", "damage_log", timeinfo->tm_hour);
    out.close();
    std::rename(filename.c_str(), filenameBuffer);
}

// Main function to demonstrate the usage of executeRandomAttack
int main() {
    // Initialize attacks
    std::vector<Attack> attacks = {createAttack(1, 45), createAttack(2, 70), createAttack(3, 95),
                                   createAttack(4, 125), createAttack(5, 160)};

    unsigned char iv[AES_BLOCK_SIZE];
    if (!RAND_bytes(iv, sizeof(iv))) {
        std::cerr << "Failed to generate IV.\n";
        return -1;
    }

    EVP_CIPHER_CTX* ctx = initCipher("password", iv);
    if (!ctx) {
        std::cerr << "Failed to initialize cipher.\n";
        return -1;
    }

    std::atomic<int> damageLogIndex(0);
    int lastDamage = 0, consecutiveSame = 0;

    // Simulate concurrent attack executions
    std::vector<std::thread> threads;
    for (int i = 0; i < 100000; ++i) {
        threads.emplace_back(executeRandomAttack, ctx, attacks, iv, &damageLogIndex, lastDamage, consecutiveSame);
    }

    for (auto& t : threads) t.join();

    logDamageToFile("damage_log.txt", &damageLogIndex);

    // Cleanup
    EVP_CIPHER_CTX_free(ctx);
    for (auto& attack : attacks) cleanupAttack(attack);

    return 0;
}
