#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/sha.h>

#define MAX_USER_ID 100
#define MAX_NAME_LENGTH 50
#define MAX_EMAIL_LENGTH 100
#define MAX_PASSWORD_LENGTH 100

typedef struct {
    int id;
    char name[MAX_NAME_LENGTH];
    char email[MAX_EMAIL_LENGTH];
    char hashed_password[SHA256_DIGEST_LENGTH * 2 + 1];
} User;

User users[MAX_USER_ID];
int user_count = 0;
pthread_mutex_t mutex;

void hash_password(char* password, char* output_buffer) {
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char*)password, strlen(password), (unsigned char*)&hash);
    for(int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        sprintf(output_buffer + i * 2, "%02x", hash[i]);
    }
}

void* handle_request(void* arg) {
    // Simulate request handling logic
    pthread_mutex_lock(&mutex);
    for(int i = 0; i < user_count; ++i) {
        if(users[i].id == ((int)arg)) {
            printf("Updating user %d\n", users[i].id);
            strcpy(users[i].name, "New Name");
            strcpy(users[i].email, "newemail@example.com");
            // Update password securely
            hash_password("newpassword123", users[i].hashed_password);
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
    }
    printf("User not found %d\n", (int)arg);
    pthread_mutex_unlock(&mutex);
    return NULL;
}

int main() {
    pthread_t threads[5000];
    user_count = 1;
    users[0].id = 1;
    strcpy(users[0].name, "John Doe");
    strcpy(users[0].email, "john@example.com");
    hash_password("password123", users[0].hashed_password);

    pthread_mutex_init(&mutex, NULL);

    for(int i = 0; i < 5000; ++i) {
        pthread_create(&threads[i], NULL, handle_request, (void*)i);
    }

    for(int i = 0; i < 5000; ++i) {
        pthread_join(threads[i], NULL);
    }

    pthread_mutex_destroy(&mutex);
    return 0;
}
```

This code snippet demonstrates a basic structure for handling user account operations in a multi-threaded environment. It uses OpenSSL to securely hash passwords and implements a simple mutex to ensure thread safety. The main function creates multiple threads to simulate concurrent requests, updating a user's details in a shared data store (simulated with an array of `User` structs). This example provides a foundation for building upon with more complex logic, such as integrating with external databases, handling errors, and providing performance metrics.']

