#define MAX_TRANSACTIONS 1000

typedef struct {
    uint32_t TRANSACTION_ID;
    uint32_t SEQUENCE_NUMBER;
    uint32_t PAYLOAD_SIZE;
    uint8_t STATUS;
} MAC_TRANSACTION_T;

typedef struct {
    MAC_TRANSACTION_T *transactions;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} MAC_TRANSACTION_MANAGER_T;

void init_mac_transaction_manager(MAC_TRANSACTION_MANAGER_T *manager) {
    manager->transactions = malloc(MAX_TRANSACTIONS * sizeof(MAC_TRANSACTION_T));
    if (manager->transactions == NULL) {
        fprintf(stderr, "Failed to allocate memory for transaction manager\n");
        exit(EXIT_FAILURE);
    }
    manager->count = 0;
    manager->capacity = MAX_TRANSACTIONS;
    pthread_mutex_init(&manager->lock, NULL);
}

void free_mac_transaction_manager(MAC_TRANSACTION_MANAGER_T *manager) {
    free(manager->transactions);
    pthread_mutex_destroy(&manager->lock);
}

bool add_mac_transaction(MAC_TRANSACTION_MANAGER_T *manager, MAC_TRANSACTION_T transaction) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->capacity) {
        fprintf(stderr, "Transaction manager is full\n");
        pthread_mutex_unlock(&manager->lock);
        return false;
    }
    if (manager->count > 0 && manager->transactions[manager->count - 1].SEQUENCE_NUMBER == transaction.SEQUENCE_NUMBER) {
        fprintf(stderr, "Duplicate sequence number not allowed\n");
        pthread_mutex_unlock(&manager->lock);
        return false;
    }
    manager->transactions[manager->count++] = transaction;
    pthread_mutex_unlock(&manager->lock);
    return true;
}

void log_transaction_status(MAC_TRANSACTION_T *transaction) {
    // Implement logging mechanism here
    printf("Transaction ID: %u, Sequence Number: %u, Payload Size: %u, Status: %d\n",
           transaction->TRANSACTION_ID,
           transaction->SEQUENCE_NUMBER,
           transaction->PAYLOAD_SIZE,
           transaction->STATUS);
}

void process_transactions(MAC_TRANSACTION_MANAGER_T *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        MAC_TRANSACTION_T *transaction = &manager->transactions[i];
        if (transaction->STATUS != 0) {
            log_transaction_status(transaction);
        }
        // Add logic to handle transaction processing and status updates
    }
}
