#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RECORDS 1000

typedef struct {
    int key;
    time_t timestamp;
} Record;

void init_records(Record *records, long *offsets, int *keys) {
    srand(time(NULL));
    for (int i = 0; i < MAX_RECORDS; ++i) {
        keys[i] = rand();
        offsets[i] = i * sizeof(Record);
        records[i].key = keys[i];
        records[i].timestamp = time(NULL);
    }
}

void serialize_records(Record *records, long *offsets, int *keys, FILE *file) {
    for (int i = 0; i < MAX_RECORDS; ++i) {
        fseek(file, offsets[i], SEEK_SET);
        fwrite(&records[i], sizeof(Record), 1, file);
    }
}

void deserialize_records(Record *records, long *offsets, int *keys, FILE *file) {
    for (int i = 0; i < MAX_RECORDS; ++i) {
        fseek(file, offsets[i], SEEK_SET);
        fread(&records[i], sizeof(Record), 1, file);
    }
}

void insert_record(Record *records, long *offsets, int *keys, int new_key) {
    for (int i = 0; i < MAX_RECORDS; ++i) {
        if (keys[i] == -1) {
            keys[i] = new_key;
            records[i].key = new_key;
            records[i].timestamp = time(NULL);
            offsets[i] = i * sizeof(Record);
            return;
        }
    }
}

void delete_record(Record *records, long *offsets, int *keys, int key_to_delete) {
    for (int i = 0; i < MAX_RECORDS; ++i) {
        if (keys[i] == key_to_delete) {
            keys[i] = -1;
            records[i].key = -1;
            offsets[i] = -1;
            return;
        }
    }
}

void lookup_record(Record *records, int key_to_find) {
    for (int i = 0; i < MAX_RECORDS; ++i) {
        if (keys[i] == key_to_find) {
            printf("Key %d found at index %d\n", key_to_find, i);
            return;
        }
    }
    printf("Key %d not found\n", key_to_find);
}

int main() {
    Record records[MAX_RECORDS];
    long offsets[MAX_RECORDS];
    int keys[MAX_RECORDS];

    for (int i = 0; i < MAX_RECORDS; ++i) {
        keys[i] = -1;
    }

    init_records(records, offsets, keys);

    FILE *file = fopen("records.bin", "w+b");
    if (file == NULL) {
        perror("Error opening file");
        return EXIT_FAILURE;
    }

    serialize_records(records, offsets, keys, file);
    fclose(file);

    file = fopen("records.bin", "rb");
    if (file == NULL) {
        perror("Error opening file");
        return EXIT_FAILURE;
    }

    deserialize_records(records, offsets, keys, file);
    fclose(file);

    insert_record(records, offsets, keys, 12345);
    lookup_record(records, 12345);
    delete_record(records, offsets, keys, 12345);

    return EXIT_SUCCESS;
}
