#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    // Session metadata, socket information, network buffers, etc.
} CSCD;

typedef struct {
    CSCD** pool;
    size_t pool_size;
    size_t next_available;
    sem_t semaphore;
    pthread_mutex_t mutex;
} CSCDPool;

CSCDPool* cscd_pool_create(size_t initial_size) {
    CSCDPool* pool = (CSCDPool*)malloc(sizeof(CSCDPool));
    if (!pool) return NULL;

    pool->pool = (CSCD**)malloc(initial_size * sizeof(CSCD*));
    if (!pool->pool) {
        free(pool);
        return NULL;
    }

    for (size_t i = 0; i < initial_size; ++i) {
        pool->pool[i] = (CSCD*)malloc(sizeof(CSCD));
        if (!pool->pool[i]) {
            for (size_t j = 0; j < i; ++j) free(pool->pool[j]);
            free(pool->pool);
            free(pool);
            return NULL;
        }
    }

    pool->pool_size = initial_size;
    pool->next_available = 0;

    if (sem_init(&pool->semaphore, 0, initial_size) != 0 ||
        pthread_mutex_init(&pool->mutex, NULL) != 0) {
        for (size_t i = 0; i < initial_size; ++i) free(pool->pool[i]);
        free(pool->pool);
        free(pool);
        return NULL;
    }

    return pool;
}

void cscd_pool_destroy(CSCDPool* pool) {
    for (size_t i = 0; i < pool->pool_size; ++i) free(pool->pool[i]);
    free(pool->pool);
    sem_destroy(&pool->semaphore);
    pthread_mutex_destroy(&pool->mutex);
    free(pool);
}

CSCD* cscd_pool_get(CSCDPool* pool) {
    if (sem_wait(&pool->semaphore) != 0) return NULL;

    pthread_mutex_lock(&pool->mutex);
    CSCD* cscd = pool->pool[pool->next_available++];
    if (pool->next_available == pool->pool_size) {
        pool->next_available = 0;
    }
    pthread_mutex_unlock(&pool->mutex);

    return cscd;
}

void cscd_pool_put(CSCDPool* pool, CSCD* cscd) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->next_available == 0) {
        for (size_t i = 0; i < pool->pool_size; ++i) {
            if (pool->pool[i] == cscd) {
                pool->pool[i] = NULL;
                break;
            }
        }
    } else {
        pool->pool[--pool->next_available] = cscd;
    }
    pthread_mutex_unlock(&pool->mutex);

    sem_post(&pool->semaphore);
}
