#include <stdlib.h>
#include <pthread.h>
#include <stdio.h>

// Define a structure for Connection Specific Context Descriptor (CSCD)
typedef struct {
    int session_id;
    int socket_descriptor;
    char *network_buffer;
} CSCD;

// Define a structure for the pool of CSCDs
typedef struct {
    CSCD **cscd_pool;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} CSCDPool;

// Function to initialize the CSCD pool
CSCDPool* cscdpool_init(size_t initial_capacity) {
    CSCDPool *pool = (CSCDPool*)malloc(sizeof(CSCDPool));
    if (!pool) {
        perror("Failed to allocate memory for CSCD Pool");
        return NULL;
    }
    pool->cscd_pool = (CSCD**)malloc(initial_capacity * sizeof(CSCD*));
    if (!pool->cscd_pool) {
        perror("Failed to allocate memory for CSCD Pool Array");
        free(pool);
        return NULL;
    }
    pool->capacity = initial_capacity;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

// Function to add a CSCD to the pool
int cscdpool_add(CSCDPool *pool, CSCD *cscd) {
    if (pthread_mutex_lock(&pool->lock)) {
        perror("Failed to lock CSCD Pool");
        return -1;
    }
    if (pool->count >= pool->capacity) {
        pool->capacity *= 2;
        pool->cscd_pool = realloc(pool->cscd_pool, pool->capacity * sizeof(CSCD*));
        if (!pool->cscd_pool) {
            perror("Failed to reallocate memory for CSCD Pool Array");
            pthread_mutex_unlock(&pool->lock);
            return -1;
        }
    }
    pool->cscd_pool[pool->count++] = cscd;
    pthread_mutex_unlock(&pool->lock);
    return 0;
}

// Function to get a CSCD from the pool
CSCD* cscdpool_get(CSCDPool *pool, int session_id) {
    if (pthread_mutex_lock(&pool->lock)) {
        perror("Failed to lock CSCD Pool");
        return NULL;
    }
    for (size_t i = 0; i < pool->count; ++i) {
        if (pool->cscd_pool[i]->session_id == session_id) {
            pthread_mutex_unlock(&pool->lock);
            return pool->cscd_pool[i];
        }
    }
    pthread_mutex_unlock(&pool->lock);
    return NULL;
}

// Function to remove a CSCD from the pool
void cscdpool_remove(CSCDPool *pool, int session_id) {
    if (pthread_mutex_lock(&pool->lock)) {
        perror("Failed to lock CSCD Pool");
        return;
    }
    for (size_t i = 0; i < pool->count; ++i) {
        if (pool->cscd_pool[i]->session_id == session_id) {
            free(pool->cscd_pool[i]);
            for (size_t j = i; j < pool->count - 1; ++j) {
                pool->cscd_pool[j] = pool->cscd_pool[j + 1];
            }
            --pool->count;
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

// Function to destroy the CSCD pool
void cscdpool_destroy(CSCDPool *pool) {
    for (size_t i = 0; i < pool->count; ++i) {
        free(pool->cscd_pool[i]);
    }
    free(pool->cscd_pool);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}
