        list[i].RX_UE_INFORMATION_TAG = i + 1;
        list[i].RNTI = unique_rntis[i];
        list[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Assuming CRCFLAG can be 0 or 1
        list[i].CRCFLAG = list[i].CRC_INDICATION_REL8_TAG;
    }

