// Function to compute MD5 hash of a string
std::string computeMD5(const std::string& input) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)input.c_str(), input.length(), (unsigned char*)&digest);
    char mdString[33];
    for(int i = 0; i < 16; ++i)
        sprintf(&mdString[i*2], "%02x", (unsigned int)digest[i]);
    return std::string(mdString);
}

// Function to process strings and compute their MD5 hashes
std::unordered_map<std::string, std::string> computeMD5Hashes(const std::list<std::string>& inputList) {
    std::unordered_map<std::string, std::string> hashMap;
    for(const auto& item : inputList) {
        std::string md5Hash = computeMD5(item);
        hashMap[item] = md5Hash;
        std::cout << "Computed MD5 hash for: " << item << ", Hash: " << md5Hash << std::endl;
    }
    return hashMap;
}

