typedef struct {
    int key;
    long offset;
    int priority;
} record;

record records[RECORD_SIZE];
int record_count = 0;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_records() {
    srand(time(0));
    for (int i = 0; i < RECORD_SIZE; i++) {
        records[i].key = rand();
        records[i].offset = rand();
        records[i].priority = rand() % 10;
    }
    record_count = RECORD_SIZE;
}

void insert_record(int key, long offset, int priority) {
    pthread_mutex_lock(&lock);
    if (record_count < RECORD_SIZE) {
        records[record_count].key = key;
        records[record_count].offset = offset;
        records[record_count].priority = priority;
        record_count++;
    }
    pthread_mutex_unlock(&lock);
}

void delete_record(int key) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < record_count; i++) {
        if (records[i].key == key) {
            records[i] = records[record_count - 1];
            record_count--;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

void* lookup_record(int key) {
    for (int i = 0; i < record_count; i++) {
        if (records[i].key == key) {
            return &records[i];
        }
    }
    return NULL;
}

void serialize_records(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    fwrite(records, sizeof(record), record_count, file);
    fclose(file);
}

int deserialize_records(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return -1;
    }

    int count = fread(records, sizeof(record), RECORD_SIZE, file);
    fclose(file);
    record_count = count;
    return 0;
}
