struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
};

class ListNode {
public:
    NFAPI_CRC_INDICATION_PDU_T data;
    ListNode* next;

    ListNode(NFAPI_CRC_INDICATION_PDU_T data) : data(data), next(nullptr) {}
};

class LinkedList {
private:
    ListNode* head;
    std::mutex mtx;

public:
    LinkedList() : head(nullptr) {}

    ~LinkedList() {
        while (head != nullptr) {
            ListNode* temp = head;
            head = head->next;
            delete temp;
        }
    }

    bool insert(NFAPI_CRC_INDICATION_PDU_T data) {
        std::lock_guard<std::mutex> lock(mtx);
        if (find(data.RNTI)) return false;
        ListNode* newNode = new ListNode(data);
        newNode->next = head;
        head = newNode;
        return true;
    }

    bool find(int RNTI) {
        std::lock_guard<std::mutex> lock(mtx);
        ListNode* current = head;
        while (current != nullptr) {
            if (current->data.RNTI == RNTI) return true;
            current = current->next;
        }
        return false;
    }

    bool saveToFile(const std::string& path) {
        std::ofstream file(path, std::ios::binary);
        if (!file.is_open()) return false;

        ListNode* current = head;
        while (current != nullptr) {
            file.write(reinterpret_cast<char*>(&current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!file) return false;
            current = current->next;
        }

        file.close();
        return true;
    }
};

void generateAndManageNFACRCList() {
    LinkedList list;
    std::srand(std::time(0));

    for (int i = 0; i < 1000; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = rand();
        pdu.CRC_INDICATION_REL8_TAG = rand();
        pdu.CRCFLAG = (rand() % 2 == 0);

        if (!list.insert(pdu)) {
            std::cerr << "Duplicate RNTI detected, skipping entry." << std::endl;
        }
    }

    std::string directory = "/user/specified/directory/";
    std::string filePath = directory + "crc_indications.bin";

    if (list.saveToFile(filePath)) {
        std::cout << "CRC indications saved to file successfully." << std::endl;
    } else {
        std::cerr << "Failed to save CRC indications to file." << std::endl;
    }
}
