#define ERROR_OUT_OF_RANGE_POWER_LEVEL -3

// Function to initialize a buffer with default values
void initBuffer(MAC_TX_BUFFER_T *buffer) {
    memset(buffer, 0, sizeof(*buffer));
}

// Function to validate the sequence number and power level
int validateBuffer(const MAC_TX_BUFFER_T *current, const MAC_TX_BUFFER_T *previous, unsigned char minPowerLevel, unsigned char maxPowerLevel) {
    if (previous && current->seqNumber == previous->seqNumber) return ERROR_INVALID_SEQ_NUMBER;
    if (current->txPowerLevel < minPowerLevel || current->txPowerLevel > maxPowerLevel) return ERROR_OUT_OF_RANGE_POWER_LEVEL;
    return ERROR_NONE;
}

// Function to allocate and initialize a buffer collection
MAC_TX_BUFFER_T* allocateBuffers(int count, unsigned char minPowerLevel, unsigned char maxPowerLevel) {
    MAC_TX_BUFFER_T *buffers = (MAC_TX_BUFFER_T*)malloc(count * sizeof(MAC_TX_BUFFER_T));
    if (!buffers) return NULL;

    for (int i = 0; i < count; ++i) {
        initBuffer(&buffers[i]);
        if (validateBuffer(&buffers[i], i > 0 ? &buffers[i - 1] : NULL, minPowerLevel, maxPowerLevel)) {
