#include <string>
#include <unordered_map>
#include <openssl/md5.h>
#include <fstream>
#include <mutex>

// Define NFAPI_CRC_INDICATION_PDU_T structure
struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
};

// Function to generate and manage NFACRC list
void generateAndManageNFACRCList() {
    std::list<NFAPI_CRC_INDICATION_PDU_T> crcList;
    std::mutex mtx;

    // Generate unique RNTIs and add to the list
    for (int i = 0; i < 100; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = i * 1000;
        pdu.RNTI = i;
        pdu.CRC_INDICATION_REL8_TAG = i * 500;
        pdu.CRCFLAG = (rand() % 2) == 0;

        std::lock_guard<std::mutex> lock(mtx);
        if (std::find_if(crcList.begin(), crcList.end(), [pdu](const NFAPI_CRC_INDICATION_PDU_T& e) {
            return e.RNTI == pdu.RNTI;
        }) == crcList.end()) {
            crcList.push_back(pdu);
        }
    }

    // Serialize list to file
    std::ofstream ofs("crc_indications.bin", std::ios::binary);
    if (!ofs.is_open()) {
        std::cerr << "Failed to open file for writing" << std::endl;
        return;
    }

    for (const auto& pdu : crcList) {
        ofs.write(reinterpret_cast<const char*>(&pdu), sizeof(pdu));
    }
    ofs.close();
}

// Java method to compute MD5 hashes
std::unordered_map<std::string, std::string> computeMD5Hashes(const std::vector<std::string>& inputStrings) {
    std::unordered_map<std::string, std::string> hashMap;
    std::mutex mtx;

    for (const auto& str : inputStrings) {
        unsigned char digest[MD5_DIGEST_LENGTH];
        MD5((unsigned char*)str.c_str(), str.size(), (unsigned char*)&digest);

        char mdString[33];
        for(int i = 0; i < 16 ; ++i)
            sprintf(&mdString[i*2], "%02x", (unsigned int)digest[i]);

        std::lock_guard<std::mutex> lock(mtx);
        hashMap[str] = std::string(mdString);
    }

    return hashMap;
}
