# In-memory cache for transaction details
transaction_cache = {}

def rate_limiter(max_requests=10, period=60):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            ip_address = request.remote_addr
            current_time = time.time()
            user_requests = [t for t in request_times[ip_address] if current_time - t < period]

            if len(user_requests) >= max_requests:
                return jsonify({"error": "Rate limit exceeded"}), 429

            request_times[ip_address].append(current_time)
            if len(request_times[ip_address]) > max_requests:
                request_times[ip_address].pop(0)

            return func(*args, **kwargs)
        request_times = {}
        return wrapper
    return decorator

