import time
from functools import wraps
from collections import defaultdict

# Mocked payment gateway interface
class PaymentGateway:
    def __init__(self):
        self.transactions = {}

    def initiate_transaction(self, transaction_id, amount, currency, api_key):
        if transaction_id in self.transactions:
            return False
        # Simulate API key validation
        if not self.validate_api_key(api_key):
            return False
        self.transactions[transaction_id] = {'amount': amount, 'currency': currency, 'status': 'initiated'}
        return True

    def refund_transaction(self, transaction_id, amount, api_key):
        if transaction_id not in self.transactions:
            return False
        original_transaction = self.transactions[transaction_id]
        # Simulate API key validation
        if not self.validate_api_key(api_key):
            return False
        if original_transaction['amount'] < amount or original_transaction['status'] != 'initiated':
            return False
        original_transaction['status'] = 'refunded'
        return True

    def chargeback_transaction(self, transaction_id, api_key):
        if transaction_id not in self.transactions:
            return False
        original_transaction = self.transactions[transaction_id]
        # Simulate API key validation
        if not self.validate_api_key(api_key):
            return False
        if original_transaction['status'] != 'initiated':
            return False
        original_transaction['status'] = 'chargeback'
        return True

    def validate_api_key(self, api_key):
        # Simulated valid API keys
        valid_keys = ['key123', 'key456']
        return api_key in valid_keys

# Rate limiting decorator
def rate_limit(max_calls, period=60):
    calls = defaultdict(int)

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            ip_address = kwargs.get('ip_address')
            current_time = time.time()
            if ip_address not in calls:
                calls[ip_address] = [(current_time, func(*args, **kwargs))]
                return
            calls[ip_address] = [
                call for call in calls[ip_address]
                if current_time - call[0] <= period
            ]
            if len(calls[ip_address]) >= max_calls:
                raise Exception("Rate limit exceeded")
            calls[ip_address].append((current_time, func(*args, **kwargs)))
        return wrapper
    return decorator

# Main payment processing function
@rate_limit(10)
def process_transaction(payload):
    gateway = PaymentGateway()
    transaction_id = payload.get('transaction_id')
    amount = payload['amount']
    currency = payload['currency']
    sub_action = payload['sub_action']
    api_key = payload['api_key']
    ip_address = payload['ip_address']

    if sub_action == 'initiate':
        return gateway.initiate_transaction(transaction_id, amount, currency, api_key)
    elif sub_action == 'refund':
        return gateway.refund_transaction(transaction_id, amount, api_key)
    elif sub_action == 'chargeback':
        return gateway.chargeback_transaction(transaction_id, api_key)
    else:
        raise Exception("Invalid sub_action")

# Example usage
payload = {
    'transaction_id': 'tx12345',
    'amount': 100,
    'currency': 'USD',
    'sub_action': 'initiate',
    'api_key': 'key123',
    'ip_address': '192.168.1.1'
}
print(process_transaction(payload))
