            log_error(True, "Transaction initiated: %s", transaction_id)
            return {"status": "success", "message": "Transaction initiated"}

        elif sub_action == 'refund':
            if not transaction_data:
                raise ValueError("Transaction not found")
            payment_gateway.refund_transaction(transaction_id, amount)
            log_error(True, "Refund processed for transaction: %s", transaction_id)
            return {"status": "success", "message": "Refund processed"}

        elif sub_action == 'chargeback':
            if not transaction_data:
                raise ValueError("Transaction not found")
            payment_gateway.chargeback_transaction(transaction_id)
            log_error(True, "Chargeback processed for transaction: %s", transaction_id)
            return {"status": "success", "message": "Chargeback processed"}

    except Exception as e:
        log_error(True, "Error processing operation: %s", str(e))
        return {"status": "error", "message": str(e)}

# Example usage
