class InventoryManager {
    private $db;
    private $cache;

    public function __construct($db, $cache) {
        $this->db = $db;
        $this->cache = $cache;
    }

    public function handleRequest($request) {
        $data = json_decode($request, true);
        if (empty($data)) {
            return json_encode(['status' => 'error', 'message' => 'Invalid request']);
        }

        switch ($data['action'] ?? 'add') {
            case 'delete':
                return $this->deleteProduct($data['product_id']);
            case 'update':
            default:
                return $this->saveProduct($data);
        }
    }

    private function saveProduct($data) {
        if (!$this->validateData($data)) {
            return json_encode(['status' => 'error', 'message' => 'Validation failed']);
        }

        $product_id = $data['product_id'] ?? null;
        unset($data['action']);

        if ($product_id && $this->db->exists('products', ['product_id' => $product_id])) {
            $this->db->update('products', $data, ['product_id' => $product_id]);
            $this->cache->delete('product_' . $product_id);
            return json_encode(['status' => 'success', 'message' => 'Product updated']);
        } else {
            $new_product_id = $this->db->insert('products', $data);
            $this->cache->set('product_' . $new_product_id, $data);
            return json_encode(['status' => 'success', 'message' => 'Product created']);
        }
    }

    private function deleteProduct($product_id) {
        if ($this->db->delete('products', ['product_id' => $product_id])) {
            $this->cache->delete('product_' . $product_id);
            return json_encode(['status' => 'success', 'message' => 'Product deleted']);
        } else {
            return json_encode(['status' => 'error', 'message' => 'Product not found']);
        }
    }

    private function validateData($data) {
        // Implement validation logic here
        return true; // Placeholder for validation logic
    }

    public function getProducts($page = 1, $limit = 10) {
        $cached_key = 'products_page_' . $page;
        $products = $this->cache->get($cached_key);
        if (!$products) {
            $offset = ($page - 1) * $limit;
            $products = $this->db->select('products', [], ['limit' => $limit, 'offset' => $offset]);
            $this->cache->set($cached_key, $products, 3600); // Cache for 1 hour
        }

        return json_encode(['status' => 'success', 'message' => 'Products retrieved', 'data' => $products]);
    }
}

// Example usage:
