void* create_and_populate_list(void* arg) {
    int N = *(int*)arg; // Number of elements to populate
    pthread_mutex_lock(&list_lock);

    if (N > MAX_MEMORY_USAGE || list_size + N > max_list_size) {
        log_error("Memory usage exceeds threshold or list size limit");
        pthread_mutex_unlock(&list_lock);
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        if (i != 0 && list[i - 1].RNTI == rand() % MAX_RNTI) {
            log_error("Consecutive structures with the same RNTI");
            pthread_mutex_unlock(&list_lock);
            return NULL;
        }

        NFAPI_CRC_INDICATION_PDU_T new_element = {
            .RX_UE_INFORMATION_TAG = rand(),
            .NFAPI_L1_TAG = get_unique_NFAPI_L1_TAG(),
            .RNTI = rand() % MAX_RNTI,
            .CRCFLAG = (rand() % 2) ? 1 : 0
        };

        list[list_size++] = new_element;
    }

    pthread_mutex_unlock(&list_lock);
    return NULL;
}

