<?php

class InventoryManager {
    private $database;
    private $cache;

    public function __construct($dbConnection, $cacheService) {
        $this->database = $dbConnection;
        $this->cache = $cacheService;
    }

    public function handleRequest($requestPayload) {
        try {
            $data = json_decode($requestPayload, true);

            if (!isset($data['name']) || !isset($data['description']) || !isset($data['price']) || !isset($data['stock_quantity'])) {
                throw new Exception("Missing required fields.");
            }

            if (isset($data['product_id'])) {
                return $this->updateProduct($data);
            } elseif (isset($data['action']) && $data['action'] === 'delete') {
                return $this->deleteProduct($data);
            } else {
                return $this->getProducts($data);
            }
        } catch (Exception $e) {
            http_response_code(400);
            echo json_encode(['error' => $e->getMessage()]);
        }
    }

    private function updateProduct($data) {
        $sql = "UPDATE products SET name = ?, description = ?, price = ?, stock_quantity = ? WHERE product_id = ?";
        $stmt = $this->database->prepare($sql);
        $stmt->bind_param("ssdii", $data['name'], $data['description'], $data['price'], $data['stock_quantity'], $data['product_id']);

        if ($stmt->execute()) {
            return json_encode(['message' => 'Product updated successfully.']);
        } else {
            throw new Exception("Failed to update product.");
        }
    }

    private function deleteProduct($data) {
        $sql = "DELETE FROM products WHERE product_id = ?";
        $stmt = $this->database->prepare($sql);
        $stmt->bind_param("i", $data['product_id']);

        if ($stmt->execute()) {
            return json_encode(['message' => 'Product deleted successfully.']);
        } else {
            throw new Exception("Failed to delete product.");
        }
    }

    private function getProducts($data) {
        $page = isset($data['page_number']) ? intval($data['page_number']) : 1;
        $limit = isset($data['items_per_page']) ? intval($data['items_per_page']) : 10;

        $key = "products_page_{$page}_limit_{$limit}";
        if ($this->cache->exists($key)) {
            return $this->cache->get($key);
        }

        $offset = ($page - 1) * $limit;
        $sql = "SELECT * FROM products LIMIT ? OFFSET ?";
        $stmt = $this->database->prepare($sql);
        $stmt->bind_param("ii", $limit, $offset);
        $stmt->execute();
        $result = $stmt->get_result();

        if ($result) {
            $products = [];
            while ($row = $result->fetch_assoc()) {
                $products[] = $row;
            }

            $this->cache->set($key, json_encode($products), 3600); // Cache for 1 hour
            return json_encode($products);
        } else {
            throw new Exception("Failed to fetch products.");
        }
    }
}

