struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
};

class NFACRCListManager {
private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T*> list;

public:
    void generateAndManageNFACRCList() {
        // Generate unique RNTIs and create structures
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(1, 1000);

        for (int i = 0; i < 100; ++i) {
            int rnti = dis(gen);
            bool foundDuplicate = false;
            for (const auto& node : list) {
                if (node->RNTI == rnti) {
                    foundDuplicate = true;
                    break;
                }
            }
            if (!foundDuplicate) {
                NFAPI_CRC_INDICATION_PDU_T* newNode = new NFAPI_CRC_INDICATION_PDU_T;
                newNode->RX_UE_INFORMATION_TAG = i;
                newNode->RNTI = rnti;
                newNode->CRC_INDICATION_REL8_TAG = i;
                newNode->CRCFLAG = (rand() % 2 == 0);
                list.push_back(newNode);
            }
        }

        // Serialize the list to a file
        std::ofstream outFile("crc_indications.bin", std::ios::binary);
        if (!outFile.is_open()) {
            std::cerr << "Failed to open file for writing." << std::endl;
            return;
        }

        for (const auto& node : list) {
            outFile.write(reinterpret_cast<const char*>(node), sizeof(NFAPI_CRC_INDICATION_PDU_T));
        }

        outFile.close();
    }

    ~NFACRCListManager() {
        for (auto node : list) {
            delete node;
        }
    }
};

int main() {
    NFACRCListManager manager;
    manager.generateAndManageNFACRCList();
    return 0;
}
