import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

public class MD5Hasher {

    public static Map<String, String> computeMD5Hashes(List<String> strings) {
        Map<String, String> hashes = new HashMap<>();
        MessageDigest md;
        try {
            md = MessageDigest.getInstance("MD5");
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }

        for (String s : strings) {
            byte[] hashBytes = md.digest(s.getBytes());
            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                sb.append(String.format("%02x", b));
            }
            hashes.put(s, sb.toString());
        }

        return hashes;
    }

    public static void main(String[] args) {
        List<String> strings = Arrays.asList("example1", "example2");
        Map<String, String> hashes = computeMD5Hashes(strings);
        for (Map.Entry<String, String> entry : hashes.entrySet()) {
            System.out.println(entry.getKey() + ": " + entry.getValue());
        }
    }
}
