#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ENTRIES 50000

typedef struct {
    int RNTI;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T entries[MAX_ENTRIES];
int entry_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_entry(int RNTI, bool CRCFLAG) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < entry_count; i++) {
        if (entries[i].RNTI == RNTI) {
            entries[i] = (NFAPI_CRC_INDICATION_PDU_T){RNTI, CRCFLAG};
            pthread_mutex_unlock(&lock);
            return;
        }
    }
    if (entry_count < MAX_ENTRIES) {
        entries[entry_count++] = (NFAPI_CRC_INDICATION_PDU_T){RNTI, CRCFLAG};
    } else {
        printf("Error: Maximum entries reached\n");
    }
    pthread_mutex_unlock(&lock);
}

void remove_entry(int RNTI) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < entry_count; i++) {
        if (entries[i].RNTI == RNTI) {
            for (int j = i; j < entry_count - 1; j++) {
                entries[j] = entries[j + 1];
            }
            entry_count--;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

void update_entry(int RNTI, bool CRCFLAG) {
    add_entry(RNTI, CRCFLAG);
}

int get_entry_count() {
    return entry_count;
}

int get_crcflag_count() {
    int count = 0;
    pthread_mutex_lock(&lock);
    for (int i = 0; i < entry_count; i++) {
        if (entries[i].CRCFLAG) {
            count++;
        }
    }
    pthread_mutex_unlock(&lock);
    return count;
}

void* update_thread(void* arg) {
    int RNTI = *(int*)arg;
    free(arg);
    add_entry(RNTI, true); // Simulate update
    return NULL;
}

int main() {
    for (int i = 0; i < 100; i++) {
        int* rnti = malloc(sizeof(int));
        *rnti = i + 1;
        pthread_t thread;
        pthread_create(&thread, NULL, update_thread, rnti);
    }

    while (entry_count > 0) {
        sleep(1); // Simulate periodic updates
    }

    return 0;
}
