    size_t capacity;
} UE_CRC_Indication_List;

UE_CRC_Indication_List* create_crc_indication_list(size_t initial_capacity) {
    UE_CRC_Indication_List* list = (UE_CRC_Indication_List*)malloc(sizeof(UE_CRC_Indication_List));
    if (!list) return NULL;

    pthread_mutex_init(&list->lock, NULL);
    list->pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->pdu_list) {
        free(list);
        return NULL;
    }

    list->size = 0;
    list->capacity = initial_capacity;

    return list;
}

void destroy_crc_indication_list(UE_CRC_Indication_List* list) {
    if (list) {
        pthread_mutex_lock(&list->lock);
        free(list->pdu_list);
        pthread_mutex_unlock(&list->lock);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

void resize_crc_indication_list(UE_CRC_Indication_List* list, size_t new_capacity) {
    if (new_capacity <= list->capacity) return;

    NFAPI_CRC_INDICATION_PDU_T* new_pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->pdu_list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdu_list) return;

    list->pdu_list = new_pdu_list;
    list->capacity = new_capacity;
}

void add_crc_indication(UE_CRC_Indication_List* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) resize_crc_indication_list(list, list->capacity * 2);
    list->pdu_list[list->size++] = pdu;
    pthread_mutex_unlock(&list->lock);
}

