<?php
class UserAccountManager {
    private $db;
    private $cache;
    private $authService;
    private $rateLimiter;
    private $logger;

    public function __construct($db, $cache, $authService, $rateLimiter, $logger) {
        $this->db = $db;
        $this->cache = $cache;
        $this->authService = $authService;
        $this->rateLimiter = $rateLimiter;
        $this->logger = $logger;
    }

    public function handleRequest() {
        if (!$this->rateLimiter->allow($this->getIP(), 'user_action')) {
            return $this->errorResponse('Rate limit exceeded');
        }

        $token = $_REQUEST['token'];
        $userId = isset($_REQUEST['id']) ? intval($_REQUEST['id']) : null;
        $name = $_REQUEST['name'];
        $email = $_REQUEST['email'];
        $password = $_REQUEST['password'];
        $subAction = $_REQUEST['sub_action'];

        if (!$this->authService->validateToken($token)) {
            return $this->errorResponse('Invalid token');
        }

        try {
            switch ($subAction) {
                case 'create':
                    if ($this->userExists($email)) {
                        return $this->errorResponse('Email already in use');
                    }
                    $this->createUser($name, $email, $password);
                    break;
                case 'update':
                    if (!$userId || !$this->userExists($userId)) {
                        return $this->errorResponse('Invalid user ID');
                    }
                    $this->updateUser($userId, $name, $email, $password);
                    break;
                case 'delete':
                    if (!$userId || !$this->userExists($userId)) {
                        return $this->errorResponse('Invalid user ID');
                    }
                    $this->deleteUser($userId);
                    break;
                default:
                    return $this->errorResponse('Invalid sub-action');
            }

            $this->logAction($subAction, $userId);

            return $this->successResponse();
        } catch (Exception $e) {
            $this->logger->logError($e);
            return $this->errorResponse('Internal server error');
        }
    }

    private function userExists($emailOrId) {
        // Check if user exists in cache
        if ($user = $this->cache->get($emailOrId)) {
            return true;
        }

        // Query database for user
        $stmt = $this->db->prepare("SELECT COUNT(*) FROM users WHERE email = :email OR id = :id");
        $stmt->execute(['email' => $emailOrId, 'id' => $emailOrId]);
        $count = $stmt->fetchColumn();

        if ($count > 0) {
            // Store user in cache for future requests
            $this->cache->set($emailOrId, true);
            return true;
        }

        return false;
    }

    private function createUser($name, $email, $password) {
        // Hash and salt the password
        $hashedPassword = password_hash($password, PASSWORD_DEFAULT);

        // Insert user into database
        $stmt = $this->db->prepare("INSERT INTO users (name, email, password) VALUES (:name, :email, :password)");
        $stmt->execute(['name' => $name, 'email' => $email, 'password' => $hashedPassword]);

        // Store user in cache
        $this->cache->set($email, true);
    }

    private function updateUser($userId, $name, $email, $password) {
        if ($userId != $email && $this->userExists($email)) {
            return $this->errorResponse('Email already in use');
        }

        // Hash and salt the password
        $hashedPassword = password_hash($password, PASSWORD_DEFAULT);

        // Update user in database
        $stmt = $this->db->prepare("UPDATE users SET name = :name, email = :email, password = :password WHERE id = :id");
        $stmt->execute(['name' => $name, 'email' => $email, 'password' => $hashedPassword, 'id' => $userId]);

        // Update user in cache
        $this->cache->set($email, true);
    }

    private function deleteUser($userId) {
        // Delete user from database
        $stmt = $this->db->prepare("DELETE FROM users WHERE id = :id");
        $stmt->execute(['id' => $userId]);

        // Remove user from cache
        $this->cache->delete($userId);
    }

    private function getIP() {
        return $_SERVER['REMOTE_ADDR'];
    }

    private function successResponse() {
        return json_encode(['message' => 'success']);
    }

    private function errorResponse($message) {
        return json_encode(['message' => $message]);
    }

    private function logAction($action, $userId) {
        // Log action to centralized logging system
        $this->logger->log("User {$action} by user ID: {$userId}");
    }
}
