#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_CAPACITY 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    int count;
    int capacity;
    int initialized;
} crcArrayManager;

crcArrayManager* initCrcArray(int N, int seed) {
    crcArrayManager *manager = (crcArrayManager*)malloc(sizeof(crcArrayManager));
    manager->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->count = 0;
    manager->capacity = N;
    manager->initialized = 1;
    srand(seed);
    for(int i = 0; i < N; i++) {
        manager->array[i].RX_UE_INFORMATION_TAG = (seed * 100 + i) % MAX_CAPACITY;
        manager->array[i].RNTI = seed * 200 + i;
        manager->array[i].CRC_INDICATION_REL8_TAG = rand() % 256;
    }
    return manager;
}

void addElement(crcArrayManager *manager, int tag, int rnti) {
    if(manager->count >= manager->capacity) {
        printf("Array is full!\n");
        return;
    }
    manager->array[manager->count].RX_UE_INFORMATION_TAG = tag;
    manager->array[manager->count].RNTI = rnti;
    manager->array[manager->count].CRC_INDICATION_REL8_TAG = rand() % 256;
    manager->count++;
}

void freeCrcArray(crcArrayManager *manager) {
    free(manager->array);
    free(manager);
}

