<?php

class UserService {
    private $authService;
    private $cache;
    private $apiKey;

    public function __construct($authService, $cache, $apiKey) {
        $this->authService = $authService;
        $this->cache = $cache;
        $this->apiKey = $apiKey;
    }

    public function handleUserRequest($_REQUEST) {
        try {
            // Validate request parameters
            if (!isset($_REQUEST['name']) || !isset($_REQUEST['email']) || !isset($_REQUEST['password']) || !isset($_REQUEST['sub_action']) || !isset($_REQUEST['token'])) {
                throw new Exception("Invalid request parameters");
            }

            $id = isset($_REQUEST['id']) ? $_REQUEST['id'] : null;
            $name = $_REQUEST['name'];
            $email = $_REQUEST['email'];
            $password = $_REQUEST['password'];
            $sub_action = $_REQUEST['sub_action'];
            $token = $_REQUEST['token'];

            // Validate authentication token
            if (!$this->authService->validateToken($token, $this->apiKey)) {
                throw new Exception("Invalid authentication token");
            }

            // Validate email uniqueness
            if ($sub_action !== 'delete' && $this->cache->hasEmail($email)) {
                throw new Exception("Email already exists");
            }

            // Rate limiting and caching
            if (!$this->cache->rateLimitExceeded($email)) {
                throw new Exception("Rate limit exceeded");
            }

            switch ($sub_action) {
                case 'create':
                    $userId = $this->authService->createUser($name, $email, $password);
                    break;
                case 'update':
                    if (!$this->cache->validateMFA($id)) {
                        throw new Exception("Invalid MFA code");
                    }
                    $this->authService->updateUser($id, $name, $email, $password);
                    break;
                case 'delete':
                    if (!$this->cache->validateMFA($id)) {
                        throw new Exception("Invalid MFA code");
                    }
                    $this->authService->deleteUser($id);
                    break;
                default:
                    throw new Exception("Invalid sub_action");
            }

            // Log successful action
            error_log("User {$sub_action}: ID={$id}, Name={$name}, Email={$email}");

        } catch (Exception $e) {
            // Log exception
            error_log("Error: " . $e->getMessage());

            // Handle exceptions gracefully
            return ['status' => 'error', 'message' => $e->getMessage()];
        }

        return ['status' => 'success', 'message' => "User {$sub_action} successful"];
    }
}

