#include <string>
#include <random>
#include <unordered_set>
#include <filesystem>

struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
};

class NFACRCListManager {
public:
    static NFAPI_CRC_INDICATION_PDU_T* generateAndManageNFACRCList(const std::string& directory) {
        // Check directory validity
        if (!std::filesystem::is_directory(directory)) {
            std::cerr << "Invalid directory path." << std::endl;
            return nullptr;
        }

        static const int MAX_RNTI = 1000;
        static const int MIN_RNTI = 1;

        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(MIN_RNTI, MAX_RNTI);

        NFAPI_CRC_INDICATION_PDU_T* head = nullptr;
        NFAPI_CRC_INDICATION_PDU_T* current = nullptr;
        std::unordered_set<int> usedRNTIs;

        while (usedRNTIs.size() < 10) { // Assuming we want 10 unique RNTIs
            int rnti = dis(gen);
            if (!usedRNTIs.count(rnti)) {
                usedRNTIs.insert(rnti);

                NFAPI_CRC_INDICATION_PDU_T* newNode = new NFAPI_CRC_INDICATION_PDU_T;
                if (!newNode) {
                    std::cerr << "Memory allocation failed." << std::endl;
                    return nullptr;
                }

                newNode->RX_UE_INFORMATION_TAG = rnti;
                newNode->RNTI = rnti;
                newNode->CRC_INDICATION_REL8_TAG = rnti; // Assuming a simple mapping
                newNode->CRCFLAG = (dis(gen) % 2 == 0); // Randomly set CRCFLAG

                if (!head) {
                    head = newNode;
                } else {
                    current->next = newNode;
                }
                current = newNode;
            }
        }

        std::string filePath = directory + "/crc_indications.bin";
        std::ofstream outFile(filePath, std::ios::binary);
        if (!outFile.is_open()) {
            std::cerr << "Failed to open file for writing." << std::endl;
            return nullptr;
        }

        NFAPI_CRC_INDICATION_PDU_T* temp = head;
        while (temp) {
            outFile.write(reinterpret_cast<char*>(&temp->RX_UE_INFORMATION_TAG), sizeof(int));
            outFile.write(reinterpret_cast<char*>(&temp->RNTI), sizeof(int));
            outFile.write(reinterpret_cast<char*>(&temp->CRC_INDICATION_REL8_TAG), sizeof(int));
            outFile.write(reinterpret_cast<char*>(&temp->CRCFLAG), sizeof(bool));
            temp = temp->next;
        }

        outFile.close();

        return head;
    }
};

int main() {
    NFAPI_CRC_INDICATION_PDU_T* listHead = NFACRCListManager::generateAndManageNFACRCList("/path/to/directory");
    if (listHead) {
        // Handle the list as needed
    }
    return 0;
}
