MLBD* get_mlbd(int session_id, const MAC_PDU *pdu) {
    pthread_mutex_lock(&session_manager.mlbd_lock);
    for (size_t i = 0; i < session_manager.size; ++i) {
        if (session_manager.mlbd_list[i].pdu.sequence_number == pdu->sequence_number) {
            pthread_mutex_unlock(&session_manager.mlbd_lock);
            return &session_manager.mlbd_list[i];
        }
    }
    pthread_mutex_unlock(&session_manager.mlbd_lock);
    return allocate_mlbd(pdu);
}

void release_all_mlbd() {
    pthread_mutex_lock(&session_manager.mlbd_lock);
    for (size_t i = 0; i < session_manager.size; ++i) {
        release_mlbd(&session_manager.mlbd_list[i]);
    }
    free(session_manager.mlbd_list);
    session_manager.mlbd_list = NULL;
    session_manager.size = 0;
    pthread_mutex_unlock(&session_manager.mlbd_lock);
}

int main() {
    init_session_manager();
    // Simulate MLBD allocation and release
    MAC_PDU pdu = { {0x00, 0x1A, 0x2B, 0x3C, 0x4D, 0x5E}, 1 };
    MLBD *mlbd = get_mlbd(1, &pdu);
    if (mlbd != NULL) {
        printf("MLBD allocated for session with sequence number %d\n", mlbd->pdu.sequence_number);
        release_mlbd(mlbd);
    }
    release_all_mlbd();
    return 0;
}
