import hashlib
import os

def calculate_sha256(file_path, chunk_size=1024*1024):
    hasher = hashlib.sha256()
    try:
        with open(file_path, 'rb') as f:
            while True:
                data = f.read(chunk_size)
                if not data:
                    break
                hasher.update(data)
    except IOError as e:
        print(f"Error reading file: {e}")
        return None

    return hasher.hexdigest()
