#include <iostream>
#include <vector>
#include <mutex>
#include <atomic>
#include <thread>
#include <condition_variable>

struct TCP_CONNECTION_INFO {
    int sessionId;
    std::string ipAddress;
};

class StorageSystem {
public:
    StorageSystem(int capacity) : capacity(capacity), data(capacity, nullptr) {}

    ~StorageSystem() {
        for (auto& item : data) {
            delete item;
        }
    }

    bool addConnection(TCP_CONNECTION_INFO* connInfo) {
        std::unique_lock<std::mutex> lock(mutex);
        if (size >= capacity) return false;
        data[size++] = connInfo;
        return true;
    }

private:
    int capacity;
    TCP_CONNECTION_INFO** data;
    size_t size = 0;
    std::mutex mutex;
};

class ConnectionManager {
public:
    static ConnectionManager& getInstance() {
        static ConnectionManager instance;
        return instance;
    }

    void initializeConnectionAndStorageSystem(int initialCapacity) {
        storage.initialize(initialCapacity);
        invocationCount++;
        if (invocationCount % 10 == 0) {
            logInvocationCount();
        }
    }

private:
    ConnectionManager() {}
    ~ConnectionManager() {}

    StorageSystem storage;
    std::atomic<int> invocationCount = 0;

    void logInvocationCount() {
        // Log the number of times the function has been invoked
        std::cout << "Function invoked " << invocationCount.load() << " times." << std::endl;
    }
};

int main() {
    ConnectionManager& manager = ConnectionManager::getInstance();
    TCP_CONNECTION_INFO connInfo1 = {1, "192.168.1.1"};
    TCP_CONNECTION_INFO connInfo2 = {2, "192.168.1.2"};

    manager.initializeConnectionAndStorageSystem(5);
    if (manager.storage.addConnection(&connInfo1) && manager.storage.addConnection(&connInfo2)) {
        std::cout << "Connections added successfully." << std::endl;
    } else {
        std::cout << "Failed to add connections." << std::endl;
    }

    return 0;
}
```

