#include <dirent.h>
#include <sys/stat.h>
#include <openssl/md5.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PATH_LENGTH 2048
#define MAX_MD5_LENGTH 33
#define BUFFER_SIZE 1024 * 1024 * 100 // 100MB

int process_files(const char* dir_path, const char* output_dir_path, const char* log_file_path) {
    DIR *dir;
    struct dirent *ent;
    char full_path[MAX_PATH_LENGTH];
    FILE *log_file = fopen(log_file_path, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    dir = opendir(dir_path);
    if (dir == NULL) {
        perror("Could not open directory");
        fclose(log_file);
        return 1;
    }

    while ((ent = readdir(dir)) != NULL) {
        snprintf(full_path, sizeof(full_path), "%s/%s", dir_path, ent->d_name);
        struct stat file_stat;
        if (stat(full_path, &file_stat) != 0) {
            perror("Failed to get file status");
            continue;
        }

        if (!S_ISLNK(file_stat.st_mode)) {
            FILE *output_file = fopen(output_dir_path, "w");
            if (!output_file) {
                perror("Failed to open output file");
                continue;
            }

            unsigned char md5[MD5_DIGEST_LENGTH];
            MD5_CTX md5_ctx;
            MD5_Init(&md5_ctx);

            if (file_stat.st_size > BUFFER_SIZE) {
                // Handle large files
            } else {
                FILE *input_file = fopen(full_path, "rb");
                if (!input_file) {
                    perror("Failed to open input file");
                    fclose(output_file);
                    continue;
                }

                size_t bytes_read;
                char buffer[BUFFER_SIZE];
                while ((bytes_read = fread(buffer, 1, sizeof(buffer), input_file)) > 0) {
                    MD5_Update(&md5_ctx, buffer, bytes_read);
                }
                fclose(input_file);
            }

            MD5_Final(md5, &md5_ctx);

            // Write to log and output
            fprintf(log_file, "Processed %s\n", full_path);
            fprintf(output_file, "%s %s\n", full_path, md5);

            fclose(output_file);
        }
    }

    closedir(dir);
    fclose(log_file);
    return 0;
}
