#define MAX_UE_INSTANCES 1024

typedef struct {
    // Define your structure members here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *crc_ind_structs;
    size_t size;
    size_t allocated_size;
    pthread_mutex_t mutex;
} UE_Collection;

UE_Collection* create_ue_collection(size_t initial_size) {
    UE_Collection *collection = (UE_Collection *)malloc(sizeof(UE_Collection));
    if (!collection) return NULL;

    collection->crc_ind_structs = (NFAPI_CRC_INDICATION_PDU_T *)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!collection->crc_ind_structs) {
        free(collection);
        return NULL;
    }

    collection->size = 0;
    collection->allocated_size = initial_size;
    pthread_mutex_init(&collection->mutex, NULL);

    return collection;
}

void destroy_ue_collection(UE_Collection *collection) {
    if (collection->crc_ind_structs) free(collection->crc_ind_structs);
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}

int add_crc_indication(UE_Collection *collection, NFAPI_CRC_INDICATION_PDU_T new_struct) {
    pthread_mutex_lock(&collection->mutex);

    if (collection->size >= collection->allocated_size) {
        size_t new_size = collection->allocated_size * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(collection->crc_ind_structs, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&collection->mutex);
            return -1;
        }
        collection->crc_ind_structs = new_array;
        collection->allocated_size = new_size;
    }

    collection->crc_ind_structs[collection->size++] = new_struct;

    pthread_mutex_unlock(&collection->mutex);
    return 0;
}

int process_incoming_packets(UE_Collection *collection, NFAPI_CRC_INDICATION_PDU_T *incoming_packets, size_t packet_count) {
    for (size_t i = 0; i < packet_count; ++i) {
        if (incoming_packets[i].CRCFLAG != incoming_packets[i].RX_UE_INFORMATION_TAG.CRC_INDICATION_REL8_TAG.CRCFLAG) {
            // Handle discrepancy
        }
        add_crc_indication(collection, incoming_packets[i]);
    }
    return 0;
}
