        int maxConcurrentRequests = options.getIntValue("max-concurrent", DEFAULT_MAX_CONCURRENT_REQUESTS);
        long cacheLimit = options.getLongValue("cache-limit", DEFAULT_CACHE_LIMIT);
        int logLevel = options.getIntValue("log-level", DEFAULT_LOG_LEVEL);
        int timeout = options.getIntValue("timeout", DEFAULT_TIMEOUT);

        app.setMaxConcurrentRequests(maxConcurrentRequests);
        app.setCacheLimit(cacheLimit);
        app.setLogLevel(logLevel);
        app.setTimeout(timeout);

        if (locations.isEmpty()) {
            app.printHelp();
            return;
        }

        try (PrintStream out = outputFile != null ? new PrintStream(new FileOutputStream(outputFile)) : System.out) {
            app.processLocations(locations, timeframe, out);
