PHY_LAYER_STATS_RECORD_T* init_stats_records(uint32_t size, uint64_t seed, int log_level) {
    if (size == 0 || size > UINT32_MAX) {
        if (log_level >= LOG_ERROR) {
            // Log error message
        }
        return NULL;
    }

    PHY_LAYER_STATS_RECORD_T* records = malloc(size * sizeof(PHY_LAYER_STATS_RECORD_T));
    if (records == NULL) {
        if (log_level >= LOG_ERROR) {
            // Log memory allocation failure
        }
        return NULL;
    }

    srand(seed);

    for (uint32_t i = 0; i < size; i++) {
        records[i].TX_FRAME_ID = rand();
        strncpy(records[i].FRAME_TYPE, "DATA", sizeof(records[i].FRAME_TYPE) - 1);
        records[i].TX_POWER = ((float)(rand() % 100)) / 10.0;
        records[i].SNR = rand() % 30 + 50; // 50-80 dB
        records[i].BER = ((float)(rand() % 100)) / 1000.0;

        // Initialize TX_FRAME_HISTORY for each record
        TX_FRAME_HISTORY* history = malloc(sizeof(TX_FRAME_HISTORY));
        if (history == NULL) {
            if (log_level >= LOG_ERROR) {
                // Log memory allocation failure
            }
            free(records);
            return NULL;
        }

        history->RETRANSMISSION_COUNT = rand() % 5;
        history->LAST_TRANSMISSION_TIME = time(NULL) - (rand() % 86400); // Last transmission within the last day
        history->TRANSMISSION_SUCCESS_RATE = ((float)(rand() % 95)) / 10.0; // 95-100%

        records[i].TX_FRAME_HISTORY = history;
    }

    if (log_level >= LOG_INFO) {
        // Log successful allocation and initialization
    }

    return records;
}

// Function to cleanup the allocated resources
void cleanup_stats_records(PHY_LAYER_STATS_RECORD_T* records, uint32_t size) {
    for (uint32_t i = 0; i < size; i++) {
        free(records[i].TX_FRAME_HISTORY);
    }
    free(records);
}
