#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Node {
    int key;
    struct Node* next;
} Node;

typedef struct Record {
    int key;
    Node* nodePtr;
} Record;

Record** createRecords(int range, int count) {
    Record** records = (Record**)malloc(count * sizeof(Record*));
    for (int i = 0; i < count; ++i) {
        records[i] = (Record*)malloc(sizeof(Record));
        records[i]->key = rand() % range + 1;
        while (rand() % 2 == 0) { // Ensure uniqueness
            records[i]->key = rand() % range + 1;
        }
        records[i]->nodePtr = NULL;
    }
    return records;
}

void serializeRecords(Record** records, int count, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        printf("Failed to open file for writing.\n");
        return;
    }
    fwrite(records, sizeof(Record*), count, file);
    fclose(file);
}

void deserializeRecords(Record** records, int count, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        printf("Failed to open file for reading.\n");
        return;
    }
    fread(records, sizeof(Record*), count, file);
    fclose(file);
}

void insertNode(Node** head, int key) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->key = key;
    newNode->next = *head;
    *head = newNode;
}

Node* deleteNode(Node** head, int key) {
    Node* temp = *head;
    Node* prev = NULL;

    if (temp != NULL && temp->key == key) {
        *head = temp->next;
        free(temp);
        return *head;
    }

    while (temp != NULL && temp->key != key) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) {
        return *head;
    }

    prev->next = temp->next;

    free(temp);

    return *head;
}

Node* searchNode(Node* head, int key) {
    Node* current = head;
    while (current != NULL && current->key != key) {
        current = current->next;
    }
    return current;
}

int main() {
    srand(time(0));
    Record** records = createRecords(1000, 5);
    serializeRecords(records, 5, "records.bin");
    deserializeRecords(records, 5, "records.bin");

    Node* head = NULL;
    for (int i = 0; i < 5; ++i) {
        insertNode(&head, records[i]->key);
    }

    Node* result = searchNode(head, 342);
    if (result != NULL) {
        printf("Found key: %d\n", result->key);
    } else {
        printf("Key not found.\n");
    }

    head = deleteNode(&head, 342);

    return 0;
}
