};

int main() {
    ClusterManager manager;
    Node node1, node2;

    manager.addNode(&node1);
    manager.addNode(&node2);

    // Asynchronously add keys to the cluster
    auto addFuture1 = std::async(std::launch::async, [&manager]() { manager.getKeyFromNodes("key1"); });
    auto addFuture2 = std::async(std::launch::async, [&manager]() { manager.getKeyFromNodes("key2"); });

    // Wait for operations to complete
    addFuture1.get();
    addFuture2.get();

    return 0;
}
```

