#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int key;
    struct Node* node;
    struct Record* next;
} Record;

typedef struct Node {
    int data;
    struct Node* next;
} Node;

typedef struct DataManagementLibrary {
    Record** records;
    int capacity;
    int size;
} DataManagementLibrary;

DataManagementLibrary* createLibrary(int capacity) {
    DataManagementLibrary* library = (DataManagementLibrary*)malloc(sizeof(DataManagementLibrary));
    library->records = (Record**)calloc(capacity, sizeof(Record*));
    library->capacity = capacity;
    library->size = 0;
    return library;
}

void destroyLibrary(DataManagementLibrary* library) {
    for (int i = 0; i < library->capacity; ++i) {
        Record* record = library->records[i];
        while (record != NULL) {
            Node* node = record->node;
            free(record);
            record = node;
        }
    }
    free(library->records);
    free(library);
}

int insertRecord(DataManagementLibrary* library, int key, int data) {
    if (library->size >= library->capacity) return -1; // Full
    Record* record = (Record*)malloc(sizeof(Record));
    record->key = key;
    Node* node = (Node*)malloc(sizeof(Node));
    node->data = data;
    node->next = NULL;
    record->node = node;
    record->next = library->records[key % library->capacity];
    library->records[key % library->capacity] = record;
    library->size++;
    return 0;
}

Node* lookupRecord(DataManagementLibrary* library, int key) {
    Record* record = library->records[key % library->capacity];
    while (record != NULL && record->key != key) {
        record = record->next;
    }
    if (record == NULL) return NULL; // Not Found
    return record->node;
}

int deleteRecord(DataManagementLibrary* library, int key) {
    Record** prev = &library->records[key % library->capacity];
    while (*prev != NULL && (*prev)->key != key) {
        prev = &(*prev)->next;
    }
    if (*prev == NULL) return -1; // Not Found
    Record* record = *prev;
    Node* node = record->node;
    *prev = record->next;
    free(record);
    free(node);
    library->size--;
    return 0;
}

void serializeLibrary(DataManagementLibrary* library, const char* filename) {
    FILE* file = fopen(filename, "wb");
    fwrite(&library->capacity, sizeof(int), 1, file);
    fwrite(&library->size, sizeof(int), 1, file);
    for (int i = 0; i < library->capacity; ++i) {
        Record* record = library->records[i];
        while (record != NULL) {
            fwrite(&record->key, sizeof(int), 1, file);
            Node* node = record->node;
            fwrite(&node->data, sizeof(int), 1, file);
            fwrite(&node->next, sizeof(Node*), 1, file);
            record = record->next;
        }
    }
    fclose(file);
}

void deserializeLibrary(DataManagementLibrary* library, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (fread(&library->capacity, sizeof(int), 1, file) != 1 || fread(&library->size, sizeof(int), 1, file) != 1) return;
    free(library->records);
    library->records = (Record**)calloc(library->capacity, sizeof(Record*));
    for (int i = 0; i < library->capacity; ++i) {
        int key;
        while (fread(&key, sizeof(int), 1, file) == 1) {
            Record* record = (Record*)malloc(sizeof(Record));
            record->key = key;
            Node* node = (Node*)malloc(sizeof(Node));
            fread(&node->data, sizeof(int), 1, file);
            fread(&node->next, sizeof(Node*), 1, file);
            record->node = node;
            record->next = library->records[key % library->capacity];
            library->records[key % library->capacity] = record;
        }
    }
    fclose(file);
}

int main() {
    srand(time(NULL));
    DataManagementLibrary* library = createLibrary(100);
    insertRecord(library, rand(), 42);
    Node* node = lookupRecord(library, rand());
    deleteRecord(library, rand());
    serializeLibrary(library, "library.dat");
    destroyLibrary(library);
    return 0;
}
