#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RECORDS 10000
#define RANGE_START 1
#define RANGE_END 100000

typedef struct Node {
    int key;
    struct Node* next;
} Node;

typedef struct Record {
    int key;
    Node* node;
} Record;

Record records[MAX_RECORDS];
int record_count = 0;
Node* head = NULL;

void generate_unique_key(int *key) {
    do {
        *key = RANGE_START + rand() % (RANGE_END - RANGE_START + 1);
    } while (record_exists(*key));
}

int record_exists(int key) {
    for (int i = 0; i < record_count; ++i) {
        if (records[i].key == key) return 1;
    }
    return 0;
}

void insert_record(int key) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->key = key;
    new_node->next = head;
    head = new_node;

    Record new_record;
    new_record.key = key;
    new_record.node = new_node;
    records[record_count++] = new_record;
}

void delete_record(int key) {
    Node** current = &head;
    while (*current != NULL) {
        if ((*current)->key == key) {
            Node* temp = *current;
            *current = (*current)->next;
            free(temp);
            return;
        }
        current = &(*current)->next;
    }
}

Node* find_record(int key) {
    for (int i = 0; i < record_count; ++i) {
        if (records[i].key == key) return records[i].node;
    }
    return NULL;
}

void serialize_records(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&record_count, sizeof(int), 1, file);
    for (int i = 0; i < record_count; ++i) {
        fwrite(&records[i].key, sizeof(int), 1, file);
    }
    fclose(file);
}

void deserialize_records(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return;

    fread(&record_count, sizeof(int), 1, file);
    for (int i = 0; i < record_count; ++i) {
        int key;
        fread(&key, sizeof(int), 1, file);

        Node* new_node = (Node*)malloc(sizeof(Node));
        new_node->key = key;
        new_node->next = head;
        head = new_node;

        records[i].key = key;
        records[i].node = new_node;
    }
    fclose(file);
}

int main() {
    srand(time(NULL));

    // Example usage
    insert_record(42);
    Node* node = find_record(42);
    if (node) printf("Node found: %d\n", node->key);

    serialize_records("records.dat");

    record_count = 0;
    deserialize_records("records.dat");

    node = find_record(42);
    if (node) printf("Node found after deserialization: %d\n", node->key);

    delete_record(42);
    node = find_record(42);
    if (!node) printf("Node deleted successfully.\n");

    return 0;
}
