#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_IP_LENGTH 16

typedef struct Node {
    char ip[MAX_IP_LENGTH];
    int port;
    float latency;
    struct Node* neighbors[10]; // Assuming each node can connect to at most 10 other nodes
    int neighbor_count;
    pthread_mutex_t lock;
} Node;

Node* network = NULL;

// Function to add a new node to the network
void add_node(const char* ip, int port, float latency) {
    if (network == NULL) {
        network = (Node*)malloc(sizeof(Node));
        strcpy(network->ip, ip);
        network->port = port;
        network->latency = latency;
        network->neighbor_count = 0;
        pthread_mutex_init(&network->lock, NULL);
    } else {
        Node* current = network;
        while (current != NULL) {
            if (strcmp(current->ip, ip) == 0) {
                printf("Node with IP %s already exists.\n", ip);
                return;
            }
            current = current->neighbors[current->neighbor_count - 1];
        }
        Node* new_node = (Node*)malloc(sizeof(Node));
        strcpy(new_node->ip, ip);
        new_node->port = port;
        new_node->latency = latency;
        new_node->neighbor_count = 0;
        pthread_mutex_init(&new_node->lock, NULL);

        current->neighbors[current->neighbor_count++] = new_node;
    }
}

// Function to remove a node from the network
void remove_node(const char* ip) {
    if (network == NULL) {
        printf("Network is empty.\n");
        return;
    }

    Node* current = network;
    Node* previous = NULL;

    while (current != NULL) {
        if (strcmp(current->ip, ip) == 0) {
            if (previous == NULL) {
                network = current->neighbors[0];
            } else {
                for (int i = 0; i < current->neighbor_count - 1; i++) {
                    previous->neighbors[i] = current->neighbors[i + 1];
                }
                previous->neighbor_count--;
            }
            pthread_mutex_destroy(&current->lock);
            free(current);
            return;
        }

        Node* temp = current;
        current = current->neighbors[current->neighbor_count - 1];
        previous = temp;
    }

    printf("Node with IP %s not found.\n", ip);
}

// Function to update a node's metadata
void update_node(const char* ip, int new_port, float new_latency) {
    Node* current = network;

    while (current != NULL) {
        if (strcmp(current->ip, ip) == 0) {
            pthread_mutex_lock(&current->lock);
            current->port = new_port;
            current->latency = new_latency;
            pthread_mutex_unlock(&current->lock);
            return;
        }
        current = current->neighbors[current->neighbor_count - 1];
    }

    printf("Node with IP %s not found.\n", ip);
}

// Function to perform breadth-first search on the network
void bfs() {
    if (network == NULL) {
        printf("Network is empty.\n");
        return;
    }

    Node* current = network;

    while (current != NULL) {
        printf("Node IP: %s, Port: %d, Latency: %.2f\n", current->ip, current->port, current->latency);
        current = current->neighbors[current->neighbor_count - 1];
    }
}

// Function to perform depth-first search on the network
void dfs(Node* node) {
    if (node == NULL) {
        return;
    }

    printf("Node IP: %s, Port: %d, Latency: %.2f\n", node->ip, node->port, node->latency);

    for (int i = 0; i < node->neighbor_count; i++) {
        dfs(node->neighbors[i]);
    }
}

// Function to handle concurrent updates using mutex locks
void* thread_function(void* arg) {
    Node* current = network;
    pthread_mutex_lock(&current->lock);
    current->port++;
    pthread_mutex_unlock(&current->lock);

    return NULL;
}
