#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    int value;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record *records;
    int capacity;
    int size;
    pthread_mutex_t lock;
} DynamicCollection;

DynamicCollection* create_collection(int initial_capacity) {
    DynamicCollection *collection = (DynamicCollection*)malloc(sizeof(DynamicCollection));
    collection->capacity = initial_capacity;
    collection->size = 0;
    collection->offsets = (long*)malloc(initial_capacity * sizeof(long));
    collection->keys = (int*)malloc(initial_capacity * sizeof(int));
    collection->records = (Record*)malloc(initial_capacity * sizeof(Record));
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void destroy_collection(DynamicCollection *collection) {
    free(collection->offsets);
    free(collection->keys);
    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int add_record(DynamicCollection *collection, int key, int value) {
    pthread_mutex_lock(&collection->lock);
    if (collection->size == collection->capacity) {
        // Resize the arrays
        int new_capacity = collection->capacity * 2;
        long *new_offsets = (long*)realloc(collection->offsets, new_capacity * sizeof(long));
        int *new_keys = (int*)realloc(collection->keys, new_capacity * sizeof(int));
        Record *new_records = (Record*)realloc(collection->records, new_capacity * sizeof(Record));

        if (!new_offsets || !new_keys || !new_records) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Memory allocation failed
        }

        collection->offsets = new_offsets;
        collection->keys = new_keys;
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    for (int i = 0; i < collection->size; i++) {
        if (collection->keys[i] == key) {
            pthread_mutex_unlock(&collection->lock);
            return -2; // Duplicate key
        }
    }

    collection->offsets[collection->size] = (long)((char*)&collection->records[collection->size] - (char*)collection);
    collection->keys[collection->size] = key;
    collection->records[collection->size].value = value;
    collection->size++;
    pthread_mutex_unlock(&collection->lock);
    return 0; // Success
}

int update_record(DynamicCollection *collection, int key, int new_value) {
    pthread_mutex_lock(&collection->lock);
    for (int i = 0; i < collection->size; i++) {
        if (collection->keys[i] == key) {
            collection->records[i].value = new_value;
            pthread_mutex_unlock(&collection->lock);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&collection->lock);
    return -1; // Key not found
}

void print_collection(DynamicCollection *collection) {
    for (int i = 0; i < collection->size; i++) {
        printf("Key: %d, Value: %d\n", collection->keys[i], collection->records[i].value);
    }
}
