#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Node {
    char ip[16];
    int port;
    float latency;
    int bandwidth;
    struct Node* next;
} Node;

typedef struct NetworkTopology {
    Node** nodes;
    int size;
    int capacity;
    pthread_mutex_t lock;
} NetworkTopology;

NetworkTopology* create_network_topology() {
    NetworkTopology* topology = (NetworkTopology*)malloc(sizeof(NetworkTopology));
    topology->nodes = NULL;
    topology->size = 0;
    topology->capacity = 10;
    pthread_mutex_init(&topology->lock, NULL);
    return topology;
}

void free_network_topology(NetworkTopology* topology) {
    for (int i = 0; i < topology->size; i++) {
        Node* node = topology->nodes[i];
        while (node != NULL) {
            Node* next = node->next;
            free(node);
            node = next;
        }
    }
    pthread_mutex_destroy(&topology->lock);
    free(topology->nodes);
    free(topology);
}

int add_node(NetworkTopology* topology, char* ip, int port, float latency, int bandwidth) {
    pthread_mutex_lock(&topology->lock);
    if (topology->size >= topology->capacity) {
        Node** new_nodes = (Node**)realloc(topology->nodes, topology->capacity * 2 * sizeof(Node*));
        if (new_nodes == NULL) {
            pthread_mutex_unlock(&topology->lock);
            return -1;
        }
        topology->nodes = new_nodes;
        topology->capacity *= 2;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        pthread_mutex_unlock(&topology->lock);
        return -1;
    }
    strcpy(new_node->ip, ip);
    new_node->port = port;
    new_node->latency = latency;
    new_node->bandwidth = bandwidth;
    new_node->next = topology->nodes[topology->size];
    topology->nodes[topology->size] = new_node;
    topology->size++;
    pthread_mutex_unlock(&topology->lock);
    return 0;
}

void remove_node(NetworkTopology* topology, char* ip) {
    pthread_mutex_lock(&topology->lock);
    for (int i = 0; i < topology->size; i++) {
        Node** current = &topology->nodes[i];
        while (*current != NULL) {
            if (strcmp((*current)->ip, ip) == 0) {
                Node* temp = *current;
                *current = (*current)->next;
                free(temp);
                break;
            }
            current = &(*current)->next;
        }
    }
    pthread_mutex_unlock(&topology->lock);
}

void update_node(NetworkTopology* topology, char* ip, int port, float latency, int bandwidth) {
    pthread_mutex_lock(&topology->lock);
    for (int i = 0; i < topology->size; i++) {
        Node* node = topology->nodes[i];
        if (strcmp(node->ip, ip) == 0) {
            node->port = port;
            node->latency = latency;
            node->bandwidth = bandwidth;
            break;
        }
    }
    pthread_mutex_unlock(&topology->lock);
}

