#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Record {
    int key;
    struct Record* next;
} Record;

typedef struct LinkedList {
    Record* head;
    size_t size;
} LinkedList;

Record* create_record(int key) {
    Record* record = (Record*)malloc(sizeof(Record));
    record->key = key;
    record->next = NULL;
    return record;
}

void insert_record(LinkedList* list, int key) {
    Record* new_record = create_record(key);
    if (list->head == NULL || list->head->key > key) {
        new_record->next = list->head;
        list->head = new_record;
    } else {
        Record* current = list->head;
        while (current->next != NULL && current->next->key < key) {
            current = current->next;
        }
        new_record->next = current->next;
        current->next = new_record;
    }
    list->size++;
}

void delete_record(LinkedList* list, int key) {
    Record** current = &list->head;
    while (*current != NULL && (*current)->key < key) {
        current = &(*current)->next;
    }
    if (*current != NULL && (*current)->key == key) {
        Record* temp = *current;
        *current = (*current)->next;
        free(temp);
        list->size--;
    }
}

Record* find_record(LinkedList* list, int key) {
    Record* current = list->head;
    while (current != NULL && current->key < key) {
        current = current->next;
    }
    if (current != NULL && current->key == key) {
        return current;
    }
    return NULL;
}

void serialize_linked_list(LinkedList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Error opening file for writing");
        return;
    }
    fwrite(&list->size, sizeof(size_t), 1, file);
    Record* current = list->head;
    while (current != NULL) {
        fwrite(&current->key, sizeof(int), 1, file);
        current = current->next;
    }
    fclose(file);
}

void deserialize_linked_list(LinkedList* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Error opening file for reading");
        return;
    }
    size_t size;
    fread(&size, sizeof(size_t), 1, file);
    list->head = NULL;
    while (size-- > 0) {
        int key;
        fread(&key, sizeof(int), 1, file);
        insert_record(list, key);
    }
    fclose(file);
}

void free_linked_list(LinkedList* list) {
    Record* current = list->head;
    while (current != NULL) {
        Record* next = current->next;
        free(current);
        current = next;
    }
    list->size = 0;
}
