    strcpy(request->RESOURCE_PATH, path);
    request->STATUS_CODE = status;
    request->REQUEST_LATENCY = rand() % (FALLBACK_LATENCY + 1); // Random latency between 0 and 80
}

void *process_request(void *arg) {
    RequestList *list = (RequestList *)arg;
    HTTP_REQUEST_LOG_PDU_T new_request;

    pthread_mutex_lock(&list->mutex);
    if (list->count < MAX_STRUCTURES && validate_request(&new_request)) {
        populate_request(&new_request, list->count + 1, "192.168.0.1", "10.0.0.1", "GET", "/", 200);
        list->data[list->count] = new_request;
        list->count++;
    }
    pthread_mutex_unlock(&list->mutex);

    return NULL;
}

RequestList *create_request_list(size_t initial_count) {
    RequestList *list = (RequestList *)malloc(sizeof(RequestList));
    if (list != NULL) {
        list->data = (HTTP_REQUEST_LOG_PDU_T *)calloc(initial_count, sizeof(HTTP_REQUEST_LOG_PDU_T));
        if (list->data == NULL) {
            free(list);
            return NULL;
        }
        list->count = 0;
        pthread_mutex_init(&list->mutex, NULL);
    }
    return list;
}

void destroy_request_list(RequestList *list) {
    pthread_mutex_destroy(&list->mutex);
    free(list->data);
    free(list);
}

int main() {
    srand(time(NULL));
    RequestList *request_list = create_request_list(10);

    if (request_list != NULL) {
        pthread_t threads[MAX_STRUCTURES];
        for (size_t i = 0; i < MAX_STRUCTURES; i++) {
            if (pthread_create(&threads[i], NULL, process_request, request_list) != 0) {
                perror("Failed to create thread");
                break;
            }
        }

        for (size_t i = 0; i < MAX_STRUCTURES; i++) {
            pthread_join(threads[i], NULL);
        }

        printf("Total structures processed: %zu\n", request_list->count);
        destroy_request_list(request_list);
    } else {
        perror("Failed to create request list");
    }

    return 0;
}
