    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    for (int i = 0; i < N; i++) {
        HTTP_REQUEST_LOG_PDU_T *request_log = (HTTP_REQUEST_LOG_PDU_T*)malloc(sizeof(HTTP_REQUEST_LOG_PDU_T));
