        request_log->REQUEST_LATENCY = network_latency;

        // Lock the list to ensure thread safety
        pthread_mutex_lock(&mutex);
        if (log_list->count < MAX_STRUCTS) {
            log_list->list[log_list->count++] = request_log;
        } else {
            free(request_log);
            break;
        }
        pthread_mutex_unlock(&mutex);

        // Optionally log the creation of each structure
