            printf("Created HTTP_REQUEST_LOG_PDU_T with REQUEST_ID: %d\n", request_log->REQUEST_ID);
        }

        // Simulate processing time
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);
        while ((clock_gettime(CLOCK_MONOTONIC, &end) - start.tv_sec < 0.25) ||
               (end.tv_nsec - start.tv_nsec < 250 * 1000 * 1000)) {
            // Busy wait to simulate processing time
        }
    }

    pthread_mutex_destroy(&mutex);
    return log_list;
}

