size_t mlbd_capacity = 0;
pthread_mutex_t mlbd_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t mlbd_cv = PTHREAD_COND_INITIALIZER;
int active_sessions = 0;

// Function to validate session
int is_session_active(int session_id) {
    // Simulate external data source check
    return (session_id >= 1 && session_id <= 10); // Example range of active sessions
}

// Function to allocate MLBD
Mlbd* allocate_mlbd(int session_id) {
    if (!is_session_active(session_id)) {
        fprintf(stderr, "Error: Session %d is inactive.\n", session_id);
        return NULL;
    }

    pthread_mutex_lock(&mlbd_lock);

    // Check cache first
    for (size_t i = 0; i < mlbd_count; ++i) {
        if (mlbd_list[i].sequence_number == -1) { // Assuming -1 means free slot
            Mlbd *mlbd = &mlbd_list[i];
            pthread_mutex_unlock(&mlbd_lock);
            return mlbd;
        }
    }

    // Expand list if necessary
    if (mlbd_count >= mlbd_capacity) {
        mlbd_capacity = (mlbd_capacity == 0) ? 1 : mlbd_capacity * 2;
        Mlbd *new_mlbd_list = realloc(mlbd_list, mlbd_capacity * sizeof(Mlbd));
        if (!new_mlbd_list) {
            fprintf(stderr, "Error: Failed to allocate memory.\n");
            pthread_mutex_unlock(&mlbd_lock);
            return NULL;
        }
        mlbd_list = new_mlbd_list;
    }

    Mlbd *mlbd = &mlbd_list[mlbd_count++];
    pthread_mutex_unlock(&mlbd_lock);

    return mlbd;
}

// Function to release MLBD
void release_mlbd(Mlbd *mlbd) {
    pthread_mutex_lock(&mlbd_lock);
    mlbd->sequence_number = -1; // Mark as free
    active_sessions--;
    pthread_cond_signal(&mlbd_cv);
    pthread_mutex_unlock(&mlbd_lock);
}

// Function to initialize MLBD management
void init_mlbd_management() {
    mlbd_capacity = 0;
    mlbd_count = 0;
    mlbd_list = NULL;
}

// Function to cleanup MLBD management
void cleanup_mlbd_management() {
    free(mlbd_list);
}
