    std::mutex mutex;
    std::condition_variable cv;
    bool stop;

public:
    NEStatusUpdater() : stop(false) {}

    void addNE(NetworkElement* ne) {
        std::lock_guard<std::mutex> lock(mutex);
        neList.push_back(ne);
    }

    void updateNEStatus(NetworkElement* ne, const std::string& status) {
        std::lock_guard<std::mutex> lock(mutex);
        // Update the status of the NE
        cv.notify_all();
    }

    void processUpdates() {
        while (!stop) {
            std::unique_lock<std::mutex> lock(mutex);
            cv.wait(lock, [this] { return !neList.empty(); });

            for (NetworkElement* ne : neList) {
                // Process the status update
                neList.erase(std::remove(neList.begin(), neList.end(), ne), neList.end());
            }
        }
    }

    void stopProcessing() {
        {
            std::lock_guard<std::mutex> lock(mutex);
            stop = true;
