    unsigned char key[EVP_MAX_KEY_LENGTH], iv[EVP_MAX_IV_LENGTH];
    unsigned int salt[8] = {0};
    unsigned char derived_key[32];

    // Derive the encryption key using SHA-256
    HMAC_CTX* ctx = HMAC_CTX_new();
    HMAC_Init_ex(ctx, password.c_str(), password.length(), EVP_sha256(), NULL);
    HMAC_Update(ctx, reinterpret_cast<const unsigned char*>(salt), sizeof(salt));
    HMAC_Final(ctx, derived_key, &len);
    HMAC_CTX_free(ctx);

