    struct Node* prev;
    struct Node* next;
} Node;

// Function to create and populate a doubly linked list of NFAPI_CRC_INDICATION_PDU_T structures
Node* create_and_populate_list(int N) {
    Node* head = NULL;
    for (int i = 0; i < N; i++) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) return NULL; // Handle memory allocation failure
        new_node->data.RNTI = generate_unique_RNTI(); // Assume generate_unique_RNTI() is defined
        populate_valid_tags(&new_node->data); // Assume populate_valid_tags() is defined
        new_node->prev = NULL;
        new_node->next = head;
        if (head) head->prev = new_node;
        head = new_node;
    }
    return head;
}

// Function to serialize the list to a file
int serialize_list(Node* head, const char* filename, int binary_mode, int async_io) {
    FILE* file = fopen(filename, binary_mode ? "wb" : "w");
    if (!file) return -1; // Handle file opening failure

    Node* current = head;
    while (current) {
        if (binary_mode) {
            fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        } else {
            fprintf(file, "%d\n", current->data.RNTI); // Serialize RNTI for text mode
        }
        current = current->next;
    }

    fclose(file);
    return 0; // Success
}

// Function to deserialize the list from a file
Node* deserialize_list(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return NULL; // Handle file opening failure

    Node* head = NULL;
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T data;
        if (fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) != 1) break;

        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) return NULL; // Handle memory allocation failure
        new_node->data = data;
        new_node->prev = NULL;
        new_node->next = head;
        if (head) head->prev = new_node;
        head = new_node;
    }

    fclose(file);
    return head;
}

// Function to manage cache for serialized list loading
Node* load_cached_list(const char* filename, int memory_pressure) {
