// Function to process text file lines and calculate average of last two fields
void processTextFile(const char* filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Remove newline character
        size_t len = strlen(line);
        if (len > 0 && line[len - 1] == '\n') {
            line[--len] = '\0';
        }

        // Process the line and calculate average of last two fields
        char *token = strtok(line, ",");
        int count = 0;
        double sum = 0.0;

        while (token != NULL) {
            sum += atof(token);
            count++;
            token = strtok(NULL, ",");
        }

        if (count >= 2) {
            double average = (sum - atof(strtok(NULL, ","))) / (count - 1);
            printf("%s,%f\n", line, average);
        }
    }

    fclose(file);
}

