from flask import Flask, request, jsonify
import time
import random
from collections import defaultdict
from functools import wraps

app = Flask(__name__)

# Simulated payment gateway API key validation
API_KEY = 'your_api_key_here'

# In-memory caching for transaction details
transaction_cache = {}

# Rate limiting dictionary with token-based authentication
rate_limit_tokens = {}
TOKEN_EXPIRY_SECONDS = 60 * 10  # 10 minutes

def rate_limited(max_calls, period):
    def decorator(func):
        calls = defaultdict(int)

        @wraps(func)
        def wrapper(*args, **kwargs):
            token = request.headers.get('Authorization')
            if not token:
                return jsonify({'error': 'Missing API key'}), 401
            elif token != API_KEY:
                return jsonify({'error': 'Invalid API key'}), 403

            now = time.time()
            if token not in calls or now - rate_limit_tokens[token] > TOKEN_EXPIRY_SECONDS:
                calls[token] = [now]
            else:
                calls[token].append(now)
                if len(calls[token]) > max_calls:
                    return jsonify({'error': 'Rate limit exceeded'}), 429

            return func(*args, **kwargs)

        return wrapper
    return decorator

def validate_transaction(transaction_id, amount, currency):
    # Simulated transaction validation logic
    pass

def process_initiation(amount, currency):
    # Simulated initiation processing logic
    pass

def process_refund(transaction_id, amount):
    # Simulated refund processing logic
    pass

def process_chargeback(transaction_id, amount):
    # Simulated chargeback processing logic
    pass

@app.route('/transaction', methods=['POST'])
@rate_limited(max_calls=10, period=TOKEN_EXPIRY_SECONDS)
def transaction():
    data = request.json
    sub_action = data.get('sub_action')

    if not sub_action:
        return jsonify({'error': 'Sub-action is required'}), 400

    try:
        if sub_action == 'initiate':
            validate_transaction(data['transaction_id'], data['amount'], data['currency'])
            process_initiation(data['amount'], data['currency'])
        elif sub_action == 'refund':
            transaction_cache[data['transaction_id']]
            process_refund(data['transaction_id'], data['amount'])
        elif sub_action == 'chargeback':
            transaction_cache[data['transaction_id']]
            process_chargeback(data['transaction_id'], data['amount'])
        else:
            return jsonify({'error': 'Invalid sub-action'}), 400

        return jsonify({'status': 'success'}), 200
    except Exception as e:
        app.logger.error(f'Error processing transaction: {e}')
        return jsonify({'error': str(e)}), 500

if __name__ == '__main__':
    app.run(debug=True)
