#include <iostream>
#include <vector>
#include <string>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <openssl/ssl.h>
#include <openssl/err.h>

// Define data structures for device status and logs
struct DeviceStatus {
    std::string deviceId;
    double value;
};

struct LogEntry {
    std::string message;
    time_t timestamp;
};

class DataPipeline {
private:
    std::vector<DeviceStatus> devices;
    std::vector<LogEntry> logs;
    std::mutex logMutex;
    std::condition_variable dataCondition;
    bool dataReady;
    SSL_CTX* tlsContext;

public:
    DataPipeline() : dataReady(false) {}

    ~DataPipeline() {
        cleanupTLS();
    }

    void ingestData(const DeviceStatus& device) {
        devices.push_back(device);
        dataReady = true;
        dataCondition.notify_one();
    }

    void processDevices() {
        std::unique_lock<std::mutex> lock(logMutex);
        while (true) {
            dataCondition.wait(lock, [this]{ return dataReady; });
            if (!devices.empty()) {
                logDeviceStatus(devices.back());
                devices.pop_back();
                dataReady = false;
            }
        }
    }

    void logDeviceStatus(const DeviceStatus& device) {
        LogEntry entry;
        entry.message = "Device " + device.deviceId + " updated to value: " + std::to_string(device.value);
        entry.timestamp = time(nullptr);
        logs.push_back(entry);
    }

    SSL_CTX* initializeTLS() {
        SSL_library_init();
        OpenSSL_add_all_algorithms();
        SSL_load_error_strings();

        tlsContext = SSL_CTX_new(TLSv1_2_method());
        if (!tlsContext) {
            std::cerr << "Failed to create TLS context" << std::endl;
            return nullptr;
        }

        // Configure TLS parameters
        SSL_CTX_set_options(tlsContext, SSL_OP_NO_SSLv2 | SSL_OP_NO_SSLv3);
        SSL_CTX_use_certificate_file(tlsContext, "path/to/certificate.pem", SSL_FILETYPE_PEM);
        SSL_CTX_use_PrivateKey_file(tlsContext, "path/to/privatekey.pem", SSL_FILETYPE_PEM);

        return tlsContext;
    }

    void cleanupTLS() {
        if (tlsContext) {
            SSL_CTX_free(tlsContext);
            tlsContext = nullptr;
        }
    }

    static DataPipeline* getInstance() {
        static DataPipeline instance;
        return &instance;
    }
};

// Example usage
int main() {
    DataPipeline* pipeline = DataPipeline::getInstance();
    pipeline->tlsContext = pipeline->initializeTLS();

    // Simulate data ingestion
    DeviceStatus device1 = {"device1", 23.5};
    pipeline->ingestData(device1);

    // Process devices in a separate thread
    std::thread processThread(&DataPipeline::processDevices, pipeline);
    processThread.join();

    return 0;
}
