import os
import zipfile
from hashlib import sha256
from datetime import datetime
from functools import wraps
from logging import getLogger

logger = getLogger(__name__)

# Constants
MAX_FILE_SIZE = 10 * 1024 * 1024  # 10MB
CONTENT_TYPE_LIMITS = {
    'image': ['image/jpeg', 'image/png'],
    'text': ['text/plain']
}

# Decorator for rate limiting
def rate_limit(max_calls, period):
    def decorator(func):
        from collections import defaultdict
        from time import time

        calls = defaultdict(int)

        @wraps(func)
        def wrapper(*args, **kwargs):
            user_id = kwargs.get('user_id')
            now = time()
            current_period = (now // period) * period

            if user_id not in calls or calls[user_id] < max_calls:
                calls[user_id] += 1
                return func(*args, **kwargs)
            else:
                raise Exception("Rate limit exceeded for user")

        return wrapper
    return decorator

@rate_limit(max_calls=20, period=3600)  # 20 requests per hour
def handle_file_upload(request_payload):
    file_name = request_payload.get('file_name')
    content_type = request_payload.get('content_type')
    file_data = request_payload.get('file_data')
    user_id = request_payload.get('user_id')
    upload_date = request_payload.get('upload_date')
    checksum = request_payload.get('checksum')
    operation_type = request_payload.get('operation_type')

    if not all([file_name, content_type, file_data, user_id, upload_date, checksum, operation_type]):
        logger.error("Missing required fields in the payload")
        return

    try:
        if operation_type == 'upload':
            if content_type not in CONTENT_TYPE_LIMITS['text'] and len(file_data) > MAX_FILE_SIZE:
                raise Exception("File size or type exceeds limits")

            calculated_checksum = sha256(file_data).hexdigest()
            if checksum != calculated_checksum:
                logger.error("Checksum mismatch for uploaded file")
                raise Exception("Checksum validation failed")

            # Store the file in a secure manner
            with open(file_name, 'wb') as f:
                f.write(file_data)

        elif operation_type == 'delete':
            try:
                os.remove(file_name)
                os.remove(f"{file_name}.metadata")
            except FileNotFoundError:
                logger.error("File not found for deletion")

        elif operation_type == 'rename':
            new_file_name = request_payload.get('new_file_name')
            if os.path.exists(new_file_name):
                raise Exception("New file name already exists")
            os.rename(file_name, new_file_name)
            os.rename(f"{file_name}.metadata", f"{new_file_name}.metadata")

        elif operation_type == 'archive':
            with zipfile.ZipFile(f"{file_name}.zip", 'w') as zipf:
                zipf.writestr(file_name, file_data)

    except Exception as e:
        logger.error(f"Error handling file {operation_type}: {str(e)}")
        raise

# Example usage
if __name__ == "__main__":
    payload = {
        'file_name': 'example.txt',
        'content_type': 'text/plain',
        'file_data': b'Hello, world!',
        'user_id': 'user123',
        'upload_date': datetime.now(),
        'checksum': sha256(b'Hello, world!').hexdigest(),
        'operation_type': 'upload'
    }
    handle_file_upload(payload)
