#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define the structure fields here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct HashTableEntry {
    int RNTI;
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct HashTableEntry *next;
} HashTableEntry;

typedef struct {
    HashTableEntry **buckets;
    int size;
    pthread_mutex_t lock;
} HashTable;

void initHashTable(HashTable *ht, int size) {
    ht->buckets = (HashTableEntry **)malloc(size * sizeof(HashTableEntry *));
    for (int i = 0; i < size; i++) {
        ht->buckets[i] = NULL;
    }
    ht->size = size;
    pthread_mutex_init(&ht->lock, NULL);
}

void insertToHashTable(HashTable *ht, int RNTI, NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&ht->lock);
    int index = RNTI % ht->size;
    HashTableEntry *newEntry = (HashTableEntry *)malloc(sizeof(HashTableEntry));
    newEntry->RNTI = RNTI;
    newEntry->data = data;
    newEntry->next = ht->buckets[index];
    ht->buckets[index] = newEntry;
    pthread_mutex_unlock(&ht->lock);
}

NFAPI_CRC_INDICATION_PDU_T *lookupInHashTable(HashTable *ht, int RNTI) {
    pthread_mutex_lock(&ht->lock);
    int index = RNTI % ht->size;
    HashTableEntry *entry = ht->buckets[index];
    while (entry != NULL) {
        if (entry->RNTI == RNTI) {
            NFAPI_CRC_INDICATION_PDU_T *result = entry->data;
            pthread_mutex_unlock(&ht->lock);
            return result;
        }
        entry = entry->next;
    }
    pthread_mutex_unlock(&ht->lock);
    return NULL;
}

void removeFromHashTable(HashTable *ht, int RNTI) {
    pthread_mutex_lock(&ht->lock);
    int index = RNTI % ht->size;
    HashTableEntry *entry = ht->buckets[index];
    HashTableEntry *prev = NULL;
    while (entry != NULL) {
        if (entry->RNTI == RNTI) {
            if (prev == NULL) {
                ht->buckets[index] = entry->next;
            } else {
                prev->next = entry->next;
            }
            free(entry);
            pthread_mutex_unlock(&ht->lock);
            return;
        }
        prev = entry;
        entry = entry->next;
    }
    pthread_mutex_unlock(&ht->lock);
}

void cleanupHashTable(HashTable *ht) {
    for (int i = 0; i < ht->size; i++) {
        HashTableEntry *entry = ht->buckets[i];
        while (entry != NULL) {
            HashTableEntry *temp = entry;
            entry = entry->next;
            free(temp);
        }
    }
    pthread_mutex_destroy(&ht->lock);
    free(ht->buckets);
}

