// Mutex for thread safety
std::mutex mtx;

// Function to initialize network events or validate input command
void initializeNetworkEventsOrValidateInputCommand(const std::string& command, int N = 10, int latencyAdjustment = 50) {
    static bool initialized = false;
    static std::chrono::time_point<std::chrono::system_clock> lastExecutionTime = std::chrono::system_clock::now() - std::chrono::seconds(11);

    std::unique_lock<std::mutex> lock(mtx);

    // Cooldown period enforcement
    auto now = std::chrono::system_clock::now();
    if (std::chrono::duration_cast<std::chrono::seconds>(now - lastExecutionTime) < std::chrono::seconds(10)) {
        return;
    }

    if (!initialized || !isValidCommand(command)) {
        // Initialize network events
        std::vector<NFAPI_CRC_INDICATION_PDU_T> events;
        initializeNetworkEvents(N, latencyAdjustment, events);
        initialized = true;
    } else {
        // Process validated input command
        processInputCommand(command);
    }

    lastExecutionTime = now;
}

// Utility function to clean up allocated resources
void cleanup() {
    // Placeholder for resource cleanup logic
}
