void init_UE_crc_list(UE_CRC_LIST *list) {
    list->list = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

int add_to_UE_crc_list(UE_CRC_LIST *list, int ue_id, int rnti) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 16;
        NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(list->list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Memory allocation failed
        }
        list->list = new_list;
        list->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T *entry = create_UE_entry(ue_id, rnti);
    if (!entry) {
        pthread_mutex_unlock(&list->mutex);
        return -2; // Entry creation failed
    }

    int network_status = get_network_status(); // Assume this function fetches network status
    while (!validate_UE(entry->ue_info, network_status)) {
        free(entry);
        entry = create_UE_entry(ue_id, rnti); // Retry with updated UE information
        if (!entry) {
            pthread_mutex_unlock(&list->mutex);
            return -3; // Entry creation failed on retry
        }
    }

    list->list[list->count++] = *entry;
    free(entry);

    if (list->count % 1000 == 0) {
        log_performance_metrics(list->count); // Assume this function logs metrics
    }

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void destroy_UE_crc_list(UE_CRC_LIST *list) {
    pthread_mutex_lock(&list->mutex);
    free(list->list);
    list->list = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_unlock(&list->mutex);
}
```

