    struct NFAPI_CRC_INDICATION_PDU *next;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the linked list structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    pthread_mutex_t lock;
} CRC_LIST_T;

// Function to initialize the linked list
void crc_list_init(CRC_LIST_T *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Function to insert a new element into the linked list
int crc_list_insert(CRC_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *new_element) {
    pthread_mutex_lock(&list->lock);
    new_element->next = list->head;
    list->head = new_element;
    pthread_mutex_unlock(&list->lock);
    return 0; // Return success
}

// Function to delete an element from the linked list
int crc_list_delete(CRC_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&list->lock);
    if (list->head == element) {
        list->head = element->next;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *current = list->head;
        while (current->next != element) {
            current = current->next;
        }
        current->next = element->next;
    }
    pthread_mutex_unlock(&list->lock);
    free(element); // Free the memory
    return 0; // Return success
}

// Function to clean up the linked list
void crc_list_cleanup(CRC_LIST_T *list) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *temp = current;
        current = current->next;
        free(temp); // Free the memory
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
