enum AttackType { Attack1, Attack2, Attack3, Attack4, Attack5 };

class UEManager {
public:
    void generateAndExecuteAttackSequence(int numUEs) {
        std::vector<NFAPI_CRC_INDICATION_PDU_T> nfaipduArray(numUEs);

        for (int i = 0; i < numUEs; ++i) {
            populateUEInfo(nfaipduArray[i], i);
        }

        executeAttackSequence();
    }

private:
    std::mutex logMutex;
    std::condition_variable cv;
    bool updateAvailable = false;

    void populateUEInfo(NFAPI_CRC_INDICATION_PDU_T& ue, int index) {
        // Populate the UE information with valid RNTI and CRC flag
        ue.RX_UE_INFORMATION_TAG.RNTI = 100 + index; // Example RNTI assignment

        // Simulate a random CRC flag for demonstration purposes
        ue.CRC_INDICATION_REL8_TAG.CRC_FLAG = (rand() % 2 == 0);

        logUpdate("UE info updated", "Source: Random");
    }

    void executeAttackSequence() {
        while (true) {
            std::unique_lock<std::mutex> lock(logMutex);
            cv.wait(lock, [this] { return updateAvailable; });

            // Select an attack randomly
            AttackType selectedAttack = static_cast<AttackType>(rand() % 5 + 1);
            int damage = getDamageForAttack(selectedAttack);
            logAttack("Executing Attack", selectedAttack, damage);

            lock.unlock();
            std::this_thread::sleep_for(std::chrono::seconds(15));
        }
    }

    int getDamageForAttack(AttackType attack) {
        switch (attack) {
            case Attack1: return 45;
            case Attack2: return 70;
            case Attack3: return 95;
            case Attack4: return 125;
            case Attack5: return 160;
            default: return 0; // Should not happen
        }
    }

    void logUpdate(const std::string& message, const std::string& source) {
        std::lock_guard<std::mutex> lock(logMutex);
        std::cout << "[" << getCurrentTime() << "] " << message << " from " << source << std::endl;
        updateAvailable = true;
        cv.notify_all();
    }

    void logAttack(const std::string& message, AttackType attack, int damage) {
        std::lock_guard<std::mutex> lock(logMutex);
        std::cout << "[" << getCurrentTime() << "] " << message << " Attack: " << static_cast<int>(attack)
                  << ", Damage: " << damage << std::endl;
    }

    std::string getCurrentTime() {
        auto now = std::chrono::system_clock::now();
        std::time_t now_c = std::chrono::system_clock::to_time_t(now);
        return std::ctime(&now_c); // Note: This will include a newline at the end
    }
};

int main() {
    UEManager manager;
    manager.generateAndExecuteAttackSequence(1000);
    return 0;
}
