#include <openssl/evp.h>
#include <openssl/rand.h>

struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct CRC_INDICATION_REL8_TAG {
        bool crc_flag;
    } crc_indication_rel8_tag;
};

std::mutex log_mutex;
std::condition_variable cv;
bool stop = false;

void logMessage(const std::string& message) {
    std::lock_guard<std::mutex> lock(log_mutex);
    std::cout << "[" << std::chrono::system_clock::now().time_since_epoch().count() << "] " << message << std::endl;
}

void generateAndExecuteAttackSequence(int numUes, int batchSize) {
    std::vector<NFAPI_CRC_INDICATION_PDU_T> ues(numUes);

    for (int i = 0; i < numUes; ++i) {
        ues[i].RX_UE_INFORMATION_TAG = i + 1;
        ues[i].RNTI = rand() % 4096;
        ues[i].crc_indication_rel8_tag.crc_flag = (rand() % 2 == 0);
    }

    int attackCooldown = 15000; // 15 seconds
    int nextAttackTime = std::chrono::system_clock::now().time_since_epoch().count() + attackCooldown;

    while (!stop) {
        for (int i = 0; i < batchSize && i < numUes; ++i) {
            NFAPI_CRC_INDICATION_PDU_T& ue = ues[i];
            // Process UE data
            logMessage("Processing UE " << ue.RX_UE_INFORMATION_TAG);
        }

        if (std::chrono::system_clock::now().time_since_epoch().count() >= nextAttackTime) {
            int attackNumber = rand() % 5 + 1;
            int damage = 0;
            switch (attackNumber) {
                case 1: damage = 45; break;
                case 2: damage = 70; break;
                case 3: damage = 95; break;
                case 4: damage = 125; break;
                case 5: damage = 160; break;
            }
            logMessage("Attacking with Attack " << attackNumber << " for " << damage << " damage");
            nextAttackTime = std::chrono::system_clock::now().time_since_epoch().count() + attackCooldown;
        }

        cv.notify_one();
        std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
}

void periodicUpdate(int interval) {
    while (!stop) {
        // Simulate periodic update
        generateAndExecuteAttackSequence(rand() % 1000, rand() % 50 + 1);
        std::this_thread::sleep_for(std::chrono::seconds(interval));
    }
}

int main() {
    std::thread updateThread(periodicUpdate, 10);

    // Simulate stopping the process after a while
    std::this_thread::sleep_for(std::chrono::minutes(5));
    stop = true;
    cv.notify_all();
    updateThread.join();

    return 0;
}
