#include <time.h>

#define NFAPI_CRC_INDICATION_PDU_T_SIZE 1024
#define MAX_UE_INSTANCES 10000

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    bool CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T** initialize_and_populate_nfapi_crc_indication_pdu(int num_ues, int batch_size, pthread_mutex_t* mutex, pthread_cond_t* cond_var) {
    NFAPI_CRC_INDICATION_PDU_T** pdu_array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(num_ues * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!pdu_array) {
        // Log error and handle memory allocation failure
        return NULL;
    }

    for (int i = 0; i < num_ues; i++) {
        pdu_array[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(NFAPI_CRC_INDICATION_PDU_T_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu_array[i]) {
            // Log error and handle memory allocation failure
            for (int j = 0; j < i; j++) {
                free(pdu_array[j]);
            }
            free(pdu_array);
            return NULL;
        }

        // Simulate fetching UE information with a delay
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_sec += 1; // Delay for 1 second
        nanosleep(&ts, NULL);

        pthread_mutex_lock(mutex);
        while (/* Condition to check if data is available */) {
            pthread_cond_wait(cond_var, mutex);
        }

        // Populate the structure with random data and log successful operation
        pdu_array[i]->RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu_array[i]->RNTI = rand() % 1024;
        pdu_array[i]->CRC_INDICATION_REL8_TAG = (rand() % 2) == 1;

        // Log successful operation
        pthread_mutex_unlock(mutex);
    }

    return pdu_array;
}

// Example usage in a multi-threaded environment
void* thread_function(void* arg) {
    int start_index = *(int*)arg;
    int end_index = start_index + batch_size;
    NFAPI_CRC_INDICATION_PDU_T** pdu_array = initialize_and_populate_nfaip_crc_indication_pdu(end_index, batch_size, mutex, cond_var);
    if (pdu_array) {
        // Process pdu_array
        for (int i = start_index; i < end_index; i++) {
            free(pdu_array[i]);
        }
        free(pdu_array);
    }
    return NULL;
}

int main() {
    int num_ues = 10000;
    int batch_size = 1000;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond_var = PTHREAD_COND_INITIALIZER;

    pthread_t threads[MAX_UE_INSTANCES / batch_size];
    int thread_args[MAX_UE_INSTANCES / batch_size];

    for (int i = 0; i < MAX_UE_INSTANCES / batch_size; i++) {
        thread_args[i] = i * batch_size;
        if (pthread_create(&threads[i], NULL, thread_function, &thread_args[i]) != 0) {
            // Log error and handle thread creation failure
        }
    }

    for (int i = 0; i < MAX_UE_INSTANCES / batch_size; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
