#include <pthread.h>
#include <semaphore.h>
#include <log4c.h>

#define MAX_CONNECTIONS 50000
#define DEFAULT_BATCH_SIZE 1024

typedef struct {
    uint64_t BYTES_RECEIVED;
    uint64_t BYTES_SENT;
    time_t ACTIVE_SESSION_DURATION;
    int LAST_ERROR_CODE;
} TCP_CONNECTION_STATS_T;

TCP_CONNECTION_STATS_T* connections[MAX_CONNECTIONS];
int connection_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
sem_t batch_semaphore;

void log_connection_stats(int index) {
    // Log connection stats using log4c or any other logging library
}

void initialize_connection_stats() {
    sem_init(&batch_semaphore, 0, DEFAULT_BATCH_SIZE);
}

int add_connection_stat(TCP_CONNECTION_STATS_T* stat) {
    pthread_mutex_lock(&lock);
    if (connection_count >= MAX_CONNECTIONS) {
        pthread_mutex_unlock(&lock);
        return -1; // Error: Max connections reached
    }
    connections[connection_count++] = stat;
    sem_post(&batch_semaphore);
    pthread_mutex_unlock(&lock);
    return 0;
}

void process_connection_stats() {
    while (sem_wait(&batch_semaphore) == 0) {
        pthread_mutex_lock(&lock);
        if (connection_count > 0) {
            log_connection_stats(connection_count - 1);
            connection_count--;
        }
        pthread_mutex_unlock(&lock);
    }
}

void* batch_processing_thread(void* arg) {
    while (1) {
        process_connection_stats();
        // Sleep or yield to other threads
        usleep(1000); // Sleep for 1ms
    }
    return NULL;
}

int main() {
    initialize_connection_stats();

    // Start batch processing thread
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, batch_processing_thread, NULL) != 0) {
        // Handle error
    }

    // Example usage: Adding connection stats
    TCP_CONNECTION_STATS_T* new_stat = malloc(sizeof(TCP_CONNECTION_STATS_T));
    // Populate new_stat with data
    add_connection_stat(new_stat);

    // Clean up
    pthread_join(thread_id, NULL);
    sem_destroy(&batch_semaphore);
    for (int i = 0; i < connection_count; i++) {
        free(connections[i]);
    }
    return 0;
}
```

