#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char device_name[50];
    char ip_address[16];
    char subnet_mask[16];
    char gateway[16];
} NetworkConfig;

typedef struct Node {
    NetworkConfig config;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} NetworkList;

void initNetworkList(NetworkList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void addConfig(NetworkList* list, const char* device_name, const char* ip_address, const char* subnet_mask, const char* gateway) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    strncpy(newNode->config.device_name, device_name, sizeof(newNode->config.device_name)-1);
    strncpy(newNode->config.ip_address, ip_address, sizeof(newNode->config.ip_address)-1);
    strncpy(newNode->config.subnet_mask, subnet_mask, sizeof(newNode->config.subnet_mask)-1);
    strncpy(newNode->config.gateway, gateway, sizeof(newNode->config.gateway)-1);
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
}

void removeConfig(NetworkList* list, const char* device_name) {
    Node* current = list->head;
    Node* previous = NULL;

    pthread_mutex_lock(&list->lock);
    while (current != NULL && strcmp(current->config.device_name, device_name) != 0) {
        previous = current;
        current = current->next;
    }
    if (current != NULL) {
        if (previous == NULL) {
            list->head = current->next;
        } else {
            previous->next = current->next;
        }
        free(current);
    }
    pthread_mutex_unlock(&list->lock);
}

void updateConfig(NetworkList* list, const char* device_name, const char* ip_address, const char* subnet_mask, const char* gateway) {
    Node* current = list->head;

    pthread_mutex_lock(&list->lock);
    while (current != NULL && strcmp(current->config.device_name, device_name) != 0) {
        current = current->next;
    }
    if (current != NULL) {
        strncpy(current->config.ip_address, ip_address, sizeof(current->config.ip_address)-1);
        strncpy(current->config.subnet_mask, subnet_mask, sizeof(current->config.subnet_mask)-1);
        strncpy(current->config.gateway, gateway, sizeof(current->config.gateway)-1);
    }
    pthread_mutex_unlock(&list->lock);
}

void printConfigs(NetworkList* list) {
    Node* current = list->head;

    pthread_mutex_lock(&list->lock);
    while (current != NULL) {
        printf("Device: %s\n", current->config.device_name);
        printf("IP: %s\n", current->config.ip_address);
        printf("Subnet Mask: %s\n", current->config.subnet_mask);
        printf("Gateway: %s\n", current->config.gateway);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void destroyNetworkList(NetworkList* list) {
    Node* current = list->head;

    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}
