int remove_PDU_session(UE_Session *session, int PDU_ID) {
    for (int i = 0; i < session->pdu_count; i++) {
        if (session->PDU_Sessions[i].PDU_ID == PDU_ID) {
            for (int j = i; j < session->pdu_count - 1; j++) {
                session->PDU_Sessions[j] = session->PDU_Sessions[j + 1];
            }
            session->pdu_count--;
            return 0;
        }
    }
    return -1;
}

void update_PDU_session(UE_Session *session, int PDU_ID, char *new_status) {
    for (int i = 0; i < session->pdu_count; i++) {
        if (session->PDU_Sessions[i].PDU_ID == PDU_ID) {
            snprintf(session->PDU_Sessions[i].STATUS, sizeof(session->PDU_Sessions[i].STATUS), new_status);
