                logger.severe("Error processing file: " + filePath + ", Error: " + e.getMessage());
                throw new RuntimeException("Failed to process file: " + filePath, e);
            }
        }

        return fileMetaMap;
    }

    private FileMetaData getMetadata(Path path) throws IOException, NoSuchAlgorithmException {
        FileMetaData metaData = new FileMetaData();
        metaData.setSize(Files.size(path));
        metaData.setLastModified(Files.getLastModifiedTime(path).toMillis());
        metaData.setFileType(Files.probeContentType(path));

        // Calculate SHA-256 and MD5 checksums
        MessageDigest sha256Digest = MessageDigest.getInstance("SHA-256");
        byte[] sha256Checksum = Files.readAllBytes(path);
        sha256Digest.update(sha256Checksum);
        metaData.setSha256Checksum(Base64.getEncoder().encodeToString(sha256Digest.digest()));

        MessageDigest md5Digest = MessageDigest.getInstance("MD5");
        byte[] md5Checksum = Files.readAllBytes(path);
        md5Digest.update(md5Checksum);
        metaData.setMd5Checksum(Base64.getEncoder().encodeToString(md5Digest.digest()));

        return metaData;
    }

    private void updateBucketLifecycle(S3Client s3Client, String bucketName, FileMetaData metaData) {
        List<LifecycleRule> rules = new ArrayList<>();
        LifecycleRule rule = LifecycleRule.builder()
                .id("Expire Files")
                .status(LifecycleRuleStatus.ENABLED)
                .prefix(metaData.getFileType())
                .expiration(DaysExpiration.builder().days(365).build())
                .build();
        rules.add(rule);

        BucketLifecycleConfiguration bucketLifecycleConfig = BucketLifecycleConfiguration.builder()
                .rules(rules)
                .build();

        s3Client.setBucketLifecycleConfiguration(SetBucketLifecycleConfigurationRequest.builder()
                .bucket(bucketName)
                .lifecycleConfiguration(bucketLifecycleConfig)
                .build());
    }

    private void monitorAndCleanup(Path path) {
        // Placeholder for external monitoring and cleanup logic
    }
}

