import java.io.FileInputStream;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

import software.amazon.awssdk.regions.Region;
import software.amazon.awssdk.services.s3.S3Client;
import software.amazon.awssdk.services.s3.model.PutBucketLifecycleConfigurationRequest;
import software.amazon.awssdk.services.s3.model.BucketLifecycleConfiguration;
import software.amazon.awssdk.services.s3.model.Rule;

public class FileMetadataProcessor {

    private static final Map<String, String> FILE_HASHES = new ConcurrentHashMap<>();

    public static Map<String, String> processFileMetadata(List<Path> filePaths) {
        Map<String, String> fileMetadataMap = new HashMap<>();
        S3Client s3Client = S3Client.builder().region(Region.US_EAST_1).build();

        for (Path path : filePaths) {
            try {
                byte[] fileBytes = Files.readAllBytes(path);
                String sha256 = computeSha256(fileBytes);
                String md5 = computeMd5(fileBytes);

                FILE_HASHES.put(sha256, md5);

                long fileSize = path.toFile().length();
                long lastModifiedTime = path.toFile().lastModified();

                fileMetadataMap.put(path.toString(), "Size: " + fileSize + ", Last Modified: " + lastModifiedTime + ", SHA-256: " + sha256 + ", MD5: " + md5);

                updateBucketLifecycle(s3Client, "my-bucket", new BucketRule(sha256, fileSize));
            } catch (IOException e) {
                throw new RuntimeException("Failed to process file: " + path.toString(), e);
            }
        }

        return fileMetadataMap;
    }

    private static String computeSha256(byte[] data) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] hashBytes = digest.digest(data);
        StringBuilder sb = new StringBuilder();
        for (byte b : hashBytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private static String computeMd5(byte[] data) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("MD5");
        byte[] hashBytes = digest.digest(data);
        StringBuilder sb = new StringBuilder();
        for (byte b : hashBytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private static void updateBucketLifecycle(S3Client s3Client, String bucketName, BucketRule rule) {
        try {
            BucketLifecycleConfiguration lifecycleConfig = new BucketLifecycleConfiguration.Builder()
                    .rule(rule.toRule())
                    .build();

            PutBucketLifecycleConfigurationRequest request = PutBucketLifecycleConfigurationRequest.builder()
                    .bucket(bucketName)
                    .lifecycleConfiguration(lifecycleConfig)
                    .build();

            s3Client.putBucketLifecycleConfiguration(request);
        } catch (Exception e) {
            throw new RuntimeException("Failed to update bucket lifecycle", e);
        }
    }

    public static class BucketRule {
        private String sha256;
        private long fileSize;

        public BucketRule(String sha256, long fileSize) {
            this.sha256 = sha256;
            this.fileSize = fileSize;
        }

        public Rule toRule() {
            return new Rule.Builder()
                    .id(sha256)
                    .status(Rule.RuleStatus.ENABLED)
                    .expirationDays((int) (fileSize / 1048576)) // Approximate days based on file size in MB
                    .build();
        }
    }

    public static class FileMetadata {
        private long size;
        private long lastModified;
        private String fileType;

        public FileMetadata(long size, long lastModified, String fileType) {
            this.size = size;
            this.lastModified = lastModified;
            this.fileType = fileType;
        }

        // Getters and setters
    }
}
