    printf("Errors encountered: %d\n", errorsEncountered);
}

int main() {
    int count = 1000;
    NFAPI_CRC_INDICATION_PDU_T *pdus = (NFAPI_CRC_INDICATION_PDU_T *) malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (pdus == NULL) {
        logInitialization(0, 1);
        return 1;
    }

    initializeNfaApiCrcIndicationPdu(pdus, count);

    for (int i = 0; i < count; i++) {
        // Validate structure integrity
        if (!(pdus[i].RX_UE_INFORMATION_TAG <= 1000 && pdus[i].RNTI <= 65536 && (pdus[i].CRCFLAG == 0 || pdus[i].CRCFLAG == 1))) {
            free(pdus);
            logInitialization(i, 1);
            return 1;
        }
    }

    free(pdus);
    logInitialization(count, 0);

    return 0;
}
