#include <stdlib.h>
#include <pthread.h>

typedef struct Data_Packet {
    int Packet_ID;
    time_t Transmission_Time;
    char Transmission_Status[50];
} Data_Packet;

typedef struct UserPlane_Connection {
    int Connection_ID;
    int Encryption_Status;
    pthread_mutex_t lock;
    Data_Packet** packets;
    int packet_count;
    int max_packets;
} UserPlane_Connection;

UserPlane_Connection* create_connection(int connection_id) {
    UserPlane_Connection* conn = malloc(sizeof(UserPlane_Connection));
    conn->Connection_ID = connection_id;
    conn->Encryption_Status = 0; // Assuming off by default
    pthread_mutex_init(&conn->lock, NULL);
    conn->packets = malloc(10 * sizeof(Data_Packet*)); // Initial capacity of 10
    conn->packet_count = 0;
    conn->max_packets = 10;
    return conn;
}

void destroy_connection(UserPlane_Connection* conn) {
    for (int i = 0; i < conn->packet_count; i++) {
        free(conn->packets[i]);
    }
    free(conn->packets);
    pthread_mutex_destroy(&conn->lock);
    free(conn);
}

int add_packet(UserPlane_Connection* conn, Data_Packet* packet) {
    pthread_mutex_lock(&conn->lock);
    if (conn->packet_count == conn->max_packets) {
        conn->packets = realloc(conn->packets, conn->max_packets * 2 * sizeof(Data_Packet*));
        conn->max_packets *= 2;
    }
    conn->packets[conn->packet_count++] = packet;
    pthread_mutex_unlock(&conn->lock);
    return 0; // Assuming success
}

int remove_packet(UserPlane_Connection* conn, int packet_id) {
    pthread_mutex_lock(&conn->lock);
    for (int i = 0; i < conn->packet_count; i++) {
        if (conn->packets[i]->Packet_ID == packet_id) {
            free(conn->packets[i]);
            for (int j = i; j < conn->packet_count - 1; j++) {
                conn->packets[j] = conn->packets[j + 1];
            }
            conn->packet_count--;
            pthread_mutex_unlock(&conn->lock);
            return 0; // Assuming success
        }
    }
    pthread_mutex_unlock(&conn->lock);
    return -1; // Packet not found
}

void update_packet(UserPlane_Connection* conn, int packet_id, char* new_status) {
    pthread_mutex_lock(&conn->lock);
    for (int i = 0; i < conn->packet_count; i++) {
        if (conn->packets[i]->Packet_ID == packet_id) {
            strcpy(conn->packets[i]->Transmission_Status, new_status);
            break;
        }
    }
    pthread_mutex_unlock(&conn->lock);
}

void transmit_packets(UserPlane_Connection* conn) {
    pthread_mutex_lock(&conn->lock);
    for (int i = 0; i < conn->packet_count; i++) {
        // Simulate transmission logic
        printf("Transmitting Packet %d\n", conn->packets[i]->Packet_ID);
    }
    pthread_mutex_unlock(&conn->lock);
}
