  async createNavItem(config) {
    const { route, label, iconClass, parentId, ...rest } = config;
    if (parentId) {
      // This is a nested item
      return this.createNestedItem(route, label, iconClass, parentId);
    } else {
      try {
        const resolvedLabel = localizeLabel(label, this.locale);
        const resolvedIconClass = await this.getIconClass(iconClass);
        const routeUrl = `${this.baseUrl}${route}`;
        return `<li><a href="${routeUrl}" class="sidebar-item"><i class="${resolvedIconClass}"></i> ${resolvedLabel}</a></li>`;
      } catch (error) {
        console.error('Failed to process item:', error);
        return '<li>Error processing item</li>';
      }
    }
  }

  async createNestedItem(route, label, iconClass, parentId) {
    // This method would recursively generate nested items if supported
    return `<li><a href="${this.baseUrl}${route}" class="sidebar-item"><i class="${iconClass}"></i> ${label}</a></li>`;
  }

  async getIconClass(iconClass) {
    if (this.iconCache[iconClass]) {
      return this.iconCache[iconClass];
    }
    try {
      const icon = await fetchIcon(iconClass);
      this.iconCache[iconClass] = icon;
      return icon;
    } catch (error) {
      console.error('Failed to load icon:', error);
      return 'default-icon-class';
    }
  }
}

