    return file_hashes

def is_symlink(path):
    return os.path.islink(path)

def is_encrypted(filename):
    with open(filename, 'rb') as f:
        header = f.read(16)
        return b'ENCRYPTED_FILE_HEADER' in header

def calculate_md5(file_path):
    md5_hash = hashlib.md5()
    if get_file_size(file_path) > 100 * 1024 * 1024:
        return calculate_md5_for_large_file(file_path, md5_hash)
    else:
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b""):
                md5_hash.update(chunk)
        return md5_hash.hexdigest()

def get_file_size(file_path):
    return os.path.getsize(file_path)

def calculate_md5_for_large_file(file_path, md5_hash):
    temp_dir = '/tmp/large_files'
    os.makedirs(temp_dir, exist_ok=True)
    with open(os.path.join(temp_dir, 'temp_file'), 'wb') as temp_file:
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b""):
                md5_hash.update(chunk)
                temp_file.write(chunk)
    return md5_hash.hexdigest()
