typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} CRC_Indication_Array_T;

CRC_Indication_Array_T* initialize_crc_indications(size_t initial_capacity) {
    CRC_Indication_Array_T *array = (CRC_Indication_Array_T*)malloc(sizeof(CRC_Indication_Array_T));
    if (!array) {
        perror("Failed to allocate memory for CRC indication array");
        return NULL;
    }

    array->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        free(array);
        perror("Failed to allocate memory for CRC indication data");
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void destroy_crc_indication_array(CRC_Indication_Array_T *array) {
    free(array->data);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int add_crc_indication(CRC_Indication_Array_T *array, NFAPI_CRC_INDICATION_PDU_T *indication) {
    pthread_mutex_lock(&array->lock);

    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&array->lock);
            perror("Failed to reallocate memory for CRC indication array");
            return -1;
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }

    memcpy(&array->data[array->size], indication, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->size++;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

