import os
import hashlib
import tempfile
import time
from retrying import retry

def process_directory(directory):
    file_hashes = {}
    for root, _, files in os.walk(directory):
        for file in files:
            file_path = os.path.join(root, file)
            if not os.path.islink(file_path) and not is_encrypted_file(file_path):
                hash_value = calculate_md5_hash(file_path)
                if hash_value is not None:
                    file_hashes[file_path] = hash_value
    return file_hashes

@retry(stop_max_attempt_number=3, wait_fixed=2000)
def calculate_md5_hash(file_path):
    try:
        if os.path.getsize(file_path) > 100 * 1024 * 1024:
            return process_large_file(file_path)
        else:
            return compute_md5(file_path)
    except Exception as e:
        print(f"Error processing file {file_path}: {e}")
        raise

def is_encrypted_file(file_path):
    with open(file_path, 'rb') as f:
        header = f.read(10)  # Assuming encryption headers are within the first 10 bytes
        return header.startswith(b'ENCRYPTED')

def compute_md5(file_path):
    hasher = hashlib.md5()
    with open(file_path, 'rb') as f:
        while chunk := f.read(4096):
            hasher.update(chunk)
    return hasher.hexdigest()

@retry(stop_max_attempt_number=3, wait_fixed=2000)
def process_large_file(file_path):
    temp_dir = tempfile.mkdtemp()
    temp_file = os.path.join(temp_dir, 'large_file')
    try:
        with open(file_path, 'rb') as large_file, open(temp_file, 'wb') as tmp:
            while chunk := large_file.read(1024 * 1024):
                tmp.write(chunk)
        return compute_md5(tmp.name)
    except Exception as e:
        print(f"Error processing large file {file_path}: {e}")
        raise
    finally:
        os.remove(temp_file)
        os.rmdir(temp_dir)
