import os
import hashlib
import logging
from concurrent.futures import ThreadPoolExecutor, as_completed

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

def process_file(file_path):
    if file_path.endswith('.enc'):
        logger.info(f"Skipping encrypted file: {file_path}")
        return None
    try:
        with open(file_path, 'rb') as file:
            hasher = hashlib.md5()
            while chunk := file.read(1024 * 1024):  # Read in 1MB chunks
                hasher.update(chunk)
            md5_hash = hasher.hexdigest()
            return {file_path: md5_hash}
    except Exception as e:
        logger.error(f"Error processing file {file_path}: {e}")
        return None

def process_directory(directory):
    results = {}
    with ThreadPoolExecutor(max_workers=10) as executor:
        futures = {executor.submit(process_file, os.path.join(root, file)): (root, file) for root, _, files in os.walk(directory) for file in files if not os.path.islink(os.path.join(root, file))}
        for future in as_completed(futures):
            try:
                result = future.result()
                if result:
                    results.update(result)
            except Exception as e:
                logger.error(f"Error processing file {futures[future]}: {e}")
    return results

# Example usage
