import os
import hashlib
import tempfile
from collections import defaultdict

def process_directory(directory_path):
    file_hashes = {}
    for root, _, files in os.walk(directory_path):
        for file_name in files:
            file_path = os.path.join(root, file_name)
            if os.path.islink(file_path) or is_corrupted_file(file_path):
                continue
            if get_file_size(file_path) > 100 * 1024 * 1024:
                process_large_file(file_hashes, file_path)
            else:
                process_small_file(file_hashes, file_path)
    return file_hashes

def is_corrupted_file(file_path):
    # Implement logic to check if the file is corrupted
    pass

def get_file_size(file_path):
    return os.path.getsize(file_path)

def process_large_file(file_hashes, file_path):
    with tempfile.TemporaryDirectory() as temp_dir:
        temp_file_path = os.path.join(temp_dir, os.path.basename(file_path))
        # Implement logic to read large files in chunks and save to temporary directory
        for chunk in read_in_chunks(file_path):
            write_chunk_to_temp_file(chunk, temp_file_path)
        file_hashes[file_path] = calculate_md5_hash(temp_file_path)

def process_small_file(file_hashes, file_path):
    file_hashes[file_path] = calculate_md5_hash(file_path)

def read_in_chunks(file_path, chunk_size=1024*1024):
    with open(file_path, 'rb') as f:
        while True:
            data = f.read(chunk_size)
            if not data:
                break
            yield data

def write_chunk_to_temp_file(chunk, temp_file_path):
    with open(temp_file_path, 'ab') as f:
        f.write(chunk)

def calculate_md5_hash(file_path):
    md5 = hashlib.md5()
    for chunk in read_in_chunks(file_path):
        md5.update(chunk)
    return md5.hexdigest()

