    {
    }

    public override async Task<bool> AccessFailedAsync(IdentityUser user)
    {
        if (await GetAccessFailedCountAsync(user) >= Options.Lockout.MaxFailedAccessAttempts)
        {
            await LockoutAsync(user, Options.Lockout.DefaultLockoutTimeSpan);
        }
        return await base.AccessFailedAsync(user);
    }

    public override async Task<IdentityResult> CreateAsync(IdentityUser user, string password)
    {
        if (password.Length < 8)
        {
            return IdentityResult.Failed(new IdentityError { Code = "PasswordTooShort", Description = "The password must be at least 8 characters long." });
        }
        return await base.CreateAsync(user, password);
