    if (!array) {
        perror("Failed to allocate memory for CRC Indication Array");
        return NULL;
    }

    array->crc_indications = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->crc_indications) {
        perror("Failed to allocate memory for CRC Indication PDUs");
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void destroy_crc_indications(CRC_Indication_Array *array) {
    if (array) {
        pthread_mutex_destroy(&array->mutex);
        free(array->crc_indications);
        free(array);
    }
}

bool add_crc_indication(CRC_Indication_Array *array, NFAPI_CRC_INDICATION_PDU_T new_indication) {
    pthread_mutex_lock(&array->mutex);

    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(array->crc_indications, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            perror("Failed to reallocate memory for CRC Indication PDUs");
            pthread_mutex_unlock(&array->mutex);
            return false;
        }

        array->crc_indications = new_data;
        array->capacity = new_capacity;
    }

    array->crc_indications[array->size++] = new_indication;

    pthread_mutex_unlock(&array->mutex);
    return true;
}

