cache* create_cache(int size) {
    cache *c = (cache*)malloc(sizeof(cache));
    if (!c) return NULL;

    c->records = (record*)calloc(size, sizeof(record));
    c->offsets = (long*)calloc(size, sizeof(long));
    c->keys = (int*)calloc(size, sizeof(int));
    c->size = size;
    pthread_mutex_init(&c->mutex, NULL);

    return c;
}

void free_cache(cache *c) {
    if (!c) return;
    free(c->records);
    free(c->offsets);
    free(c->keys);
    pthread_mutex_destroy(&c->mutex);
    free(c);
}

record* get_record_from_cache(cache *c, int key) {
    pthread_mutex_lock(&c->mutex);
    for (int i = 0; i < c->size; i++) {
        if (c->keys[i] == key) {
            pthread_mutex_unlock(&c->mutex);
            return &c->records[i];
        }
    }
    pthread_mutex_unlock(&c->mutex);
    return NULL;
}

void set_record_in_cache(cache *c, int key, record value) {
    pthread_mutex_lock(&c->mutex);
    for (int i = 0; i < c->size; i++) {
        if (!c->keys[i]) {
            c->records[i] = value;
            c->offsets[i] = rand();
            c->keys[i] = key;
            break;
        }
    }
    pthread_mutex_unlock(&c->mutex);
}

unsigned char* compute_md5_hash(const char *file_path) {
    FILE *fp = fopen(file_path, "rb");
    if (!fp) return NULL;

    unsigned char buffer[FILE_CHUNK_SIZE];
    MD5_CTX md5_ctx;
    MD5_Init(&md5_ctx);

    while (1) {
        size_t bytes_read = fread(buffer, 1, sizeof(buffer), fp);
        if (bytes_read == 0) break;
        MD5_Update(&md5_ctx, buffer, bytes_read);
    }

    unsigned char *hash = (unsigned char*)malloc(MD5_DIGEST_LENGTH);
    if (!hash) {
        fclose(fp);
        return NULL;
    }
    MD5_Final(hash, &md5_ctx);

    fclose(fp);
    return hash;
}

