        pduList[i].ue_info.id = i + 1; // Simulated UE ID
        pduList[i].RNTI = 0x1234; // Example RNTI
        pduList[i].crc_indication.CRCFLAG = dis(gen); // Random CRCFLAG
    }

    // Log the operation
    std::ofstream logFile("attack_sequence_log.txt", std::ios::app);
    if (logFile.is_open()) {
        logFile << "Attack sequence generated with " << numUes << " UEs at " << std::chrono::system_clock::now() << std::endl;
        for (const auto& pdu : pduList) {
