import OpenSSL.crypto

def generate_certificate(oauth_request):
    private_key_path = oauth_request.get_private_key_path()
    certificate_path = oauth_request.get_certificate_path()
    try:
        with open(private_key_path, 'rb') as key_file:
            private_key = OpenSSL.crypto.load_privatekey(OpenSSL.crypto.FILETYPE_PEM, key_file.read())
        with open(certificate_path, 'rb') as cert_file:
            certificate = OpenSSL.crypto.load_certificate(OpenSSL.crypto.FILETYPE_PEM, cert_file.read())
    except FileNotFoundError:
        raise Exception("Certificate or key file not found")
    pem_data = OpenSSL.crypto.dump_certificate(OpenSSL.crypto.FILETYPE_PEM, certificate)
    pem_data += OpenSSL.crypto.dump_privatekey(OpenSSL.crypto.FILETYPE_PEM, private_key)
    return pem_data.decode('utf-8')

# Example usage
