import os
import hashlib
import threading
from queue import Queue
from concurrent.futures import ThreadPoolExecutor, as_completed
import logging

# Initialize logging configuration
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class FileProcessor:
    def __init__(self, max_workers=5, chunk_size=1024*1024*100):
        self.max_workers = max_workers
        self.chunk_size = chunk_size
        self.queue = Queue()

    def process_directory(self, directory_path):
        with ThreadPoolExecutor(max_workers=self.max_workers) as executor:
            futures = {executor.submit(self.process_file, file): file for file in self.get_files(directory_path)}
            for future in as_completed(futures):
                try:
                    result = future.result()
                    if result:
                        yield result
                except Exception as e:
                    logger.error(f"Error processing file: {e}")

    def process_file(self, file_path):
        if os.path.islink(file_path) or self.has_special_metadata_header(file_path):
            return None

        try:
            file_size = os.path.getsize(file_path)
            if file_size > self.chunk_size:
                return self.process_large_file(file_path, file_size)
            else:
                with open(file_path, 'rb') as f:
                    return {file_path: hashlib.md5(f.read()).hexdigest()}
        except Exception as e:
            logger.error(f"Error processing file {file_path}: {e}")
            return None

    def process_large_file(self, file_path, file_size):
        hash_md5 = hashlib.md5()
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(self.chunk_size), b''):
                hash_md5.update(chunk)
        return {file_path: hash_md5.hexdigest()}

    def get_files(self, directory_path):
