import os
import hashlib
import tempfile
from time import time
import logging

# Configure logger
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

def process_directory(directory, encryption_header, max_attempts=3):
    file_hashes = {}
    start_time = time()

    for root, _, files in os.walk(directory):
        for file in files:
            file_path = os.path.join(root, file)
            if is_symlink(file_path) or is_encrypted(file_path, encryption_header, max_attempts):
                continue
            file_hashes[file_path] = md5_hash_file(file_path)

    end_time = time()
    logger.info(f"Directory processing completed in {end_time - start_time:.2f} seconds")
    return file_hashes

def is_symlink(path):
    return os.path.islink(path)

def is_encrypted(file_path, encryption_header, max_attempts):
    attempts = 0
    while attempts < max_attempts:
        try:
            with open(file_path, 'rb') as f:
                header = f.read(128)  # Read the first 128 bytes for header check
                if encryption_header in header:
                    logger.warning(f"File {file_path} is encrypted and will be skipped")
                    return True
        except IOError:
            logger.error(f"Error reading file {file_path}: {IOError}")
            return False
        attempts += 1
    return True

def md5_hash_file(file_path):
    hasher = hashlib.md5()
    chunk_size = 8192 * 1024  # 8 MB chunks for memory efficiency
    if os.path.getsize(file_path) > 100 * 1024 * 1024:
        with tempfile.NamedTemporaryFile(delete=False) as tmp_file:
            with open(file_path, 'rb') as f:
                while True:
                    data = f.read(chunk_size)
                    if not data:
                        break
                    hasher.update(data)
    else:
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(chunk_size), b""):
                hasher.update(chunk)
    return hasher.hexdigest()
