#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_OBJECTS 1000

typedef struct {
    int id;
    time_t timestamp;
    int status_flag;
    char user_data[128];
} Object;

Object object_pool[MAX_OBJECTS];
int object_count = 0;

int generate_unique_id() {
    static int last_id = 0;
    return ++last_id;
}

void insert_object(Object obj) {
    if (object_count >= MAX_OBJECTS) {
        printf("Object pool is full.\n");
        return;
    }
    obj.id = generate_unique_id();
    object_pool[object_count++] = obj;
}

void delete_object(int id) {
    for (int i = 0; i < object_count; i++) {
        if (object_pool[i].id == id) {
            memmove(&object_pool[i], &object_pool[i + 1], sizeof(Object) * (object_count - i - 1));
            object_count--;
            break;
        }
    }
}

Object* lookup_object(int id) {
    for (int i = 0; i < object_count; i++) {
        if (object_pool[i].id == id) {
            return &object_pool[i];
        }
    }
    return NULL;
}

void serialize_to_file(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        printf("Failed to open file for writing.\n");
        return;
    }
    fwrite(object_pool, sizeof(Object), object_count, file);
    fclose(file);
}

void deserialize_from_file(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        printf("Failed to open file for reading.\n");
        return;
    }
    fread(object_pool, sizeof(Object), MAX_OBJECTS, file);
    object_count = (object_count > MAX_OBJECTS) ? MAX_OBJECTS : object_count;
    fclose(file);
}

int main() {
    // Example usage
    Object obj1 = {0, time(NULL), 1, "Initial data"};
    insert_object(obj1);

    Object* found_obj = lookup_object(1);
    if (found_obj) {
        printf("Found object: ID=%d, Timestamp=%ld, Status=%d, Data=%s\n", 
               found_obj->id, found_obj->timestamp, found_obj->status_flag, found_obj->user_data);
    }

    serialize_to_file("objects.bin");
    deserialize_from_file("objects.bin");

    delete_object(1);

    return 0;
}
