import os
import hashlib
import tempfile
from concurrent.futures import ThreadPoolExecutor
import logging
import time

# Initialize logger
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

def process_file(file_path):
    try:
        if not os.path.isfile(file_path) or os.path.islink(file_path):
            return None
        with open(file_path, 'rb') as f:
            md5_hash = hashlib.md5(f.read()).hexdigest()
        return {file_path: md5_hash}
    except Exception as e:
        logger.error(f"Failed to process file {file_path}: {e}")
        return None

def batch_process_files(file_paths):
    results = {}
    with ThreadPoolExecutor(max_workers=10) as executor:
        futures = {executor.submit(process_file, path): path for path in file_paths}
        for future in futures.as_completed(futures):
            path = futures[future]
            try:
                result = future.result()
                if result:
                    results.update(result)
            except Exception as e:
                logger.error(f"Error processing file {path}: {e}")
    return results

def main(directory_path):
    start_time = time.time()
    all_files = [os.path.join(root, f) for root, _, files in os.walk(directory_path) for f in files]
    md5_dict = batch_process_files(all_files)
    elapsed_time = time.time() - start_time
    logger.info(f"Processed {len(md5_dict)} files in {elapsed_time:.2f} seconds")

if __name__ == "__main__":
    directory_path = "/path/to/your/directory"
    main(directory_path)
