def calculate_md5(file_path):
    """Calculate MD5 hash for a given file."""
    hasher = hashlib.md5()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b''):
            hasher.update(chunk)
    return hasher.hexdigest()

def process_file(file_path):
    """Process a single file to calculate its MD5 hash."""
    try:
        if os.path.islink(file_path) or is_encrypted(file_path):
            return None
        if get_file_size(file_path) > 100 * 2**20:
