    return os.path.getsize(file_path)

def is_remote_access(file_path):
    """Check if the file has a specific metadata header indicating remote access."""
    with open(file_path, 'rb') as f:
        header = f.read(1024)  # Read first 1024 bytes for the header
    return b'REMOTE_ACCESS' in header

def process_directory(directory):
