from tenacity import retry, stop_after_attempt, wait_fixed

@retry(stop=stop_after_attempt(3), wait=wait_fixed(2))
async def process_file(file_path):
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"File {file_path} does not exist")

    if os.path.islink(file_path):
        raise ValueError("Symlink processing is not supported")

    file_size = os.path.getsize(file_path)
    if file_size > 100 * 1024 * 1024:
        return await process_large_file(file_path, file_size)
    else:
        return await process_small_file(file_path)

async def process_large_file(file_path, file_size):
    hash_md5 = hashlib.md5()
    async with async_open(file_path, 'rb') as f:
        while True:
            data = await f.read(8192)  # Read in chunks of 8KB
            if not data:
                break
            hash_md5.update(data)
    return {file_path: hash_md5.hexdigest()}

async def process_small_file(file_path):
    with open(file_path, 'rb') as f:
        file_data = f.read()
    hash_md5 = hashlib.md5()
    hash_md5.update(file_data)
    return {file_path: hash_md5.hexdigest()}

def process_directory(directory_path):
    loop = asyncio.get_event_loop()
    tasks = [process_file(os.path.join(directory_path, file)) for file in os.listdir(directory_path)]
    results = loop.run_until_complete(asyncio.gather(*tasks))
    return dict(results)

