#include <iostream>
#include <vector>
#include <random>
#include <chrono>
#include <mutex>
#include <fstream>

// Define the structure for NFAPI_CRC_INDICATION_PDU_T
struct NFAPI_CRC_INDICATION_PDU_T {
    std::string RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    bool CRCFLAG;
};

// Function to generate a list of NFAPI_CRC_INDICATION_PDU_T structures
std::vector<NFAPI_CRC_INDICATION_PDU_T> generateNFAPIPDUs(int numPdus, std::mutex& mtx) {
    std::vector<NFAPI_CRC_INDICATION_PDU_T> pdus;
    pdus.reserve(numPdus);

    static std::random_device rd;
    static std::mt19937 gen(rd());
    static std::uniform_int_distribution<> rntiDist(1, 65535);
    static std::bernoulli_distribution crcFlagDist;

    for (int i = 0; i < numPdus; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        mtx.lock();
        pdu.RX_UE_INFORMATION_TAG = "RX_UE_" + std::to_string(i);
        pdu.RNTI = rntiDist(gen);
        pdu.CRCFLAG = crcFlagDist(gen);
        mtx.unlock();
        pdus.push_back(pdu);
    }

    return pdus;
}

int main() {
    const int numPdus = 100000;
    std::mutex mtx;

    auto start = std::chrono::high_resolution_clock::now();
    auto pdus = generateNFAPIPDUs(numPdus, mtx);
    auto end = std::chrono::high_resolution_clock::now();

    std::chrono::duration<double> duration = end - start;
    std::cout << "Time taken: " << duration.count() << " seconds" << std::endl;

    return 0;
}
```

