function generateSidebar(config, baseUrl = '#/', locale = 'en') {
    // Fetch route metadata from external API
    async function fetchRouteMetadata(route) {
        try {
            const response = await fetch(`/api/routes/${route}`);
            return response.json();
        } catch (error) {
            console.error(`Error fetching route metadata for ${route}:`, error);
            return {};
        }
    }

    // Fetch icon class from external API
    async function fetchIconClass(iconId, locale) {
        try {
            const response = await fetch(`/api/icons/${iconId}?locale=${locale}`);
            const data = await response.json();
            return data.icon_class;
        } catch (error) {
            console.error(`Error fetching icon class for ${iconId}:`, error);
            return 'default-icon';
        }
    }

    // Recursive function to build the sidebar HTML
    async function buildSidebarItem(item, parentClass = '') {
        const { route, label, icon, children } = item;
        const metadata = await fetchRouteMetadata(route);
        const iconClass = await fetchIconClass(icon, locale);

        let html = `
            <li class="sidebar-item ${parentClass}">
                <a href="${baseUrl + route}" class="sidebar-link">
                    <i class="${iconClass}"></i> ${label}
                </a>
                ${children && children.length ? '<ul>' : ''}
        `;

        if (children && children.length) {
            for (const child of children) {
                html += await buildSidebarItem(child, 'submenu');
            }
            html += '</ul>';
        }

        return html;
    }

    // Generate the sidebar HTML
    async function generateHTML() {
        let sidebarHtml = '<ul class="sidebar">';
        for (const item of config) {
            sidebarHtml += await buildSidebarItem(item);
        }
        sidebarHtml += '</ul>';
        return sidebarHtml;
    }

    return generateHTML();
}

// Example usage:
