import os
import hashlib
import tempfile
import threading
import time

def generate_md5_hash(file_path):
    hasher = hashlib.md5()
    with open(file_path, 'rb') as f:
        buf = f.read(65536)  # Read in chunks of 64KB to manage memory usage
        while buf:
            hasher.update(buf)
            buf = f.read(65536)
    return hasher.hexdigest()

def process_directory(directory_path, max_retries=3):
    file_hashes = {}
    temp_dir = tempfile.mkdtemp()

    def process_file(file_path):
        if os.path.islink(file_path):
            return
        try:
            if os.path.getsize(file_path) > 1024 * 1024 * 100:  # Check file size
                temp_path = os.path.join(temp_dir, os.path.basename(file_path))
                with open(file_path, 'rb') as src, open(temp_path, 'wb') as dst:
                    shutil.copyfileobj(src, dst)  # Copy large files to temporary storage
                    hash_value = generate_md5_hash(temp_path)
            else:
                hash_value = generate_md5_hash(file_path)
            file_hashes[file_path] = hash_value
        except Exception as e:
            for _ in range(max_retries):
                try:
                    hash_value = generate_md5_hash(file_path)
                    file_hashes[file_path] = hash_value
                    break
                except Exception as e:
                    time.sleep(1)  # Wait before retrying

    def check_disk_usage():
        while True:
            disk_usage = get_disk_usage()  # Implement this function to retrieve disk usage
            if disk_usage > threshold:
                prioritize_small_files()  # Implement this function to handle high disk usage
            time.sleep(60)  # Check every minute

    disk_usage_thread = threading.Thread(target=check_disk_usage)
    disk_usage_thread.start()

    for root, _, files in os.walk(directory_path):
        for file in files:
            file_path = os.path.join(root, file)
            process_file(file_path)

    disk_usage_thread.join()
    return file_hashes

# Example usage
directory_path = '/path/to/directory'
result = process_directory(directory_path)
print(result)
