#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct {
    unsigned int CRC_FLAG : 1;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

int initialize_and_populate(NFAPI_CRC_INDICATION_PDU_T *pdu_array, int num_instances) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
    int allocated_memory_size = 1024 * 1024; // 1MB

    if (num_instances > 50000) {
        fprintf(stderr, "Error: Number of UE instances exceeds maximum limit.\n");
        return -1;
    }

    pdu_array = realloc(pdu_array, num_instances * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_array) {
        perror("Failed to allocate memory for PDU array.");
        return -2;
    }

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < num_instances; i++) {
        pthread_mutex_lock(&mutex);
        while (allocated_memory_size <= i * sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
            pthread_cond_wait(&cond, &mutex);
        }
        allocated_memory_size += sizeof(NFAPI_CRC_INDICATION_PDU_T);

        RX_UE_INFORMATION_TAG rx_info_tag;
        CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;

        // Populate with valid data
        rx_info_tag.RNTI = rand();
        crc_indication_rel8_tag.CRC_FLAG = (rand() % 2) == 0 ? 1 : 0; // Randomly set CRC flag

        pdu_array[i].rx_ue_info_tag = rx_info_tag;
        pdu_array[i].crc_indication_rel8_tag = crc_indication_rel8_tag;

        pthread_cond_signal(&cond);
        pthread_mutex_unlock(&mutex);
    }

    return num_instances;
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *pdu_array = NULL;
    int num_instances = 10000; // Example number of UE instances

    if (initialize_and_populate(pdu_array, num_instances) == -1) {
        fprintf(stderr, "Error initializing PDU array.\n");
        return EXIT_FAILURE;
    }

    // Use pdu_array for further processing

    free(pdu_array);
    return EXIT_SUCCESS;
}
