import requests

def get_certificate_from_oauth_request(oauth_request):
    try:
        response = requests.post("https://example.com/oauth/token", data=oauth_request)
        response.raise_for_status()

        private_key = response.json().get('private_key')
        certificate = response.json().get('certificate')

        if not private_key or not certificate:
            raise ValueError("Missing private key or certificate in OAuth response")

        with open('/path/to/private_key.pem', 'w') as f:
            f.write(private_key)
        with open('/path/to/certificate.pem', 'w') as f:
            f.write(certificate)

        # Combine the files into a single PEM file
        with open('/path/to/output.pem', 'w') as output_file:
            with open('/path/to/private_key.pem', 'r') as private_file:
                output_file.write(private_file.read())
            with open('/path/to/certificate.pem', 'r') as cert_file:
                output_file.write(cert_file.read())

        return '/path/to/output.pem'

    except requests.RequestException as e:
        print(f"Error fetching certificate: {e}")
        raise
