typedef struct {
    NFAPI_RX_FRAME_PDU_T *frames;
    size_t count;
    pthread_mutex_t lock;
} FrameList;

FrameList* create_frame_list(size_t initial_size) {
    FrameList *list = (FrameList*)malloc(sizeof(FrameList));
    if (!list) return NULL;

    list->frames = (NFAPI_RX_FRAME_PDU_T*)malloc(initial_size * sizeof(NFAPI_RX_FRAME_PDU_T));
    if (!list->frames) {
        free(list);
        return NULL;
    }

    list->count = initial_size;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_frame_list(FrameList *list) {
    pthread_mutex_lock(&list->lock);
    free(list->frames);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_frame(FrameList *list, NFAPI_RX_FRAME_PDU_T *frame) {
    pthread_mutex_lock(&list->lock);

    if (list->count == 0 || list->frames[list->count - 1].RX_FRAME_INFORMATION_TAG != frame->RX_FRAME_INFORMATION_TAG) {
        list->frames = (NFAPI_RX_FRAME_PDU_T*)realloc(list->frames, (list->count + 1) * sizeof(NFAPI_RX_FRAME_PDU_T));
        if (!list->frames) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
    }

    memcpy(&list->frames[list->count], frame, sizeof(NFAPI_RX_FRAME_PDU_T));
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

