import os
import hashlib
import tempfile
import time
import logging
import asyncio

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

def process_directory(directory):
    file_hashes = {}
    temp_dir = tempfile.mkdtemp()

    for root, _, files in os.walk(directory):
        for file in files:
            file_path = os.path.join(root, file)
            if not os.path.islink(file_path):
                try:
                    if is_encrypted_file(file_path):
                        logger.info(f"Skipping encrypted file: {file_path}")
                        continue
                    hash_value = calculate_md5_hash(file_path, temp_dir)
                    if hash_value:
                        file_hashes[file_path] = hash_value
                except Exception as e:
                    logger.error(f"Error processing file {file_path}: {e}")

    logger.info("File processing completed.")
    return file_hashes

def is_encrypted_file(file_path):
    # Implement logic to check for encryption header
    pass

async def calculate_md5_hash(file_path, temp_dir):
    hash_md5 = hashlib.md5()
    chunk_size = 8192 * 1024  # 8MB chunks

    if os.path.getsize(file_path) > 100 * 1024 * 1024:
        with tempfile.NamedTemporaryFile(dir=temp_dir, delete=False) as temp_file:
            with open(file_path, 'rb') as f:
                while True:
                    chunk = f.read(chunk_size)
                    if not chunk:
                        break
                    hash_md5.update(chunk)
                    temp_file.write(chunk)
            file_path = temp_file.name

    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(chunk_size), b""):
            hash_md5.update(chunk)

    return hash_md5.hexdigest()

def retry_with_exponential_backoff(func, max_retries=3):
    for attempt in range(max_retries + 1):
        try:
            return func()
        except Exception as e:
            if attempt < max_retries:
                delay = 2 ** attempt
                logger.warning(f"Attempt {attempt + 1} failed. Retrying in {delay}s.")
                time.sleep(delay)
            else:
                raise e

# Example usage
directory_path = '/path/to/directory'
result = retry_with_exponential_backoff(lambda: process_directory(directory_path))
