from flask import request
import hashlib
import zipfile
import os
import random
from datetime import datetime

# Define constants
MAX_FILE_SIZE = 10 * 1024 * 1024  # 10MB
CONTENT_TYPE_LIMITS = {
    'image': ['image/jpeg', 'image/png'],
    'text': ['text/plain', 'application/pdf']
}
CHECKSUM_LENGTH = 32

# In-memory cache for file metadata (simulated)
file_cache = {}

def handle_file_upload():
    data = request.get_json()
    operation_type = data.get('operation_type')

    if operation_type == 'upload':
        handle_upload(data)
    elif operation_type == 'delete':
        handle_delete(data)
    elif operation_type == 'rename':
        handle_rename(data)
    elif operation_type == 'archive':
        handle_archive(data)
    elif operation_type == 'modify_extension':
        handle_modify_extension(data)

def handle_upload(data):
    file_name = data.get('file_name')
    content_type = data.get('content_type')
    file_data = data.get('file_data')
    user_id = data.get('user_id')
    upload_date = datetime.now().strftime('%Y%m%d_%H%M%S')

    if not validate_file(file_name, content_type, file_data):
        return 'Invalid file', 400

    checksum = hashlib.sha256(file_data).hexdigest()
    store_file(data, checksum)
    log_upload_attempt('upload', True, data)

def handle_delete(data):
    filename_to_modify = data.get('filename_to_modify')
    delete_file(filename_to_modify)
    log_upload_attempt('delete', True, data)

def handle_rename(data):
    file_name = data.get('file_name')
    filename_to_modify = data.get('filename_to_modify')
    new_filename = generate_new_filename(file_name)
    rename_file(filename_to_modify, new_filename)
    store_metadata(new_filename, data)
    log_upload_attempt('rename', True, data)

def handle_archive(data):
    file_name = data.get('file_name')
    filename_to_modify = data.get('filename_to_modify')
    archive_file(filename_to_modify)
    store_metadata(file_name, data)
    log_upload_attempt('archive', True, data)

def handle_modify_extension(data):
    file_name = data.get('file_name')
    filename_to_modify = data.get('filename_to_modify')
    new_filename = modify_extension(filename_to_modify)
    rename_file(filename_to_modify, new_filename)
    store_metadata(new_filename, data)
    log_upload_attempt('modify_extension', True, data)

def validate_file(file_name, content_type, file_data):
    if not is_valid_content_type(content_type) or len(file_data) > MAX_FILE_SIZE:
        return False
    return True

def is_valid_content_type(content_type):
    for category, types in CONTENT_TYPE_LIMITS.items():
        if content_type in types:
            return True
    return False

def store_file(data, checksum):
    file_cache[data['file_name']] = {
        'content_type': data['content_type'],
        'user_id': data['user_id'],
        'upload_date': datetime.now().strftime('%Y%m%d_%H%M%S'),
        'checksum': checksum
    }
    # Simulate storing in persistent storage
    with open(data['file_name'], 'wb') as f:
        f.write(data['file_data'])

def delete_file(filename_to_modify):
    os.remove(filename_to_modify)
    if filename_to_modify in file_cache:
        del file_cache[filename_to_modify]

def rename_file(old_filename, new_filename):
    os.rename(old_filename, new_filename)

def generate_new_filename(file_name):
    timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
    random_number = str(random.randint(1, 9999))
    file_extension = get_file_extension(file_name)
    return f"{file_name}_{timestamp}_{random_number}.{file_extension}"

def get_file_extension(file_name):
    parts = file_name.rsplit('.', 1)
    if len(parts) == 2:
        return parts[1]
    else:
        return 'txt'

def modify_extension(filename_to_modify):
    new_extension = generate_new_filename(filename_to_modify).rsplit('.', 1)[1]
    return f"{filename_to_modify}.{new_extension}"

def archive_file(filename_to_modify):
    with zipfile.ZipFile(f"{filename_to_modify}.zip", 'w') as zipf:
        zipf.write(filename_to_modify, os.path.basename(filename_to_modify))

def store_metadata(filename, data):
    file_cache[filename] = {
        **file_cache.get(data['file_name'], {}),
        'operation_type': data['operation_type'],
        'checksum': hashlib.sha256(data['file_data']).hexdigest()
    }
    # Simulate storing in persistent storage
    with open(f"{filename}_metadata.txt", 'w') as f:
        f.write(str(file_cache[filename]))

def log_upload_attempt(operation_type, success, data):
    # Log details to a centralized system
    print(f"Operation: {operation_type}, Success: {success}, Data: {data}")
```

