typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define your structure members here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct UeInstance {
    NFAPI_CRC_INDICATION_PDU_T *crcIndication;
    pthread_mutex_t lock;
    int priority;
    // Other UE instance specific data
} UeInstance;

UeInstance *ueInstances[MAX_UE_INSTANCES];
int ueCount = 0;
pthread_mutex_t ueListLock;

void initUeInstance(int ueId, int initialPriority) {
    if (ueId < 0 || ueId >= MAX_UE_INSTANCES) return;
    pthread_mutex_lock(&ueListLock);
    if (ueInstances[ueId] == NULL) {
        ueInstances[ueId] = (UeInstance *)malloc(sizeof(UeInstance));
        ueInstances[ueId]->crcIndication = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pthread_mutex_init(&ueInstances[ueId]->lock, NULL);
        ueInstances[ueId]->priority = initialPriority;
    }
    pthread_mutex_unlock(&ueListLock);
}

void freeUeInstance(int ueId) {
    if (ueId < 0 || ueId >= MAX_UE_INSTANCES) return;
    pthread_mutex_lock(&ueListLock);
    if (ueInstances[ueId] != NULL) {
        free(ueInstances[ueId]->crcIndication);
        pthread_mutex_destroy(&ueInstances[ueId]->lock);
        free(ueInstances[ueId]);
        ueInstances[ueId] = NULL;
    }
    pthread_mutex_unlock(&ueListLock);
}

void updateUePriority(int ueId, int newPriority) {
    if (ueId < 0 || ueId >= MAX_UE_INSTANCES) return;
    pthread_mutex_lock(&ueInstances[ueId]->lock);
    ueInstances[ueId]->priority = newPriority;
    pthread_mutex_unlock(&ueInstances[ueId]->lock);
}

void *generateCrcIndication(void *arg) {
    int ueId = *(int *)arg;
    if (ueId < 0 || ueId >= MAX_UE_INSTANCES) return NULL;

    pthread_mutex_lock(&ueInstances[ueId]->lock);
    // Generate CRC indication for the UE instance
    // Example: memcpy(ueInstances[ueId]->crcIndication, &generatedData, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_unlock(&ueInstances[ueId]->lock);

    return NULL;
}

int main() {
    pthread_t threads[MAX_UE_INSTANCES];
    int threadIds[MAX_UE_INSTANCES];

    // Initialize UE instances
    for (int i = 0; i < MAX_UE_INSTANCES; i++) {
        initUeInstance(i, 1); // Initial priority set to 1
    }

    // Create threads to generate CRC indications for each UE instance
    for (int i = 0; i < MAX_UE_INSTANCES; i++) {
        threadIds[i] = i;
        pthread_create(&threads[i], NULL, generateCrcIndication, &threadIds[i]);
    }

    // Join threads
    for (int i = 0; i < MAX_UE_INSTANCES; i++) {
        pthread_join(threads[i], NULL);
    }

    // Free allocated memory and clean up UE instances
    for (int i = 0; i < MAX_UE_INSTANCES; i++) {
        freeUeInstance(i);
    }

    return 0;
}
