def rate_limit(max_calls, period=timedelta(minutes=1)):
    def decorator(func):
        calls = {}

        @wraps(func)
        def wrapper(*args, **kwargs):
            client_ip = kwargs.get('client_ip')
            now = time.time()

            if client_ip in calls:
                calls[client_ip] = [x for x in calls[client_ip] if now - x < period.total_seconds()]
                if len(calls[client_ip]) >= max_calls:
                    raise Exception("Rate limit exceeded")

            calls.setdefault(client_ip, []).append(now)
            return func(*args, **kwargs)

        return wrapper
    return decorator

def log_transaction(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        operation_id = kwargs.get('operation_id', 'N/A')
        client_ip = kwargs.get('client_ip', 'N/A')
        start_time = time.time()

        try:
            result = func(*args, **kwargs)
            status = "Success"
        except Exception as e:
            logging.error(f"Operation {operation_id} failed for IP {client_ip}: {str(e)}")
            status = "Failure"

        end_time = time.time()
        logging.info(f"Operation {operation_id} by IP {client_ip} took {end_time - start_time:.2f}s and was {status}")

        return result
    return wrapper

