// Function to generate a dynamically allocated array of custom network protocol packets
char** update_system_config_with_custom_protocol(int num_packets, const char* data_format, size_t max_payload_size) {
    if (num_packets <= 0 || data_format == NULL || max_payload_size == 0) {
        return NULL;
    }

    // Allocate memory for the array of packet strings
    char** packets = (char**)malloc(num_packets * sizeof(char*));
    if (packets == NULL) {
        perror("Failed to allocate memory for packets");
        return NULL;
    }

    // Generate unique protocol identifiers, timestamps, and payloads for each packet
    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < num_packets; ++i) {
        char* packet = (char*)malloc(256 * sizeof(char));
        if (packet == NULL) {
            perror("Failed to allocate memory for packet");
            return packets; // Return partially allocated array
        }

        // Generate unique protocol identifier
        snprintf(packet, 256, "Protocol%d", i);

        // Get current timestamp
        time_t now = time(NULL);
        struct tm* tm_info = localtime(&now);
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        // Generate a unique payload based on the data format and max_payload_size
        char* payload = generate_random_payload(data_format, max_payload_size);
        if (payload == NULL) {
            free(packet); // Free partially allocated memory
            return packets; // Return partially allocated array
        }

        // Construct the packet string
        snprintf(packet, 256, "%s|%s|%s", packet, timestamp, payload);

        // Add the packet to the array
        packets[i] = packet;
    }

    return packets;
}

// Helper function to generate a random payload based on data format and max_payload_size
char* generate_random_payload(const char* data_format, size_t max_payload_size) {
    if (data_format == NULL || max_payload_size == 0) {
        return NULL;
    }

    // Implement logic to generate a unique payload based on the data format and max_payload_size
    // This is a placeholder implementation
    char* payload = (char*)malloc(max_payload_size * sizeof(char));
    if (payload == NULL) {
        perror("Failed to allocate memory for payload");
        return NULL;
    }

    // Fill the payload with random characters or formatted data
    for (size_t i = 0; i < max_payload_size - 1; ++i) {
        payload[i] = rand() % 256;
    }
    payload[max_payload_size - 1] = '\0';

    return payload;
}
