#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a structure for a linked list node
typedef struct Node {
    int key;
    struct Node* next;
} Node;

// Define a function to create a new node
Node* create_node(int key) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    new_node->key = key;
    new_node->next = NULL;
    return new_node;
}

// Define a function to insert a node into the linked list
void insert_node(Node** head, int key) {
    Node* new_node = create_node(key);
    if (*head == NULL) {
        *head = new_node;
    } else {
        Node* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }
}

// Define a function to delete a node from the linked list
void delete_node(Node** head, int key) {
    Node* temp = *head;
    Node* prev = NULL;
    while (temp != NULL && temp->key != key) {
        prev = temp;
        temp = temp->next;
    }
    if (temp == NULL) {
        printf("Key not found\n");
        return;
    }
    if (prev == NULL) {
        *head = temp->next;
    } else {
        prev->next = temp->next;
    }
    free(temp);
}

// Define a function to search for a node in the linked list
Node* search_node(Node** head, int key) {
    Node* temp = *head;
    while (temp != NULL && temp->key != key) {
        temp = temp->next;
    }
    return temp;
}

// Define a function to serialize the linked list to a binary file
void serialize_list(Node** head, FILE* fp) {
    Node* temp = *head;
    while (temp != NULL) {
        fwrite(&temp->key, sizeof(int), 1, fp);
        temp = temp->next;
    }
}

// Define a function to deserialize the linked list from a binary file
void deserialize_list(Node** head, FILE* fp) {
    int key;
    while (fread(&key, sizeof(int), 1, fp)) {
        insert_node(head, key);
    }
}
