// Define structures for network interface configuration
typedef struct {
    char device_name[64];
    char ip_address[128];
    char subnet_mask[32];
    char gateway[128];
    char security_key[256];
} NetworkConfig;

typedef struct {
    NetworkConfig *configs;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} ConfigList;

// Initialize the configuration list
void init_config_list(ConfigList *list) {
    list->configs = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);
}

// Add a new network configuration to the list
int add_config(ConfigList *list, NetworkConfig config) {
    pthread_mutex_lock(&list->lock);
    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity == 0 ? 1 : list->capacity * 2;
        NetworkConfig *new_configs = realloc(list->configs, new_capacity * sizeof(NetworkConfig));
        if (!new_configs) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }
        list->configs = new_configs;
        list->capacity = new_capacity;
    }
    memcpy(&list->configs[list->count], &config, sizeof(NetworkConfig));
    list->count++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Remove a network configuration from the list
int remove_config(ConfigList *list, const char *device_name) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; i++) {
        if (strcmp(list->configs[i].device_name, device_name) == 0) {
            memmove(&list->configs[i], &list->configs[i + 1], (list->count - i - 1) * sizeof(NetworkConfig));
            list->count--;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // Configuration not found
}

// Update an existing network configuration
int update_config(ConfigList *list, const char *device_name, NetworkConfig new_config) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; i++) {
        if (strcmp(list->configs[i].device_name, device_name) == 0) {
            memcpy(&list->configs[i], &new_config, sizeof(NetworkConfig));
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // Configuration not found
}

// Clean up and free the configuration list
void cleanup_config_list(ConfigList *list) {
    pthread_mutex_lock(&list->lock);
    free(list->configs);
    pthread_mutex_destroy(&list->lock);
    memset(list, 0, sizeof(ConfigList));
}
