            stream.next_out = output.data();
            deflate(&stream, Z_FINISH);
            output.resize(stream.total_out);
        } while (stream.avail_out == 0);
        deflateEnd(&stream);
        return std::string(reinterpret_cast<char*>(output.data()), stream.total_out);
