            stream.next_out = output.data();
            inflate(&stream, Z_FINISH);
            output.resize(stream.total_out);
        } while (stream.avail_out == 0);
        inflateEnd(&stream);
        std::vector<AttackStructure> attackPool(output.size() / sizeof(AttackStructure));
