```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define N 1000

typedef struct {
    // Define your structure fields here
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T** list = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int allocate_list() {
    pthread_mutex_lock(&lock);
    if (list != NULL) {
        pthread_mutex_unlock(&lock);
        return -1; // List already allocated
    }
    list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (list == NULL) {
        pthread_mutex_unlock(&lock);
        return -2; // Memory allocation failed
    }
    for (int i = 0; i < N; i++) {
        list[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (list[i] == NULL) {
            pthread_mutex_unlock(&lock);
            return -3; // Memory allocation failed
        }
        // Initialize fields with random values
        list[i]->RX_UE_INFORMATION_TAG = rand();
        list[i]->RNTI = rand();
        list[i]->CRC_INDICATION_REL8_TAG = rand();
        list[i]->CRCFLAG = rand() % 2;
    }
    pthread_mutex_unlock(&lock);
    return 0; // Success
}

void free_list() {
    pthread_mutex_lock(&lock);
    if (list != NULL) {
        for (int i = 0; i < N; i++) {
            if (list[i] != NULL) {
                free(list[i]);
            }
        }
        free(list);
        list = NULL;
    }
    pthread_mutex_unlock(&lock);
}

void* reverse_iterator(void* arg) {
    int index = *(int*)arg;
    while (index >= 0 && list[index] != NULL) {
        // Process list[index]
        printf("Processing: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d, CRCFLAG=%d\n",
               list[index]->RX_UE_INFORMATION_TAG, list[index]->RNTI,
               list[index]->CRC_INDICATION_REL8_TAG, list[index]->CRCFLAG);
        index--;
    }
    free(arg);
    return NULL;
}

int main() {
    if (allocate_list() == 0) {
        pthread_t threads[N];
        int indices[N];
        for (int i = 0; i < N; i++) {
            indices[i] = i;
            pthread_create(&threads[i], NULL, reverse_iterator, &indices[i]);
        }
        for (int i = 0; i < N; i++) {
            pthread_join(threads[i], NULL);
        }
        free_list();
    } else {
        printf("Failed to allocate list\n");
    }
    return 0;
}
