#define MAX_TRANSACTION_LOGS 1000

typedef struct {
    int id;
    char timestamp[20];
    char operation_type[50];
    int status_code;
} TransactionLog;

typedef struct {
    int transaction_id;
    int latest_status_code;
} GlobalTransactionStatus;

GlobalTransactionStatus global_statuses[MAX_TRANSACTION_LOGS];

void updateGlobalDatabase(int transaction_id, int status_code) {
    for (int i = 0; i < MAX_TRANSACTION_LOGS; ++i) {
        if (global_statuses[i].transaction_id == transaction_id) {
            global_statuses[i].latest_status_code = status_code;
            return;
        }
    }
}

void processBatchTransactionLogs(TransactionLog logs[], int count) {
    for (int i = 0; i < count; ++i) {
        updateGlobalDatabase(logs[i].id, logs[i].status_code);
    }
}

int main() {
    TransactionLog logs[MAX_TRANSACTION_LOGS];
    // Assume logs are populated here

    processBatchTransactionLogs(logs, MAX_TRANSACTION_LOGS);

    for (int i = 0; i < MAX_TRANSACTION_LOGS; ++i) {
        printf("Transaction ID: %d, Latest Status Code: %d\n", global_statuses[i].transaction_id, global_statuses[i].latest_status_code);
    }

    return 0;
}
