#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* allocate_memory(int N) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < N; i++) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (new_node == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        new_node->data.RX_UE_INFORMATION_TAG = rand() % 100;
        new_node->data.RNTI = rand() % 100;
        new_node->data.CRC_INDICATION_REL8_TAG = rand() % 100;
        new_node->data.CRCFLAG = rand() % 2;
        new_node->next = head;
        head = new_node;
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}

void cleanup_memory() {
    pthread_mutex_lock(&lock);
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    head = NULL;
    pthread_mutex_unlock(&lock);
}
