#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>

#define MAX_LOG_EVENTS 1024

typedef enum {
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR
} LogLevel;

typedef struct {
    int event_id;
    time_t timestamp;
    LogLevel level;
    char *message;
} LOG_EVENT_T;

typedef struct {
    LOG_EVENT_T **events;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} LogSystem;

void init_log_system(LogSystem *ls) {
    ls->events = (LOG_EVENT_T **)malloc(MAX_LOG_EVENTS * sizeof(LOG_EVENT_T *));
    if (!ls->events) {
        perror("Failed to allocate memory for log events");
        exit(EXIT_FAILURE);
    }
    ls->count = 0;
    ls->capacity = MAX_LOG_EVENTS;
    pthread_mutex_init(&ls->mutex, NULL);
}

void destroy_log_system(LogSystem *ls) {
    for (size_t i = 0; i < ls->count; ++i) {
        free(ls->events[i]->message);
        free(ls->events[i]);
    }
    free(ls->events);
    pthread_mutex_destroy(&ls->mutex);
}

int add_log_event(LogSystem *ls, LogLevel level, const char *format, ...) {
    pthread_mutex_lock(&ls->mutex);
    if (ls->count >= ls->capacity) {
        fprintf(stderr, "Log buffer is full\n");
        pthread_mutex_unlock(&ls->mutex);
        return -1;
    }

    size_t message_len = snprintf(NULL, 0, format, NULL) + 1;
    char *message = (char *)malloc(message_len);
    if (!message) {
        perror("Failed to allocate memory for log message");
        pthread_mutex_unlock(&ls->mutex);
        return -1;
    }

    va_list args;
    va_start(args, format);
    vsnprintf(message, message_len, format, args);
    va_end(args);

    LOG_EVENT_T *event = (LOG_EVENT_T *)malloc(sizeof(LOG_EVENT_T));
    if (!event) {
        perror("Failed to allocate memory for log event");
        free(message);
        pthread_mutex_unlock(&ls->mutex);
        return -1;
    }

    event->event_id = ls->count + 1;
    time(&event->timestamp);
    event->level = level;
    event->message = message;

    ls->events[ls->count++] = event;
    pthread_mutex_unlock(&ls->mutex);

    return 0;
}

void iterate_log_events(LogSystem *ls) {
    pthread_mutex_lock(&ls->mutex);
    for (size_t i = 0; i < ls->count; ++i) {
        printf("Event %d: [%s] %s\n", ls->events[i]->event_id, ctime(&ls->events[i]->timestamp), ls->events[i]->message);
    }
    pthread_mutex_unlock(&ls->mutex);
}
