class TokenManager {
public:
    void insertAfterToken(std::forward_list<std::string>& list, const std::string& targetToken, const std::string& insertToken) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = list.begin();
        while (it != list.end()) {
            try {
                json tokenJson = json::parse(*it);
                validateToken(tokenJson);
                if (tokenJson["access_token"] == targetToken) {
                    if (!hasInserted.find(targetToken)->second) {
                        it = list.insert_after(it, insertToken);
                        hasInserted[targetToken] = true;
                    } else {
                        ++it;
                    }
                } else {
                    ++it;
                }
            } catch (const json::parse_error&) {
                // Skip invalid JSON
                ++it;
            }
        }

        if (!hasInserted.find(targetToken)->second) {
            list.push_back(insertToken);
        }
    }

