class TokenManager {
public:
    struct Token {
        std::string access_token;
        int expires_in;
        std::string token_type;
        std::optional<std::string> refresh_token;
    };

    bool validateToken(const Token& token) {
        // Validate token fields and constraints
        return token.token_type == "Bearer" && token.expires_in > 0 &&
               !token.access_token.empty() && !token.token_type.empty();
    }

    void insertTokenAfter(std::forward_list<Token>& tokens, const Token& newToken, const std::string& targetToken) {
        auto it = tokens.before_begin();
        for (auto prevIt = tokens.begin(); prevIt != tokens.end(); ++prevIt, ++it) {
            if (*prevIt.access_token == targetToken) {
                tokens.insert_after(it, newToken);
                return;
