#include <nlohmann/json.hpp>
#include <openssl/md5.h>

class AccessTokenManager {
    std::forward_list<nlohmann::json> tokens;

public:
    bool validateToken(const nlohmann::json& token) {
        if (!token.contains("access_token") || !token.contains("expires_in") || !token.contains("token_type")) return false;
        if (token["token_type"] != "Bearer" || token["expires_in"].type() != nlohmann::json::value_t::number_unsigned) return false;
        return true;
    }

    void insertTokenAfter(const std::string& targetToken, const nlohmann::json& newToken) {
        if (!validateToken(newToken)) return;

        auto it = tokens.begin();
        while (it != tokens.end()) {
            if ((*it)["access_token"] == targetToken) {
                tokens.insert_after(it, newToken);
                return;
            }
            ++it;
        }

        tokens.push_front(newToken);
    }

    std::string md5Hash(const std::string& input) {
        unsigned char digest[MD5_DIGEST_LENGTH];
        MD5((unsigned char*)input.c_str(), input.length(), (unsigned char*)&digest);

        std::stringstream ss;
        for(int i = 0; i < MD5_DIGEST_LENGTH; ++i)
            ss << std::hex << std::setw(2) << std::setfill('0') << (int)digest[i];
        return ss.str();
    }
};

