// Global transaction status database
TransactionLog *transactionDatabase = NULL;
int dbSize = 0;
int dbCapacity = 1000; // Initial capacity

// Function to allocate memory for the database
void allocateMemory() {
    transactionDatabase = (TransactionLog *)malloc(dbCapacity * sizeof(TransactionLog));
    if (!transactionDatabase) {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }
}

// Function to free allocated memory
void freeMemory() {
    free(transactionDatabase);
    dbSize = 0;
    dbCapacity = 1000; // Reset capacity for future allocations
}

// Function to add a transaction log to the database
void addToDatabase(TransactionLog *log) {
    if (dbSize == dbCapacity) {
        dbCapacity *= 2;
        transactionDatabase = (TransactionLog *)realloc(transactionDatabase, dbCapacity * sizeof(TransactionLog));
        if (!transactionDatabase) {
            fprintf(stderr, "Failed to reallocate memory\n");
            exit(EXIT_FAILURE);
        }
    }
    memcpy(&transactionDatabase[dbSize++], log, sizeof(TransactionLog));
}

// Function to process a batch of transaction logs
void batchProcessTransactions(TransactionLog *logs, int count) {
    allocateMemory(); // Initialize database memory

    for (int i = 0; i < count; i++) {
        addToDatabase(&logs[i]); // Add each log to the database
    }

    // Simulate processing by printing logs
    for (int i = 0; i < dbSize; i++) {
