    for (int i = 0; i < count; ++i) {
        Transaction log = logs[i];

        // Validate transaction ID
        if (log.id <= 0 || log.id > 1000) {
            printf("Invalid transaction ID: %d\n", log.id);
            continue;
        }

        // Validate timestamp
        time_t now = time(NULL);
        if (difftime(now, log.timestamp) < 0) {
            printf("Future timestamp detected for transaction ID: %d\n", log.id);
            continue;
        }

        // Validate operation type and status code
        char* validOperations[] = {"DEBIT", "CREDIT"};
        int opValid = 0;
        for (int j = 0; j < sizeof(validOperations) / sizeof(validOperations[0]); ++j) {
            if (strcmp(log.operation, validOperations[j]) == 0) {
                opValid = 1;
                break;
            }
        }
        if (!opValid || log.status_code < 200 || log.status_code >= 500) {
            printf("Invalid operation or status code for transaction ID: %d\n", log.id);
            continue;
        }

        // Update global transaction database
        if (dbIndex < sizeof(globalDB) / sizeof(globalDB[0])) {
            globalDB[dbIndex++] = log;
        } else {
            printf("Global database is full, cannot store more transactions.\n");
        }
    }
}

