#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_LOG_SIZE 1024
#define DEFAULT_MAX_EVENTS 1000

typedef enum {
    LOG_LEVEL_DEBUG,
    LOG_LEVEL_INFO,
    LOG_LEVEL_WARNING,
    LOG_LEVEL_ERROR
} LOG_LEVEL_T;

typedef struct log_event {
    int id;
    long timestamp;
    LOG_LEVEL_T level;
    char message[MAX_LOG_SIZE];
    struct log_event *next;
    pthread_mutex_t lock;
} LOG_EVENT_T;

typedef struct log_system {
    LOG_EVENT_T **events;
    int max_events;
    int current_events;
    pthread_mutex_t events_lock;
} LOG_SYSTEM_T;

LOG_SYSTEM_T *create_log_system(int max_events) {
    LOG_SYSTEM_T *system = (LOG_SYSTEM_T *)malloc(sizeof(LOG_SYSTEM_T));
    system->max_events = max_events ? max_events : DEFAULT_MAX_EVENTS;
    system->events = (LOG_EVENT_T **)calloc(system->max_events, sizeof(LOG_EVENT_T *));
    system->current_events = 0;
    pthread_mutex_init(&system->events_lock, NULL);
    return system;
}

void destroy_log_system(LOG_SYSTEM_T *system) {
    for (int i = 0; i < system->current_events; i++) {
        LOG_EVENT_T *event = system->events[i];
        free(event->message);
        pthread_mutex_destroy(&event->lock);
        free(event);
    }
    free(system->events);
    pthread_mutex_destroy(&system->events_lock);
    free(system);
}

void add_log_event(LOG_SYSTEM_T *system, int id, LOG_LEVEL_T level, const char *message) {
    pthread_mutex_lock(&system->events_lock);
    if (system->current_events >= system->max_events) {
        fprintf(stderr, "Log system is full\n");
        pthread_mutex_unlock(&system->events_lock);
        return;
    }
    LOG_EVENT_T *event = (LOG_EVENT_T *)malloc(sizeof(LOG_EVENT_T));
    event->id = id;
    event->timestamp = time(NULL);
    event->level = level;
    strncpy(event->message, message, MAX_LOG_SIZE - 1);
    event->message[MAX_LOG_SIZE - 1] = '\0';
    pthread_mutex_init(&event->lock, NULL);
    system->events[system->current_events++] = event;
    pthread_mutex_unlock(&system->events_lock);
}

void iterate_log_events(LOG_SYSTEM_T *system) {
    pthread_mutex_lock(&system->events_lock);
    for (int i = 0; i < system->current_events; i++) {
        LOG_EVENT_T *event = system->events[i];
        pthread_mutex_lock(&event->lock);
        printf("Event %d: Level %s, Time %ld, Message '%s'\n", event->id,
               (event->level == LOG_LEVEL_DEBUG) ? "DEBUG" :
               (event->level == LOG_LEVEL_INFO) ? "INFO" :
               (event->level == LOG_LEVEL_WARNING) ? "WARNING" : "ERROR",
               event->timestamp, event->message);
        pthread_mutex_unlock(&event->lock);
    }
    pthread_mutex_unlock(&system->events_lock);
}

int main() {
    LOG_SYSTEM_T *log_system = create_log_system(10);
    add_log_event(log_system, 1, LOG_LEVEL_INFO, "System initialized");
    iterate_log_events(log_system);
    destroy_log_system(log_system);
    return 0;
}
```

