#define MAX_IP_LEN 16
#define MAX_DATA_LEN 4096
#define BLOOM_FILTER_SIZE 256

typedef struct {
    char SRC_IP[MAX_IP_LEN];
    char DST_IP[MAX_IP_LEN];
    int PORT;
    int DATA_LENGTH;
} PACKET_INFO_T;

typedef struct {
    PACKET_INFO_T data[BLOOM_FILTER_SIZE];
    int size;
} BloomFilter;

typedef struct QueueNode {
    PACKET_INFO_T packet_info;
    struct QueueNode* next;
} QueueNode;

typedef struct {
    QueueNode* front;
    QueueNode* rear;
    pthread_mutex_t mutex;
    BloomFilter bloom_filter;
    int current_size;
} PacketQueue;

void initialize_bloom_filter(BloomFilter* bf) {
    // Initialize the bloom filter
}

int bloom_filter_contains(BloomFilter* bf, char* ip) {
    // Check if an IP is in the bloom filter
    return 0; // Replace with actual implementation
}

int enqueue(PacketQueue* queue, PACKET_INFO_T packet_info) {
    pthread_mutex_lock(&queue->mutex);
    QueueNode* new_node = (QueueNode*)malloc(sizeof(QueueNode));
    if (!new_node) {
        pthread_mutex_unlock(&queue->mutex);
        return -1; // Memory allocation failure
    }
    memcpy(&new_node->packet_info, &packet_info, sizeof(PACKET_INFO_T));
    new_node->next = NULL;
    if (queue->rear == NULL) {
        queue->front = queue->rear = new_node;
    } else {
        queue->rear->next = new_node;
        queue->rear = new_node;
    }
    queue->current_size++;
    pthread_mutex_unlock(&queue->mutex);
    return 0;
}

int dequeue(PacketQueue* queue, PACKET_INFO_T* packet_info) {
    pthread_mutex_lock(&queue->mutex);
    if (queue->front == NULL) {
        pthread_mutex_unlock(&queue->mutex);
        return -1; // Queue is empty
    }
    QueueNode* temp = queue->front;
    memcpy(packet_info, &temp->packet_info, sizeof(PACKET_INFO_T));
    queue->front = queue->front->next;
    if (queue->front == NULL) {
        queue->rear = NULL;
    }
    free(temp);
    queue->current_size--;
    pthread_mutex_unlock(&queue->mutex);
    return 0;
}

void* packet_processor(void* arg) {
    PacketQueue* queue = (PacketQueue*)arg;
    while (1) {
        PACKET_INFO_T packet_info;
        if (dequeue(queue, &packet_info) == 0) {
            // Process the packet
            printf("Processing packet with SRC_IP: %s, DST_IP: %s\n", packet_info.SRC_IP, packet_info.DST_IP);
        }
    }
}

int main() {
    PacketQueue queue;
    initialize_bloom_filter(&queue.bloom_filter);
    pthread_mutex_init(&queue.mutex, NULL);
    queue.front = queue.rear = NULL;
    queue.current_size = 0;

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, packet_processor, &queue);
    }

    // Enqueue packets
    PACKET_INFO_T new_packet = {"192.168.1.1", "10.0.0.1", 80, 1024};
    enqueue(&queue, new_packet);

    // Wait for threads to finish (for demonstration purposes)
    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
