LOG_EVENT_T log_buffer[MAX_LOG_EVENTS];
int event_count = 0;
pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;

void enhanced_manage_log_system(LOG_EVENT_T *new_event) {
    pthread_mutex_lock(&log_lock);
    if (event_count < MAX_LOG_EVENTS) {
        new_event->id = event_count++;
        strcpy(log_buffer[new_event->id].level, new_event->level);
        strcpy(log_buffer[new_event->id].message, new_event->message);
        printf("Log added successfully with ID: %d\n", new_event->id);
    } else {
        printf("Error: Log buffer is full. Cannot add more events.\n");
    }
    pthread_mutex_unlock(&log_lock);
}

void iterate_log_system() {
    pthread_mutex_lock(&log_lock);
    for (int i = 0; i < event_count; i++) {
        printf("Event ID: %d, Level: %s, Message: %s\n", log_buffer[i].id, log_buffer[i].level, log_buffer[i].message);
    }
    pthread_mutex_unlock(&log_lock);
}

void clear_log_system() {
    pthread_mutex_lock(&log_lock);
    event_count = 0;
    memset(log_buffer, 0, sizeof(log_buffer));
    printf("Log system cleared.\n");
    pthread_mutex_unlock(&log_lock);
}
