        switch (opt) {
            case 'h':
                display_help();
                return 0;
            case 'v':
                display_version();
                return 0;
            case 'c':
                case_sensitive = 1;
                break;
            case 's':
                output_file = optarg;
                break;
            default:
                fprintf(stderr, "Invalid option: %c\n", optopt);
                return 1;
        }
    }

    if (optind == argc) {
        display_help();
        return 1;
    }

    char** input_files = argv + optind;
    int num_files = argc - optind;

    if (output_file != NULL) {
        freopen(output_file, "w", stdout);
    }

    generate_summary_report(input_files, num_files);

    if (output_file != NULL) {
        fclose(stdout);
    }

    return 0;
}
