        List<LocationData> results = new ArrayList<>();
        for (Future<LocationData> future : futures) {
            LocationData data = future.get();
            if (data != null) {
                results.add(data);
            }
        }
        executor.shutdown();
        return results;
    }

    private static LocationData fetchDataFromAPI(String apiKey, String location, int timeout) throws Exception {
