#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <openssl/md5.h>

#define MAX_PATH_LEN 2048

void displayManpage() {
    printf("Usage: program_name [options] directory_path\n");
    printf("Options:\n");
    printf("  --manpage     Display detailed usage information\n");
    printf("  -cs           Calculate MD5 hash of all files within the directory, excluding symbolic links\n");
    printf("  -o output_file Save resulting hashes to the designated output file instead of printing them directly\n");
}

void calculateMD5(const char *filePath) {
    FILE *file = fopen(filePath, "rb");
    if (!file) {
        perror("Error opening file");
        return;
    }

    unsigned char hash[MD5_DIGEST_LENGTH];
    MD5_CTX md5;
    MD5_Init(&md5);

    char buffer[4096];
    size_t bytesRead;
    while ((bytesRead = fread(buffer, 1, sizeof(buffer), file)) > 0) {
        MD5_Update(&md5, buffer, bytesRead);
    }

    fclose(file);

    MD5_Final(hash, &md5);

    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        printf("%02x", hash[i]);
    }
    printf("\n");
}

void processDirectory(const char *dirPath, const char *outputFile, int calculateHashes) {
    DIR *dir;
    struct dirent *entry;

    if (!(dir = opendir(dirPath))) {
        perror("Error opening directory");
        return;
    }

    FILE *output = NULL;
    if (outputFile) {
        output = fopen(outputFile, "w");
        if (!output) {
            perror("Error opening output file");
            closedir(dir);
            return;
        }
    }

    while ((entry = readdir(dir)) != NULL) {
        char fullPath[MAX_PATH_LEN];
        snprintf(fullPath, sizeof(fullPath), "%s/%s", dirPath, entry->d_name);

        if (entry->d_type == DT_DIR && strcmp(entry->d_name, ".") != 0 && strcmp(entry->d_name, "..") != 0) {
            processDirectory(fullPath, outputFile, calculateHashes);
        } else if (entry->d_type == DT_LNK) {
            continue; // Skip symbolic links
        } else if (calculateHashes) {
            printf("File: %s\n", fullPath);
            calculateMD5(fullPath);

            if (output) {
                fprintf(output, "%s\n", fullPath);
            }
        }
    }

    closedir(dir);
    if (output) {
        fclose(output);
    }
}

int main(int argc, char *argv[]) {
    const char *dirPath = NULL;
    int calculateHashes = 0;
    const char *outputFile = NULL;

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "--manpage") == 0) {
            displayManpage();
            return 0;
        } else if (strcmp(argv[i], "-cs") == 0) {
            calculateHashes = 1;
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            outputFile = argv[++i];
        } else if (!dirPath) {
            dirPath = argv[i];
        }
    }

    if (!dirPath) {
        displayManpage();
        return 0;
    }

    processDirectory(dirPath, outputFile, calculateHashes);

    return 0;
}
