#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_FILES 100

typedef enum {
    ACTION_NONE,
    ACTION_HELP,
    ACTION_COUNT_LINES,
    ACTION_WRITE_LINE_NUMBERS
} Action;

void display_usage() {
    printf("Usage: program_name [options] input_files...\n");
    printf("Options:\n");
    printf("  --help          Display this help message\n");
    printf("  -c              Count lines in the input files\n");
    printf("  -o <output_file> Specify an output file to write line numbers to\n");
}

void parse_command_line(int argc, char *argv[], Action *action, char **output_file, int *file_count, char **input_files) {
    *action = ACTION_NONE;
    *output_file = NULL;
    *file_count = 0;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--help") == 0) {
            *action = ACTION_HELP;
            break;
        } else if (strcmp(argv[i], "-c") == 0) {
            *action = ACTION_COUNT_LINES;
        } else if (strncmp(argv[i], "-o", 2) == 0) {
            *action = ACTION_WRITE_LINE_NUMBERS;
            *output_file = argv[i + 1];
            i++;
        } else {
            input_files[*file_count] = argv[i];
            (*file_count)++;
        }
    }
}

int count_lines_in_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1;

    int line_count = 0;
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        line_count++;
    }
    fclose(file);
    return line_count;
}

void write_line_numbers_to_file(const char *filename, const char **input_files, int file_count) {
    FILE *file = fopen(filename, "w");
    if (!file) {
        printf("Error opening output file\n");
        return;
    }

    for (int i = 0; i < file_count; i++) {
        int line_count = count_lines_in_file(input_files[i]);
        fprintf(file, "File: %s, Lines: %d\n", input_files[i], line_count);
    }
    fclose(file);
}

int main(int argc, char *argv[]) {
    Action action;
    char *output_file;
    int file_count;
    char *input_files[MAX_FILES];

    parse_command_line(argc, argv, &action, &output_file, &file_count, input_files);

    if (action == ACTION_HELP) {
        display_usage();
        return 0;
    }

    if (file_count == 0) {
        printf("No input files specified\n");
        display_usage();
        return 1;
    }

    switch (action) {
        case ACTION_COUNT_LINES:
            for (int i = 0; i < file_count; i++) {
                int line_count = count_lines_in_file(input_files[i]);
                if (line_count == -1) {
                    printf("Error opening file %s\n", input_files[i]);
                } else {
                    printf("File: %s, Lines: %d\n", input_files[i], line_count);
                }
            }
            break;
        case ACTION_WRITE_LINE_NUMBERS:
            write_line_numbers_to_file(output_file, input_files, file_count);
            break;
        default:
            printf("Unknown action\n");
            display_usage();
            return 1;
    }

    return 0;
}
```

This code provides a basic structure for a C program that dynamically parses command line arguments to determine the action to perform. It supports displaying usage information, counting lines in input files, and writing line numbers to an output file. The program handles multiple input files and provides aggregated results. Error handling is included for unexpected conditions, and the program aims to manage large datasets efficiently.']

