#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef enum {
    FILE_TYPE_DIRECTORY,
    FILE_TYPE_FILE
} FILE_TYPE_T;

typedef struct FILE_SYSTEM_NODE_T {
    char name[256];
    FILE_TYPE_T type;
    size_t size;
    time_t creation_time;
    time_t modification_time;
    int permissions;
    void* data; // Pointer to file data or next node in the list
    pthread_mutex_t mutex; // Mutex for thread-safe access
} FILE_SYSTEM_NODE_T;

typedef struct {
    FILE_SYSTEM_NODE_T** nodes;
    size_t capacity;
    size_t count;
    size_t max_size;
    pthread_mutex_t buffer_mutex; // Mutex for buffer management
} DYNAMIC_BUFFER_T;

void initialize_buffer(DYNAMIC_BUFFER_T* buffer, size_t initial_capacity) {
    buffer->nodes = (FILE_SYSTEM_NODE_T**)malloc(initial_capacity * sizeof(FILE_SYSTEM_NODE_T*));
    buffer->capacity = initial_capacity;
    buffer->count = 0;
    buffer->max_size = initial_capacity;
    pthread_mutex_init(&buffer->mutex, NULL);
}

void free_buffer(DYNAMIC_BUFFER_T* buffer) {
    for (size_t i = 0; i < buffer->count; ++i) {
        pthread_mutex_destroy(&buffer->nodes[i]->mutex);
        free(buffer->nodes[i]);
    }
    free(buffer->nodes);
    pthread_mutex_destroy(&buffer->buffer_mutex);
}

int add_node(DYNAMIC_BUFFER_T* buffer, FILE_SYSTEM_NODE_T* node) {
    pthread_mutex_lock(&buffer->buffer_mutex);
    if (buffer->count >= buffer->capacity) {
        size_t new_capacity = buffer->capacity * 2;
        FILE_SYSTEM_NODE_T** new_nodes = (FILE_SYSTEM_NODE_T**)realloc(buffer->nodes, new_capacity * sizeof(FILE_SYSTEM_NODE_T*));
        if (!new_nodes) {
            pthread_mutex_unlock(&buffer->buffer_mutex);
            return -1; // Memory allocation failed
        }
        buffer->nodes = new_nodes;
        buffer->capacity = new_capacity;
    }
    pthread_mutex_lock(&node->mutex);
    buffer->nodes[buffer->count++] = node;
    pthread_mutex_unlock(&node->mutex);
    pthread_mutex_unlock(&buffer->buffer_mutex);
    return 0;
}

int delete_node(DYNAMIC_BUFFER_T* buffer, FILE_SYSTEM_NODE_T* node) {
    pthread_mutex_lock(&buffer->buffer_mutex);
    for (size_t i = 0; i < buffer->count; ++i) {
        if (buffer->nodes[i] == node) {
            pthread_mutex_lock(&node->mutex);
            buffer->nodes[i] = buffer->nodes[--buffer->count];
            pthread_mutex_unlock(&node->mutex);
            break;
        }
    }
    pthread_mutex_unlock(&buffer->buffer_mutex);
    return 0;
}

void list_nodes(DYNAMIC_BUFFER_T* buffer, void (*callback)(FILE_SYSTEM_NODE_T*)) {
    pthread_mutex_lock(&buffer->buffer_mutex);
    for (size_t i = 0; i < buffer->count; ++i) {
        pthread_mutex_lock(&buffer->nodes[i]->mutex);
        callback(buffer->nodes[i]);
        pthread_mutex_unlock(&buffer->nodes[i]->mutex);
    }
    pthread_mutex_unlock(&buffer->buffer_mutex);
}

