#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ENTRIES 10000

typedef struct {
    int SUBFRAME_ID;
    int TX_POWER_LEVEL;
    int MCS;
    float CODING_RATE;
} DL_FRAME_INFO_T;

typedef struct Node {
    DL_FRAME_INFO_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    int size;
    pthread_mutex_t mutex;
} DynamicList;

DynamicList* createList() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void freeList(DynamicList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int addEntry(DynamicList* list, DL_FRAME_INFO_T newEntry) {
    pthread_mutex_lock(&list->mutex);
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Memory allocation failed
    }
    newNode->data = newEntry;
    newNode->next = list->head;
    list->head = newNode;
    list->size++;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int updateEntry(DynamicList* list, int SUBFRAME_ID, DL_FRAME_INFO_T updatedEntry) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.SUBFRAME_ID == SUBFRAME_ID) {
            current->data = updatedEntry;
            pthread_mutex_unlock(&list->mutex);
            return 0; // Entry updated
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
    return -1; // Entry not found
}

int removeEntry(DynamicList* list, int SUBFRAME_ID) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    Node* prev = NULL;
    while (current != NULL) {
        if (current->data.SUBFRAME_ID == SUBFRAME_ID) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            list->size--;
            pthread_mutex_unlock(&list->mutex);
            return 0; // Entry removed
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
    return -1; // Entry not found
}

int countEntries(DynamicList* list) {
    return list->size;
}

double averageTXPowerLevel(DynamicList* list) {
    if (list->size == 0) {
        return 0.0;
    }
    pthread_mutex_lock(&list->mutex);
    int total = 0;
    Node* current = list->head;
    while (current != NULL) {
        total += current->data.TX_POWER_LEVEL;
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
    return (double)total / list->size;
}

int queryByMCSAndCodingRate(DynamicList* list, int minMCS, float minCodingRate, DL_FRAME_INFO_T** result, int* count) {
    pthread_mutex_lock(&list->mutex);
    *count = 0;
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.MCS >= minMCS && current->data.CODING_RATE >= minCodingRate) {
            (*result)[(*count)] = current->data;
            (*count)++;
            if (*count == MAX_ENTRIES) {
                break; // Limit to max entries
            }
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int main() {
    DynamicList* list = createList();
    DL_FRAME_INFO_T newEntry = {1, 25, 3, 0.5};
    addEntry(list, newEntry);

    int count = countEntries(list);
    printf("Number of entries: %d\n", count);

    double avgTXPower = averageTXPowerLevel(list);
    printf("Average TX Power Level: %.2f\n", avgTXPower);

    DL_FRAME_INFO_T* queryResult = (DL_FRAME_INFO_T*)malloc(MAX_ENTRIES * sizeof(DL_FRAME_INFO_T));
    int queryCount;
    queryByMCSAndCodingRate(list, 3, 0.5, &queryResult, &queryCount);
    printf("Query count: %d\n", queryCount);

    freeList(list);
    return 0;
}
