    memset(&file_system_manager, 0, sizeof(file_system_manager));
    pthread_mutex_init(&file_system_manager.lock, NULL);
}

int add_node(const char *name, int type, size_t size, unsigned int permissions) {
    pthread_mutex_lock(&file_system_manager.lock);
    if (file_system_manager.count >= MAX_NODES) {
        pthread_mutex_unlock(&file_system_manager.lock);
        return -1; // Error: Maximum number of nodes reached
    }
    FILE_SYSTEM_NODE_T *new_node = (FILE_SYSTEM_NODE_T *)malloc(sizeof(FILE_SYSTEM_NODE_T));
    if (!new_node) {
        pthread_mutex_unlock(&file_system_manager.lock);
        return -2; // Error: Memory allocation failed
    }
    snprintf(new_node->name, sizeof(new_node->name), "%s", name);
    new_node->type = type;
    new_node->size = size;
    new_node->creation_time = time(NULL);
    new_node->modification_time = time(NULL);
    new_node->permissions = permissions;
    file_system_manager.nodes[file_system_manager.count++] = new_node;
    pthread_mutex_unlock(&file_system_manager.lock);
    return 0; // Success
