#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <openssl/md5.h>

#define MAX_PATH_LENGTH 256
#define MAX_MD5_LENGTH 33
#define BUFFER_SIZE 1024 * 1024 // 1MB buffer size for large files

void calculate_md5(const char* file_path, char* md5_hash) {
    FILE* file = fopen(file_path, "rb");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    MD5_CTX md5_context;
    MD5_Init(&md5_context);

    unsigned char buffer[BUFFER_SIZE];
    size_t bytes_read;

    while ((bytes_read = fread(buffer, 1, BUFFER_SIZE, file)) > 0) {
        MD5_Update(&md5_context, buffer, bytes_read);
    }

    fclose(file);

    MD5_Final((unsigned char*)md5_hash, &md5_context);

    for (int i = 0; i < 16; ++i) {
        sprintf(md5_hash + (i * 2), "%02x", md5_hash[i]);
    }
}

void process_directory(const char* directory_path) {
    DIR* dir = opendir(directory_path);
    if (!dir) {
        perror("Failed to open directory");
        return;
    }

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue; // Skip current and parent directories
        }

        char file_path[MAX_PATH_LENGTH];
        snprintf(file_path, MAX_PATH_LENGTH, "%s/%s", directory_path, entry->d_name);

        struct stat file_stat;
        if (stat(file_path, &file_stat) != 0) {
            perror("Failed to get file stats");
            continue;
        }

        if (S_ISLNK(file_stat.st_mode)) {
            // Skip symbolic links
            continue;
        }

        char md5_hash[MAX_MD5_LENGTH];
        calculate_md5(file_path, md5_hash);

        printf("File: %s, MD5: %s\n", file_path, md5_hash);
    }

    closedir(dir);
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <directory_path>\n", argv[0]);
        return 1;
    }

    process_directory(argv[1]);

    return 0;
}
