#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define RX_UE_INFORMATION_TAG 0x1234
#define RNTI 0xABCD

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int tag;
    int rnti;
    unsigned char crcFlag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode* next;
} ListNode;

typedef struct List {
    pthread_mutex_t mutex;
    ListNode* head;
    size_t size;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_list(List* list) {
    if (!list) return;
    pthread_mutex_lock(&list->mutex);
    ListNode* current = list->head;
    while (current) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

void add_to_list(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (!list) return;
    pthread_mutex_lock(&list->mutex);
    ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
    if (new_node) {
        new_node->data = data;
        new_node->next = list->head;
        list->head = new_node;
        list->size++;
    }
    pthread_mutex_unlock(&list->mutex);
}

int serialize_list(List* list, const char* filename) {
    if (!list || !filename) return -1;
    pthread_mutex_lock(&list->mutex);
    FILE* file = fopen(filename, "wb");
    if (!file) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    size_t written = fwrite(&list->size, sizeof(size_t), 1, file);
    if (written != 1) {
        fclose(file);
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    ListNode* current = list->head;
    while (current) {
        written = fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        if (written != 1) {
            fclose(file);
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }
        current = current->next;
    }
    fclose(file);
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int deserialize_list(List* list, const char* filename) {
    if (!list || !filename) return -1;
    pthread_mutex_lock(&list->mutex);
    FILE* file = fopen(filename, "rb");
    if (!file) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    size_t size;
    size_t read = fread(&size, sizeof(size_t), 1, file);
    if (read != 1) {
        fclose(file);
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    for (size_t i = 0; i < size; i++) {
        NFAPI_CRC_INDICATION_PDU_T data;
