    }

    void update() {
        std::unique_lock<std::mutex> lock(mutex);
        processedCount++;
        if (processedCount >= maxProgress) {
            std::cout << "Processing progress: " << static_cast<int>((processedCount / maxProgress) * 100) << "%\n";
            processedCount = 0;
        }
    }

private:
