    tracker.start(inputFiles.size());

    std::vector<std::thread> threads;
    for (const auto& file : inputFiles) {
        threads.emplace_back(processFile, file, std::ref(tracker));
    }

    for (auto& thread : threads) {
        thread.join();
    }

    return 0;
}
