typedef struct HTTP_REQUEST_LOG_PDU_T {
    int REQUEST_ID;
    char CLIENT_IP_ADDRESS[16];
    char SERVER_IP_ADDRESS[16];
    char REQUEST_METHOD[8];
    char RESOURCE_PATH[256];
    int STATUS_CODE;
    char USER_AGENT[256];
    float REQUEST_LATENCY;
} HTTP_REQUEST_LOG_PDU_T;

typedef struct {
    HTTP_REQUEST_LOG_PDU_T *list;
    size_t count;
    size_t max_count;
    pthread_mutex_t mutex;
} DynamicList;

DynamicList* create_list(size_t initial_size, size_t max_size) {
    DynamicList *list = (DynamicList*)malloc(sizeof(DynamicList));
    list->list = (HTTP_REQUEST_LOG_PDU_T*)calloc(initial_size, sizeof(HTTP_REQUEST_LOG_PDU_T));
    list->count = 0;
    list->max_count = max_size;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_list(DynamicList *list) {
    pthread_mutex_lock(&list->mutex);
    free(list->list);
    pthread_mutex_unlock(&list->mutex);
    free(list);
}

int add_request_to_list(DynamicList *list, HTTP_REQUEST_LOG_PDU_T *request) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= list->max_count) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // List is full
    }
    memcpy(&list->list[list->count], request, sizeof(HTTP_REQUEST_LOG_PDU_T));
    list->count++;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

