    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(*array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_size);
    if (new_array == NULL) return;
    memset(&new_array[*size], 0, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (new_size - *size));
    *array = new_array;
    *size = new_size;
}

