import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

public class MD5Hasher {
    private static final Map<String, String> cache = new HashMap<>();

    public static Map<String, String> computeMD5Hashes(List<String> strings) {
        Map<String, String> result = new HashMap<>();

        for (String str : strings) {
            if (!cache.containsKey(str)) {
                String md5Hash = getMD5Hash(str);
                cache.put(str, md5Hash);
                System.out.println("Computed and cached hash for: " + str);
            }
            result.put(str, cache.get(str));
        }

        return result;
    }

    private static String getMD5Hash(String input) {
        try {
            MessageDigest digest = MessageDigest.getInstance("MD5");
            byte[] hashBytes = digest.digest(input.getBytes());
            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("MD5 algorithm not found", e);
        }
    }

    public static void main(String[] args) {
        List<String> inputStrings = List.of("example1", "example2", "example3");
        Map<String, String> hashes = computeMD5Hashes(inputStrings);
        System.out.println(hashes);
    }
}
