<?php

class UserManager {
    private $db;
    private $cache;
    private $logger;

    public function __construct($db, $cache, $logger) {
        $this->db = $db;
        $this->cache = $cache;
        $this->logger = $logger;
    }

    public function manageUser($_REQUEST) {
        if (!isset($_REQUEST['api_key']) || $_REQUEST['api_key'] !== 'your_api_key') {
            return json_encode(['error' => 'Invalid API key']);
        }

        if (isset($_REQUEST['rate_limit_exceeded'])) {
            return json_encode(['error' => 'Rate limit exceeded. Please try again later.']);
        }

        $action = $_REQUEST['sub_action'];
        $id = isset($_REQUEST['id']) ? intval($_REQUEST['id']) : null;
        $name = $_REQUEST['name'] ?? null;
        $email = $_REQUEST['email'] ?? null;
        $password = $_REQUEST['password'] ?? null;
        $file = $_FILES['file'] ?? null;

        switch ($action) {
            case 'create':
                return $this->createUser($id, $name, $email, $password);
            case 'update':
                return $this->updateUser($id, $name, $email, $password);
            case 'delete':
                return $this->deleteUser($id);
            case 'retrieve':
                return $this->retrieveUser($id);
            case 'bulk_delete':
                return $this->bulkDeleteUsers($file);
            default:
                return json_encode(['error' => 'Invalid sub_action']);
        }
    }

    private function createUser($id, $name, $email, $password) {
        // Validate and sanitize inputs
        if (!$this->isValidEmail($email)) {
            return json_encode(['error' => 'Invalid email format']);
        }
        if ($this->isEmailExists($email)) {
            return json_encode(['error' => 'Email already exists']);
        }

        // Create user in database
        $user = [
            'name' => $name,
            'email' => $email,
            'password' => password_hash($password, PASSWORD_BCRYPT)
        ];
        $this->db->insert('users', $user);

        // Cache the new user
        $this->cache->set('user:' . $id, $user);

        return json_encode(['message' => 'User created successfully']);
    }

    private function updateUser($id, $name, $email, $password) {
        // Validate and sanitize inputs
        if (!isset($id)) {
            return json_encode(['error' => 'User ID is required']);
        }
        if ($this->isEmailExists($email, $id)) {
            return json_encode(['error' => 'Email already exists for another user']);
        }

        // Update user in database
        $user = [
            'name' => $name,
            'email' => $email
        ];
        if (!empty($password)) {
            $user['password'] = password_hash($password, PASSWORD_BCRYPT);
        }
        $this->db->update('users', $id, $user);

        // Cache the updated user
        $this->cache->set('user:' . $id, $user);

        return json_encode(['message' => 'User updated successfully']);
    }

    private function deleteUser($id) {
        // Validate and sanitize inputs
        if (!isset($id)) {
            return json_encode(['error' => 'User ID is required']);
        }

        // Retrieve user details from cache or database
        $user = $this->cache->get('user:' . $id);
        if (!$user) {
            $user = $this->db->select('users', ['id' => $id]);
            if (empty($user)) {
                return json_encode(['error' => 'User not found']);
            }
            $this->cache->set('user:' . $id, $user);
        }

        // Send confirmation email
        $confirmationToken = bin2hex(random_bytes(32));
        $this->sendConfirmationEmail($user['email'], $confirmationToken);

        return json_encode(['message' => 'Confirmation email sent. Please check your inbox']);
    }

    private function retrieveUser($id) {
        // Validate and sanitize inputs
        if (!isset($id)) {
            return json_encode(['error' => 'User ID is required']);
        }

        // Retrieve user details from cache or database
        $user = $this->cache->get('user:' . $id);
        if (!$user) {
            $user = $this->db->select('users', ['id' => $id]);
            if (empty($user)) {
                return json_encode(['error' => 'User not found']);
            }
            $this->cache->set('user:' . $id, $user);
        }

        // Mask sensitive information
        $user['password'] = '[Masked]';
        $user['email'] = '[Masked]';

        return json_encode($user);
    }

    private function bulkDeleteUsers($file) {
        // Validate file format and content
        if (!isset($file)) {
            return json_encode(['error' => 'File is required']);
        }
        if ($file['type'] !== 'text/csv') {
            return json_encode(['error' => 'Invalid file type. Please upload a CSV file']);
        }

        // Read and process the CSV file
        $rows = array_map('str_getcsv', file($file['tmp_name']));
        foreach ($rows as $row) {
            if (count($row) !== 1) {
                continue;
            }
            $userId = intval($row[0]);
            if ($this->db->delete('users', ['id' => $userId])) {
                $this->cache->del('user:' . $userId);
            } else {
                return json_encode(['error' => 'Failed to delete user with ID: ' . $userId]);
            }
        }

        return json_encode(['message' => 'Users deleted successfully']);
    }

    private function isValidEmail($email) {
        // Basic email validation
        return filter_var($email, FILTER_VALIDATE_EMAIL);
    }

    private function isEmailExists($email, $id = null) {
        // Check if email exists in database (excluding current user if provided)
        $query = "SELECT COUNT(*) AS count FROM users WHERE email = ? AND id != ?";
        return $this->db->count($query, [$email, $id]);
    }

    private function sendConfirmationEmail($email, $confirmationToken) {
        // Simulate sending confirmation email
        echo "Sending confirmation email to: $email with token: $confirmationToken";
    }
}

