#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef enum {
    PDU_TYPE_A,
    PDU_TYPE_B,
    PDU_TYPE_C,
    NUM_PDU_TYPES
} PDU_TYPE;

typedef enum {
    STATUS_CODE_OK,
    STATUS_CODE_ERROR,
    STATUS_CODE_PENDING,
    NUM_STATUS_CODES
} STATUS_CODE;

typedef struct {
    PDU_TYPE type;
    int sequence_number;
    STATUS_CODE status_code;
} MAC_PDU_T;

void initialize_mac_pdu_array(MAC_PDU_T** array, size_t size) {
    *array = malloc(size * sizeof(MAC_PDU_T));
    if (*array == NULL) {
        perror("Memory allocation failed");
        return;
    }

    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < size; ++i) {
        (*array)[i].type = (PDU_TYPE)(rand() % NUM_PDU_TYPES);
        (*array)[i].sequence_number = rand();
        (*array)[i].status_code = (STATUS_CODE)(rand() % NUM_STATUS_CODES);

        // Validate the structure integrity
        if ((*array)[i].type == PDU_TYPE_INVALID || (*array)[i].sequence_number < 0 || (*array)[i].status_code == STATUS_CODE_INVALID) {
            fprintf(stderr, "Invalid MAC_PDU_T structure at index %zu\n", i);
            free(*array);
            *array = NULL;
            return;
        }
    }

    // Log the initialization process
    printf("Successfully allocated and initialized %zu MAC_PDU_T structures\n", size);
}

void cleanup_mac_pdu_array(MAC_PDU_T** array) {
    if (*array != NULL) {
        free(*array);
        *array = NULL;
    }
}

int validate_mac_pdu(const MAC_PDU_T* pdu, STATUS_CODE status_code) {
    // Perform the validation check
    if (pdu->status_code == status_code) {
        return 0; // Validation successful
    } else {
        fprintf(stderr, "Validation failed: Expected %d, but got %d\n", status_code, pdu->status_code);
        return -1; // Validation failed
    }
}
