typedef struct {
    int UE_INSTANCE_ID;
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generate_NFAPI_CRC_INDICATION(int num_ues) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_ues * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        perror("Memory allocation failed");
        return NULL;
    }
    for (int i = 0; i < num_ues; i++) {
        pdu_list[i].UE_INSTANCE_ID = i + 1;
        pdu_list[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu_list[i].RNTI = rand() % 4096;
        pdu_list[i].CRCFLAG = rand() % 2;
    }
    return pdu_list;
}

void* service_thread(void* arg) {
    int num_ues = *(int*)arg;
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = generate_NFAPI_CRC_INDICATION(num_ues);
    if (!pdu_list) {
        pthread_exit(NULL);
    }

    srand(time(NULL));
    for (int i = 0; i < 10; i++) { // Repeatedly start and stop the service
        int delay = rand() % 5 + 1; // Random delay between 1 and 5 seconds
        sleep(delay);

        // Populate the list with valid data here

        delay = rand() % 5 + 1;
        sleep(delay);
    }

    free(pdu_list);
    pthread_exit(NULL);
}

int main() {
    int num_threads = 3; // Number of UE instances and threads
    pthread_t threads[num_threads];
    int thread_args[num_threads];

    for (int i = 0; i < num_threads; i++) {
        thread_args[i] = i + 1;
        if (pthread_create(&threads[i], NULL, service_thread, &thread_args[i]) != 0) {
            perror("Thread creation failed");
            return 1;
        }
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
        printf("Service stopped for UE %d\n", thread_args[i]);
    }

    return 0;
}
```

