def compute_md5(file_path):
    # Compute MD5 hash for a given file path
    with open(file_path, 'rb') as f:
        md5 = hashlib.md5()
        while chunk := f.read(8192):
            md5.update(chunk)
    return md5.hexdigest()

def process_directory(directory_path):
