                except Exception as e:
                    # Handle errors for inaccessible files
                    pass
    return file_hashes

def retry_upload(func, *args, max_retries=3):
    retries = 0
    while retries < max_retries:
        try:
            func(*args)
            return True
        except Exception as e:
            time.sleep(2 ** retries)  # Exponential backoff strategy
            retries += 1
    return False
