#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <time.h>

#define MAX_UE_INSTANCES 1000

typedef struct {
    // Define the structure members as per your requirements
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
} UE_Info;

typedef struct {
    CRC_INDICATION_REL8_TAG CRCFLAG;
    UE_Info* ue_info;
} NetworkServiceData;

void* network_service_thread(void* arg) {
    NetworkServiceData* data = (NetworkServiceData*)arg;
    // Simulate service processing
    printf("Processing UE Instance %u\n", data->ue_info->RX_UE_INFORMATION_TAG);
    return NULL;
}

NFAPI_CRC_INDICATION_PDU_T* generate_network_service(int num_ues, int batch_size) {
    NFAPI_CRC_INDICATION_PDU_T* services = (NFAPI_CRC_INDICATION_PDU_T*)calloc(num_ues, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!services) {
        perror("Failed to allocate memory");
        return NULL;
    }

    pthread_t threads[MAX_UE_INSTANCES];
    int num_threads = (num_ues + batch_size - 1) / batch_size;

    for (int i = 0; i < num_threads; ++i) {
        NetworkServiceData* thread_data = (NetworkServiceData*)malloc(sizeof(NetworkServiceData));
        if (!thread_data) {
            perror("Failed to allocate memory");
            return NULL;
        }

        int start_index = i * batch_size;
        int end_index = (i + 1) * batch_size > num_ues ? num_ues : (i + 1) * batch_size;

        for (int j = start_index; j < end_index; ++j) {
            thread_data->ue_info = &services[j].ue_info;
            services[j].ue_info.RX_UE_INFORMATION_TAG = rand() % MAX_UE_INSTANCES;
            services[j].ue_info.RNTI = rand() % 65536;
        }

        if (pthread_create(&threads[i], NULL, network_service_thread, thread_data) != 0) {
            perror("Failed to create thread");
            free(thread_data);
            return NULL;
        }
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    return services;
}

int main() {
    srand(time(NULL));
    int num_ues = rand() % MAX_UE_INSTANCES + 1;
    int batch_size = 10;

    NFAPI_CRC_INDICATION_PDU_T* services = generate_network_service(num_ues, batch_size);
    if (services) {
        printf("Network service generated successfully for %d UEs\n", num_ues);
        free(services);
    } else {
        printf("Failed to generate network service\n");
    }

    return 0;
}
