#define MAX_DATA_CONTENT_SIZE 4096
#define NUM_UE_INSTANCES 100

typedef struct {
    int record_id;
    long timestamp;
    char data_content[MAX_DATA_CONTENT_SIZE];
} DATA_RECORD;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRCFLAG crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
DATA_RECORD *data_store = NULL;
int data_store_size = 0;

void manage_dynamic_data_store(int num_ues, const char* file_path) {
    // Initialize data store and allocate memory
    if (num_ues > NUM_UE_INSTANCES) {
        pthread_mutex_lock(&mutex);
        data_store = realloc(data_store, num_ues * sizeof(DATA_RECORD));
        data_store_size = num_ues;
        pthread_mutex_unlock(&mutex);
    }

    // Populate NFAPI_CRC_INDICATION_PDU_T structures
    for (int i = 0; i < num_ues; i++) {
        // Assume ue_info and rnti are populated elsewhere
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.ue_info = ...;
        pdu.rnti = ...;
        pdu.crc_flag = ...;
    }

    // Validate data_content against schema and compute SHA-256 hash
    FILE *file = fopen(file_path, "rb");
    if (file) {
        unsigned char buffer[4096];
        size_t bytesRead;
        SHA256_CTX sha256;
        unsigned char hash[SHA256_DIGEST_LENGTH];

        SHA256_Init(&sha256);
        while ((bytesRead = fread(buffer, 1, sizeof(buffer), file)) > 0) {
