### Java Method: Processing String MD5 Hashes

```java
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

public class MD5Hasher {
    public static Map<String, String> computeMD5Hashes(List<String> strings) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        Map<String, String> hashes = new HashMap<>();

        for (String str : strings) {
            byte[] hashBytes = md.digest(str.getBytes());
            StringBuilder hexString = new StringBuilder();
            for (byte b : hashBytes) {
                String hex = Integer.toHexString(0xff & b);
                if(hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            hashes.put(str, hexString.toString());
        }

        return hashes;
    }
}
```

