import os
import zipfile
import hashlib
from datetime import datetime
from functools import wraps

# Define constants for file handling
MAX_FILE_SIZE = 10 * 1024 * 1024  # 10MB
CONTENT_TYPE_LIMITS = {
    'image': ['image/jpeg', 'image/png'],
    'text': ['text/plain', 'application/pdf']
}
UPLOAD_DIR = '/path/to/upload/directory'
ARCHIVE_DIR = '/path/to/archive/directory'

# Cache for frequently uploaded file metadata
file_cache = {}

def log_error(message, *args):
    # Simulate logging error to a centralized system
    print(f"ERROR: {message % args}")

def retry_with_exponential_backoff(func, max_retries=3, initial_delay=1, multiplier=2):
    @wraps(func)
    def wrapper(*args, **kwargs):
        attempts = 0
        while attempts < max_retries:
            try:
                return func(*args, **kwargs)
            except Exception as e:
                if attempts == max_retries - 1:
                    raise
                delay = initial_delay * (multiplier ** attempts)
                time.sleep(delay)
                attempts += 1
    return wrapper

@retry_with_exponential_backoff
def handle_file_upload(request_payload):
    file_name = request_payload.get('file_name')
    content_type = request_payload.get('content_type')
    file_data = request_payload.get('file_data')
    user_id = request_payload.get('user_id')
    upload_date = request_payload.get('upload_date')
    checksum = request_payload.get('checksum')
    operation_type = request_payload.get('operation_type')

    if not all([file_name, content_type, file_data, user_id, upload_date, checksum, operation_type]):
        log_error("Invalid request payload")
        return

    if operation_type == 'upload':
        # Validate file type and size
        if content_type not in CONTENT_TYPE_LIMITS['image']:
            log_error("Unsupported file type: %s", content_type)
            return

        if len(file_data) > MAX_FILE_SIZE:
            log_error("File too large: %d bytes", len(file_data))
            return

        # Validate checksum
        computed_checksum = hashlib.md5(file_data).hexdigest()
        if checksum != computed_checksum:
            log_error("Checksum mismatch")
            return

        # Store file in system
        file_path = os.path.join(UPLOAD_DIR, file_name)
        with open(file_path, 'wb') as f:
            f.write(file_data)

        file_cache[file_name] = {
            'file_type': content_type,
            'upload_date': upload_date,
            'user_id': user_id
        }

    elif operation_type == 'delete':
        # Remove the specified file and associated metadata
        if file_name in file_cache:
            os.remove(os.path.join(UPLOAD_DIR, file_name))
            del file_cache[file_name]
        else:
            log_error("File not found for deletion")

    elif operation_type == 'rename':
        new_file_name = request_payload.get('new_file_name')
        if new_file_name in file_cache and new_file_name != file_name:
            os.rename(os.path.join(UPLOAD_DIR, file_name), os.path.join(UPLOAD_DIR, new_file_name))
            file_cache[new_file_name] = file_cache.pop(file_name)
            file_cache[new_file_name]['file_name'] = new_file_name
        else:
            log_error("Invalid rename request")

    elif operation_type == 'archive':
        # Compress the file into a ZIP archive and store it
        with zipfile.ZipFile(os.path.join(ARCHIVE_DIR, f"{user_id}_{datetime.now().strftime('%Y%m%d%H%M%S')}.zip"), 'w') as zipf:
            zipf.writestr(file_name, file_data)

    else:
        log_error("Unsupported operation type: %s", operation_type)

# Example usage
request_payload = {
    'file_name': 'example.jpg',
    'content_type': 'image/jpeg',
    'file_data': b'\xff\xd8\xff\xe0\x00\x10JFIF\x00\x01\x01\x00\x00\x01\x00\x01\x00\x00\xff\xdb\x00C...\x00',
    'user_id': 'user123',
    'upload_date': datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
    'checksum': 'md5_checksum_here',
    'operation_type': 'upload'
}
handle_file_upload(request_payload)
