typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t allocated;
    size_t free;
    pthread_mutex_t lock;
} MemoryPool;

void init_memory_pool(MemoryPool *mp, size_t initial_size) {
    mp->pool = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!mp->pool) {
        // Handle allocation failure
        exit(EXIT_FAILURE);
    }
    mp->allocated = initial_size;
    mp->free = initial_size;
    pthread_mutex_init(&mp->lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T *allocate_pdu(MemoryPool *mp) {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    pthread_mutex_lock(&mp->lock);
    if (mp->free == 0) {
        // Allocate more memory
        size_t new_size = mp->allocated * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_pool = (NFAPI_CRC_INDICATION_PDU_T *)realloc(mp->pool, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pool) {
            // Handle allocation failure
            exit(EXIT_FAILURE);
        }
        mp->pool = new_pool;
        mp->allocated = new_size;
    }
    pdu = &mp->pool[--mp->free];
    pthread_mutex_unlock(&mp->lock);
    return pdu;
}

void deallocate_pdu(MemoryPool *mp, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&mp->lock);
    mp->pool[mp->free++] = *pdu; // Reuse the structure
    pthread_mutex_unlock(&mp->lock);
}

void destroy_memory_pool(MemoryPool *mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
}
