NFAPI_LIST_NODE_T* nfaapi_pool = NULL;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

NFAPI_LIST_NODE_T* generateNfaapiListWithTransactionMetrics(int count) {
    NFAPI_LIST_NODE_T* head = NULL;
    for (int i = 0; i < count; i++) {
        NFAPI_LIST_NODE_T* node = (NFAPI_LIST_NODE_T*)malloc(sizeof(NFAPI_LIST_NODE_T));
        if (!node) return NULL;

        pthread_mutex_lock(&pool_lock);
        if (nfaapi_pool != NULL) {
            node->next = nfaapi_pool;
            nfaapi_pool = nfaapi_pool->next;
        } else {
            node->next = NULL;
        }
        pthread_mutex_unlock(&pool_lock);

        // Initialize random values
        srand(time(NULL));
        node->data.RX_UE_INFORMATION_TAG = rand();
        node->data.RNTI = (uint16_t)rand();
        node->data.CRC_INDICATION_REL8_TAG = (uint8_t)(rand() % 256);

        if (head == NULL) {
            head = node;
        } else {
            NFAPI_LIST_NODE_T* temp = head;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = node;
        }
    }
    return head;
}

void freeNfaapiList(NFAPI_LIST_NODE_T* list) {
    NFAPI_LIST_NODE_T* current = list;
    while (current != NULL) {
        NFAPI_LIST_NODE_T* next = current->next;

        pthread_mutex_lock(&pool_lock);
        current->next = nfaapi_pool;
        nfaapi_pool = current;
        pthread_mutex_unlock(&pool_lock);

        free(current);
        current = next;
    }
}
