    char data[BUFFER_SIZE];
    int length;
} DataPacket;

DataPacket buffer[MAX_STREAMS];
int head = 0, tail = 0;
sem_t empty, full, mutex;

void* producer(void* arg) {
    while (1) {
        // Simulate data generation
        DataPacket packet;
        sem_wait(&empty);
        sem_wait(&mutex);
        // Add data to buffer
        buffer[tail] = packet;
        tail = (tail + 1) % MAX_STREAMS;
        sem_post(&mutex);
        sem_post(&full);
    }
}

void* consumer(void* arg) {
    while (1) {
        sem_wait(&full);
        sem_wait(&mutex);
        // Process data from buffer
        DataPacket packet = buffer[head];
        head = (head + 1) % MAX_STREAMS;
        sem_post(&mutex);
        sem_post(&empty);
    }
}

int main() {
    pthread_t producers[MAX_STREAMS], consumers[MAX_STREAMS];

    sem_init(&empty, 0, MAX_STREAMS);
    sem_init(&full, 0, 0);
    sem_init(&mutex, 0, 1);

    for (int i = 0; i < MAX_STREAMS; i++) {
        pthread_create(&producers[i], NULL, producer, NULL);
        pthread_create(&consumers[i], NULL, consumer, NULL);
    }

    for (int i = 0; i < MAX_STREAMS; i++) {
        pthread_join(producers[i], NULL);
        pthread_join(consumers[i], NULL);
    }

    sem_destroy(&empty);
    sem_destroy(&full);
    sem_destroy(&mutex);

    return 0;
}
