int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <directory>\n", argv[0]);
        return 1;
    }

    DIR *dir = opendir(argv[1]);
    if (!dir) {
        perror("opendir");
        return 1;
    }

    struct dirent *entry;
    FileHashPair **file_hashes = NULL;
    int count = 0;

    while ((entry = readdir(dir)) != NULL) {
        char path[256];
        snprintf(path, sizeof(path), "%s/%s", argv[1], entry->d_name);

        if (strcmp(entry->d_type, DT_LNK) == 0) {
            continue;
        }

        struct stat file_stat;
        if (stat(path, &file_stat) != 0) {
            perror("stat");
            continue;
        }

        FileMetadata metadata = {file_stat.st_size, file_stat.st_mtime, entry->d_type};
        process_file(path, &file_hashes, &count);
        update_cloud_storage_bucket(&metadata, "your-bucket-name");
    }

    closedir(dir);

    // Free allocated memory
    for (int i = 0; i < count; i++) {
        free(file_hashes[i]->file_path);
        free(file_hashes[i]->hash);
        free(file_hashes[i]);
    }
    free(file_hashes);

    return 0;
}
