#define LOG_INTERVAL 50

typedef struct {
    int signal_strength;
    double error_rate;
    float channel_utilization;
} PHY_FRAME_STATS;

int allocate_phy_frame_stats(PHY_FRAME_STATS **stats, size_t *count) {
    size_t chunk_size = INIT_CHUNK_SIZE;
    size_t total_allocated = 0;
    int log_count = 0;

    while (total_allocated < MAX_MEMORY_USAGE) {
        *stats = realloc(*stats, (*count + chunk_size) * sizeof(PHY_FRAME_STATS));
        if (*stats == NULL) {
            // Memory allocation failed, reduce chunk size and retry
            chunk_size /= 2;
            if (chunk_size == 0) {
                fprintf(stderr, "Memory allocation failed.\n");
                return -1;
            }
            continue;
        }

        for (size_t i = *count; i < *count + chunk_size; ++i) {
            (*stats)[i].signal_strength = 0;
            (*stats)[i].error_rate = 0.0;
            (*stats)[i].channel_utilization = 0.0;
        }

        *count += chunk_size;
        total_allocated += chunk_size * sizeof(PHY_FRAME_STATS);
        ++log_count;

        if (log_count >= LOG_INTERVAL) {
            printf("Allocated %zu structures, using %.2f MB\n", *count, (double)total_allocated / 1024.0 / 1024.0);
            log_count = 0;
        }
    }

    return *count;
}

int main() {
    PHY_FRAME_STATS *stats = NULL;
    size_t count = 0;

    if (allocate_phy_frame_stats(&stats, &count) != -1) {
        printf("Successfully allocated %zu structures.\n", count);
        // Free the allocated memory when done
        free(stats);
    }

    return 0;
}
