```python
import os
import hashlib
import asyncio
import socket
from logging import getLogger, StreamHandler, DEBUG, INFO
from concurrent.futures import ThreadPoolExecutor

log = getLogger(__name__)
log.setLevel(DEBUG)
handler = StreamHandler()
log.addHandler(handler)

def calculate_md5(file_path):
    hasher = hashlib.md5()
    chunk_size = 64 * 1024  # 64 KB
    with open(file_path, 'rb') as f:
        while True:
            data = f.read(chunk_size)
            if not data:
                break
            hasher.update(data)
    return hasher.hexdigest()

def process_file(file_path):
    try:
        if os.path.islink(file_path) or file_path.endswith('.enc'):
            return None
        if os.stat(file_path).st_size > 100 * 1024 * 1024:
            # Handle large files
            pass
        md5_hash = calculate_md5(file_path)
        return {file_path: md5_hash}
    except (PermissionError, FileNotFoundError, OSError) as e:
        log.error(f"Failed to process file {file_path}: {e}")
        return None

async def process_directory(directory):
    results = {}
    with ThreadPoolExecutor() as executor:
        tasks = [executor.submit(process_file, os.path.join(directory, f)) for f in os.listdir(directory)]
        for future in asyncio.as_completed(tasks):
            result = future.result()
            if result:
                results.update(result)
    return results

def main():
    directory_path = '/path/to/directory'
    loop = asyncio.get_event_loop()
    md5_dict = loop.run_until_complete(process_directory(directory_path))
    log.info(f"Processed files: {md5_dict}")

if __name__ == "__main__":
    main()
```

