import os
import hashlib
import logging
from concurrent.futures import ThreadPoolExecutor, as_completed

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

def process_file(file_path):
    try:
        with open(file_path, 'rb') as f:
            file_size = os.path.getsize(file_path)
            if file_size > 100 * 1024 * 1024:  # 100 MB
                md5_hash = hashlib.md5()
                with tempfile.NamedTemporaryFile(delete=False) as temp_file:
                    while chunk := f.read(64 * 1024):  # Read in chunks of 64 KB
                        md5_hash.update(chunk)
                        temp_file.write(chunk)
                    md5_value = md5_hash.hexdigest()
            else:
                md5_value = hashlib.md5(f.read()).hexdigest()
            return {file_path: md5_value}
    except Exception as e:
        logger.error(f"Failed to process file {file_path}: {e}")
        return None

def process_directory(directory):
    result = {}
    with ThreadPoolExecutor(max_workers=10) as executor:
        futures = {executor.submit(process_file, os.path.join(directory, f)): f for f in os.listdir(directory)}
        for future in as_completed(futures):
            file_path = futures[future]
            try:
                md5_info = future.result()
                if md5_info is not None:
                    result.update(md5_info)
            except Exception as e:
                logger.error(f"Failed to process directory {directory}: {e}")
    return result
