    if (!collection) return NULL;
    collection->count = 0;
    pthread_mutex_init(&collection->mutex, NULL);
    return collection;
}

int add_measurement(MeasurementCollection* collection, LTE_MEASUREMENT_REPORT_PDU_T* measurement) {
    pthread_mutex_lock(&collection->mutex);
    if (collection->count >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&collection->mutex);
        free(measurement);
        return -1; // Collection full
    }
    collection->elements[collection->count++] = measurement;
    pthread_mutex_unlock(&collection->mutex);
    return 0;
}

void destroy_measurement_collection(MeasurementCollection* collection) {
    pthread_mutex_lock(&collection->mutex);
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->elements[i]);
    }
    collection->count = 0;
    pthread_mutex_unlock(&collection->mutex);
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}
