#include <iostream>
#include <forward_list>
#include <string>
#include <map>
#include <algorithm>
#include <openssl/md5.h>

class TokenManager {
public:
    struct Token {
        std::string access_token;
        int expires_in;
        std::string token_type;
        std::optional<std::string> refresh_token;

        bool isValid() const {
            if (token_type != "Bearer" || expires_in <= 0) return false;
            // Check for presence of required fields
            return true;
        }
    };

private:
    std::forward_list<Token> tokens;

public:
    void insertToken(const Token& token, const std::string& targetToken = "") {
        auto it = std::find_if(tokens.begin(), tokens.end(), [&](const Token& t) { return t.access_token == targetToken; });
        if (it != tokens.end()) {
            tokens.insert_after(it, token);
        } else {
            tokens.push_front(token);
        }
    }

    static std::string calculateMD5(const std::string& input) {
        unsigned char digest[MD5_DIGEST_LENGTH];
        MD5((unsigned char*)input.c_str(), input.size(), (unsigned char*)&digest);

        char mdString[33];
        for(int i = 0; i < 16 ; ++i)
            sprintf(&mdString[i*2], "%02x", (unsigned int)digest[i]);

        return std::string(mdString);
    }
};
