    if (used_size >= allocated_size) {
        size_t new_size = std::max(allocated_size * 2, size_t(1000));
        LTE_MEASUREMENT_REPORT_PDU_T* new_reports = realloc(measurement_reports, new_size * sizeof(LTE_MEASUREMENT_REPORT_PDU_T));
