import os
import gzip
from Crypto.Cipher import AES
import json
import time
import logging

class LogProcessor:
    def __init__(self, log_directory):
        self.log_directory = log_directory
        self.logger = self.setup_logger()

    @staticmethod
    def setup_logger():
        logger = logging.getLogger('LogProcessor')
        handler = logging.FileHandler('log_processing.log')
        formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
        handler.setFormatter(formatter)
        logger.addHandler(handler)
        logger.setLevel(logging.DEBUG)
        return logger

    def process_logs(self):
        failed_auths = {}
        for root, _, files in os.walk(self.log_directory):
            for file_name in files:
                full_path = os.path.join(root, file_name)
                try:
                    with self.open_log_file(full_path) as f:
                        for line in f:
                            self.process_log_line(line, failed_auths)
                except Exception as e:
                    self.logger.error(f"Failed to process {full_path}: {e}")

    def open_log_file(self, full_path):
        if full_path.endswith('.gz'):
            return gzip.open(full_path, 'rt')
        elif full_path.endswith('.aes'):
            with open(full_path, 'rb') as f:
                iv = f.read(16)
                cipher = AES.new(b'secretkey12345', AES.MODE_CBC, iv)
                return io.TextIOWrapper(cipher.decryptor(), encoding='utf-8')
        else:
            return open(full_path, 'rt')

    def process_log_line(self, line, failed_auths):
        try:
            data = json.loads(line)
            if 'auth_status' in data and not data['auth_status']:
                user = data.get('user', 'unknown')
                failed_auths[user] = failed_auths.get(user, 0) + 1
        except Exception as e:
            self.logger.error(f"Failed to parse log line: {e}")

if __name__ == "__main__":
    processor = LogProcessor('/path/to/log/directory')
    start_time = time.time()
    processor.process_logs()
    end_time = time.time()
    print(f"Processing completed in {end_time - start_time} seconds")
