NFAPI_MEMORY_POOL_T* create_memory_pool() {
    NFAPI_MEMORY_POOL_T *pool = (NFAPI_MEMORY_POOL_T*)malloc(sizeof(NFAPI_MEMORY_POOL_T));
    if (!pool) return NULL;

    pool->elements = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_ELEMENTS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->elements) {
        free(pool);
        return NULL;
    }

    pool->count = 0;
    pool->capacity = MAX_ELEMENTS;
    pthread_mutex_init(&pool->mutex, NULL);

    return pool;
}

void destroy_memory_pool(NFAPI_MEMORY_POOL_T *pool) {
    free(pool->elements);
    pthread_mutex_destroy(&pool->mutex);
    free(pool);
}

int allocate_element(NFAPI_MEMORY_POOL_T *pool, NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&pool->mutex);

    if (pool->count >= pool->capacity) {
        pthread_mutex_unlock(&pool->mutex);
        return -1; // Memory overflow
    }

    pool->elements[pool->count++] = *element;
    pthread_mutex_unlock(&pool->mutex);

    return 0;
}

int deallocate_element(NFAPI_MEMORY_POOL_T *pool, size_t index) {
    pthread_mutex_lock(&pool->mutex);

    if (index >= pool->count) {
        pthread_mutex_unlock(&pool->mutex);
        return -1; // Index out of bounds
    }

    // Move the last element to fill the gap and decrement count
    if (index != --pool->count) {
        pool->elements[index] = pool->elements[pool->count];
    }

    pthread_mutex_unlock(&pool->mutex);

    return 0;
}
