#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_ELEMENTS 5000
#define PAYLOAD_MIN_LENGTH 16
#define PAYLOAD_MAX_LENGTH 256

typedef struct {
    uint32_t messageID;
    uint64_t timestamp;
    uint8_t payload[PAYLOAD_MAX_LENGTH];
} NFDataMessage_t;

typedef struct {
    NFDataMessage_t* pool;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} MemoryPool_t;

MemoryPool_t* create_memory_pool() {
    MemoryPool_t* pool = (MemoryPool_t*)malloc(sizeof(MemoryPool_t));
    if (!pool) return NULL;
    pool->pool = (NFDataMessage_t*)malloc(MAX_ELEMENTS * sizeof(NFDataMessage_t));
    if (!pool->pool) {
        free(pool);
        return NULL;
    }
    pool->capacity = MAX_ELEMENTS;
    pool->size = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_memory_pool(MemoryPool_t* pool) {
    pthread_mutex_destroy(&pool->lock);
    free(pool->pool);
    free(pool);
}

int add_message_to_pool(MemoryPool_t* pool, uint32_t messageID, uint64_t timestamp, const uint8_t* payload, size_t length) {
    pthread_mutex_lock(&pool->lock);
    if (pool->size >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&pool->lock);
        return -1; // Overflow
    }
    NFDataMessage_t* msg = &pool->pool[pool->size];
    msg->messageID = messageID;
    msg->timestamp = timestamp;
    memcpy(msg->payload, payload, length);
    pool->size++;
    pthread_mutex_unlock(&pool->lock);
    return 0;
}

