import json
import yaml
import os
from ipaddress import IPv4Address, IPv6Address

def parse_network_config(file_path):
    if not os.path.exists(file_path) or os.path.getsize(file_path) > 50 * 1024 * 1024:
        raise Exception("File not found or exceeds size limit")

    try:
        with open(file_path, 'r') as file:
            data = file.read()
            if file_path.endswith('.json'):
                config = json.loads(data)
            elif file_path.endswith('.yaml'):
                config = yaml.safe_load(data)
            else:
                # Handle plain text parsing
                pass
    except (json.JSONDecodeError, yaml.YAMLError) as e:
        raise Exception(f"Failed to parse file: {e}")

    route_table = {}
    for entry in config.get('routes', []):
        ip = entry['ip']
        if isinstance(ip, str) and (IPv4Address.ip_address(ip) or IPv6Address.ip_address(ip)):
            route_table[ip] = entry['route']

    return route_table

def process_network_config_files(file_paths):
    results = {}
    for file_path in file_paths:
        try:
            results[file_path] = parse_network_config(file_path)
        except Exception as e:
            print(f"Error processing {file_path}: {e}")

    return results
