    MAC_PDU *pdu;
    pthread_mutex_t lock;
} MLBD;

typedef struct Session {
    unsigned int session_id;
    MLBD *mlbd_list;
    size_t mlbd_count;
    size_t mlbd_capacity;
    pthread_mutex_t mutex;
} Session;

Session* create_session() {
    Session *session = (Session*)malloc(sizeof(Session));
    if (!session) {
        fprintf(stderr, "Failed to allocate memory for session\n");
        return NULL;
    }
    session->mlbd_list = NULL;
    session->mlbd_count = 0;
    session->mlbd_capacity = 0;
    pthread_mutex_init(&session->mutex, NULL);
    return session;
}

void destroy_session(Session *session) {
    if (session->mlbd_list) {
        for (size_t i = 0; i < session->mlbd_count; ++i) {
            if (session->mlbd_list[i].pdu) {
                free(session->mlbd_list[i].pdu);
            }
            pthread_mutex_destroy(&session->mlbd_list[i].lock);
        }
        free(session->mlbd_list);
    }
    pthread_mutex_destroy(&session->mutex);
    free(session);
}

int add_mlbd_to_session(Session *session, MAC_PDU *pdu) {
    pthread_mutex_lock(&session->mutex);
    if (session->mlbd_count >= session->mlbd_capacity) {
        size_t new_capacity = session->mlbd_capacity == 0 ? 1 : session->mlbd_capacity * 2;
        MLBD *new_mlbd_list = realloc(session->mlbd_list, new_capacity * sizeof(MLBD));
        if (!new_mlbd_list) {
            pthread_mutex_unlock(&session->mutex);
            fprintf(stderr, "Failed to allocate memory for new MLBD list\n");
            return -1;
        }
        session->mlbd_list = new_mlbd_list;
        session->mlbd_capacity = new_capacity;
    }
    session->mlbd_list[session->mlbd_count].pdu = pdu;
    pthread_mutex_init(&session->mlbd_list[session->mlbd_count].lock, NULL);
    ++session->mlbd_count;
    pthread_mutex_unlock(&session->mutex);
    return 0;
}

void validate_mlbd(MLBD *mlbd) {
    pthread_mutex_lock(&mlbd->lock);
    if (mlbd->pdu && /* Validate CRC_INDICATION_REL8_TAG against CRCFLAG */) {
        // Update state accordingly
    }
    pthread_mutex_unlock(&mlbd->lock);
}

int process_data_packets(Session *session, unsigned char *packet_data, size_t packet_size) {
    for (size_t i = 0; i < packet_size; ++i) {
        MAC_PDU pdu;
        // Parse packet_data to populate pdu
        if (add_mlbd_to_session(session, &pdu) != 0) {
            return -1;
        }
        validate_mlbd(&session->mlbd_list[session->mlbd_count - 1]);
    }
    return 0;
}

void cleanup_resources(Session *session) {
    destroy_session(session);
}
