<?php
function handleUserRequest() {
    $input = $_POST;

    if (empty($input['action'])) {
        return json_encode(['error' => 'invalid_request']);
    }

    switch ($input['action']) {
        case 'fetch':
            return fetchUser($input);
        case 'create':
            return createUser($input);
        case 'update':
            return updateUser($input);
        case 'delete':
            return deleteUser($input);
        default:
            return json_encode(['error' => 'invalid_request']);
    }
}

function fetchUser($input) {
    $id = isset($input['id']) ? intval($input['id']) : 0;

    if ($id <= 0) {
        return json_encode(['error' => 'invalid_request']);
    }

    // Simulated database fetch
    $user = getUserFromDatabase($id);

    if (!$user) {
        return json_encode(['error' => 'User not found']);
    }

    return json_encode($user);
}

function createUser($input) {
    $name = isset($input['name']) ? trim($input['name']) : '';
    $email = isset($input['email']) ? trim($input['email']) : '';
    $password = isset($input['password']) ? trim($input['password']) : '';

    if (strlen($name) < 2 || strlen($name) > 50) {
        return json_encode(['error' => 'Invalid name']);
    }

    if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
        return json_encode(['error' => 'Invalid email']);
    }

    if (strlen($password) < 8) {
        return json_encode(['error' => 'Password must be at least 8 characters long']);
    }

    // Simulated database save
    $user = saveUserToDatabase($name, $email, $password);

    if (!$user) {
        return json_encode(['error' => 'Failed to create user']);
    }

    return json_encode(['message' => 'User created successfully']);
}

function updateUser($input) {
    $id = isset($input['id']) ? intval($input['id']) : 0;
    $name = isset($input['name']) ? trim($input['name']) : '';
    $email = isset($input['email']) ? trim($input['email']) : '';
    $password = isset($input['password']) ? trim($input['password']) : '';

    if ($id <= 0) {
        return json_encode(['error' => 'Invalid user ID']);
    }

    if (strlen($name) < 2 || strlen($name) > 50) {
        return json_encode(['error' => 'Invalid name']);
    }

    if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
        return json_encode(['error' => 'Invalid email']);
    }

    if (strlen($password) < 8) {
        return json_encode(['error' => 'Password must be at least 8 characters long']);
    }

    // Simulated database update
    $updated = updateUserInDatabase($id, $name, $email, $password);

    if (!$updated) {
        return json_encode(['error' => 'Failed to update user']);
    }

    return json_encode(['message' => 'User updated successfully']);
}

function deleteUser($input) {
    $id = isset($input['id']) ? intval($input['id']) : 0;

    if ($id <= 0) {
        return json_encode(['error' => 'Invalid user ID']);
    }

    // Simulated database delete
    $deleted = deleteUserFromDatabase($id);

    if (!$deleted) {
        return json_encode(['error' => 'Failed to delete user']);
    }

    return json_encode(['message' => 'User deleted successfully']);
}

function getUserFromDatabase($id) {
    // Simulated user data retrieval from the database
    $users = [
        1 => ['id' => 1, 'name' => 'John Doe', 'email' => 'john@example.com', 'status' => 'active']
    ];

    return isset($users[$id]) ? $users[$id] : null;
