#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct LTE_PDCP_PDU_T {
    PDCP_PDU_HEADER header;
    uint32_t SN;
    uint8_t SDU[1024]; // Placeholder for SDU data
} LTE_PDCP_PDU_T;

typedef struct ListNode {
    int key;
    LTE_PDCP_PDU_T* node;
    struct ListNode* next;
} ListNode;

typedef struct PDCP_Database {
    ListNode** records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock; // Mutex for thread safety
    FILE* file; // File pointer for serialization/deserialization
    bool isPersistingToDB; // Flag to indicate if data should be persisted to external DB
} PDCP_Database;

PDCP_Database* create_database(size_t initial_capacity) {
    PDCP_Database* db = (PDCP_Database*)malloc(sizeof(PDCP_Database));
    if (!db) return NULL;

    db->records = (ListNode**)calloc(initial_capacity, sizeof(ListNode*));
    if (!db->records) {
        free(db);
        return NULL;
    }

    db->capacity = initial_capacity;
    db->size = 0;
    pthread_mutex_init(&db->lock, NULL);
    db->file = fopen("pdcppdu_database.bin", "w+b");
    if (!db->file) {
        free(db->records);
        free(db);
        return NULL;
    }

    // Initialize other members as needed
    db->isPersistingToDB = false;
    return db;
}

void destroy_database(PDCP_Database* db) {
    pthread_mutex_lock(&db->lock);
    for (size_t i = 0; i < db->capacity; ++i) {
        if (db->records[i]) {
            free(db->records[i]->node);
            free(db->records[i]);
        }
    }
    pthread_mutex_unlock(&db->lock);

    fclose(db->file);
    free(db->records);
    pthread_mutex_destroy(&db->lock);
    free(db);
}

LTE_PDCP_PDU_T* allocate_pdu() {
    LTE_PDCP_PDU_T* pdu = (LTE_PDCP_PDU_T*)malloc(sizeof(LTE_PDCP_PDU_T));
    if (!pdu) return NULL;

    // Initialize PDU fields
    pdu->header.type = 0; // Example initialization, replace with actual logic
    pdu->SN = rand(); // Random SN value
    memset(pdu->SDU, 0, sizeof(pdu->SDU)); // Placeholder for SDU data

    return pdu;
}

int insert_record(PDCP_Database* db, int key, LTE_PDCP_PDU_T* node) {
    pthread_mutex_lock(&db->lock);

    if (key < 0 || key >= db->capacity) {
        pthread_mutex_unlock(&db->lock);
        return -1; // Invalid key
    }

    ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
    if (!newNode) {
        pthread_mutex_unlock(&db->lock);
        return -2; // Memory allocation failed
    }

    newNode->key = key;
    newNode->node = node;
    newNode->next = db->records[key];
    db->records[key] = newNode;
    ++db->size;

    pthread_mutex_unlock(&db->lock);

    // Persist to external DB if necessary
    if (db->isPersistingToDB) {
        persist_to_db(db, key, node);
    }

    return 0;
}

void* get_record(PDCP_Database* db, int key) {
    pthread_mutex_lock(&db->lock);

    if (key < 0 || key >= db->capacity || !db->records[key]) {
        pthread_mutex_unlock(&db->lock);
        return NULL; // Record not found
    }

    ListNode* node = db->records[key];
    pthread_mutex_unlock(&db->lock);

    // Cache hit or load from disk if necessary
    return node->node;
}

