#include "resource_manager.h"

typedef struct {
    TX_PACKET_METADATA metadata;
    pthread_mutex_t mutex;
} Packet;

Packet* packet_list = NULL;
size_t list_size = 0;
pthread_mutex_t list_mutex;

void initialize_packet_list(size_t N) {
    list_size = N;
    packet_list = (Packet*)malloc(N * sizeof(Packet));
    if (packet_list == NULL) {
        // Log memory allocation failure
        return;
    }
    for (size_t i = 0; i < N; ++i) {
        pthread_mutex_init(&packet_list[i].mutex, NULL);
    }
}

void destroy_packet_list() {
    for (size_t i = 0; i < list_size; ++i) {
        pthread_mutex_destroy(&packet_list[i].mutex);
    }
    free(packet_list);
}

int add_packet(TX_UE_INFORMATION_TAG ue_tag, NFAPI_L1_TAG l1_tag, uint16_t pci, CRC_INDICATION_REL8_TAG crc_indication) {
    pthread_mutex_lock(&list_mutex);
    for (size_t i = 0; i < list_size - 1; ++i) {
        pthread_mutex_lock(&packet_list[i].mutex);
        if (packet_list[i].metadata.pci == pci || packet_list[i + 1].metadata.pci == pci) {
            pthread_mutex_unlock(&packet_list[i].mutex);
            pthread_mutex_unlock(&list_mutex);
            return -1; // PCI conflict
        }
        pthread_mutex_unlock(&packet_list[i].mutex);
    }
    for (size_t i = 0; i < list_size; ++i) {
        if (pthread_mutex_trylock(&packet_list[i].mutex) == 0) {
            packet_list[i].metadata.ue_tag = ue_tag;
            packet_list[i].metadata.l1_tag = l1_tag;
            packet_list[i].metadata.pci = pci;
            packet_list[i].metadata.crc_indication = crc_indication;
            pthread_mutex_unlock(&packet_list[i].mutex);
            pthread_mutex_unlock(&list_mutex);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&list_mutex);
    return -1; // Full list
}

void* packet_generator_thread(void* arg) {
    size_t N = *(size_t*)arg;
    for (size_t i = 0; i < N; ++i) {
        TX_UE_INFORMATION_TAG ue_tag = generate_ue_tag();
        NFAPI_L1_TAG l1_tag = generate_l1_tag();
        uint16_t pci = get_available_pci();
        CRC_INDICATION_REL8_TAG crc_indication = { .crcflag = rand() % 2 };
        while (add_packet(ue_tag, l1_tag, pci, crc_indication) != 0);
    }
    return NULL;
}

int main() {
    size_t N = 1000; // Example value
    initialize_packet_list(N);

    pthread_t threads[N];
    for (size_t i = 0; i < N; ++i) {
        pthread_create(&threads[i], NULL, packet_generator_thread, &N);
    }

    for (size_t i = 0; i < N; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_packet_list();
    return 0;
}
