    list->buckets = (Node**)calloc(initialCapacity, sizeof(Node*));
    list->capacity = initialCapacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroyFrameList(FrameList* list) {
    for (size_t i = 0; i < list->capacity; ++i) {
        Node* current = list->buckets[i];
        while (current != NULL) {
            Node* next = current->next;
            free(current);
            current = next;
        }
    }
    free(list->buckets);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void addOrUpdateFrame(FrameList* list, DL_FRAME_INFO_T frame) {
    size_t index = hash(frame.SUBFRAME_ID, list->capacity);
    Node** currentBucket = &list->buckets[index];
    while (*currentBucket != NULL) {
        if ((*currentBucket)->frame.SUBFRAME_ID == frame.SUBFRAME_ID) {
            (*currentBucket)->frame = frame;
            return;
        }
        currentBucket = &(*currentBucket)->next;
    }
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->frame = frame;
    newNode->next = NULL;
    *currentBucket = newNode;
    list->count++;
}

void removeFrame(FrameList* list, int SUBFRAME_ID) {
    size_t index = hash(SUBFRAME_ID, list->capacity);
    Node** currentBucket = &list->buckets[index];
    while (*currentBucket != NULL) {
        if ((*currentBucket)->frame.SUBFRAME_ID == SUBFRAME_ID) {
            Node* temp = *currentBucket;
            *currentBucket = (*currentBucket)->next;
            free(temp);
            list->count--;
            return;
        }
        currentBucket = &(*currentBucket)->next;
    }
}

