typedef struct LTE_ENB_LOG_ENTRY_T {
    int LOG_TIMESTAMP;
    int CELL_ID;
    char LOG_TYPE[50];
} LTE_ENB_LOG_ENTRY_T;

typedef struct ENB_LOG_LIST_NODE {
    LTE_ENB_LOG_ENTRY_T entry;
    struct ENB_LOG_LIST_NODE *next;
} ENB_LOG_LIST_NODE;

typedef struct ENB_LOG_MANAGER {
    ENB_LOG_LIST_NODE *head;
    pthread_mutex_t lock;
} ENB_LOG_MANAGER;

ENB_LOG_MANAGER* enb_log_manager_create() {
    ENB_LOG_MANAGER *manager = (ENB_LOG_MANAGER*)malloc(sizeof(ENB_LOG_MANAGER));
    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void enb_log_manager_add_entry(ENB_LOG_MANAGER *manager, LTE_ENB_LOG_ENTRY_T entry) {
    pthread_mutex_lock(&manager->lock);
    ENB_LOG_LIST_NODE *new_node = (ENB_LOG_LIST_NODE*)malloc(sizeof(ENB_LOG_LIST_NODE));
    new_node->entry = entry;
    new_node->next = manager->head;
    manager->head = new_node;
    pthread_mutex_unlock(&manager->lock);
}

void enb_log_manager_update_entry(ENB_LOG_MANAGER *manager, int cell_id, LTE_ENB_LOG_ENTRY_T new_entry) {
    pthread_mutex_lock(&manager->lock);
    ENB_LOG_LIST_NODE *current = manager->head;
    while (current != NULL) {
        if (current->entry.CELL_ID == cell_id) {
            current->entry = new_entry;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
}

void enb_log_manager_remove_entry(ENB_LOG_MANAGER *manager, int cell_id) {
    pthread_mutex_lock(&manager->lock);
    ENB_LOG_LIST_NODE *current = manager->head;
    ENB_LOG_LIST_NODE *previous = NULL;
    while (current != NULL) {
        if (current->entry.CELL_ID == cell_id) {
            if (previous == NULL) {
                manager->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
}

int enb_log_manager_get_total_entries(ENB_LOG_MANAGER *manager) {
    int count = 0;
    pthread_mutex_lock(&manager->lock);
    ENB_LOG_LIST_NODE *current = manager->head;
    while (current != NULL) {
        count++;
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
    return count;
}

int enb_log_manager_get_critical_entries(ENB_LOG_MANAGER *manager, const char *critical_level) {
    int count = 0;
    pthread_mutex_lock(&manager->lock);
    ENB_LOG_LIST_NODE *current = manager->head;
    while (current != NULL) {
        if (strcmp(current->entry.LOG_TYPE, critical_level) == 0) {
            count++;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
    return count;
}

void enb_log_manager_destroy(ENB_LOG_MANAGER *manager) {
    pthread_mutex_lock(&manager->lock);
    ENB_LOG_LIST_NODE *current = manager->head;
    while (current != NULL) {
        ENB_LOG_LIST_NODE *temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
