struct NetworkElement {
    int RNTI;
    std::string protocol;
    // Add other NE properties here
};

class NetworkManager {
public:
    enum Strategy { LATENCY_REDUCED, THROUGHPUT_ENHANCED, RELIABILITY_IMPROVED, BALANCED, STRATEGY_5 };
    enum AggregationMethod { AVERAGE, MEDIAN, MAX_VALUE, MIN_VALUE, STD_DEVIATION };

    void addNE(const NetworkElement& ne) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (neMap_.find(ne.RNTI) != neMap_.end()) {
            // Update existing NE
            neList_.erase(neMap_[ne.RNTI]);
        }
        neMap_[ne.RNTI] = neList_.insert(neList_.begin(), ne);
    }

    void removeNE(int RNTI) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = neMap_.find(RNTI);
        if (it != neMap_.end()) {
            neList_.erase(it->second);
            neMap_.erase(it);
        }
    }

    void applyStrategy(Strategy strategy) {
        std::lock_guard<std::mutex> lock(mutex_);
        // Apply the selected strategy with a random delay
        std::this_thread::sleep_for(std::chrono::milliseconds(rand() % 51));
        if (strategyHistory_.size() >= 2 && strategy == strategyHistory_.back()) {
            int nextStrategy = (static_cast<int>(strategy) + 1) % Strategy::STRATEGY_5;
            applyStrategy(static_cast<Strategy>(nextStrategy));
        } else {
            strategyHistory_.push_back(strategy);
            if (strategyHistory_.size() > 10) {
                strategyHistory_.pop_front();
            }
        }
    }

    // Implement other functions and data structures as per the task requirements
private:
    std::unordered_map<int, std::list<NetworkElement>::iterator> neMap_;
    std::list<NetworkElement> neList_;
    std::mutex mutex_;
    std::queue<Strategy> strategyHistory_;
};
