void add_or_update_entry(NFAPI_DYNAMIC_LIST_T* list, int RNTI, int RX_UE_INFORMATION_TAG, bool CRC_INDICATION_REL8_TAG, int EXTENDED_CARRIER_INFO_TAG) {
    pthread_mutex_lock(&list->lock);
    NFAPI_LIST_NODE_T* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            // Update existing entry
            current->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
            current->data.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
            current->data.EXTENDED_CARRIER_INFO_TAG = EXTENDED_CARRIER_INFO_TAG;
            pthread_mutex_unlock(&list->lock);
