    // Add new entry
    NFAPI_LIST_NODE_T* new_node = (NFAPI_LIST_NODE_T*)malloc(sizeof(NFAPI_LIST_NODE_T));
    if (new_node == NULL) {
        pthread_mutex_unlock(&list->lock);
