void add_entry(uint32_t rx_tag, uint16_t rnti, bool crc_flag) {
    for (int i = 0; i < entry_count; i++) {
        if (entries[i].RNTI == rnti) {
            entries[i] = (NFAPI_CRC_INDICATION_PDU_T){rx_tag, rnti, crc_flag};
            return;
