```c
#include <stdlib.h>
#include <stdio.h>

typedef struct {
    int RX_FRAME_HEADER;
    int FRAME_TYPE;
    float RX_POWER_LEVEL;
} NFAPI_RX_FRAME_PDU_T;

#define MAX_ENTRIES 50000

NFAPI_RX_FRAME_PDU_T* entries[MAX_ENTRIES];
int entry_count = 0;

void add_entry(NFAPI_RX_FRAME_PDU_T* new_entry) {
    for (int i = 0; i < entry_count; i++) {
        if (entries[i]->FRAME_TYPE == new_entry->FRAME_TYPE) {
            free(entries[i]);
            entries[i] = new_entry;
            return;
        }
    }
    if (entry_count < MAX_ENTRIES) {
        entries[entry_count++] = new_entry;
    } else {
        printf("Maximum entry limit reached.\n");
        free(new_entry);
    }
}

void remove_entry(int frame_type) {
    for (int i = 0; i < entry_count; i++) {
        if (entries[i]->FRAME_TYPE == frame_type) {
            free(entries[i]);
            for (; i < entry_count - 1; i++) {
                entries[i] = entries[i + 1];
            }
            entry_count--;
            break;
        }
    }
}

NFAPI_RX_FRAME_PDU_T* find_entry(int frame_type) {
    for (int i = 0; i < entry_count; i++) {
        if (entries[i]->FRAME_TYPE == frame_type) {
            return entries[i];
        }
    }
    return NULL;
}

void calculate_statistics() {
    float total_power = 0;
    int count = 0;

    for (int i = 0; i < entry_count; i++) {
        total_power += entries[i]->RX_POWER_LEVEL;
        count++;
    }

    if (count > 0) {
        printf("Total entries: %d\n", count);
        printf("Average RX Power Level: %.2f\n", total_power / count);
    } else {
        printf("No entries to calculate statistics.\n");
    }
}

float* read_floats_from_stdin() {
    size_t initial_capacity = 100;
    float* data = (float*)malloc(initial_capacity * sizeof(float));
    if (!data) return NULL;

    size_t size = 0;
    while (scanf("%f", &data[size]) == 1) {
        if (++size >= initial_capacity) {
            initial_capacity *= 2;
            data = realloc(data, initial_capacity * sizeof(float));
            if (!data) {
                free(data);
                return NULL;
            }
        }
    }

    float* result = (float*)malloc(size * sizeof(float));
    if (result) {
        for (size_t i = 0; i < size; i++) {
            result[i] = data[i];
        }
    }
    free(data);
    return result;
}

void calculate_mean_and_stddev(float* data, size_t size) {
    float sum = 0, mean = 0, stddev = 0;

    for (size_t i = 0; i < size; i++) {
        sum += data[i];
    }
    mean = sum / size;

    for (size_t i = 0; i < size; i++) {
        stddev += (data[i] - mean) * (data[i] - mean);
    }
    stddev = sqrt(stddev / size);

    printf("Mean: %.2f\n", mean);
    printf("Standard Deviation: %.2f\n", stddev);
}

int main() {
    // Example usage
    NFAPI_RX_FRAME_PDU_T* new_entry = (NFAPI_RX_FRAME_PDU_T*)malloc(sizeof(NFAPI_RX_FRAME_PDU_T));
    new_entry->FRAME_TYPE = 1;
    new_entry->RX_POWER_LEVEL = 10.5;
    add_entry(new_entry);

    calculate_statistics();

    float* floats = read_floats_from_stdin();
    if (floats) {
        calculate_mean_and_stddev(floats, size);
        free(floats);
    }

    return 0;
}
```

