#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_NODES 1000

typedef enum {
    HEALTH_OK,
    HEALTH_CRITICAL
} NODE_HEALTH_STATE;

typedef struct {
    int node_id;
    long heartbeat_timestamp;
    NODE_HEALTH_STATE health_state;
} NODE_STATUS_REPORT_T;

typedef struct {
    NODE_STATUS_REPORT_T reports[MAX_NODES];
    int count;
    pthread_mutex_t lock;
} NODE_MONITORING_SYSTEM_T;

void init_node_monitoring_system(NODE_MONITORING_SYSTEM_T *sys) {
    sys->count = 0;
    pthread_mutex_init(&sys->lock, NULL);
}

int add_or_update_node_report(NODE_MONITORING_SYSTEM_T *sys, int node_id, long heartbeat_timestamp, NODE_HEALTH_STATE health_state) {
    pthread_mutex_lock(&sys->lock);

    for (int i = 0; i < sys->count; i++) {
        if (sys->reports[i].node_id == node_id) {
            sys->reports[i] = (NODE_STATUS_REPORT_T){node_id, heartbeat_timestamp, health_state};
            pthread_mutex_unlock(&sys->lock);
            return 0;
        }
    }

    if (sys->count >= MAX_NODES) {
        pthread_mutex_unlock(&sys->lock);
        return -1; // Error: Maximum nodes reached
    }

    sys->reports[sys->count++] = (NODE_STATUS_REPORT_T){node_id, heartbeat_timestamp, health_state};
    pthread_mutex_unlock(&sys->lock);
    return 0;
}

int remove_node_report(NODE_MONITORING_SYSTEM_T *sys, int node_id) {
    pthread_mutex_lock(&sys->lock);

    for (int i = 0; i < sys->count; i++) {
        if (sys->reports[i].node_id == node_id) {
            for (int j = i; j < sys->count - 1; j++) {
                sys->reports[j] = sys->reports[j + 1];
            }
            sys->count--;
            pthread_mutex_unlock(&sys->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&sys->lock);
    return -1; // Error: Node not found
}

void get_statistics(NODE_MONITORING_SYSTEM_T *sys, int *total_nodes, int *critical_count, long *average_heartbeat) {
    pthread_mutex_lock(&sys->lock);

    *total_nodes = sys->count;
    *critical_count = 0;
    long total_heartbeat = 0;

    for (int i = 0; i < sys->count; i++) {
        if (sys->reports[i].health_state == HEALTH_CRITICAL) {
            (*critical_count)++;
        }
        total_heartbeat += sys->reports[i].heartbeat_timestamp;
    }

    if (sys->count > 0) {
        *average_heartbeat = total_heartbeat / sys->count;
    } else {
        *average_heartbeat = 0;
    }

    pthread_mutex_unlock(&sys->lock);
}
