                int lineCount = 0;
                string line;
                while ((line = reader.ReadLine()) != null)
                {
                    lineCount++;
                }
                Console.WriteLine("Number of lines: " + lineCount);
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine("Error reading input file: " + ex.Message);
            return;
        }

        // Initialize configuration settings from XML
        try
        {
            tileSize = int.Parse(config.SelectSingleNode("/config/tileSize").InnerText);
            worldWidth = int.Parse(config.SelectSingleNode("/config/worldWidth").InnerText);
            worldHeight = int.Parse(config.SelectSingleNode("/config/worldHeight").InnerText);
