            return;
        }

        Console.WriteLine($"Tile Size: {tileSize}, World Width: {worldWidth}, World Height: {worldHeight}, Camera Speed: {cameraSpeed}");
    }

    static void PrintUsage()
    {
        Console.WriteLine("Usage: program.exe [options] [input_file]");
        Console.WriteLine("--manpage: Display man page");
        Console.WriteLine("-cs <tile_size>: Set tile size (default 32)");
