#include <string.h>
#include <pthread.h>

typedef struct {
    int RNTI;
    bool CRCFLAG;
} RX_UE_INFORMATION_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_info;
    // Other fields
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicList;

void init_list(DynamicList *list) {
    list->entries = NULL;
    list->size = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void free_list(DynamicList *list) {
    for (size_t i = 0; i < list->size; i++) {
        // Free any dynamically allocated memory within each entry
    }
    free(list->entries);
    pthread_mutex_destroy(&list->lock);
}

bool add_entry(DynamicList *list, const NFAPI_CRC_INDICATION_PDU_T *new_entry) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) {
        size_t new_capacity = (list->capacity == 0) ? 1 : list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_entries = realloc(list->entries, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_entries) {
            pthread_mutex_unlock(&list->lock);
            return false;
        }
        list->entries = new_entries;
        list->capacity = new_capacity;
    }
    memcpy(&list->entries[list->size++], new_entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_unlock(&list->lock);
    return true;
}

bool update_entry(DynamicList *list, int RNTI, const NFAPI_CRC_INDICATION_PDU_T *new_entry) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; i++) {
        if (list->entries[i].rx_ue_info.RNTI == RNTI) {
            memcpy(&list->entries[i], new_entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_mutex_unlock(&list->lock);
            return true;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return false;
}

bool remove_entry(DynamicList *list, int RNTI) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; i++) {
        if (list->entries[i].rx_ue_info.RNTI == RNTI) {
            memmove(&list->entries[i], &list->entries[i + 1], (list->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            list->size--;
            pthread_mutex_unlock(&list->lock);
            return true;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return false;
}

size_t count_entries_with_crc_flag(DynamicList *list) {
    size_t count = 0;
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; i++) {
        if (list->entries[i].rx_ue_info.CRCFLAG) {
            count++;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return count;
}

int main() {
    DynamicList list;
    init_list(&list);

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T entry1 = {{1234, true}, { /* Other fields */ }};
    add_entry(&list, &entry1);

    NFAPI_CRC_INDICATION_PDU_T updated_entry = {{1234, false}, { /* Other fields */ }};
    update_entry(&list, 1234, &updated_entry);

    remove_entry(&list, 1234);

    size_t crc_flag_count = count_entries_with_crc_flag(&list);

    free_list(&list);
    return 0;
}
