#include <stdlib.h>
#include <string.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode* next;
} ListNode;

typedef struct {
    ListNode* head;
    size_t count;
} DynamicList;

DynamicList* createDynamicList() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (list) {
        list->head = NULL;
        list->count = 0;
    }
    return list;
}

void destroyDynamicList(DynamicList* list) {
    ListNode* current = list->head;
    while (current) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

ListNode** findEntryByRNTI(DynamicList* list, RNTI rnti, size_t* index) {
    ListNode** nodePtr = &list->head;
    *index = 0;
    while (*nodePtr && (*nodePtr)->data.rnti != rnti) {
        nodePtr = &(*nodePtr)->next;
        (*index)++;
    }
    return nodePtr;
}

void addOrUpdateEntry(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T newEntry) {
    size_t index;
    ListNode** nodePtr = findEntryByRNTI(list, newEntry.rnti, &index);
    if (*nodePtr) {
        // Update existing entry
        (*nodePtr)->data = newEntry;
    } else {
        // Add new entry
        *nodePtr = (ListNode*)malloc(sizeof(ListNode));
        if (*nodePtr) {
            (*nodePtr)->data = newEntry;
            (*nodePtr)->next = list->head;
            list->head = *nodePtr;
            list->count++;
        }
    }
}

void removeEntry(DynamicList* list, RNTI rnti) {
    size_t index;
    ListNode** nodePtr = findEntryByRNTI(list, rnti, &index);
    if (*nodePtr) {
        ListNode* temp = *nodePtr;
        *nodePtr = temp->next;
        free(temp);
        list->count--;
    }
}

size_t getTotalEntries(DynamicList* list) {
    return list->count;
}

size_t getEntriesWithCRCFlagSet(DynamicList* list) {
    size_t count = 0;
    ListNode* current = list->head;
    while (current) {
        if (current->data.crc_indication_rel8_tag.CRCFLAG) {
            count++;
        }
        current = current->next;
    }
    return count;
}
