#include <time.h>

#define MAX_MEMORY_USAGE 1024 * 1024 // 1MB

typedef struct {
    uint32_t PCI;
    uint64_t TX_UE_INFORMATION_TAG;
    uint64_t NFAPI_L1_TAG;
    uint8_t CRCFLAG;
} TX_PACKET_METADATA;

TX_PACKET_METADATA* packet_list = NULL;
int list_size = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* memory_manager(void* arg) {
    while (1) {
        // Monitor system load and available resources
        // Adjust memory allocation based on load
    }
}

void* packet_generator(void* arg) {
    int N = *(int*)arg;
    srand(time(NULL));

    for (int i = 0; i < N; i++) {
        pthread_mutex_lock(&mutex);
        if (list_size >= MAX_MEMORY_USAGE / sizeof(TX_PACKET_METADATA)) {
            // Log memory allocation failure
            pthread_mutex_unlock(&mutex);
            break;
        }

        TX_PACKET_METADATA new_packet;
        new_packet.PCI = rand() % 1024; // Example: Random PCI value
        new_packet.TX_UE_INFORMATION_TAG = rand(); // Generate unique tag
        new_packet.NFAPI_L1_TAG = rand(); // Generate unique tag
        new_packet.CRCFLAG = (rand() % 2) == 0 ? 1 : 0; // Random CRC flag

        if (i > 0 && packet_list[i - 1].PCI == new_packet.PCI) {
            pthread_mutex_unlock(&mutex);
            i--; // Retry with different PCI
            continue;
        }

        int tag_exists = 0;
        for (int j = 0; j < list_size; j++) {
            if (packet_list[j].TX_UE_INFORMATION_TAG == new_packet.TX_UE_INFORMATION_TAG) {
                tag_exists = 1;
                break;
            }
        }

        if (!tag_exists) {
            packet_list[list_size++] = new_packet;
        } else {
            pthread_mutex_unlock(&mutex);
            i--; // Retry with different tag
            continue;
        }

        pthread_mutex_unlock(&mutex);

        // Simulate time taken for element creation
        usleep(1000); // 1ms
    }
}

int main() {
    int N = 100; // Example: Populate 100 elements

    packet_list = (TX_PACKET_METADATA*)malloc(MAX_MEMORY_USAGE);
    if (!packet_list) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    pthread_t mem_manager_thread, packet_gen_thread;
    pthread_create(&mem_manager_thread, NULL, memory_manager, NULL);
    pthread_create(&packet_gen_thread, NULL, packet_generator, &N);

    pthread_join(packet_gen_thread, NULL);
    free(packet_list);

    return 0;
}
