    pthread_mutex_t lock;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_entry(Entry* entry) {
    if (entry) {
        free(entry);
    }
}

void clear_list(List* list) {
