    Entry* current = list->head;
    while (current) {
        Entry* next = current->next;
        free_entry(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
}

bool add_entry(List* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);
    Entry* current = list->head;
    while (current) {
        if (current->pdu.RNTI == pdu.RNTI) {
            pthread_mutex_unlock(&list->lock);
            return false; // Duplicate RNTI
        }
        current = current->next;
    }

    Entry* new_entry = (Entry*)malloc(sizeof(Entry));
    if (!new_entry) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }
    new_entry->pdu = pdu;
    new_entry->next = list->head;
    list->head = new_entry;
    pthread_mutex_unlock(&list->lock);
    return true;
}

bool update_entry(List* list, int RNTI, NFAPI_CRC_INDICATION_PDU_T new_pdu) {
    pthread_mutex_lock(&list->lock);
    Entry* current = list->head;
    while (current) {
        if (current->pdu.RNTI == RNTI) {
            current->pdu = new_pdu;
            pthread_mutex_unlock(&list->lock);
            return true;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return false;
}

bool remove_entry(List* list, int RNTI) {
    pthread_mutex_lock(&list->lock);
    Entry* current = list->head;
    Entry* prev = NULL;
    while (current) {
        if (current->pdu.RNTI == RNTI) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            free_entry(current);
            pthread_mutex_unlock(&list->lock);
            return true;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return false;
}

int get_total_entries(List* list) {
    pthread_mutex_lock(&list->lock);
    int count = 0;
    Entry* current = list->head;
    while (current) {
        count++;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return count;
}

int get_crcflag_true_count(List* list) {
    pthread_mutex_lock(&list->lock);
    int count = 0;
    Entry* current = list->head;
    while (current) {
        if (current->pdu.CRCFLAG) {
            count++;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return count;
}

void destroy_list(List* list) {
    clear_list(list);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
