<?php
class BlogPostManager {
    private $db;

    public function __construct($db) {
        $this->db = $db;
    }

    public function manageBlogPosts($_POST) {
        $action = $_POST['action'] ?? '';
        switch ($action) {
            case 'fetch':
                return $this->fetchPost($_POST);
            case 'create':
                return $this->createPost($_POST);
            case 'update':
                return $this->updatePost($_POST);
            case 'delete':
                return $this->deletePost($_POST);
            default:
                return json_encode(['error' => 'invalid_request']);
        }
    }

    private function fetchPost($_POST) {
        $id = $_POST['id'] ?? '';
        if (empty($id)) return json_encode(['error' => 'invalid_request']);

        // Query the database for the post
        $stmt = $this->db->prepare('SELECT * FROM blog_posts WHERE id = ?');
        $stmt->execute([$id]);
        $post = $stmt->fetch(PDO::FETCH_ASSOC);

        if ($post) {
            return json_encode($post);
        } else {
            return json_encode(['error' => 'Post not found']);
        }
    }

    private function createPost($_POST) {
        // Validate input
        $title = $_POST['title'] ?? '';
        $content = $_POST['content'] ?? '';
        $tags = $_POST['tags'] ?? '';
        $category = $_POST['category'] ?? '';

        if (strlen($title) < 10 || strlen($title) > 255 ||
            strlen($content) < 50 ||
            count(explode(',', $tags)) > 5 ||
            !in_array($category, ['technology', 'lifestyle', 'travel'])) {
            return json_encode(['error' => 'invalid_request']);
        }

        // Prepare and execute the query
        $stmt = $this->db->prepare('INSERT INTO blog_posts (title, content, tags, category, created_at) VALUES (?, ?, ?, ?, NOW())');
        $stmt->execute([$title, $content, $tags, $category]);

        return json_encode(['message' => 'Post created successfully']);
    }

    private function updatePost($_POST) {
        // Validate input
        $id = $_POST['id'] ?? '';
        $title = $_POST['title'] ?? '';
        $content = $_POST['content'] ?? '';
        $tags = $_POST['tags'] ?? '';
        $category = $_POST['category'] ?? '';

        if (empty($id) || strlen($title) < 10 || strlen($title) > 255 ||
            strlen($content) < 50 ||
            count(explode(',', $tags)) > 5 ||
            !in_array($category, ['technology', 'lifestyle', 'travel'])) {
            return json_encode(['error' => 'invalid_request']);
        }

        // Check if the post exists
        $stmt = $this->db->prepare('SELECT * FROM blog_posts WHERE id = ?');
        $stmt->execute([$id]);
        $post = $stmt->fetch(PDO::FETCH_ASSOC);

        if (!$post) {
            return json_encode(['error' => 'Post not found']);
        }

        // Prepare and execute the update query
        $stmt = $this->db->prepare('UPDATE blog_posts SET title = ?, content = ?, tags = ?, category = ?, updated_at = NOW() WHERE id = ?');
        $stmt->execute([$title, $content, $tags, $category, $id]);

        return json_encode(['message' => 'Post updated successfully']);
    }

    private function deletePost($_POST) {
        $id = $_POST['id'] ?? '';

        if (empty($id)) return json_encode(['error' => 'invalid_request']);

        // Check if the post exists
        $stmt = $this->db->prepare('SELECT * FROM blog_posts WHERE id = ?');
        $stmt->execute([$id]);
        $post = $stmt->fetch(PDO::FETCH_ASSOC);

        if (!$post) {
            return json_encode(['error' => 'Post not found']);
        }

        // Prepare and execute the delete query
        $stmt = $this->db->prepare('DELETE FROM blog_posts WHERE id = ?');
        $stmt->execute([$id]);

        return json_encode(['message' => 'Post deleted successfully']);
    }
}
?>
