#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int frequency;
    int bandwidth;
} EXTENDED_CARRIER_INFO_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned short RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    EXTENDED_CARRIER_INFO_TAG carrier_info;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T* head;
    int total_entries;
    int crc_flag_true_count;
    int frequency_utilization;
    int bandwidth_utilization;
} CRC_LIST_MGR_T;

void init_crc_list_manager(CRC_LIST_MGR_T* manager) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->head = NULL;
    manager->total_entries = 0;
    manager->crc_flag_true_count = 0;
    manager->frequency_utilization = 0;
    manager->bandwidth_utilization = 0;
}

void add_entry(CRC_LIST_MGR_T* manager, NFAPI_CRC_INDICATION_PDU_T* new_entry) {
    pthread_mutex_lock(&manager->lock);
    if (new_entry == NULL) {
        return;
    }

    // Check for duplicate RNTI
    NFAPI_CRC_INDICATION_PDU_T* current = manager->head;
    while (current != NULL) {
        if (current->RNTI == new_entry->RNTI) {
            pthread_mutex_unlock(&manager->lock);
            return; // Duplicate RNTI, do not add
        }
        current = current->next;
    }

    new_entry->next = manager->head;
    manager->head = new_entry;
    manager->total_entries++;

    if (new_entry->CRC_INDICATION_REL8_TAG) {
        manager->crc_flag_true_count++;
    }
    manager->frequency_utilization += new_entry->carrier_info.frequency;
    manager->bandwidth_utilization += new_entry->carrier_info.bandwidth;

    pthread_mutex_unlock(&manager->lock);
}

// Implement update_entry, remove_entry, and other functions similarly

void destroy_crc_list_manager(CRC_LIST_MGR_T* manager) {
    pthread_mutex_lock(&manager->lock);
    NFAPI_CRC_INDICATION_PDU_T* current = manager->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
    manager->head = NULL;
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}
