#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct NetworkConfig {
    char deviceName[50];
    char ipAddress[16];
    char subnetMask[16];
    char gateway[16];
    char *securityKey;
    int timeout;
} NetworkConfig;

typedef struct ConfigList {
    NetworkConfig *config;
    struct ConfigList *next;
} ConfigList;

ConfigList *head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void addNetworkConfig(const char *deviceName, const char *ipAddress, const char *subnetMask, 
                      const char *gateway, const char *securityKey, int timeout) {
    pthread_mutex_lock(&mutex);
    ConfigList *newNode = (ConfigList *)malloc(sizeof(ConfigList));
    newNode->config = (NetworkConfig *)malloc(sizeof(NetworkConfig));

    strcpy(newNode->config->deviceName, deviceName);
    strcpy(newNode->config->ipAddress, ipAddress);
    strcpy(newNode->config->subnetMask, subnetMask);
    strcpy(newNode->config->gateway, gateway);
    if (securityKey != NULL) {
        newNode->config->securityKey = strdup(securityKey);
    } else {
        newNode->config->securityKey = NULL;
    }
    newNode->config->timeout = timeout;

    newNode->next = head;
    head = newNode;
    pthread_mutex_unlock(&mutex);
}

void removeNetworkConfig(const char *deviceName) {
    pthread_mutex_lock(&mutex);
    ConfigList *current = head, *prev = NULL;

    while (current != NULL && strcmp(current->config->deviceName, deviceName) != 0) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&mutex);
        return;
    }

    if (prev == NULL) {
        head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current->config->securityKey);
    free(current->config);
    free(current);
    pthread_mutex_unlock(&mutex);
}

void updateNetworkConfig(const char *deviceName, const char *ipAddress, const char *subnetMask, 
                         const char *gateway, const char *securityKey, int timeout) {
    removeNetworkConfig(deviceName);
    addNetworkConfig(deviceName, ipAddress, subnetMask, gateway, securityKey, timeout);
}
