#define MAX_DEVICES 500

typedef struct {
    char device_name[256];
    char ip_address[16];
    char subnet_mask[16];
    char gateway[16];
} NetworkConfig;

NetworkConfig network_configs[MAX_DEVICES];
int config_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void add_network_config(const char *device_name, const char *ip_address, const char *subnet_mask, const char *gateway) {
    pthread_mutex_lock(&mutex);
    if (config_count < MAX_DEVICES) {
        strcpy(network_configs[config_count].device_name, device_name);
        strcpy(network_configs[config_count].ip_address, ip_address);
        strcpy(network_configs[config_count].subnet_mask, subnet_mask);
        strcpy(network_configs[config_count].gateway, gateway);
        config_count++;
    }
    pthread_mutex_unlock(&mutex);
}

void remove_network_config(const char *device_name) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < config_count; i++) {
        if (strcmp(network_configs[i].device_name, device_name) == 0) {
            memmove(&network_configs[i], &network_configs[i + 1], sizeof(NetworkConfig) * (config_count - i - 1));
            config_count--;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void update_network_config(const char *device_name, const char *ip_address, const char *subnet_mask, const char *gateway) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < config_count; i++) {
        if (strcmp(network_configs[i].device_name, device_name) == 0) {
            strcpy(network_configs[i].ip_address, ip_address);
            strcpy(network_configs[i].subnet_mask, subnet_mask);
            strcpy(network_configs[i].gateway, gateway);
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

// Additional functions for decryption, error handling, and other features can be implemented here.
