```java
import java.io.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import software.amazon.awssdk.regions.Region;
import software.amazon.awssdk.services.s3.S3Client;
import software.amazon.awssdk.services.s3.model.*;

public class NetworkConfigManager {

    public static Map<String, byte[]> processFiles(List<String> filePaths) {
        ExecutorService executor = Executors.newFixedThreadPool(10);
        Map<String, byte[]> fileMetadataMap = new HashMap<>();

        for (String filePath : filePaths) {
            executor.submit(() -> {
                try {
                    Path path = Paths.get(filePath);
                    File file = path.toFile();
                    if (file.exists() && !file.isDirectory()) {
                        FileChannel channel = FileChannel.open(path, StandardOpenOption.READ);
                        ByteBuffer buffer = channel.map(FileChannel.MapMode.READ_ONLY, 0, channel.size());
                        byte[] data = new byte[buffer.remaining()];
                        buffer.get(data);
                        channel.close();

                        byte[] metadata = calculateMetadata(data);
                        fileMetadataMap.put(filePath, metadata);

                        updateS3BucketPolicy(metadata, filePath);
                    } else {
                        throw new IOException("File does not exist or is a directory: " + filePath);
                    }
                } catch (IOException e) {
                    throw new RuntimeException("Error processing file: " + filePath, e);
                }
            });
        }

        executor.shutdown();
        return fileMetadataMap;
    }

    private static byte[] calculateMetadata(byte[] data) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            digest.update(data);
            return digest.digest();
        } catch (Exception e) {
            throw new RuntimeException("Error calculating metadata", e);
        }
    }

    private static void updateS3BucketPolicy(byte[] metadata, String filePath) {
        Region region = Region.US_EAST_1;
        S3Client s3 = S3Client.builder().region(region).build();

        GetObjectRequest getObjectRequest = GetObjectRequest.builder()
                .bucket("my-bucket")
                .key(filePath)
                .build();
        GetObjectResponse response = s3.getObject(getObjectRequest);
        String bucketPolicyJson = response.responseMetadata().httpStatusCode() == 200 ? "{\"Version\":\"2012-10-17\",\"Statement\":[{\"Effect\":\"Allow\",\"Action\":[\"s3:GetObject\"],\"Resource\":\"arn:aws:s3:::my-bucket/" + filePath + "\"}]}": "{}";

        PutBucketPolicyRequest putBucketPolicyRequest = PutBucketPolicyRequest.builder()
