CustomProtocolPacket* generate_custom_protocol_packets(int num_packets, const char* data_format, size_t max_payload_size) {
    if (num_packets <= 0 || max_payload_size > MAX_PAYLOAD_SIZE) {
        return NULL;
    }

    CustomProtocolPacket* packets = malloc(num_packets * sizeof(CustomProtocolPacket));
    if (!packets) {
        return NULL;
    }

    for (int i = 0; i < num_packets; ++i) {
        // Generate unique protocol identifier
        snprintf(packets[i].protocol_id, sizeof(packets[i].protocol_id), "PROTO_%d", i);

        // Set timestamp
        packets[i].timestamp = time(NULL);

        // Generate payload based on data format
        if (strcmp(data_format, "hex") == 0) {
            for (size_t j = 0; j < max_payload_size; ++j) {
                unsigned char byte;
                if (!RAND_bytes(&byte, sizeof(byte))) {
                    free(packets);
                    return NULL;
                }
                snprintf(packets[i].payload + j * 2, 3, "%02x", byte);
            }
        } else if (strcmp(data_format, "ascii") == 0) {
            for (size_t j = 0; j < max_payload_size; ++j) {
                packets[i].payload[j] = 'a' + rand() % 26;
            }
        } else {
            free(packets);
            return NULL;
        }

        // Ensure no two packets have the same payload
        for (int j = 0; j < i; ++j) {
            if (strcmp(packets[i].payload, packets[j].payload) == 0) {
                free(packets);
                return NULL;
            }
        }

        // Ensure payload adheres to predefined constraints
        if (strlen(packets[i].payload) > max_payload_size) {
            free(packets);
            return NULL;
        }
    }

    return packets;
}

