#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/evp.h>

#define MAX_DEVICES 1000

typedef struct {
    char device_name[50];
    char ip_address[40];
    char subnet_mask[40];
    char gateway[40];
    char *security_key;
    int timeout;
} NetworkConfig;

typedef struct {
    NetworkConfig configs[MAX_DEVICES];
    int count;
    pthread_mutex_t lock;
} NetworkManager;

void initialize_manager(NetworkManager *manager) {
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

int add_config(NetworkManager *manager, const char *device_name, const char *ip_address,
               const char *subnet_mask, const char *gateway, const char *security_key, int timeout) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= MAX_DEVICES) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }
    strcpy(manager->configs[manager->count].device_name, device_name);
    strcpy(manager->configs[manager->count].ip_address, ip_address);
    strcpy(manager->configs[manager->count].subnet_mask, subnet_mask);
    strcpy(manager->configs[manager->count].gateway, gateway);
    manager->configs[manager->count].security_key = strdup(security_key);
    manager->configs[manager->count].timeout = timeout;
    manager->count++;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int remove_config(NetworkManager *manager, const char *device_name) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        if (strcmp(manager->configs[i].device_name, device_name) == 0) {
            free((char *)manager->configs[i].security_key);
            memmove(&manager->configs[i], &manager->configs[i + 1], sizeof(NetworkConfig) * (manager->count - i - 1));
            manager->count--;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1;
}

int update_config(NetworkManager *manager, const char *device_name, const char *ip_address,
                 const char *subnet_mask, const char *gateway, const char *security_key, int timeout) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        if (strcmp(manager->configs[i].device_name, device_name) == 0) {
            free((char *)manager->configs[i].security_key);
            strcpy(manager->configs[i].ip_address, ip_address);
            strcpy(manager->configs[i].subnet_mask, subnet_mask);
            strcpy(manager->configs[i].gateway, gateway);
            manager->configs[i].security_key = strdup(security_key);
            manager->configs[i].timeout = timeout;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1;
}

void destroy_manager(NetworkManager *manager) {
    for (int i = 0; i < manager->count; i++) {
        free((char *)manager->configs[i].security_key);
    }
    pthread_mutex_destroy(&manager->lock);
}
