typedef struct {
    int id;
    char ip[16];
    int port;
} TCPConnection;

TCPConnection* initTCPConnections(const char* config_file, int *num_connections) {
    FILE *file = fopen(config_file, "r");
    if (!file) {
        perror("Failed to open configuration file");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    int max_connections = file_size / sizeof(TCPConnection); // Simplified estimation
    TCPConnection *connections = malloc(max_connections * sizeof(TCPConnection));
    if (!connections) {
        perror("Memory allocation failed");
        fclose(file);
        return NULL;
    }

    char buffer[1024];
    int actual_connections = 0;
    while (fgets(buffer, sizeof(buffer), file)) {
        TCPConnection conn;
        sscanf(buffer, "%d %15s %d", &conn.id, conn.ip, &conn.port);

        // Avoid duplicate entries
        int duplicate = 0;
        for (int i = 0; i < actual_connections; ++i) {
            if (connections[i].id == conn.id && strcmp(connections[i].ip, conn.ip) == 0 && connections[i].port == conn.port) {
                duplicate = 1;
                break;
            }
        }

        if (!duplicate) {
            connections[actual_connections++] = conn;
        }
    }

    fclose(file);
    *num_connections = actual_connections;
    return realloc(connections, actual_connections * sizeof(TCPConnection));
}
