    for (size_t i = 0; i < array_size; ++i) {
        if (array[i]->id == session_id) {
            array[i]->last_active = time(NULL);
            return;
        }
    }
    printf("Session ID not found: %d\n", session_id);
}

void free_session_array(UserSession** array, size_t array_size) {
    for (size_t i = 0; i < array_size; ++i) {
        for (int j = 0; j < MAX_PERMISSIONS && array[i]->permissions[j]; ++j) {
            free(array[i]->permissions[j]);
        }
        free(array[i]);
    }
    free(array);
}
