#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int sessionId;
    char username[50];
    time_t lastActive;
    // Add other permissions and metadata fields here
} Session;

typedef struct {
    Session *sessions;
    size_t count;
    pthread_mutex_t lock;
} SessionManager;

void initSessionManager(SessionManager *manager) {
    manager->sessions = NULL;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

int addOrUpdateSession(SessionManager *manager, int sessionId, const char *username, time_t lastActive, ...) {
    pthread_mutex_lock(&manager->lock);

    // Check for duplicate session ID
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i].sessionId == sessionId) {
            // Update existing session
            strcpy(manager->sessions[i].username, username);
            manager->sessions[i].lastActive = lastActive;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    // Add new session
    Session *newSessions = realloc(manager->sessions, (manager->count + 1) * sizeof(Session));
    if (!newSessions) {
        pthread_mutex_unlock(&manager->lock);
        perror("Failed to allocate memory for sessions");
        return -1;
    }
    manager->sessions = newSessions;

    manager->sessions[manager->count].sessionId = sessionId;
    strcpy(manager->sessions[manager->count].username, username);
    manager->sessions[manager->count].lastActive = lastActive;
    // Initialize other permissions and metadata fields here

    manager->count++;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void deleteSession(SessionManager *manager, int sessionId) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i].sessionId == sessionId) {
            // Shift elements to remove the session
            memmove(&manager->sessions[i], &manager->sessions[i + 1], (manager->count - i - 1) * sizeof(Session));
            manager->count--;
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void logSessionChange(SessionManager *manager, int sessionId, const char *action) {
    // Implement logging mechanism here
    printf("Action: %s, Session ID: %d\n", action, sessionId);
}

// Example usage
int main() {
    SessionManager manager;
    initSessionManager(&manager);

    addOrUpdateSession(&manager, 1, "user1", time(NULL));
    deleteSession(&manager, 1);

    logSessionChange(&manager, 1, "Deleted");

    return 0;
}
