#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_SESSIONS 10000

typedef struct {
    int sessionId;
    char username[50];
    time_t lastActive;
    time_t expirationTime;
} SessionMetadata;

SessionMetadata *sessions[MAX_SESSIONS] = {NULL};
int sessionCount = 0;

void freeSessions() {
    for (int i = 0; i < sessionCount; i++) {
        if (sessions[i]) {
            free(sessions[i]);
        }
    }
}

int loadSessions(const char *configFile) {
    FILE *file = fopen(configFile, "r");
    if (!file) {
        perror("Error opening file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        SessionMetadata *newSession = (SessionMetadata *)malloc(sizeof(SessionMetadata));
        if (!newSession) {
            fclose(file);
            freeSessions();
            perror("Error allocating memory");
            return -1;
        }

        if (sscanf(line, "%d %s %ld %ld", &newSession->sessionId, newSession->username, &newSession->lastActive, &newSession->expirationTime) != 4) {
            free(newSession);
            continue;
        }

        for (int i = 0; i < sessionCount; i++) {
            if (sessions[i]->sessionId == newSession->sessionId) {
                free(newSession);
                break;
            }
        }

        sessions[sessionCount++] = newSession;
    }

    fclose(file);
    return 0;
}

void expireSessions() {
    time_t now = time(NULL);
    for (int i = sessionCount - 1; i >= 0; i--) {
        if (sessions[i]->expirationTime < now) {
            free(sessions[i]);
            sessions[i] = sessions[--sessionCount];
        }
    }
}

void cleanup() {
    freeSessions();
}
