["```javascript
const { spawn } = require('child_process');
const axios = require('axios');
const queue = require('async').queue;
const winston = require('winston');

// Configure logger
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'app.log' })
  ]
});

const taskQueue = queue(async (task, callback) => {
  try {
    const { command, args } = task;
    const child = spawn(command, args);

    let progressInterval;

    child.stdout.on('data', (data) => {
      logger.info(`stdout: ${data}`);
    });

    child.stderr.on('data', (data) => {
      logger.error(`stderr: ${data}`);
    });

    child.on('close', (code) => {
      logger.info(`child process exited with code ${code}`);
      clearInterval(progressInterval);
      callback();
    });

    progressInterval = setInterval(async () => {
      try {
        const response = await axios.get('https://api.example.com/task_status');
        if (response.data.progress === 100) {
          clearInterval(progressInterval);
        }
        logger.info(`Task progress: ${response.data.progress}%`);
      } catch (error) {
        logger.error('Error checking task status:', error.message);
      }
    }, 1000);

    child.on('error', (error) => {
      logger.error('Child process error:', error);
      clearInterval(progressInterval);
      callback(error);
    });

    // Set timeout for the task to complete within 10 seconds
    const timeout = setTimeout(() => {
      logger.error('Task timed out. Terminating...');
      child.kill();
      callback(new Error('Task timed out'));
    }, 10000);

    child.on('exit', (code) => {
      clearTimeout(timeout);
    });
  } catch (error) {
    logger.error('Error executing task:', error.message);
    callback(error);
  }
}, 5); // Limit to 5 concurrent tasks

function executeTask(command, args) {
  return new Promise((resolve, reject) => {
    taskQueue.push({ command, args }, (error) => {
      if (error) {
        logger.error('Failed to execute task:', error.message);
        reject(error);
      } else {
        resolve();
      }
    });
  });
}

module.exports = { executeTask };
```

This code block defines a JavaScript function `executeTask` that asynchronously executes a background task using the `child_process` module and returns a progress update every second until the task completes. It handles potential errors gracefully, ensures that the process is terminated cleanly upon completion or error, integrates with an external API service to check task status, manages resource usage effectively, logs for debugging purposes, and can be easily integrated into an existing system architecture without disrupting ongoing operations."]

