#include <iostream>
#include <queue>
#include <vector>
#include <mutex>
#include <condition_variable>

struct AssetInfo {
    std::string id;
    int priority;
    bool critical;
};

class AssetManager {
private:
    std::priority_queue<AssetInfo, std::vector<AssetInfo>, 
                        [](const AssetInfo& a, const AssetInfo& b) {
                            return a.priority > b.priority || (a.priority == b.priority && !a.critical);
                        }> priorityQueue;
    std::mutex queueMutex;
    std::condition_variable cv;
    bool isBandwidthSavingMode;
    int consecutiveLoadCount;

public:
    AssetManager() : isBandwidthSavingMode(false), consecutiveLoadCount(0) {}

    void loadAssets() {
        std::unique_lock<std::mutex> lock(queueMutex);
        while (!priorityQueue.empty()) {
            if (isBandwidthSavingMode) {
                cv.wait(lock, [this] { return !isBandwidthSavingMode; });
            }
            AssetInfo asset = priorityQueue.top();
            priorityQueue.pop();
            // Simulate loading and rendering
            std::cout << "Loading asset: " << asset.id << std::endl;
            std::this_thread::sleep_for(std::chrono::seconds(1));
            consecutiveLoadCount++;
            if (consecutiveLoadCount % 5 == 0) {
                cv.notify_all();
            }
        }
    }

    void addAsset(const AssetInfo& asset) {
        std::lock_guard<std::mutex> lock(queueMutex);
        priorityQueue.push(asset);
    }

    void setBandwidthSavingMode(bool mode) {
        isBandwidthSavingMode = mode;
    }

    void optimizeLoadingSequence() {
        // Fetch optimized loading sequence from server
        std::vector<AssetInfo> optimizedSequence = fetchOptimizedSequenceFromServer();
        for (const auto& asset : optimizedSequence) {
            addAsset(asset);
        }
        loadAssets();
    }

private:
    std::vector<AssetInfo> fetchOptimizedSequenceFromServer() {
        // Simulate fetching from server
        return {{"asset1", 3, true}, {"asset2", 2, false}, {"asset3", 4, true}};
    }
};

int main() {
    AssetManager manager;
    manager.optimizeLoadingSequence();
    return 0;
}
