#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Metric {
    double value;
    char description[256];
} Metric;

int processLog(const char* input_file, const char* output_file, double threshold, int format) {
    FILE *in = fopen(input_file, "r");
    if (!in) {
        perror("Failed to open input file");
        return 1;
    }

    FILE *out = fopen(output_file, "w");
    if (!out) {
        perror("Failed to open output file");
        fclose(in);
        return 1;
    }

    Metric *metrics = NULL;
    size_t count = 0;

    char line[256];
    while (fgets(line, sizeof(line), in)) {
        Metric m;
        if (sscanf(line, "%lf %s", &m.value, m.description) == 2) {
            if (m.value >= threshold) {
                metrics = realloc(metrics, (count + 1) * sizeof(Metric));
                metrics[count++] = m;
            }
        }
    }

    fclose(in);

    for (size_t i = 0; i < count; i++) {
        switch (format) {
            case 0:
                fprintf(out, "%.2f %s\n", metrics[i].value, metrics[i].description);
                break;
            case 1:
                fprintf(out, "Value: %.2f, Description: %s\n", metrics[i].value, metrics[i].description);
                break;
            default:
                fprintf(stderr, "Unknown format specifier\n");
                free(metrics);
                fclose(out);
                return 1;
        }
    }

    free(metrics);
    fclose(out);

    return 0;
}
