std::mutex mtx;
int lastAttack = 0;
std::chrono::time_point<std::chrono::system_clock> nextAttackTime;

void selectAndCooldownAttack() {
    std::lock_guard<std::mutex> lock(mtx);

    if (std::chrono::system_clock::now() < nextAttackTime) {
        // Cooldown period not yet over, wait and retry
        return;
    }

    static std::random_device rd;
    static std::mt19937 gen(rd());
    static std::uniform_int_distribution<> dis(1, 3);

    int newAttack;
    do {
        newAttack = dis(gen);
    } while (newAttack == lastAttack); // Avoid consecutive same attacks

    lastAttack = newAttack;

    nextAttackTime = std::chrono::system_clock::now() + std::chrono::seconds(9);
    std::time_t now = std::chrono::system_clock::to_time_t(nextAttackTime);
    std::cout << "Selected attack: " << newAttack << " at " << std::ctime(&now) << std::endl;
}

int main() {
    for (int i = 0; i < 10; ++i) {
        selectAndCooldownAttack();
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
    }
    return 0;
}
