#define MAX_ENTRIES 50000

typedef struct {
    uint16_t RNTI;
    bool CRCFLAG;
    // other fields...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T entries[MAX_ENTRIES];
    int count;
    pthread_mutex_t lock;
} DynamicList;

void initDynamicList(DynamicList *list) {
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

bool addEntry(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->count; i++) {
        if (list->entries[i].RNTI == entry.RNTI) {
            // Duplicate RNTI found, update existing entry
            list->entries[i] = entry;
            pthread_mutex_unlock(&list->lock);
            return true;
        }
    }
    if (list->count < MAX_ENTRIES) {
        list->entries[list->count++] = entry;
        pthread_mutex_unlock(&list->lock);
        return true;
    }
    pthread_mutex_unlock(&list->lock);
    return false; // List is full
}

bool removeEntry(DynamicList *list, uint16_t RNTI) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->count; i++) {
        if (list->entries[i].RNTI == RNTI) {
            for (int j = i; j < list->count - 1; j++) {
                list->entries[j] = list->entries[j + 1];
            }
            list->count--;
            pthread_mutex_unlock(&list->lock);
            return true;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return false; // RNTI not found
}

int getTotalEntries(DynamicList *list) {
    pthread_mutex_lock(&list->lock);
    int total = list->count;
    pthread_mutex_unlock(&list->lock);
    return total;
}

int getEntriesWithCRCFlag(DynamicList *list) {
    pthread_mutex_lock(&list->lock);
    int count = 0;
    for (int i = 0; i < list->count; i++) {
        if (list->entries[i].CRCFLAG) {
            count++;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return count;
}

// Add other functions as needed
