public class RangeManager {
    private int minValue;
    private int maxValue;

    public RangeManager(int minValue, int maxValue) {
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public double getRandomFloat() {
        Random random = new Random();
        return minValue + (maxValue - minValue) * random.nextDouble();
    }

    public int getRandomInt() {
        Random random = new Random();
        return minValue + random.nextInt(maxValue - minValue + 1);
    }

    @Override
    public String toString() {
        return "RangeManager{" +
                "minValue=" + minValue +
                ", maxValue=" + maxValue +
                '}';
    }

    public void executeCommand(String command, File workingDir) {
        try {
            Process process = Runtime.getRuntime().exec(command, null, workingDir);
            process.waitFor();
            deleteDirectory(workingDir);
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }

    private void deleteDirectory(File dir) {
        if (dir.exists()) {
            File[] files = dir.listFiles();
            if (files != null) {
                for (File file : files) {
                    if (file.isDirectory()) {
                        deleteDirectory(file);
                    } else {
                        file.delete();
                    }
                }
            }
            dir.delete();
        }
    }

    public String updateResource(String url, String requestBody) {
        try {
            URL obj = new URL(url);
            HttpURLConnection con = (HttpURLConnection) obj.openConnection();
            con.setRequestMethod("PUT");
            con.setDoOutput(true);
            OutputStream os = con.getOutputStream();
            BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(os));
            writer.write(requestBody);
            writer.flush();
            writer.close();

            int responseCode = con.getResponseCode();
            return "POST Response Code :: " + responseCode;
        } catch (IOException e) {
            e.printStackTrace();
            return null;
        }
    }

    public String deleteResource(String url) {
        try {
            URL obj = new URL(url);
            HttpURLConnection con = (HttpURLConnection) obj.openConnection();
            con.setRequestMethod("DELETE");

            int responseCode = con.getResponseCode();
            return "POST Response Code :: " + responseCode;
        } catch (IOException e) {
            e.printStackTrace();
            return null;
        }
    }

    // Additional methods for concurrent execution, configuration management,
    // scheduling tasks, memory optimization, and cloud deployment can be added here.
}
