#define MAX_DEVICES 1000

typedef struct NetworkConfig {
    char device_name[64];
    char ip_address[16];
    char subnet_mask[16];
    char gateway[16];
    int timeout;
    pthread_mutex_t mutex;
} NetworkConfig;

NetworkConfig *network_configs[MAX_DEVICES] = {NULL};
int config_count = 0;

pthread_mutex_t global_mutex = PTHREAD_MUTEX_INITIALIZER;

void add_network_config(const char *device_name, const char *ip_address, 
                        const char *subnet_mask, const char *gateway, int timeout) {
    pthread_mutex_lock(&global_mutex);
    if (config_count < MAX_DEVICES) {
        NetworkConfig *new_config = malloc(sizeof(NetworkConfig));
        strcpy(new_config->device_name, device_name);
        strcpy(new_config->ip_address, ip_address);
        strcpy(new_config->subnet_mask, subnet_mask);
        strcpy(new_config->gateway, gateway);
        new_config->timeout = timeout;
        pthread_mutex_init(&new_config->mutex, NULL);
        network_configs[config_count++] = new_config;
    }
    pthread_mutex_unlock(&global_mutex);
}

void remove_network_config(const char *device_name) {
    pthread_mutex_lock(&global_mutex);
    for (int i = 0; i < config_count; i++) {
        if (strcmp(network_configs[i]->device_name, device_name) == 0) {
            pthread_mutex_destroy(&network_configs[i]->mutex);
            free(network_configs[i]);
            for (int j = i; j < config_count - 1; j++) {
                network_configs[j] = network_configs[j + 1];
            }
            config_count--;
            break;
        }
    }
    pthread_mutex_unlock(&global_mutex);
}

void update_network_config(const char *device_name, const char *ip_address, 
                          const char *subnet_mask, const char *gateway, int timeout) {
    pthread_mutex_lock(&global_mutex);
    for (int i = 0; i < config_count; i++) {
        if (strcmp(network_configs[i]->device_name, device_name) == 0) {
            pthread_mutex_t new_mutex;
            pthread_mutex_init(&new_mutex, NULL);
            free(network_configs[i]);
            network_configs[i] = malloc(sizeof(NetworkConfig));
            strcpy(network_configs[i]->device_name, device_name);
            strcpy(network_configs[i]->ip_address, ip_address);
            strcpy(network_configs[i]->subnet_mask, subnet_mask);
            strcpy(network_configs[i]->gateway, gateway);
            network_configs[i]->timeout = timeout;
            pthread_mutex_destroy(&new_mutex);
            break;
        }
    }
    pthread_mutex_unlock(&global_mutex);
}
