```python
import os
import hashlib
import logging
from concurrent.futures import ThreadPoolExecutor, as_completed
from time import time

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

def file_hash(path):
    """Calculate MD5 hash of a file."""
    hasher = hashlib.md5()
    with open(path, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b''):
            hasher.update(chunk)
    return hasher.hexdigest()

def process_files(directory):
    """Process files and generate MD5 hash dictionary."""

    def process_file(file_path):
        try:
            if os.path.isfile(file_path) and not file_path.endswith('.lnk'):  # Skip symlinks
                md5_hash = file_hash(file_path)
                return {file_path: md5_hash}
            else:
                logger.info(f'Skipping non-regular file or symlink: {file_path}')
        except Exception as e:
            logger.error(f'Error processing file {file_path}: {e}')
            return {}

    start_time = time()
    results = {}
    with ThreadPoolExecutor(max_workers=10) as executor:
        futures = {executor.submit(process_file, os.path.join(directory, f)): f for f in os.listdir(directory)}
        for future in as_completed(futures):
            file_path = futures[future]
            try:
                results.update(future.result())
            except Exception as e:
                logger.error(f'Error processing file: {e}')
    end_time = time()

    logger.info(f'File processing completed. Total files processed: {len(results)}. Time taken: {end_time - start_time} seconds.')
    return results
