u_char* resolveHostnameDNS(const char* hostname, size_t& ipAddressSize) {
    struct addrinfo hints, *res, *p;
    int status;
    u_char* ipAddress = new u_char[16]; // IPv6 address size

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_INET6; // Use IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        logError(gai_strerror(status));
        return nullptr;
    }

    for (p = res;p != NULL; p = p->ai_next) {
        struct sockaddr_in6* h = (struct sockaddr_in6 *) p->ai_addr;
        std::memcpy(ipAddress, &h->sin6_addr.s6_addr, 16);
        ipAddressSize = 16;
        break;
    }

    freeaddrinfo(res); // free the linked list
    return ipAddress;
}

void rateLimit() {
    static size_t requestCount = 0;
    static std::chrono::steady_clock::time_point lastResetTime = std::chrono::steady_clock::now();

    auto now = std::chrono::steady_clock::now();
    if (std::chrono::duration_cast<std::chrono::seconds>(now - lastResetTime).count() >= 60) {
        requestCount = 0;
        lastResetTime = now;
    }

    if (++requestCount > 10) { // Limit to 10 requests per minute
        logWarning("Rate limit exceeded");
        throw std::runtime_error("Too many requests");
    }
}

void monitorSystemResources() {
    // Simulate monitoring system resources
    size_t memoryUsage = getMemoryUsage();
    size_t cpuUsage = getCpuUsage();

