#include <stdio.h>
#include <stdlib.h>

// Define a structure for record
typedef struct Record {
    int value;
    struct Node* node;  // Pointer to corresponding linked list node
} Record;

// Define a structure for linked list node
typedef struct Node {
    Record data;
    struct Node* next;
} Node;

// Function to create a new record
Record* create_record(int value) {
    Record* rec = (Record*)malloc(sizeof(Record));
    if (rec == NULL) {
        fprintf(stderr, "Memory allocation failed for record\n");
        exit(EXIT_FAILURE);
    }
    rec->value = value;
    rec->node = NULL;  // Initialize node pointer to NULL
    return rec;
}

// Function to create a new linked list node
Node* create_node(Record data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (node == NULL) {
        fprintf(stderr, "Memory allocation failed for node\n");
        exit(EXIT_FAILURE);
    }
    node->data = data;
    node->next = NULL;  // Initialize next pointer to NULL
    return node;
}

// Function to insert a new record into the linked list and hash map
void insert_record(Record* records, int size, Record new_record, int** hash_map) {
    if (hash_map[new_record.value % size] != NULL) {
        printf("Duplicate value detected\n");
        free(new_record);
        return;
    }
    Node* node = create_node(new_record);
    node->next = records[new_record.value % size];
    records[new_record.value % size] = node;
    hash_map[new_record.value % size] = &(node->data);
}

// Function to delete a record from the linked list and hash map
void delete_record(Record* records, int size, int value, int** hash_map) {
    Node** current = &records[value % size];
    while (*current != NULL) {
        if ((*current)->data.value == value) {
            Node* temp = *current;
            *current = (*current)->next;
            free(temp);
            hash_map[value % size] = NULL;
            return;
        }
        current = &((*current)->next);
    }
    printf("Record not found\n");
}

// Function to serialize the linked list and hash map to a binary file
void serialize_to_file(Node* records, int size, const char* filename) {
    FILE* fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file for writing\n");
        return;
    }
    fwrite(records, sizeof(Node), size, fp);
    fclose(fp);
}

// Function to deserialize the linked list and hash map from a binary file
void deserialize_from_file(Record* records, int* size, const char* filename) {
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file for reading\n");
        return;
    }
    fread(records, sizeof(Node), *size, fp);
    fclose(fp);
}

// Function to clean up allocated memory
void cleanup(Record* records, Node* nodes, int size) {
    for (int i = 0; i < size; i++) {
        Node* current = records[i];
        while (current != NULL) {
            Node* temp = current;
            current = current->next;
            free(temp);
        }
    }
    free(records);
    free(nodes);
}
```

This code block provides a basic implementation of the required data structures and functions. It includes creating records and nodes, inserting and deleting records from a linked list, serializing and deserializing to/from a binary file, and cleaning up allocated memory. The hash map functionality is simplified for demonstration purposes and does not include resizing or handling collisions beyond basic existence checks.

The code is designed with basic error checking and assumes the existence of an existing application framework with specific performance constraints. For production use, you would need to integrate this into a larger system, handle more complex scenarios (like memory leaks), and optimize based on profiling data.']

