import java.io.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.*;
import java.util.concurrent.*;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import software.amazon.awssdk.services.s3.S3Client;
import software.amazon.awssdk.services.s3.model.*;

public class FileMetadataProcessor {
    private static final Logger logger = LogManager.getLogger(FileMetadataProcessor.class);
    private S3Client s3Client;

    public FileMetadataProcessor() {
        this.s3Client = S3Client.create();
    }

    public Map<String, String> processFiles(List<String> filePaths) {
        Map<String, String> metadataMap = new ConcurrentHashMap<>();
        ExecutorService executorService = Executors.newFixedThreadPool(10);

        for (String filePath : filePaths) {
            executorService.submit(() -> {
                try {
                    Path path = Paths.get(filePath);
                    BasicFileAttributes attrs = Files.readAttributes(path, BasicFileAttributes.class);
                    String md5Hash = calculateMD5(path);
                    String sha256Hash = calculateSHA256(path);

                    metadataMap.put(filePath, "{\"size\":" + attrs.size() + 
                        ",\"lastModified\":" + attrs.lastModifiedTime().toMillis() +
                        ",\"fileType\":\"" + attrs.fileType() + 
                        "\",\"md5\":\"" + md5Hash + 
                        "\",\"sha256\":\"" + sha256Hash + "\"}");

                    updateBucketPolicy(path, md5Hash, sha256Hash);
                } catch (IOException | NoSuchAlgorithmException e) {
                    logger.error("Error processing file: " + filePath, e);
                    throw new RuntimeException("Failed to process file: " + filePath, e);
                }
            });
        }

        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
            Thread.currentThread().interrupt();
        }

        return metadataMap;
    }

    private String calculateMD5(Path path) throws IOException, NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        try (InputStream is = Files.newInputStream(path)) {
            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = is.read(buffer)) != -1) {
                md.update(buffer, 0, bytesRead);
            }
        }
        return bytesToHex(md.digest());
    }

    private String calculateSHA256(Path path) throws IOException, NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        try (InputStream is = Files.newInputStream(path)) {
            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = is.read(buffer)) != -1) {
                md.update(buffer, 0, bytesRead);
            }
        }
        return bytesToHex(md.digest());
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private void updateBucketPolicy(Path path, String md5Hash, String sha256Hash) throws IOException {
        // Implement bucket policy update logic here
        logger.info("Updated bucket policy for file: " + path);
    }
}
