typedef struct MemoryPool_t {
    void* memory;
    size_t size;
    size_t used;
    pthread_mutex_t lock;
} MemoryPool_t;

MemoryPool_t* create_memory_pool(size_t size) {
    MemoryPool_t* pool = (MemoryPool_t*)malloc(sizeof(MemoryPool_t));
    if (!pool) return NULL;
    pool->memory = malloc(size);
    if (!pool->memory) {
        free(pool);
        return NULL;
    }
    pool->size = size;
    pool->used = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_memory_pool(MemoryPool_t* pool) {
    if (pool) {
        pthread_mutex_destroy(&pool->lock);
        free(pool->memory);
        free(pool);
    }
}

void* allocate_from_pool(MemoryPool_t* pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used + size > pool->size) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    void* ptr = ((uint8_t*)pool->memory) + pool->used;
    pool->used += size;
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

void deallocate_from_pool(MemoryPool_t* pool, void* ptr, size_t size) {
    // In a real implementation, you would need to manage free list or similar
    // for deallocation. This is a simplified example.
}

// Function to create and manage an array of NFDataMessage_t structures using the custom memory pool
NFDataMessage_t** create_nfd_message_array(MemoryPool_t* pool, size_t count) {
    if (count > 5000) return NULL;
    NFDataMessage_t** array = allocate_from_pool(pool, count * sizeof(NFDataMessage_t*));
    if (!array) return NULL;
    for (size_t i = 0; i < count; i++) {
        array[i] = allocate_from_pool(pool, sizeof(NFDataMessage_t));
        if (!array[i]) {
            // Cleanup previously allocated elements
            for (size_t j = 0; j < i; j++) {
                deallocate_from_pool(pool, array[j], sizeof(NFDataMessage_t));
            }
            deallocate_from_pool(pool, array, count * sizeof(NFDataMessage_t*));
            return NULL;
        }
    }
    return array;
}

void destroy_nfd_message_array(MemoryPool_t* pool, NFDataMessage_t** array, size_t count) {
    for (size_t i = 0; i < count; i++) {
        deallocate_from_pool(pool, array[i], sizeof(NFDataMessage_t));
    }
    deallocate_from_pool(pool, array, count * sizeof(NFDataMessage_t*));
}

