#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    uint32_t TRANSACTION_ID;
    uint32_t SEQUENCE_NUMBER;
    uint32_t PAYLOAD_SIZE;
    char STATUS[16];
} MAC_TRANSACTION_T;

typedef struct {
    MAC_TRANSACTION_T *transactions;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} MAC_TRANSACTION_MANAGER_T;

MAC_TRANSACTION_MANAGER_T* mac_transaction_manager_init(size_t initial_capacity) {
    MAC_TRANSACTION_MANAGER_T *manager = malloc(sizeof(MAC_TRANSACTION_MANAGER_T));
    if (!manager) return NULL;

    manager->transactions = malloc(initial_capacity * sizeof(MAC_TRANSACTION_T));
    if (!manager->transactions) {
        free(manager);
        return NULL;
    }

    manager->count = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void mac_transaction_manager_destroy(MAC_TRANSACTION_MANAGER_T *manager) {
    free(manager->transactions);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int mac_transaction_manager_add_transaction(MAC_TRANSACTION_MANAGER_T *manager, const MAC_TRANSACTION_T *transaction) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity ? manager->capacity * 2 : 16;
        MAC_TRANSACTION_T *new_transactions = realloc(manager->transactions, new_capacity * sizeof(MAC_TRANSACTION_T));
        if (!new_transactions) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->transactions = new_transactions;
        manager->capacity = new_capacity;
    }

    if (manager->count > 0 && manager->transactions[manager->count - 1].SEQUENCE_NUMBER == transaction->SEQUENCE_NUMBER) {
        pthread_mutex_unlock(&manager->lock);
        return -2; // Duplicate sequence number
    }

    memcpy(&manager->transactions[manager->count], transaction, sizeof(MAC_TRANSACTION_T));
    manager->count++;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

void mac_transaction_manager_log_status(MAC_TRANSACTION_MANAGER_T *manager, int transaction_index) {
    if (transaction_index < 0 || transaction_index >= manager->count) return;

    pthread_mutex_lock(&manager->lock);
    printf("Transaction %d status: %s\n", manager->transactions[transaction_index].TRANSACTION_ID, manager->transactions[transaction_index].STATUS);
    pthread_mutex_unlock(&manager->lock);
}
