#define MAX_LOG_EVENTS 10000

typedef enum {
    LOG_DEBUG,
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR,
    LOG_CRITICAL
} LOG_LEVEL;

typedef struct log_event_t {
    long EVENT_TIMESTAMP;
    LOG_LEVEL LOG_LEVEL;
    int SOURCE_ID;
    int MESSAGE_SIZE;
    char TARGET_SYSTEM[256];
    struct log_event_t *next;
} LOG_EVENT_T;

typedef struct {
    LOG_EVENT_T *head;
    int size;
} LOG_MANAGER_T;

LOG_MANAGER_T* log_manager_create() {
    LOG_MANAGER_T *manager = (LOG_MANAGER_T*)malloc(sizeof(LOG_MANAGER_T));
    if (!manager) return NULL;
    manager->head = NULL;
    manager->size = 0;
    return manager;
}

int log_event_add(LOG_MANAGER_T *manager, long timestamp, LOG_LEVEL level, int source_id, const char *message, int message_size, const char *target_system) {
    if (manager->size >= MAX_LOG_EVENTS) return -1; // Max events reached

    if (manager->head != NULL && manager->head->LOG_LEVEL == level) return -2; // Duplicate log level

    LOG_EVENT_T *new_event = (LOG_EVENT_T*)malloc(sizeof(LOG_EVENT_T));
    if (!new_event) return -3; // Memory allocation failed

    new_event->EVENT_TIMESTAMP = timestamp;
    new_event->LOG_LEVEL = level;
    new_event->SOURCE_ID = source_id;
    new_event->MESSAGE_SIZE = message_size;
    strncpy(new_event->TARGET_SYSTEM, target_system, 256);
    new_event->next = manager->head;
    manager->head = new_event;
    manager->size++;

    return 0; // Success
}

void log_manager_destroy(LOG_MANAGER_T *manager) {
    LOG_EVENT_T *current = manager->head;
    while (current != NULL) {
        LOG_EVENT_T *temp = current;
        current = current->next;
        free(temp);
    }
    free(manager);
}
