ConnectionList connection_list;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t list_condition = PTHREAD_COND_INITIALIZER;

void init_connection_list() {
    memset(&connection_list, 0, sizeof(connection_list));
}

int add_record(const TCP_CONNECTION_RECORD *record) {
    pthread_mutex_lock(&list_mutex);
    if (connection_list.count >= MAX_CONNECTIONS) {
        pthread_mutex_unlock(&list_mutex);
        return -1;
    }
    memcpy(&connection_list.records[connection_list.count], record, sizeof(TCP_CONNECTION_RECORD));
    connection_list.count++;
    pthread_cond_signal(&list_condition);
    pthread_mutex_unlock(&list_mutex);
    return 0;
}

int remove_record(int index) {
    pthread_mutex_lock(&list_mutex);
    if (index < 0 || index >= connection_list.count) {
        pthread_mutex_unlock(&list_mutex);
        return -1;
    }
    memmove(&connection_list.records[index], &connection_list.records[index + 1], sizeof(TCP_CONNECTION_RECORD) * (connection_list.count - index - 1));
    connection_list.count--;
    pthread_cond_signal(&list_condition);
    pthread_mutex_unlock(&list_mutex);
    return 0;
}

