class BookstoreInventory:
    def __init__(self):
        self.inventory = {}
        self.sales_data = {}

    def add_book(self, book_id, title, author, genre, publication_year, rating=0):
        self.inventory[book_id] = {
            'title': title,
            'author': author,
            'genre': genre,
            'publication_year': publication_year,
            'rating': rating
        }

    def update_book(self, book_id, **kwargs):
        if book_id in self.inventory:
            self.inventory[book_id].update(kwargs)

    def remove_book(self, book_id):
        if book_id in self.inventory:
            del self.inventory[book_id]

    def get_books_by_author(self, author):
        return [book for book in self.inventory.values() if book['author'] == author]

    def get_books_by_genre(self, genre):
        return [book for book in self.inventory.values() if book['genre'] == genre]

    def generate_sales_report(self, start_date, end_date):
        report = {
            'total_sales': 0,
            'best_selling_titles': {},
            'best_selling_authors': {}
        }
        for book_id, sales in self.sales_data.items():
            if start_date <= sales['date'] <= end_date:
                report['total_sales'] += sales['amount']
                title = self.inventory[book_id]['title']
                author = self.inventory[book_id]['author']
                if title not in report['best_selling_titles']:
                    report['best_selling_titles'][title] = 0
                if author not in report['best_selling_authors']:
                    report['best_selling_authors'][author] = 0
                report['best_selling_titles'][title] += sales['amount']
                report['best_selling_authors'][author] += sales['amount']
