typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

enum { SUCCESS, FAILURE };

NFAPI_CRC_INDICATION_PDU_T* parse_json_config(const char* filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open JSON file");
        return NULL;
    }

    struct json_object *parsed_json;
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        parsed_json = json_tokener_parse(buffer);
        break; // Assuming the first line contains the valid JSON
    }
    fclose(file);

    if (!json_object_is_type(parsed_json, json_type_object)) {
        fprintf(stderr, "Invalid JSON format\n");
        return NULL;
    }

    struct json_object *access_token, *expires_in, *token_type, *refresh_token;
    if (json_object_object_get_ex(parsed_json, "access_token", &access_token) &&
        json_object_object_get_ex(parsed_json, "expires_in", &expires_in) &&
        json_object_object_get_ex(parsed_json, "token_type", &token_type)) {
        int expires_in_val = json_object_get_int(expires_in);
        if (expires_in_val <= 0) {
            fprintf(stderr, "Invalid expires_in value\n");
            return NULL;
        }

        const char *token_type_str = json_object_get_string(token_type);
        if (strcmp(token_type_str, "Bearer") != 0) {
            fprintf(stderr, "Invalid token_type value\n");
            return NULL;
        }

        NFAPI_CRC_INDICATION_PDU_T *head = NULL, *current = NULL;
        do {
            NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!new_node) {
                fprintf(stderr, "Memory allocation failed\n");
                while (head) {
                    NFAPI_CRC_INDICATION_PDU_T *temp = head;
                    head = head->next;
                    free(temp);
                }
                return NULL;
            }

            new_node->RX_UE_INFORMATION_TAG = rand();
            new_node->RNTI = rand();
            new_node->CRC_INDICATION_REL8_TAG = (rand() % 2 == 0) ? 1 : 0; // Randomly generate CRC flag
            new_node->next = NULL;

            if (!head) {
                head = new_node;
                current = new_node;
            } else {
                current->next = new_node;
                current = new_node;
            }
        } while (json_object_object_get_ex(parsed_json, "refresh_token", &refresh_token));

        return head;
    }

    fprintf(stderr, "Missing required fields in JSON\n");
    return NULL;
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *head = parse_json_config("config.json");
    if (head) {
        printf("Parsing successful\n");
        while (head) {
            printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d\n",
                   head->RX_UE_INFORMATION_TAG, head->RNTI, head->CRC_INDICATION_REL8_TAG);
            NFAPI_CRC_INDICATION_PDU_T *temp = head;
            head = head->next;
            free(temp);
        }
    } else {
        printf("Parsing failed\n");
    }

    return 0;
}
