#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define N 10000

typedef struct {
    int tag;
    int rnti;
} RX_UE_INFORMATION_TAG;

typedef struct {
    int crc_flag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T *pool[N];
int pool_index = 0;

void init_pool() {
    for (int i = 0; i < N; i++) {
        pool[i] = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
}

void free_pool() {
    for (int i = 0; i < N; i++) {
        free(pool[i]);
    }
}

NFAPI_CRC_INDICATION_PDU_T *get_from_pool() {
    pthread_mutex_lock(&pool_lock);
    if (pool_index == 0) return NULL;
    NFAPI_CRC_INDICATION_PDU_T *item = pool[--pool_index];
    pthread_mutex_unlock(&pool_lock);
    return item;
}

void put_back_to_pool(NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&pool_lock);
    if (pool_index < N) {
        pool[pool_index++] = item;
    }
    pthread_mutex_unlock(&pool_lock);
}

void populate_array(float crc_threshold) {
    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T *item = get_from_pool();
        if (item == NULL) break;

        // Simulate data retrieval
        item->rx_ue_info_tag.tag = rand() % 1000;
        item->rx_ue_info_tag.rnti = rand() % 500;

        // Randomize CRC flag based on threshold
        if ((float)rand() / RAND_MAX < crc_threshold) {
            item->crc_ind_rel8_tag.crc_flag = 1;
        } else {
            item->crc_ind_rel8_tag.crc_flag = 0;
        }

        // Process the data (simulated)
        printf("Processed PDU with TAG: %d, RNTI: %d, CRC Flag: %d\n",
               item->rx_ue_info_tag.tag, item->rx_ue_info_tag.rnti, item->crc_ind_rel8_tag.crc_flag);

        put_back_to_pool(item);
    }
}

int main() {
    init_pool();
    populate_array(0.1); // 10% probability threshold
    free_pool();
    return 0;
}
