#define MAX_UE_RECORDS 1000
#define MAX_MR_PER_UE 5

typedef struct {
    int measurement_id;
    int signal_strength;
    int frequency_band;
} Measurement_Report;

typedef struct {
    int UE_ID;
    time_t last_seen_timestamp;
    Measurement_Report MRs[MAX_MR_PER_UE];
    int MR_count;
} UE_Status_Record;

typedef struct {
    UE_Status_Record records[MAX_UE_RECORDS];
    int record_count;
    pthread_mutex_t mutex;
} Dynamic_Array;

int add_or_update_record(Dynamic_Array *array, UE_Status_Record new_record) {
    pthread_mutex_lock(&array->mutex);
    for (int i = 0; i < array->record_count; i++) {
        if (array->records[i].UE_ID == new_record.UE_ID) {
            array->records[i] = new_record;
            pthread_mutex_unlock(&array->mutex);
            return 0;
        }
    }
    if (array->record_count < MAX_UE_RECORDS) {
        array->records[array->record_count++] = new_record;
        pthread_mutex_unlock(&array->mutex);
        return 0;
    } else {
        pthread_mutex_unlock(&array->mutex);
        fprintf(stderr, "Dynamic Array is full\n");
        return -1;
    }
}

void initialize_dynamic_array(Dynamic_Array *array) {
    array->record_count = 0;
    pthread_mutex_init(&array->mutex, NULL);
}

void destroy_dynamic_array(Dynamic_Array *array) {
    pthread_mutex_destroy(&array->mutex);
}
