UniqueIdentifier* generate_unique_identifier(int count, const char* format, size_t max_size) {
    if (count <= 0 || !format || max_size <= 0) {
        return NULL;
    }

    UniqueIdentifier* identifiers = (UniqueIdentifier*)malloc(count * sizeof(UniqueIdentifier));
    if (!identifiers) {
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < count; ++i) {
        identifiers[i].timestamp = time(NULL);

        size_t payload_size = max_size - sizeof(time_t);
        identifiers[i].payload = (char*)malloc(payload_size * sizeof(char));
        if (!identifiers[i].payload) {
            for (int j = 0; j < i; ++j) {
                free(identifiers[j].payload);
