#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_UE_ID_LENGTH 20
#define MAX_MR_COUNT 10

typedef struct {
    char ue_id[MAX_UE_ID_LENGTH];
    time_t last_seen_timestamp;
    struct Measurement_Report {
        int measurement_id;
        int signal_strength;
        int frequency_band;
    } mrs[MAX_MR_COUNT];
    int mr_count;
} UE_Status_Record;

typedef struct {
    UE_Status_Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} UE_Records_Manager;

UE_Records_Manager* create_manager(size_t initial_capacity) {
    UE_Records_Manager *manager = (UE_Records_Manager*)malloc(sizeof(UE_Records_Manager));
    if (!manager) {
        perror("Failed to allocate memory for manager");
        return NULL;
    }
    manager->records = (UE_Status_Record*)calloc(initial_capacity, sizeof(UE_Status_Record));
    if (!manager->records) {
        free(manager);
        perror("Failed to allocate memory for records");
        return NULL;
    }
    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_manager(UE_Records_Manager *manager) {
    if (manager->records) {
        free(manager->records);
    }
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_record(UE_Records_Manager *manager, UE_Status_Record record) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        UE_Status_Record *new_records = realloc(manager->records, new_capacity * sizeof(UE_Status_Record));
        if (!new_records) {
            pthread_mutex_unlock(&manager->lock);
            perror("Failed to reallocate memory for records");
            return -1;
        }
        manager->records = new_records;
        manager->capacity = new_capacity;
    }
    memcpy(&manager->records[manager->count], &record, sizeof(UE_Status_Record));
    manager->count++;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int update_record(UE_Records_Manager *manager, char *ue_id, UE_Status_Record updated_record) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; i++) {
        if (strcmp(manager->records[i].ue_id, ue_id) == 0) {
            memcpy(&manager->records[i], &updated_record, sizeof(UE_Status_Record));
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // UE_ID not found
}

void serialize_manager(UE_Records_Manager *manager, FILE *file) {
    pthread_mutex_lock(&manager->lock);
    fwrite(&manager->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < manager->count; i++) {
        fwrite(manager->records[i].ue_id, sizeof(char), MAX_UE_ID_LENGTH, file);
        fwrite(&manager->records[i].last_seen_timestamp, sizeof(time_t), 1, file);
        fwrite(&manager->records[i].mr_count, sizeof(int), 1, file);
        for (int j = 0; j < manager->records[i].mr_count; j++) {
            fwrite(&manager->records[i].mrs[j].measurement_id, sizeof(int), 1, file);
            fwrite(&manager->records[i].mrs[j].signal_strength, sizeof(int), 1, file);
            fwrite(&manager->records[i].mrs[j].frequency_band, sizeof(int), 1, file);
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void deserialize_manager(UE_Records_Manager *manager, FILE *file) {
    size_t count;
    fread(&count, sizeof(size_t), 1, file);
    if (count > manager->capacity) {
        size_t new_capacity = count * 2;
        UE_Status_Record *new_records = realloc(manager->records, new_capacity * sizeof(UE_Status_Record));
        if (!new_records) {
            perror("Failed to reallocate memory for records");
            return;
        }
        manager->records = new_records;
        manager->capacity = new_capacity;
    }
    for (size_t i = 0; i < count; i++) {
        fread(manager->records[i].ue_id, sizeof(char), MAX_UE_ID_LENGTH, file);
        fread(&manager->records[i].last_seen_timestamp, sizeof(time_t), 1, file);
        fread(&manager->records[i].mr_count, sizeof(int), 1, file);
        for (int j = 0; j < manager->records[i].mr_count; j++) {
            fread(&manager->records[i].mrs[j].measurement_id, sizeof(int), 1, file);
            fread(&manager->records[i].mrs[j].signal_strength, sizeof(int), 1, file);
            fread(&manager->records[i].mrs[j].frequency_band, sizeof(int), 1, file);
        }
    }
    manager->count = count;
}

int main() {
    UE_Records_Manager *manager = create_manager(100);
    if (!manager) return EXIT_FAILURE;

    // Example usage
    UE_Status_Record new_record = { .ue_id = "12345", .last_seen_timestamp = time(NULL), .mr_count = 1 };
    new_record.mrs[0].measurement_id = 1;
    new_record.mrs[0].signal_strength = -50;
    new_record.mrs[0].frequency_band = 20;

    add_record(manager, new_record);
    update_record(manager, "12345", new_record);

    serialize_manager(manager, stdout);
    deserialize_manager(manager, stdin);

    destroy_manager(manager);
    return EXIT_SUCCESS;
}
```

This code provides a basic structure for managing and processing a dynamic array of `UE_Status_Record` structures. It includes functions for creating, destroying, adding records, updating records, serializing the manager to a file, and deserializing it from a file. The use of mutexes ensures thread safety when accessing shared data.

To fully implement this solution, additional features such as error handling, logging, performance optimization, concurrency control mechanisms, serialization/deserialization efficiency, and unit tests would need to be added based on the specific requirements and constraints of your project.']

