int parse_json_and_populate_lists(const char* filename, NFAPI_CRC_INDICATION_PDU_T** crc_list, LTE_NAS_EMM_MESSAGE** nas_list, int list_size) {
    // Open and read JSON file
    FILE* file = fopen(filename, "r");
    if (!file) return -1;

    json_object *parsed_json;
    parsed_json = json_tokener_parse_file(file);
    fclose(file);

    if (!json_object_object_get_ex(parsed_json, "access_token", NULL)) return -1;
    if (!json_object_object_get_ex(parsed_json, "expires_in", NULL)) return -1;
    if (!json_object_object_get_ex(parsed_json, "token_type", NULL)) return -1;

    const char* token_type = json_object_get_string(json_object_object_get(parsed_json, "token_type"));
    if (strcmp(token_type, "Bearer") != 0) return -1;

    int expires_in = json_object_get_int(json_object_object_get(parsed_json, "expires_in"));
    if (expires_in <= 0) return -1;

    *crc_list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * list_size);
    if (!*crc_list) return -1;

    *nas_list = malloc(sizeof(LTE_NAS_EMM_MESSAGE) * list_size);
    if (!*nas_list) {
        free(*crc_list);
        return -1;
    }

    // Populate lists with valid data
    for (int i = 0; i < list_size; i++) {
        (*crc_list)[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        (*crc_list)[i].RNTI = rand() % 65536;
        (*crc_list)[i].CRC_INDICATION_REL8_TAG = rand() % 2;

        (*nas_list)[i].NAS_EMM_TYPE = rand() % 100;
        snprintf((*nas_list)[i].NAS_EPS_Mobility, sizeof((*nas_list)[i].NAS_EPS_Mobility), "Mobility_%d", i);
        // Generate random NAS_PDU content
        for (int j = 0; j < 512; j++) {
            (*nas_list)[i].NAS_PDU[j] = rand() % 256;
        }
    }

    json_object_put(parsed_json);
    return 0;
}

// Example usage
int main() {
    NFAPI_CRC_INDICATION_PDU_T* crc_list = NULL;
    LTE_NAS_EMM_MESSAGE* nas_list = NULL;
    int list_size = 10;

    if (parse_json_and_populate_lists("config.json", &crc_list, &nas_list, list_size) != 0) {
        printf("Failed to parse JSON or populate lists\n");
        free(crc_list);
        free(nas_list);
        return 1;
    }

    // Use crc_list and nas_list as needed

    free(crc_list);
    free(nas_list);
    return 0;
}
