#define N 10000
#define MAX_THREADS 16

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
} UE_INFO;

typedef struct {
    UE_INFO ue_info;
    int CRCFLAG;
