NFAPI_CRC_INDICATION_PDU_T *pool = NULL;
int pool_size = 0;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

void* populate_pdus(void* arg) {
    int thread_id = *(int*)arg;
    srand(time(NULL) + thread_id); // Seed for random number generation

    for (int i = thread_id * N / MAX_THREADS; i < (thread_id + 1) * N / MAX_THREADS; i++) {
        pthread_mutex_lock(&pool_lock);
        if (i >= pool_size) {
            pool = realloc(pool, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (i + 1));
            pool_size = i + 1;
        }
        pthread_mutex_unlock(&pool_lock);

        UE_INFO ue_info;
        // Simulate data retrieval from external sources
        ue_info.RX_UE_INFORMATION_TAG = rand() % 1000000; // Example value
        ue_info.RNTI = rand() % 65536; // Example value

        pthread_mutex_lock(&pool_lock);
        pool[i].ue_info = ue_info;
        pool[i].CRCFLAG = (rand() < (RAND_MAX * 0.9)); // 10% chance of error
        pthread_mutex_unlock(&pool_lock);
    }

    return NULL;
}

int main() {
    int thread_ids[MAX_THREADS];
    pthread_t threads[MAX_THREADS];

    srand(time(NULL));

    for (int i = 0; i < MAX_THREADS; i++) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, populate_pdus, &thread_ids[i]);
