['```python
import os
import hashlib
import logging

def calculate_md5(file_path):
    md5_hash = hashlib.md5()
    with open(file_path, 'rb') as f:
        while chunk := f.read(8192):  # Read in chunks of 8192 bytes
            md5_hash.update(chunk)
    return md5_hash.hexdigest()

def process_files_in_directory(directory):
    file_hashes = {}
    logging.basicConfig(level=logging.INFO)
    for root, _, files in os.walk(directory):
        for file in files:
            file_path = os.path.join(root, file)
            try:
                hash_value = calculate_md5(file_path)
                file_hashes[file] = hash_value
                logging.info(f"Processed {file} with hash: {hash_value}")
            except Exception as e:
                logging.error(f"Failed to process {file}: {e}")
    return file_hashes

def concurrent_file_hashing(directory, max_workers=3):
    from concurrent.futures import ThreadPoolExecutor
    import queue

    def worker(file_queue):
        while not file_queue.empty():
            try:
                file_path = file_queue.get(block=False)
                hash_value = calculate_md5(file_path)
                logging.info(f"Processed {file_path} with hash: {hash_value}")
            except Exception as e:
                logging.error(f"Failed to process {file_path}: {e}")

    files_to_process = queue.Queue()
    for root, _, files in os.walk(directory):
        for file in files:
            files_to_process.put(os.path.join(root, file))

    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        for _ in range(max_workers):
            executor.submit(worker, files_to_process)

    return {os.path.basename(f): calculate_md5(f) for f in os.listdir(directory)}

# Example usage
directory_path = '/path/to/directory'
hash_results = concurrent_file_hashing(directory_path)
print(hash_results)
```

This code snippet provides a solution for calculating MD5 hashes of files in a directory, handling large files efficiently, and processing files concurrently. It uses the `hashlib` library to calculate hash values and logs processing status and errors. The `concurrent.futures.ThreadPoolExecutor` is used to manage concurrent file hashing operations, ensuring efficient resource utilization.']

