#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/md5.h>

#define BUFFER_SIZE 1024

// Helper function to find the largest integer in an array of strings
int findLargestInteger(char **filePaths, int count) {
    int largest = -1;
    for (int i = 0; i < count; i++) {
        char *endPtr;
        long num = strtol(filePaths[i], &endPtr, 10);
        if (*endPtr == '\0' && num > largest) {
            largest = num;
        }
    }
    return largest;
}

// Worker function to calculate MD5 hash of a file
void* worker(void *arg) {
    char **filePaths = (char **)arg;
    for (int i = 0; filePaths[i] != NULL; i++) {
        FILE *file = fopen(filePaths[i], "rb");
        if (!file) {
            fprintf(stderr, "Error opening file: %s\n", filePaths[i]);
            continue;
        }
        MD5_CTX md5Context;
        MD5_Init(&md5Context);
        char buffer[BUFFER_SIZE];
        size_t bytesRead;
        while ((bytesRead = fread(buffer, 1, BUFFER_SIZE, file)) > 0) {
            MD5_Update(&md5Context, buffer, bytesRead);
        }
        fclose(file);
        unsigned char hash[MD5_DIGEST_LENGTH];
        MD5_Final(hash, &md5Context);
        printf("File: %s, Hash: %s\n", filePaths[i], md5_hash_to_string(hash));
    }
    return NULL;
}

// Function to read file paths and calculate MD5 hashes concurrently
void processFiles(char **filePaths, int count) {
    pthread_t threads[count];
    for (int i = 0; i < count; i++) {
        if (pthread_create(&threads[i], NULL, worker, filePaths + i) != 0) {
            fprintf(stderr, "Error creating thread\n");
            return;
        }
    }
    for (int i = 0; i < count; i++) {
        pthread_join(threads[i], NULL);
    }
}

// Convert MD5 hash to a string
char* md5_hash_to_string(unsigned char *hash) {
    static char result[33];
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        sprintf(result + i * 2, "%02x", hash[i]);
    }
    return result;
}

int main() {
    int count;
    printf("Enter the number of file paths: ");
    scanf("%d", &count);
    getchar(); // Consume newline character

    char **filePaths = (char **)malloc(count * sizeof(char *));
    for (int i = 0; i < count; i++) {
        filePaths[i] = (char *)malloc(256 * sizeof(char));
        printf("Enter file path %d: ", i + 1);
        fgets(filePaths[i], 256, stdin);
        filePaths[i][strcspn(filePaths[i], "\n")] = '\0'; // Remove newline character
    }

    processFiles(filePaths, count);

