    pthread_mutex_init(&lock, NULL);

    // Create worker threads to process URLs
    pthread_t workers[num_urls];
    WorkerArgs worker_args = {0, urls, &lock};
    for (int i = 0; i < num_urls; i++) {
        pthread_create(&workers[i], NULL, process_urls, &worker_args);
    }

    // Wait for all threads to complete
