    RRC_UE_CONTEXT_T rrc_ctx;
    uint16_t CRC_FLAG;
} LTE_ENB_RRC_MESSAGE_T;

typedef struct {
    LTE_ENB_RRC_MESSAGE_T *messages;
    size_t count;
    size_t capacity;
} LTE_ENB_RRC_MESSAGE_ARRAY;

LTE_ENB_RRC_MESSAGE_ARRAY* populate_lte_rrc_messages(size_t N, float crc_threshold) {
    LTE_ENB_RRC_MESSAGE_ARRAY *array = malloc(sizeof(LTE_ENB_RRC_MESSAGE_ARRAY));
    array->messages = NULL;
    array->count = 0;
    array->capacity = 0;

    if (N == 0 || crc_threshold < 0 || crc_threshold > 1) {
        return array; // Invalid input
    }

    srand(time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < N; ++i) {
        LTE_ENB_RRC_MESSAGE_T message;
        message.UE_ID = rand() % MAX_UE_ID;

        // Simulate data retrieval from external source
        if (message.UE_ID == 0) {
            continue; // Skip invalid or missing entries
        }

        // Initialize MAC and RRC context
        message.mac_ctx.MAC_LTE_ENB_UE_CTX_T = rand();
        message.rrc_ctx.RRC_UE_CONTEXT_T = rand();

        // Generate SIB content based on template (simulated)
        uint8_t sib_content[SIB_TEMPLATE_SIZE];
        for (size_t j = 0; j < SIB_TEMPLATE_SIZE; ++j) {
            sib_content[j] = (i * j) % 256;
        }

        // Simulate CRC flag based on threshold
        message.CRC_FLAG = (rand() / (float)RAND_MAX) < crc_threshold;

        // Expand array if necessary
        if (array->count == array->capacity) {
            size_t new_capacity = (array->capacity == 0) ? 16 : array->capacity * 2;
            LTE_ENB_RRC_MESSAGE_T *new_messages = realloc(array->messages, new_capacity * sizeof(LTE_ENB_RRC_MESSAGE_T));
            if (new_messages == NULL) {
                free(array->messages);
                return array; // Memory allocation failed
            }
            array->messages = new_messages;
            array->capacity = new_capacity;
        }

        // Add message to array
        array->messages[array->count++] = message;
    }

    return array;
}

void free_lte_rrc_message_array(LTE_ENB_RRC_MESSAGE_ARRAY *array) {
    if (array != NULL) {
        free(array->messages);
        free(array);
    }
}
