import time
from collections import defaultdict

# Define constants for transaction limits and rates
DAILY_TRANSACTION_LIMIT = 10000
MAX_REQUESTS_PER_MINUTE = 10

class PaymentProcessor:
    def __init__(self, api_key):
        self.api_key = api_key
        self.balance = 50000  # Example balance in cents
        self.daily_limit_used = 0
        self.requests = defaultdict(int)
        self.transaction_cache = {}

    def validate_transaction(self, amount):
        if self.daily_limit_used + amount > DAILY_TRANSACTION_LIMIT:
            raise ValueError("Daily transaction limit exceeded")
        if amount <= 0:
            raise ValueError("Transaction amount must be positive")

    def process_request(self, request):
        ip_address = request.get('ip', 'unknown_ip')
        sub_action = request.get('sub_action')
        transaction_id = request.get('transaction_id')

        current_time = int(time.time())
        if self.requests[ip_address] >= MAX_REQUESTS_PER_MINUTE:
            raise RateLimitError("Too many requests from this IP address")

        if sub_action == 'initiate':
            amount = request['amount']
            self.validate_transaction(amount)
            # Simulate transaction processing
            time.sleep(0.1)  # Simulate network latency
            self.balance -= amount
            self.daily_limit_used += amount
            self.requests[ip_address] += 1
        elif sub_action == 'refund':
            # Retrieve transaction details from cache or database
            original_transaction = self.get_transaction(transaction_id)
            if original_transaction['amount'] < request['amount']:
                raise ValueError("Refund amount exceeds original transaction")
            # Simulate refund processing
            time.sleep(0.1)  # Simulate network latency
            self.balance += request['amount']
            self.requests[ip_address] += 1
        elif sub_action == 'chargeback':
            # Retrieve transaction details from cache or database
            original_transaction = self.get_transaction(transaction_id)
            if original_transaction['amount'] < request['amount']:
                raise ValueError("Chargeback amount exceeds original transaction")
            # Simulate chargeback processing
            time.sleep(0.1)  # Simulate network latency
            self.balance += original_transaction['amount']
            self.requests[ip_address] += 1

    def get_transaction(self, transaction_id):
        return self.transaction_cache.get(transaction_id, {'amount': None})

class RateLimitError(Exception):
    pass

# Example usage
api_key = 'your_api_key_here'
processor = PaymentProcessor(api_key)
request = {
    'sub_action': 'initiate',
    'amount': 500,
    'currency': 'USD',
    'ip': '123.45.67.89'
}
processor.process_request(request)
