    TX_LOG_INFO("Fetching transaction logs...");
    int* transactionLogs = fetchTransactionLogs(batchSize);

    if (transactionLogs == NULL) {
        free(crcIndications);
        handleExternalDataFailure("Failed to fetch transaction logs");
    }

    for (int i = 0; i < batchSize; ++i) {
        int txId = transactionLogs[i];
        validateTransactionID(txId);

        // Fetch transaction details from external service with retries and exponential backoff
        TX_LOG_INFO("Fetching details for transaction ID %d...", txId);
        TransactionDetails* details = fetchTransactionDetailsWithRetries(txId, crcThreshold);

        if (details == NULL) {
            free(crcIndications);
            free(transactionLogs);
            handleExternalDataFailure("Failed to fetch transaction details");
        }

        // Populate NFAPI_CRC_INDICATION_PDU_T structure
        populateCRCIndicationStruct(&crcIndications[i], txId, details->rnti, random() < crcThreshold);

        // Update global transaction status database
        updateTransactionStatus(txId, details->status);
    }

    free(transactionLogs);
    return crcIndications;
}

void validateTransactionID(int txId) {
    if (txId < 0) {
        TX_LOG_ERROR("Invalid transaction ID: %d", txId);
        exit(EXIT_FAILURE);
    }
}

NFAPI_CRC_INDICATION_PDU_T* fetchTransactionDetailsWithRetries(int txId, float crcThreshold, int maxRetries) {
    NFAPI_CRC_INDICATION_PDU_T* details = NULL;

    for (int retry = 0; retry <= maxRetries; ++retry) {
        details = fetchTransactionDetails(txId);

        if (details != NULL) {
            break;
        }

        TX_LOG_WARNING("Failed to fetch transaction details. Retrying...");
        sleepForExponentialBackoff(retry);
    }

    return details;
}

void populateCRCIndicationStruct(NFAPI_CRC_INDICATION_PDU_T* crcIndication, int txId, int rnti, int crcFlag) {
    // Populate structure with valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    crcIndication->rx_ue_information_tag = getRXUEInformationTag(txId);
    crcIndication->rnti = rnti;
    crcIndication->crc_indication_rel8_flag = crcFlag ? 1 : 0;
}

void sleepForExponentialBackoff(int retryCount) {
    int delay = (1 << retryCount) * 100; // Exponential backoff
    usleep(delay * 1000); // Convert milliseconds to microseconds
}
```

