} SessionManager;

void init_session_manager(SessionManager *manager) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->session_count = 0;
}

int add_or_update_session(SessionManager *manager, User_Session new_session) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->session_count; i++) {
        if (manager->sessions[i].id == new_session.id) {
            memcpy(&manager->sessions[i], &new_session, sizeof(User_Session));
            pthread_mutex_unlock(&manager->lock);
            return 1;
        }
    }
    if (manager->session_count < MAX_SESSIONS) {
        manager->sessions[manager->session_count] = new_session;
        manager->session_count++;
        pthread_mutex_unlock(&manager->lock);
        return 0;
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Session table full
}

// Other functions for managing sessions (remove, find, etc.) would go here

void destroy_session_manager(SessionManager *manager) {
    pthread_mutex_destroy(&manager->lock);
}
```

