#include <stdlib.h>
#include <stdio.h>

#define NR_RLC_PDU_MAX 100000

typedef struct {
    uint32_t RLC_PDU_HEADER;
    uint32_t SN;
    uint32_t DATA_LENGTH;
} NR_RLC_PDU;

typedef struct {
    NR_RLC_PDU *array;
    size_t count;
    size_t capacity;
    int (*compare)(const NR_RLC_PDU *, const NR_RLC_PDU *);
} NR_RLC_PDUCollection;

int compareSN(const NR_RLC_PDU *a, const NR_RLC_PDU *b) {
    return (a->SN > b->SN) - (a->SN < b->SN);
}

void initCollection(NR_RLC_PDUCollection *col, int (*compare)(const NR_RLC_PDU *, const NR_RLC_PDU *)) {
    col->array = NULL;
    col->count = 0;
    col->capacity = 0;
    col->compare = compare;
}

int addPDU(NR_RLC_PDUCollection *col, NR_RLC_PDU pdu) {
    if (col->count >= col->capacity) {
        size_t new_capacity = col->capacity == 0 ? 1 : col->capacity * 2;
        NR_RLC_PDU *new_array = realloc(col->array, new_capacity * sizeof(NR_RLC_PDU));
        if (!new_array) {
            fprintf(stderr, "Memory allocation failed\n");
            return -1;
        }
        col->array = new_array;
        col->capacity = new_capacity;
    }

    for (size_t i = 0; i < col->count; ++i) {
        if (col->compare(&col->array[i], &pdu) == 0) {
            fprintf(stderr, "Duplicate SN detected\n");
            return -1;
        }
    }

    size_t insert_index = col->count;
    for (size_t i = 0; i < col->count; ++i) {
        if (col->compare(&col->array[i], &pdu) > 0) {
            insert_index = i;
            break;
        }
    }

    memmove(col->array + insert_index + 1, col->array + insert_index, (col->count - insert_index) * sizeof(NR_RLC_PDU));
    col->array[insert_index] = pdu;
    ++col->count;

    return 0;
}

void clearCollection(NR_RLC_PDUCollection *col) {
    free(col->array);
    col->array = NULL;
    col->count = 0;
    col->capacity = 0;
}
```

This code provides a basic implementation of managing a dynamic array of `NR_RLC_PDU` structures with efficient insertion, unique SN checking, and memory management. The `compareSN` function is used to compare PDU structures based on their `SN` values, and the `addPDU` function handles insertion while ensuring uniqueness and maintaining order. The `clearCollection` function frees all allocated memory when the collection is no longer needed.']

