#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define NR_RLC_PDU_HEADER_SIZE 4
#define MAX_PDUS 100000

typedef struct {
    uint32_t SN;
    uint32_t DATA_LENGTH;
} RLC_PDU;

typedef struct {
    RLC_PDU *pdus;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} NR_RLC_PDU_Array;

NR_RLC_PDU_Array* create_array(size_t initial_capacity) {
    NR_RLC_PDU_Array *array = (NR_RLC_PDU_Array *)malloc(sizeof(NR_RLC_PDU_Array));
    if (!array) return NULL;

    array->pdus = (RLC_PDU *)calloc(initial_capacity, sizeof(RLC_PDU));
    if (!array->pdus) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void destroy_array(NR_RLC_PDU_Array *array) {
    if (array) {
        free(array->pdus);
        pthread_mutex_destroy(&array->lock);
        free(array);
    }
}

int insert_pdu(NR_RLC_PDU_Array *array, RLC_PDU pdu) {
    pthread_mutex_lock(&array->lock);

    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 1;
        RLC_PDU *new_pdus = realloc(array->pdus, new_capacity * sizeof(RLC_PDU));
        if (!new_pdus) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failed
        }

        array->pdus = new_pdus;
        array->capacity = new_capacity;
    }

    for (size_t i = 0; i < array->size; i++) {
        if (array->pdus[i].SN == pdu.SN) {
            pthread_mutex_unlock(&array->lock);
            return -2; // Duplicate SN detected
        }
    }

    array->pdus[array->size++] = pdu;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

void batch_process_pdus(NR_RLC_PDU_Array *array, RLC_PDU *pdu_batch, size_t count) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < count && array->size < array->capacity; i++) {
        if (find_pdu(array, pdu_batch[i].SN) == -1) {
            insert_pdu(array, pdu_batch[i]);
        }
    }

    pthread_mutex_unlock(&array->lock);
}

int find_pdu(NR_RLC_PDU_Array *array, uint32_t SN) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->size; i++) {
        if (array->pdus[i].SN == SN) {
            pthread_mutex_unlock(&array->lock);
            return i;
        }
    }

    pthread_mutex_unlock(&array->lock);
    return -1; // PDU not found
}

void delete_pdu(NR_RLC_PDU_Array *array, uint32_t SN) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->size; i++) {
        if (array->pdus[i].SN == SN) {
            memmove(&array->pdus[i], &array->pdus[i + 1], (array->size - i - 1) * sizeof(RLC_PDU));
            array->size--;
            break;
        }
    }

    pthread_mutex_unlock(&array->lock);
}

void compress_array(NR_RLC_PDU_Array *array) {
    pthread_mutex_lock(&array->lock);

    if (array->size < array->capacity / 4) {
        RLC_PDU *new_pdus = realloc(array->pdus, array->size * sizeof(RLC_PDU));
        if (!new_pdus) return; // Memory allocation failed

        array->pdus = new_pdus;
        array->capacity = array->size;
    }

    pthread_mutex_unlock(&array->lock);
}

void resize_array(NR_RLC_PDU_Array *array, size_t new_capacity) {
    pthread_mutex_lock(&array->lock);

    RLC_PDU *new_pdus = realloc(array->pdus, new_capacity * sizeof(RLC_PDU));
    if (!new_pdus) return; // Memory allocation failed

    array->pdus = new_pdus;
    array->capacity = new_capacity;

    pthread_mutex_unlock(&array->lock);
}

void serialize_array(NR_RLC_PDU_Array *array, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return; // File open failed

    fwrite(array->pdus, sizeof(RLC_PDU), array->size, file);

    fclose(file);
}

void deserialize_array(NR_RLC_PDU_Array *array, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return; // File open failed

    size_t size = fread(array->pdus, sizeof(RLC_PDU), array->capacity, file);
    if (size > 0) array->size = size;

    fclose(file);
}

void log_operation(const char *operation_type, uint32_t SN, time_t timestamp) {
    printf("[%ld] %s - SN: %u\n", timestamp, operation_type, SN);
}
