#include <condition_variable>
#include <random>
#include <atomic>

std::mutex rateLimitMutex;
std::condition_variable requestCondition;
int currentRequests = 0;
const int MAX_REQUESTS_PER_SECOND = 100;
const std::chrono::seconds ONE_SECOND(1);
const int MAX_CONCURRENT_REQUESTS = 100;
const int MAX_REQUESTS_PER_MINUTE = 1000;

std::atomic<bool> isRateLimitingEnabled(true);

void rateLimiter() {
    while (true) {
        std::unique_lock<std::mutex> lock(rateLimitMutex);
        requestCondition.wait_for(lock, ONE_SECOND, []{ return currentRequests < MAX_REQUESTS_PER_SECOND; });
        if (!isRateLimitingEnabled) break;
        currentRequests = 0;
    }
}

std::future<std::string> dispatchNetworkRequest(const std::string& method, const std::map<std::string, std::string>& params) {
    static std::mt19937 randomEngine(std::chrono::system_clock::now().time_since_epoch().count());
    static std::uniform_int_distribution<int> retryDistribution(100, 200); // milliseconds

    auto requestFuture = std::async(std::launch::async, [method, params]() {
        int retries = 5;
        while (retries--) {
            try {
                // Simulate network request
                std::this_thread::sleep_for(std::chrono::milliseconds(100)); // Simulated network delay
                return "Success";
            } catch (...) {
                if (retries == 0) throw; // Rethrow exception if max retries reached
                std::this_thread::sleep_for(std::chrono::milliseconds(retryDistribution(randomEngine)));
            }
        }
        return "Failure";
    });

    std::unique_lock<std::mutex> lock(rateLimitMutex);
    while (currentRequests >= MAX_CONCURRENT_REQUESTS) {
        requestCondition.wait(lock, []{ return currentRequests < MAX_CONCURRENT_REQUESTS; });
    }

    if (isRateLimitingEnabled) {
        ++currentRequests;
        std::thread([=]() {
            rateLimiter();
        }).detach();
    }

    return requestFuture;
}

int main() {
    // Example usage
    auto future1 = dispatchNetworkRequest("GET", {{"key", "value"}});
    auto future2 = dispatchNetworkRequest("POST", {{"data", "data"}});

    std::cout << future1.get() << std::endl;
    std::cout << future2.get() << std::endl;

    return 0;
}
