NetworkConfig network_configs[MAX_DEVICES];
int config_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* process_config(void* arg) {
    int index = *(int*)arg;
    pthread_mutex_lock(&mutex);
    if (index >= config_count) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    NetworkConfig* config = &network_configs[index];

    // Process configuration here
    printf("Processing device: %s\n", config->device_name);

    pthread_mutex_unlock(&mutex);
    return NULL;
}

void process_network_configs() {
    pthread_t threads[MAX_DEVICES];
    int indices[MAX_DEVICES];

    for (int i = 0; i < MAX_DEVICES && i < config_count; ++i) {
        indices[i] = i;
        pthread_create(&threads[i], NULL, process_config, &indices[i]);
    }

    for (int i = 0; i < MAX_DEVICES && i < config_count; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void add_network_config(NetworkConfig config) {
    pthread_mutex_lock(&mutex);
    if (config_count < MAX_DEVICES) {
        network_configs[config_count++] = config;
    }
    pthread_mutex_unlock(&mutex);
}
