```java
import java.io.*;
import java.security.MessageDigest;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.List;
import software.amazon.awssdk.services.s3.S3Client;
import software.amazon.awssdk.services.s3.model.*;

public class FileProcessor {

    private static final int THREAD_POOL_SIZE = 10;

    public static void processFilePaths(List<String> filePaths, String bucketName) {
        ExecutorService executor = Executors.newFixedThreadPool(THREAD_POOL_SIZE);
        for (String path : filePaths) {
            executor.submit(() -> processFilePath(path, bucketName));
        }
        executor.shutdown();
    }

    private static void processFilePath(String path, String bucketName) {
        try (FileInputStream fis = new FileInputStream(path)) {
            byte[] fileBytes = fis.readAllBytes();

            // Extract metadata and verify integrity
            MessageDigest md256 = MessageDigest.getInstance("SHA-256");
            byte[] sha256Hash = md256.digest(fileBytes);
            String sha256Hex = bytesToHex(sha256Hash);

            MessageDigest md5 = MessageDigest.getInstance("MD5");
            byte[] md5Hash = md5.digest(fileBytes);
            String md5Hex = bytesToHex(md5Hash);

            // Update S3 lifecycle policy
            updateS3LifecyclePolicy(bucketName, path, sha256Hex, md5Hex);
        } catch (IOException | NoSuchAlgorithmException e) {
            throw new RuntimeException("Error processing file: " + path, e);
        }
    }

    private static void updateS3LifecyclePolicy(String bucketName, String path, String sha256Hex, String md5Hex) {
        S3Client s3 = S3Client.create();
        // Logic to update lifecycle policy based on metadata and user-defined policies
        s3.putBucketLifecycleConfiguration(PutBucketLifecycleConfigurationRequest.builder()
                .bucket(bucketName)
                .lifecycleConfiguration(LifecycleConfiguration.builder()
                        .rule(LifecycleRule.builder()
                                .id("Rule1")
                                .status(LifecycleRuleStatus.ENABLED)
                                .expiration(Expiration.builder().days(30).build())
                                .build())
                        .build())
                .build());
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
