import hashlib
import os
from concurrent.futures import ThreadPoolExecutor, as_completed

def compute_md5_hash(file_path, chunk_size=1024 * 1024):
    hasher = hashlib.md5()
    with open(file_path, 'rb') as file:
        for chunk in iter(lambda: file.read(chunk_size), b''):
            hasher.update(chunk)
    return hasher.hexdigest()

def process_files(file_paths, max_workers=3):
    results = {}
    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        futures = {executor.submit(compute_md5_hash, path): path for path in file_paths}
        for future in as_completed(futures):
            path = futures[future]
            try:
                md5_hash = future.result()
                print(f"MD5 hash of {path}: {md5_hash}")
                results[path] = md5_hash
            except Exception as e:
                print(f"Error processing file {path}: {e}")
    return results

# Example usage:
file_paths = ['path/to/large/file1', 'path/to/large/file2']
results = process_files(file_paths, max_workers=4)
