#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the record structure
typedef struct Record {
    int value;
    struct Node* node; // Pointer to corresponding node in linked list
} Record;

// Define the node structure for linked list
typedef struct Node {
    Record* data;
    struct Node* next;
} Node;

// Function to create a new record
Record* create_record(int value) {
    Record* rec = (Record*)malloc(sizeof(Record));
    if (!rec) return NULL;
    rec->value = value;
    rec->node = NULL;
    return rec;
}

// Function to create a new node in linked list
Node* create_node(Record* data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->data = data;
    node->next = NULL;
    return node;
}

// Function to insert a record into the linked list
void insert_record(Node** head, Record* rec) {
    Node* newNode = create_node(rec);
    if (*head == NULL) {
        *head = newNode;
    } else {
        Node* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
}

// Function to remove a record from the linked list
void remove_record(Node** head, Record* rec) {
    if (*head == NULL) return;

    Node* current = *head;
    Node* previous = NULL;

    while (current != NULL && current->data != rec) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) return; // Record not found

    if (previous == NULL) { // Removing the head
        *head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
}

// Function to serialize records to a binary file
void serialize_records(Node* head, const char* filename) {
    FILE* fp = fopen(filename, "wb");
    if (!fp) return;

    Node* temp = head;
    while (temp != NULL) {
        fwrite(&temp->data->value, sizeof(int), 1, fp);
        temp = temp->next;
    }

    fclose(fp);
}

// Function to deserialize records from a binary file
Node* deserialize_records(const char* filename) {
    FILE* fp = fopen(filename, "rb");
    if (!fp) return NULL;

    Node* head = NULL;
    int value;
    while (fread(&value, sizeof(int), 1, fp) == 1) {
        Record* rec = create_record(value);
        insert_record(&head, rec);
    }

    fclose(fp);
    return head;
}

// Function to free allocated memory
void free_memory(Node** head) {
    Node* temp;
    while (*head != NULL) {
        temp = *head;
        *head = (*head)->next;
        free(temp->data);
        free(temp);
    }
}
