#define MAX_FILES 1000
#define MD5_BLOCK_SIZE 1024

typedef struct {
    uint32_t RNTI;
    RX_UE_INFORMATION_TAG ue_info;
    CRC_INDICATION_REL8_TAG crc_ind;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicList;

void init_dynamic_list(DynamicList *list) {
    list->entries = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void free_dynamic_list(DynamicList *list) {
    if (list->entries) {
        free(list->entries);
    }
    pthread_mutex_destroy(&list->lock);
}

int add_entry(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        size_t new_capacity = (list->capacity > 0) ? list->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_entries = realloc(list->entries, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_entries) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }
        list->entries = new_entries;
        list->capacity = new_capacity;
    }
    list->entries[list->count++] = entry;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int update_entry(DynamicList *list, uint32_t RNTI, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->entries[i].RNTI == RNTI) {
            list->entries[i] = entry;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // Entry not found
}

int remove_entry(DynamicList *list, uint32_t RNTI) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->entries[i].RNTI == RNTI) {
            memmove(&list->entries[i], &list->entries[i + 1], (list->count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            --list->count;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // Entry not found
}

void calculate_md5_hashes(const char *directory) {
    DIR *dir = opendir(directory);
    if (!dir) {
        perror("Failed to open directory");
        return;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG) { // Regular file
            char file_path[1024];
            snprintf(file_path, sizeof(file_path), "%s/%s", directory, entry->d_name);

            FILE *file = fopen(file_path, "rb");
            if (!file) {
                perror("Failed to open file");
                continue;
            }

            struct stat file_stat;
            if (fstat(fileno(file), &file_stat) == -1) {
                perror("Failed to get file stats");
                fclose(file);
                continue;
            }

            MD5_CTX md5_ctx;
            MD5_Init(&md5_ctx);

            char buffer[MD5_BLOCK_SIZE];
            size_t bytes_read;
            while ((bytes_read = fread(buffer, 1, sizeof(buffer), file)) > 0) {
                MD5_Update(&md5_ctx, buffer, bytes_read);
            }

            fclose(file);

            unsigned char md5_hash[MD5_DIGEST_LENGTH];
            MD5_Final(md5_hash, &md5_ctx);

            char hexdigest[33];
            for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
                snprintf(&hexdigest[i * 2], 3, "%02x", md5_hash[i]);
            }

            printf("File: %s, MD5: %s\n", entry->d_name, hexdigest);
        }
    }

    closedir(dir);
}

