        newEntry->next = current->next;
        current->next = newEntry;
    }
    list->size++;
}

void updateEntry(DynamicList* list, int RNTI, bool CRC_INDICATION_REL8_TAG) {
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL && current->RNTI != RNTI) {
        current = current->next;
