    return list;
}

void add_entry(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->mutex);
    Entry* new_entry = (Entry*)malloc(sizeof(Entry));
    new_entry->pdu = pdu;
    new_entry->next = list->head;
    list->head = new_entry;
    list->count++;
    pthread_mutex_unlock(&list->mutex);
}

void update_entry(DynamicList* list, int RNTI, NFAPI_CRC_INDICATION_PDU_T pdu) {
