    Entry* current = list->head;
    while (current != NULL) {
        if (current->pdu.RNTI == RNTI) {
            current->pdu = pdu;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

void remove_entry(DynamicList* list, int RNTI) {
