    while (current != NULL) {
        if (current->pdu.RNTI == RNTI) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            list->count--;
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

