            if (buffer[i] == '\n') {
                line_count++;
            }
        }
    }

    fclose(input_file);
    fprintf(data->output_file, "Lines in %s: %d\n", data->filename ? data->filename : "-", line_count);
    return NULL;
}

void display_usage() {
    printf("Usage: program [options] <input_file>\n");
    printf("Options:\n");
    printf("  -h, --help        Display help message and exit.\n");
    printf("  -v, --version     Display version information and exit.\n");
    printf("  --manpage         Print the man page documentation.\n");
    printf("  -cs              Enable case-sensitive mode for line counting.\n");
    printf("  -o <output_file> Redirect output to a specified file instead of the standard output.\n");
}

void display_version() {
    printf("Version 1.0\n");
}

void display_manpage() {
    printf("Man page documentation...\n");
}

int main(int argc, char *argv[]) {
    // Parse command line arguments
    int case_sensitive = 0;
    FILE *output_file = stdout;

    for (int i = 1; i < argc; ++i) {
        if (!strcmp(argv[i], "-h") || !strcmp(argv[i], "--help")) {
            display_usage();
            return 0;
        } else if (!strcmp(argv[i], "-v") || !strcmp(argv[i], "--version")) {
            display_version();
            return 0;
        } else if (!strcmp(argv[i], "--manpage")) {
            display_manpage();
            return 0;
        } else if (!strcmp(argv[i], "-cs")) {
            case_sensitive = 1;
        } else if (!strcmp(argv[i], "-o") && i + 1 < argc) {
            output_file = fopen(argv[++i], "w");
            if (!output_file) {
                fprintf(stderr, "Error opening output file: %s\n", argv[i]);
                return 1;
            }
        } else if (argv[i][0] != '-') {
            // Input file
            break;
        } else {
            fprintf(stderr, "Invalid option: %s\n", argv[i]);
            display_usage();
            return 1;
        }
    }

    // Check for input file
    if (i == argc) {
        fprintf(stderr, "No input file provided.\n");
        display_usage();
        return 1;
    }

    ThreadArgs args = {argv[i], case_sensitive, output_file};
    pthread_t thread_id;
    int result = pthread_create(&thread_id, NULL, count_lines, &args);
    if (result != 0) {
        fprintf(stderr, "Error creating thread: %d\n", result);
        return 1;
    }

    pthread_join(thread_id, NULL);

    if (output_file != stdout) {
        fclose(output_file);
    }

    return 0;
}
