using System;
using System.Security.Cryptography;
using System.Text;
using System.Diagnostics;

public class HashGenerator
{
    public static string GenerateMD5HashWithLogging(string input)
    {
        using (MemoryStream memoryStream = new MemoryStream())
        {
            using (CryptoStream cryptoStream = new CryptoStream(memoryStream, MD5.Create().TransformBlock(input.ToCharArray(), 0, input.Length, null, 0), CryptoStreamMode.Write))
            {
                cryptoStream.FlushFinalBlock();
                byte[] hashBytes = memoryStream.ToArray();

                StringBuilder sb = new StringBuilder();
                foreach (byte b in hashBytes)
                {
                    sb.Append(b.ToString("x2"));
                }

                LogMemoryUsageAndPerformance(memoryStream.Length, Environment.TickCount);
                return sb.ToString();
            }
        }
    }

    private static void LogMemoryUsageAndPerformance(long memoryUsed, int ticks)
    {
        Debug.WriteLine($"Memory Used: {memoryUsed} bytes");
        Debug.WriteLine($"Ticks: {ticks}");
    }
}
