#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define NR_RLC_PDU_HEADER 16
#define MAX_ELEMENTS 1000000

typedef struct {
    char header[NR_RLC_PDU_HEADER];
    int SN;
    size_t DATA_LENGTH;
} NR_RLC_PDU;

typedef struct {
    NR_RLC_PDU *pdus;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
    FILE *log_file;
} PDU_Array;

PDU_Array* pdu_array_init() {
    PDU_Array *array = (PDU_Array *)malloc(sizeof(PDU_Array));
    if (!array) return NULL;
    array->pdus = (NR_RLC_PDU *)calloc(MAX_ELEMENTS, sizeof(NR_RLC_PDU));
    array->count = 0;
    array->capacity = MAX_ELEMENTS;
    pthread_mutex_init(&array->mutex, NULL);
    array->log_file = fopen("pdu_log.txt", "a");
    if (!array->log_file) {
        free(array);
        return NULL;
    }
    return array;
}

void pdu_array_destroy(PDU_Array *array) {
    pthread_mutex_lock(&array->mutex);
    free(array->pdus);
    fclose(array->log_file);
    pthread_mutex_unlock(&array->mutex);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int pdu_array_add(PDU_Array *array, NR_RLC_PDU pdu) {
    pthread_mutex_lock(&array->mutex);
    if (array->count >= array->capacity) {
        fprintf(stderr, "Array is full\n");
        pthread_mutex_unlock(&array->mutex);
        return -1;
    }
    for (size_t i = 0; i < array->count; i++) {
        if (array->pdus[i].SN == pdu.SN) {
            fprintf(array->log_file, "%s: Duplicate SN detected\n", __func__);
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
    }
    array->pdus[array->count++] = pdu;
    fprintf(array->log_file, "%s: Added PDU with SN %d\n", __func__, pdu.SN);
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

void pdu_array_compress(PDU_Array *array) {
    pthread_mutex_lock(&array->mutex);
    NR_RLC_PDU *new_pdus = (NR_RLC_PDU *)realloc(array->pdus, array->count * sizeof(NR_RLC_PDU));
    if (!new_pdus) {
        fprintf(stderr, "Realloc failed\n");
        pthread_mutex_unlock(&array->mutex);
        return;
    }
    array->pdus = new_pdus;
    array->capacity = array->count;
    fprintf(array->log_file, "%s: Compressed array to %zu elements\n", __func__, array->count);
    pthread_mutex_unlock(&array->mutex);
}

// Add more functions as per the task description
