#define MAX_NUMBERS 500000
#define MIN_VALUE 1.0
#define MAX_VALUE 100.0

// Function to calculate the average of numbers in an array
double calculate_average(double *numbers, int count) {
    double sum = 0.0;
    for (int i = 0; i < count; i++) {
        sum += numbers[i];
    }
    return sum / count;
}

// Main function to process floating-point numbers from standard input
void process_numbers() {
    double *numbers = NULL;
    int count = 0;

    // Dynamically allocate memory for the array of numbers
    numbers = (double *)malloc(MAX_NUMBERS * sizeof(double));
    if (numbers == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }

    // Read floating-point numbers from standard input
    while (scanf("%lf", &numbers[count]) != EOF && count < MAX_NUMBERS) {
        if (numbers[count] >= MIN_VALUE && numbers[count] <= MAX_VALUE) {
            count++;
        } else {
            fprintf(stderr, "Invalid number: %f. Number must be between %.2f and %.2f.\n", numbers[count], MIN_VALUE, MAX_VALUE);
        }
    }

    // Check if any valid numbers were read
    if (count == 0) {
        fprintf(stderr, "No valid numbers were read.\n");
        free(numbers);
        return;
    }

    // Calculate and print the average of the numbers
    double average = calculate_average(numbers, count);
    printf("Average: %.2f\n", average);

    // Free dynamically allocated memory
    free(numbers);
}

int main() {
    process_numbers();
    return 0;
}
