#include <pthread.h>
#include <stdlib.h>
#include <errno.h>

typedef struct {
    pthread_mutex_t* mutexes;
    int* priorities;
    int max_size;
    int current_size;
} MutexPool;

MutexPool* create_mutex_pool(int max_size) {
    if (max_size <= 0) {
        return NULL;
    }
    MutexPool* pool = (MutexPool*)malloc(sizeof(MutexPool));
    if (!pool) {
        return NULL;
    }
    pool->mutexes = (pthread_mutex_t*)calloc(max_size, sizeof(pthread_mutex_t));
    if (!pool->mutexes) {
        free(pool);
        return NULL;
    }
    pool->priorities = (int*)calloc(max_size, sizeof(int));
    if (!pool->priorities) {
        free(pool->mutexes);
        free(pool);
        return NULL;
    }
    pool->max_size = max_size;
    pool->current_size = 0;
    for (int i = 0; i < max_size; ++i) {
        pthread_mutex_init(&pool->mutexes[i], NULL);
    }
    return pool;
}

void destroy_mutex_pool(MutexPool* pool) {
    if (!pool) {
        return;
    }
    for (int i = 0; i < pool->current_size; ++i) {
        pthread_mutex_destroy(&pool->mutexes[i]);
    }
    free(pool->priorities);
    free(pool->mutexes);
    free(pool);
}

int mutex_pool_lock(MutexPool* pool, int index, int priority, struct timespec* timeout) {
    if (!pool || index < 0 || index >= pool->current_size || priority < 0) {
        errno = EINVAL;
        return -1;
    }
    while (pthread_mutex_timedlock(&pool->mutexes[index], timeout) != 0) {
        if (errno == ETIMEDOUT) {
            return -1; // Timeout occurred
        } else if (errno != EBUSY) {
            return -1; // Other error
        }
        // Backoff strategy: exponential backoff with jitter
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = (rand() % 100 + 1) * 1000000; // 1 to 100 microseconds
        nanosleep(&delay, NULL);
    }
    return 0;
}

int mutex_pool_unlock(MutexPool* pool, int index) {
    if (!pool || index < 0 || index >= pool->current_size) {
        errno = EINVAL;
        return -1;
    }
    pthread_mutex_unlock(&pool->mutexes[index]);
    return 0;
}
```

