#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_MUTEXES 20

typedef struct {
    pthread_mutex_t *mutexes;
    int max_size;
    int current_count;
} MutexPool;

MutexPool *create_mutex_pool(int size) {
    if (size > MAX_MUTEXES) {
        return NULL; // Exceeds maximum allowed mutexes
    }
    MutexPool *pool = (MutexPool *)malloc(sizeof(MutexPool));
    pool->mutexes = (pthread_mutex_t *)calloc(size, sizeof(pthread_mutex_t));
    pool->max_size = size;
    pool->current_count = 0;
    return pool;
}

void delete_mutex_pool(MutexPool *pool) {
    if (pool == NULL || pool->mutexes == NULL) {
        return; // Invalid or already deleted pool
    }
    for (int i = 0; i < pool->current_count; i++) {
        pthread_mutex_destroy(&pool->mutexes[i]);
    }
    free(pool->mutexes);
    free(pool);
}

int create_mutex(MutexPool *pool) {
    if (pool == NULL || pool->mutexes == NULL || pool->current_count >= pool->max_size) {
        return -1; // Pool is invalid or already at maximum capacity
    }
    int mutex_index = pool->current_count;
    pthread_mutex_init(&pool->mutexes[mutex_index], NULL);
    pool->current_count++;
    return 0;
}

void destroy_mutex(MutexPool *pool, int index) {
    if (pool == NULL || pool->mutexes == NULL || index < 0 || index >= pool->current_count) {
        return; // Invalid or out-of-bounds index
    }
    pthread_mutex_destroy(&pool->mutexes[index]);
    for (int i = index; i < pool->current_count - 1; i++) {
        pool->mutexes[i] = pool->mutexes[i + 1];
    }
    pool->current_count--;
}

int lock_mutex(MutexPool *pool, int index) {
    if (pool == NULL || pool->mutexes == NULL || index < 0 || index >= pool->current_count) {
        return -1; // Invalid or out-of-bounds index
    }
    pthread_mutex_lock(&pool->mutexes[index]);
    return 0;
}

int try_lock_mutex(MutexPool *pool, int index) {
    if (pool == NULL || pool->mutexes == NULL || index < 0 || index >= pool->current_count) {
        return -1; // Invalid or out-of-bounds index
    }
    return pthread_mutex_trylock(&pool->mutexes[index]);
}

int timed_lock_mutex(MutexPool *pool, int index, struct timespec *timeout) {
    if (pool == NULL || pool->mutexes == NULL || index < 0 || index >= pool->current_count || timeout == NULL) {
        return -1; // Invalid or out-of-bounds index or null timeout
    }
    return pthread_mutex_timedlock(&pool->mutexes[index], timeout);
}

int unlock_mutex(MutexPool *pool, int index) {
    if (pool == NULL || pool->mutexes == NULL || index < 0 || index >= pool->current_count) {
        return -1; // Invalid or out-of-bounds index
    }
    pthread_mutex_unlock(&pool->mutexes[index]);
    return 0;
}

void set_backoff_duration(int *backoff, int attempt) {
    *backoff = (int)(pow(2, attempt)) * 100000; // Logarithmic backoff in microseconds
}

int main() {
    MutexPool *pool = create_mutex_pool(MAX_MUTEXES);
    if (pool == NULL) {
        printf("Failed to create mutex pool.\n");
        return 1;
    }

    int mutex_index;
    if (create_mutex(pool, &mutex_index) != 0) {
        printf("Failed to create mutex.\n");
        delete_mutex_pool(pool);
        return 1;
    }

    struct timespec timeout = {2, 0}; // 2 seconds
    int ret = timed_lock_mutex(pool, mutex_index, &timeout);
    if (ret != 0) {
        printf("Failed to lock mutex with timeout.\n");
    } else {
        printf("Mutex locked successfully.\n");
        unlock_mutex(pool, mutex_index);
    }

    destroy_mutex(pool, mutex_index);
    delete_mutex_pool(pool);

    return 0;
}
