import java.io.*;
import javax.crypto.*;
import javax.crypto.spec.*;
import org.apache.commons.codec.digest.*;

public class ObjectSerializer {

    private static final String KEY = "your-secret-key"; // Replace with a secure key from KMS

    public static <T> T deserialize(byte[] data, Class<T> clazz) {
        try {
            byte[] decryptedData = decrypt(data);
            ByteArrayInputStream bis = new ByteArrayInputStream(decryptedData);
            ObjectInputStream ois = new ObjectInputStream(bis);
            T obj = clazz.cast(ois.readObject());
            ois.close();
            return obj;
        } catch (IOException | ClassNotFoundException e) {
            throw new RuntimeException("Deserialization failed", e);
        }
    }

    private static byte[] decrypt(byte[] data) throws Exception {
        SecretKeySpec secretKey = new SecretKeySpec(KEY.getBytes(), "AES");
        Cipher cipher = Cipher.getInstance("AES/ECB/PKCS5Padding");
        cipher.init(Cipher.DECRYPT_MODE, secretKey);
        return cipher.doFinal(data);
    }

