typedef struct Entry {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Entry *next;
} Entry;

typedef struct DynamicList {
    Entry *head;
    size_t count;
    pthread_mutex_t lock;
} DynamicList;

void initDynamicList(DynamicList *list) {
    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

int addEntry(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T data) {
    Entry *newEntry = (Entry *)malloc(sizeof(Entry));
    if (!newEntry) {
        return -1; // Out of memory
    }
    newEntry->data = data;
    newEntry->next = list->head;
    pthread_mutex_lock(&list->lock);
    list->head = newEntry;
    list->count++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int updateEntry(DynamicList *list, int RNTI, NFAPI_CRC_INDICATION_PDU_T newData) {
    Entry *current = list->head;
    while (current) {
        if (current->data.RNTI == RNTI) {
            pthread_mutex_lock(&list->lock);
            current->data = newData;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        current = current->next;
    }
    return -1; // Entry not found
}

int removeEntry(DynamicList *list, int RNTI) {
    Entry *current = list->head;
    Entry *prev = NULL;
    while (current) {
        if (current->data.RNTI == RNTI) {
            pthread_mutex_lock(&list->lock);
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            free(current);
            list->count--;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        prev = current;
        current = current->next;
    }
    return -1; // Entry not found
}

double calculateAverageMCS(DynamicList *list) {
    double sum = 0;
    size_t count = 0;
    Entry *current = list->head;
    while (current) {
        sum += current->data.PUSCH_MCS;
        count++;
        current = current->next;
    }
    return count > 0 ? sum / count : 0;
}

// Implement additional functions for standard deviation, logging, and thread safety as per requirements.

void destroyDynamicList(DynamicList *list) {
    Entry *current = list->head;
    while (current) {
        Entry *temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
}
