} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* crc_indication_list[MAX_LIST_SIZE];
int current_index = 0;

void log_error(const char* error_message) {
    FILE* error_file = fopen("crc_indication_errors.log", "a");
    if (error_file) {
        fprintf(error_file, "%s\n", error_message);
        fclose(error_file);
    }
}

int generate_unique_rnti(int *rntis_used, int count) {
    while (1) {
        int rnti = rand() % (MAX_RNTI - MIN_RNTI + 1) + MIN_RNTI;
        if (!rntis_used[rnti]) {
            rntis_used[rnti] = 1;
            return rnti;
        }
    }
}

void* populate_crc_indication_list(void* seed_ptr) {
    unsigned int seed = *(unsigned int*)seed_ptr;
    srand(seed);
    int rntis_used[MAX_RNTI + 1] = {0};

    pthread_mutex_lock(&list_lock);
    for (int i = current_index; i < current_index + MAX_LIST_SIZE && i < MAX_LIST_SIZE; i++) {
        if (!crc_indication_list[i]) {
