        crc_indication_list[i]->CRC_INDICATION_REL8_TAG = (rand() % 2) ? 'Y' : 'N';
    }
    pthread_mutex_unlock(&list_lock);

    current_index += MAX_LIST_SIZE;
    return NULL;
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <seed>\n", argv[0]);
        return 1;
    }

    unsigned int seed = atoi(argv[1]);

    pthread_t threads[5];
    for (int i = 0; i < 5; i++) {
        if (pthread_create(&threads[i], NULL, populate_crc_indication_list, &seed) != 0) {
            fprintf(stderr, "Failed to create thread %d\n", i);
            return 1;
        }
    }

    for (int i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
