    pthread_mutex_t lock;
} CRCIndicationList;

void initializeCRCIndicationList(CRCIndicationList *list) {
    list->count = 0;
    list->capacity = 1000;
    list->list = malloc(list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list->list == NULL) {
        perror("Failed to allocate memory for CRCIndicationList");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&list->lock, NULL);
