    if (list->count >= MAX_LIST_SIZE) {
        fprintf(stderr, "Maximum list size reached\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    if (RNTI < MIN_RNTI || RNTI > MAX_RNTI) {
        fprintf(stderr, "Invalid RNTI value: %d\n", RNTI);
