        if (list->list[i].CRCFLAG != 0 && list->list[i].CRCFLAG != 1) {
            fprintf(errorFile, "Invalid CRCFLAG at index %zu: %d\n", i, list->list[i].CRCFLAG);
        }
    }
    fclose(errorFile);
}

