            RNTI = rand() % (MAX_RNTI - MIN_RNTI + 1) + MIN_RNTI;
        } while (!addCRCIndicationToQueue(&list, RX_UE_INFORMATION_TAG, RNTI, rand() % 2));
    }

    validateCRCIndications(&list);
    freeCRCIndicationList(&list);

    return 0;
}
