    if (list->count >= list->max_size) {
        // Reduce the size to handle memory pressure
        list->max_size /= 2;
        list->list = realloc(list->list, list->max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    NFAPI_CRC_INDICATION_PDU_T* new_item = &list->list[list->count++];
    new_item->RX_UE_INFORMATION_TAG = rx_tag;
    new_item->RNTI = rnti;
    new_item->CRC_INDICATION_REL8_TAG = 0; // Assuming a fixed tag value
