Logger logger;

void init_logger() {
    logger.logs = NULL;
    logger.size = 0;
    logger.capacity = 1024;
    pthread_mutex_init(&logger.lock, NULL);
}

void resize_logger() {
    logger.capacity *= 2;
    logger.logs = realloc(logger.logs, logger.capacity * sizeof(LogEntry));
}

void log_message(int level, const char* format, ...) {
    va_list args;
    va_start(args, format);

    time_t now = time(NULL);
    struct tm* local_time = localtime(&now);

    pthread_mutex_lock(&logger.lock);

    if (logger.size >= logger.capacity) {
        resize_logger();
    }

    snprintf(logger.logs[logger.size].message, sizeof(LogEntry.message), "%04d-%02d-%02d %02d:%02d:%02d [%d] ", local_time->tm_year + 1900, local_time->tm_mon + 1, local_time->tm_mday, local_time->tm_hour, local_time->tm_min, local_time->tm_sec, level);
    vsnprintf(logger.logs[logger.size].message + strlen(logger.logs[logger.size].message), sizeof(LogEntry.message) - strlen(logger.logs[logger.size].message), format, args);

    logger.size++;
    pthread_mutex_unlock(&logger.lock);

    va_end(args);
}

