#include <vector>
#include <fstream>
#include <mutex>

class MatrixModifier {
private:
    std::vector<std::vector<int>> matrix;
    std::ofstream logFile;
    std::mutex mtx;

public:
    MatrixModifier(const std::string& logFilePath) : logFile(logFilePath, std::ios::app), mtx() {}

    void modifyMatrix(std::vector<std::vector<int>>& inputMatrix, int target, int value) {
        std::lock_guard<std::mutex> lock(mtx);

        bool found = false;
        for (auto& row : inputMatrix) {
            if (std::find(row.begin(), row.end(), target) != row.end()) {
                std::replace(row.begin(), row.end(), target, value);
                logFile << "Replaced " << target << " with " << value << " in the matrix.\n";
                found = true;
                break;
            }
        }

        if (!found) {
            inputMatrix.push_back({value});
            logFile << "Appended a new row containing " << value << "\n";
        }
    }
};

int main() {
    MatrixModifier modifier("matrix_operations.log");
    std::vector<std::vector<int>> matrix = {{1, 2, 3}, {4, 5, 6}};
    int target = 5;
    int value = 7;

    modifier.modifyMatrix(matrix, target, value);

    return 0;
}
```

