using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;

public class AsyncBatchHttpProcessor
{
    public static async Task<List<string>> ProcessAsync(List<string> urls, CancellationToken cancellationToken, int maxConcurrency)
    {
        var tasks = new List<Task<string>>();
        using (HttpClient client = new HttpClient())
        {
            foreach (var url in urls)
            {
                tasks.Add(client.GetStringAsync(url).ContinueWith(t => t.Result, TaskContinuationOptions.OnlyOnRanToCompletion, cancellationToken, TaskScheduler.Default));
            }
        }

        var results = new List<string>();
        int completedTasks = 0;
        while (completedTasks < tasks.Count)
        {
            await Task.WhenAny(tasks);
            for (int i = 0; i < tasks.Count; i++)
            {
                if (tasks[i].IsCompleted && !results.Contains(tasks[i].Result))
                {
                    results.Add(tasks[i].Result);
                    completedTasks++;
                }
            }
        }

        return results;
    }
}
