using System;
using System.Collections.Generic;
using System.Data;
using System.Data.Common;

public class SqlHelper
{
    private readonly string _providerName;
    private readonly string _connectionString;

    public SqlHelper(string providerName, string connectionString)
    {
        _providerName = providerName;
        _connectionString = connectionString;
    }

    public IDataReader ExecuteQuery(string commandText, List<SqlParameter> parameters)
    {
        using (DbProviderFactory factory = DbProviderFactories.GetFactory(_providerName))
        {
            using (IDbConnection connection = factory.CreateConnection())
            {
                if (connection == null)
                    throw new InvalidOperationException("Invalid database provider.");

                connection.ConnectionString = _connectionString;
                IDbCommand command = factory.CreateCommand();
                command.Connection = connection;
                command.CommandText = commandText;

                foreach (var parameter in parameters)
                {
                    if (parameter.Value == null)
                        parameter.DbType = DbType.Object; // Handle null values
                    command.Parameters.Add(parameter);
                }

                try
                {
                    connection.Open();
                    return command.ExecuteReader(CommandBehavior.CloseConnection);
                }
                catch (Exception ex)
                {
                    throw new InvalidOperationException("Database error: " + ex.Message, ex);
                }
            }
        }
    }
}
```

