using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Text.RegularExpressions;
using System.Threading.Tasks;
using System.Xml.XPath;

public class XmlFetcher
{
    private readonly HttpClient _httpClient;
    private XPathDocument _cachedXmlDocument;
    private readonly object _cacheLock = new object();
    private readonly TimeSpan[] _retryIntervals = { TimeSpan.FromMilliseconds(100), TimeSpan.FromSeconds(2), TimeSpan.FromSeconds(5), TimeSpan.FromSeconds(10) };
    private const int MaxRetries = 3;

    public XmlFetcher(HttpClient httpClient)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
    }

    public async Task<List<XPathNavigator>> FetchAndParseXmlAsync(string url, string elementNamePattern)
    {
        for (int attempt = 0; attempt <= MaxRetries; attempt++)
        {
            try
            {
                var xmlDocument = await GetXmlDocumentAsync(url);
                return ParseXmlDocument(xmlDocument, elementNamePattern);
            }
            catch (HttpRequestException)
            {
                if (attempt == MaxRetries) throw;
                await Task.Delay(_retryIntervals[attempt]);
            }
        }

        throw new InvalidOperationException("Failed to fetch and parse XML after multiple retries.");
    }

    private async Task<XPathDocument> GetXmlDocumentAsync(string url)
    {
        lock (_cacheLock)
        {
            if (_cachedXmlDocument != null) return _cachedXmlDocument;
        }

        using (var response = await _httpClient.GetAsync(url))
        {
            response.EnsureSuccessStatusCode();
            var xmlContent = await response.Content.ReadAsStringAsync();
            lock (_cacheLock)
            {
                _cachedXmlDocument = new XPathDocument(new StringReader(xmlContent));
            }
            return _cachedXmlDocument;
        }
    }

    private List<XPathNavigator> ParseXmlDocument(XPathDocument xmlDoc, string elementNamePattern)
    {
        var navigator = xmlDoc.CreateNavigator();
        var nodes = navigator.Select($"//{elementNamePattern}").Cast<XPathNavigator>().ToList();

        nodes.Sort((n1, n2) =>
        {
            int posCompare = n1.GetAttribute("position", String.Empty).CompareTo(n2.GetAttribute("position", String.Empty));
            if (posCompare != 0) return posCompare;

            return string.Compare(n1.Value, n2.Value, StringComparison.Ordinal);
        });

        return nodes;
    }
}
