import java.io.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class CodeGenerator {

    public static void main(String[] args) {
        generateRandomStringAndHashPassword();
    }

    public static String generateRandomStringAndHashPassword() {
        String charset = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
        int length = 10;
        String randomString = generateRandomString(charset, length);
        String hashedPassword = hashPassword("password123", "SHA-256");
        return "Random String: " + randomString + "\nHashed Password: " + hashedPassword;
    }

    private static String generateRandomString(String charset, int length) {
        StringBuilder sb = new StringBuilder();
        Random random = new Random();
        for (int i = 0; i < length; i++) {
            int index = random.nextInt(charset.length());
            sb.append(charset.charAt(index));
        }
        return sb.toString();
    }

    private static String hashPassword(String password, String algorithm) {
        try {
            MessageDigest md = MessageDigest.getInstance(algorithm);
            byte[] hashedBytes = md.digest(password.getBytes());
            StringBuilder sb = new StringBuilder();
            for (byte b : hashedBytes) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Unsupported hash algorithm: " + algorithm, e);
        }
    }
}
```

