from django.http import JsonResponse
from django.db import transaction

def manage_product(request):
    product_id = request.POST.get('product_id')
    url = request.POST.get('url')
    tags = request.POST.getlist('tags[]')
    action = request.POST.get('action')

    attribute_names = ['name', 'price', 'description']

    if action == 'delete':
        # Assuming Product is a Django model
        try:
            product = Product.objects.get(id=product_id)
            product.delete()
            return JsonResponse({'message': 'success'})
        except Product.DoesNotExist:
            return JsonResponse({'message': 'error'}, status=404)

    with transaction.atomic():
        if product_id:
            # Fetch existing product
            product = Product.objects.get(id=product_id)
        else:
            # Create new product
            product = Product()

        for attr_name in attribute_names:
            if attr_name in request.POST:
                setattr(product, attr_name, request.POST[attr_name])

        # Dynamically update tags
        product.tags.set(tags)

        # Save the changes to the database
        product.save()

    return JsonResponse({'message': 'success'})

def recommend_products(request):
    product_id = request.GET.get('product_id')
    # Assuming Product is a Django model and has related products through a ManyToMany relationship
    try:
        product = Product.objects.get(id=product_id)
        related_products = product.related_products.all()
        return JsonResponse({'recommendations': [p.id for p in related_products]})
    except Product.DoesNotExist:
        return JsonResponse({'message': 'error'}, status=404)
