// JavaScript function for copying bytes from buffered data chunks
function copyBytesFromBuffers(buffers, byteCount) {
    const totalLength = buffers.reduce((acc, buffer) => acc + buffer.length, 0);

    if (byteCount > totalLength) {
        throw new Error('Requested byte count exceeds available data');
    }

    let copiedData = Buffer.alloc(byteCount);
    let bytesRead = 0;

    for (const buffer of buffers) {
        const bytesToCopy = Math.min(byteCount - bytesRead, buffer.length);
        buffer.copy(copiedData, bytesRead, 0, bytesToCopy);
        bytesRead += bytesToCopy;
        if (bytesRead === byteCount) break;
    }

    return copiedData;
}

// C function for appending a slash to a string if it does not exceed the size limit
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* appendSlashIfWithinLimit(const char* input, size_t maxSize) {
    if (input == NULL || maxSize == 0) return NULL;

    size_t inputLength = strlen(input);
    if (inputLength >= maxSize - 1) return NULL; // Not enough space for slash and null terminator

    char* result = malloc((inputLength + 2) * sizeof(char)); // +1 for '/', +1 for null terminator
    if (result == NULL) return NULL;

    strcpy(result, input);
    result[inputLength] = '/';
    result[inputLength + 1] = '\0';

    return result;
}
```

