class TokenManager {
public:
    struct Token {
        std::string access_token;
        int expires_in;
        std::string token_type;
        std::optional<std::string> refresh_token;
    };

    bool validateToken(const Token& token) {
        return token.token_type == "Bearer" && 
               token.expires_in > 0 && 
               !token.access_token.empty() &&
               !token.token_type.empty();
    }

    void insertAfter(std::list<Token>::iterator targetToken, const Token& newToken) {
        if (targetToken != tokens_.end()) {
            tokens_.insert(targetToken, newToken);
        } else {
            tokens_.push_back(newToken);
        }
    }

private:
    std::list<Token> tokens_;
};

std::string md5(const std::string& str) {
    unsigned char hash[MD5_DIGEST_LENGTH];
    MD5_CTX md5;
    MD5_Init(&md5);
    MD5_Update(&md5, str.c_str(), str.length());
    MD5_Final(hash, &md5);

    std::stringstream ss;
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        ss << std::hex << std::setw(2) << std::setfill('0') << static_cast<int>(hash[i]);
    }
    return ss.str();
}

