#include <string.h>

#define MAX_PACKETS 10000

typedef struct Packet {
    char sourceIP[46]; // IPv4: 15 + ":port" or IPv6: 39 + ":port"
    char destinationIP[46];
    int protocolType;
    int TTL;
    struct Packet *next;
} Packet;

typedef struct Queue {
    Packet *front;
    Packet *rear;
} Queue;

Queue* createQueue() {
    Queue *queue = (Queue*)malloc(sizeof(Queue));
    queue->front = queue->rear = NULL;
    return queue;
}

int isEmpty(Queue *queue) {
    return (queue->front == NULL);
}

void enqueue(Queue *queue, char sourceIP[], char destinationIP[], int protocolType, int TTL) {
    if (queue->rear == MAX_PACKETS) {
        printf("Queue is full\n");
        return;
    }
    Packet *newPacket = (Packet*)malloc(sizeof(Packet));
    strcpy(newPacket->sourceIP, sourceIP);
    strcpy(newPacket->destinationIP, destinationIP);
    newPacket->protocolType = protocolType;
    newPacket->TTL = TTL;
    newPacket->next = NULL;

    if (isEmpty(queue)) {
        queue->front = queue->rear = newPacket;
    } else {
        queue->rear->next = newPacket;
        queue->rear = newPacket;
    }
}

Packet* dequeue(Queue *queue) {
    if (isEmpty(queue)) {
        printf("Queue is empty\n");
        return NULL;
    }
    Packet *temp = queue->front;
    if (queue->front == queue->rear) {
        queue->front = queue->rear = NULL;
    } else {
        queue->front = queue->front->next;
    }
    return temp;
}

void freeQueue(Queue *queue) {
    while (!isEmpty(queue)) {
        Packet *temp = dequeue(queue);
        free(temp);
    }
    free(queue);
}

int main() {
    Queue *queue = createQueue();

    enqueue(queue, "192.168.1.1:5000", "10.0.0.1:5001", 6, 64);
    enqueue(queue, "2001:db8::1:5000", "2001:db8::2:5001", 6, 64);

    Packet *packet = dequeue(queue);
    if (packet != NULL) {
        printf("Dequeued packet - Source IP: %s\n", packet->sourceIP);
        free(packet);
    }

    freeQueue(queue);

    return 0;
}
```

This code snippet defines a simple dynamic queue for managing packet headers. It includes functions to create, enqueue, and dequeue packets, as well as free the memory allocated for the queue. The `Packet` structure is designed to hold metadata for both IPv4 and IPv6 addresses, making it versatile for different network protocols.']

