#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PACKETS 10000
#define PACKET_SIZE 256
#define ALLOC_CHUNK 1024

typedef struct packet_header {
    char source_ip[48];
    char destination_ip[48];
    uint8_t protocol;
    uint8_t ttl;
    // Add other metadata fields as needed
} packet_header;

typedef struct packet_node {
    packet_header header;
    struct packet_node *next;
} packet_node;

typedef struct queue {
    packet_node *front, *rear;
    int size;
    pthread_mutex_t lock;
    pthread_cond_t not_full, not_empty;
} queue;

queue* create_queue() {
    queue *q = (queue*)malloc(sizeof(queue));
    if (!q) return NULL;
    q->front = q->rear = NULL;
    q->size = 0;
    pthread_mutex_init(&q->lock, NULL);
    pthread_cond_init(&q->not_full, NULL);
    pthread_cond_init(&q->not_empty, NULL);
    return q;
}

void enqueue(queue *q, packet_header header) {
    pthread_mutex_lock(&q->lock);
    while (q->size >= MAX_PACKETS) {
        pthread_cond_wait(&q->not_full, &q->lock);
    }
    packet_node *new_node = (packet_node*)malloc(ALLOC_CHUNK * sizeof(packet_node));
    if (!new_node) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&q->lock);
        return;
    }
    new_node->header = header;
    new_node->next = NULL;
    if (q->rear == NULL) q->front = q->rear = new_node;
    else {
        q->rear->next = new_node;
        q->rear = new_node;
    }
    q->size++;
    pthread_cond_signal(&q->not_empty);
    pthread_mutex_unlock(&q->lock);
}

packet_header dequeue(queue *q) {
    packet_header header;
    pthread_mutex_lock(&q->lock);
    while (q->size == 0) {
        pthread_cond_wait(&q->not_empty, &q->lock);
    }
    if (q->front != NULL) {
        header = q->front->header;
        free(q->front);
        q->front = q->front->next;
        if (q->front == NULL) q->rear = NULL;
        q->size--;
        pthread_cond_signal(&q->not_full);
    }
    pthread_mutex_unlock(&q->lock);
    return header;
}

void destroy_queue(queue *q) {
    packet_node *current = q->front, *next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&q->lock);
    pthread_cond_destroy(&q->not_full);
    pthread_cond_destroy(&q->not_empty);
    free(q);
}
