typedef struct {
    LTE_RRC_CONNECTION_RECONFIGURATION_COMPLETE message;
    BWP *bwp_list;
} RRC_Message;

// Function to dynamically generate messages
RRC_Message* generate_rrc_messages(int num_ues, int max_bwp_per_ue) {
    RRC_Message* messages = (RRC_Message*)malloc(num_ues * sizeof(RRC_Message));
    if (messages == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_ues; i++) {
        // Initialize message and BWP list
        memset(&messages[i].message, 0, sizeof(LTE_RRC_CONNECTION_RECONFIGURATION_COMPLETE));
        messages[i].bwp_list = (BWP*)malloc(max_bwp_per_ue * sizeof(BWP));
        if (messages[i].bwp_list == NULL) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }

        // Populate IMSI and RRC connection ID for demonstration
        snprintf(messages[i].message.imsi, 16, "IMSI%05d", i + 1);
        messages[i].message.rrc_connection_id = i * 10;

        // Randomly populate BWP parameters for demonstration
        for (int j = 0; j < max_bwp_per_ue; j++) {
            messages[i].bwp_list[j].bandwidth = rand() % 50 + 1;
            messages[i].bwp_list[j].center_frequency = rand() % 1000 + 1000;
        }

        // Set the number of BWP in the message
        messages[i].message.bwp_count = max_bwp_per_ue - (rand() % 3); // Randomly missing some BWPs
    }

    return messages;
}

// Function to clean up allocated memory
void free_rrc_messages(RRC_Message* messages, int num_ues) {
    for (int i = 0; i < num_ues; i++) {
        free(messages[i].bwp_list);
    }
    free(messages);
}

int main() {
    int num_ues = 10;
    int max_bwp_per_ue = 3;

    RRC_Message* messages = generate_rrc_messages(num_ues, max_bwp_per_ue);

    // Example usage of the generated messages
    for (int i = 0; i < num_ues; i++) {
        printf("UE %s, RRC ID %d, BWP Count %d\n", messages[i].message.imsi, 
               messages[i].message.rrc_connection_id, messages[i].message.bwp_count);
    }

    free_rrc_messages(messages, num_ues);

    return 0;
}
