    srand(seed);
    pthread_mutex_lock(&mutex);
    list_size = rand() % (MAX_LIST_SIZE - MIN_LIST_SIZE + 1) + MIN_LIST_SIZE;
    crc_indication_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(list_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
