#define MAX_LIST_SIZE 50000
#define MIN_LIST_SIZE 10000
#define STRUCT_CACHE_SIZE 1000
#define MAX_CPU_USAGE 80
#define CHECK_INTERVAL_SECONDS 300

typedef struct {
    int rx_ue_info_tag;
    int rnti;
    unsigned char crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *cache[STRUCT_CACHE_SIZE];
    int cache_size;
    pthread_mutex_t cache_lock;
} StructCache;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list;
    int list_size;
    int max_list_size;
    int current_cache_size;
    StructCache *cache;
    FILE *error_log;
    pthread_mutex_t list_lock;
    // Add other necessary variables for CPU usage monitoring, logging system integration, and network simulation framework support
} CrcIndicationManager;

void init_crm(CrcIndicationManager *crm) {
    crm->list = NULL;
    crm->list_size = 0;
    crm->max_list_size = MAX_LIST_SIZE;
    crm->current_cache_size = 0;
    crm->cache = (StructCache *)malloc(sizeof(StructCache));
    pthread_mutex_init(&crm->cache_lock, NULL);
    pthread_mutex_init(&crm->list_lock, NULL);
    crm->error_log = fopen("crc_indication_errors.log", "w");
}

void deinit_crm(CrcIndicationManager *crm) {
    // Free allocated memory and resources
    free(crm->cache);
    fclose(crm->error_log);
}

NFAPI_CRC_INDICATION_PDU_T *get_struct_from_cache(CrcIndicationManager *crm) {
    pthread_mutex_lock(&crm->cache_lock);
    if (crm->current_cache_size > 0) {
        NFAPI_CRC_INDICATION_PDU_T *ptr = crm->cache[--crm->current_cache_size];
        pthread_mutex_unlock(&crm->cache_lock);
        return ptr;
    }
    pthread_mutex_unlock(&crm->cache_lock);
    return (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void put_struct_in_cache(CrcIndicationManager *crm, NFAPI_CRC_INDICATION_PDU_T *ptr) {
    pthread_mutex_lock(&crm->cache_lock);
    if (crm->current_cache_size < STRUCT_CACHE_SIZE) {
        crm->cache[crm->current_cache_size++] = ptr;
    }
    pthread_mutex_unlock(&crm->cache_lock);
}

void add_crc_indication(CrcIndicationManager *crm, int rx_ue_info_tag, int rnti, unsigned char crc_flag) {
    NFAPI_CRC_INDICATION_PDU_T *ptr = get_struct_from_cache(crm);
    if (ptr == NULL) {
        return;
    }
    ptr->rx_ue_info_tag = rx_ue_info_tag;
    ptr->rnti = rnti;
    ptr->crc_flag = crc_flag;

    pthread_mutex_lock(&crm->list_lock);
    if (crm->list_size < crm->max_list_size) {
        crm->list[crm->list_size++] = *ptr;
    } else {
        // Log error
    }
    pthread_mutex_unlock(&crm->list_lock);

    put_struct_in_cache(crm, ptr);
}

void check_crc_indications(CrcIndicationManager *crm) {
    for (int i = 0; i < crm->list_size; i++) {
        if (crm->list[i].crc_flag != 1 && crm->list[i].crc_flag != 0) {
            fprintf(crm->error_log, "Invalid CRC flag: %d, RX_UE_INFO_TAG: %d, RNTI: %d\n", 
                    crm->list[i].crc_flag, crm->list[i].rx_ue_info_tag, crm->list[i].rnti);
        }
    }
}

// Add other necessary functions for CPU usage monitoring, logging system integration, and network simulation framework support

int main() {
    CrcIndicationManager crm;
    init_crm(&crm);

    srand(time(NULL));
    for (int i = 0; i < 15000; i++) {
        int rx_ue_info_tag = rand() % 10000 + 1;
        int rnti = rand() % 2048 + 1;
        unsigned char crc_flag = rand() % 2;
        add_crc_indication(&crm, rx_ue_info_tag, rnti, crc_flag);
    }

    check_crc_indications(&crm);

    deinit_crm(&crm);
    return 0;
}
