#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_CONNECTIONS 1000
#define MIN_CHANNEL 1
#define MAX_CHANNEL 16
#define DEFAULT_SIGNAL_STRENGTH -85

typedef struct WIFI_CONNECTION_INFO_T {
    char ssid[32];
    int channel;
    int signal_strength;
} WIFI_CONNECTION_INFO_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void generate_random_string(char *str, size_t length) {
    static const char characters[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    for (size_t i = 0; i < length - 1; ++i) {
        str[i] = characters[rand() % (sizeof(characters) - 1)];
    }
    str[length - 1] = '\0';
}

WIFI_CONNECTION_INFO_T* create_connection_list(int seed, int max_connections) {
    pthread_mutex_lock(&mutex);
    srand(seed);

    WIFI_CONNECTION_INFO_T* connections = malloc(max_connections * sizeof(WIFI_CONNECTION_INFO_T));
    if (connections == NULL) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    for (int i = 0; i < max_connections; ++i) {
        do {
            generate_random_string(connections[i].ssid, sizeof(connections[i].ssid));
        } while (i > 0 && strcmp(connections[i - 1].ssid, connections[i].ssid) == 0);

        connections[i].channel = MIN_CHANNEL + rand() % (MAX_CHANNEL - MIN_CHANNEL + 1);
        connections[i].signal_strength = DEFAULT_SIGNAL_STRENGTH + rand() % 41;
    }

    pthread_mutex_unlock(&mutex);
    return connections;
}

int validate_connections(WIFI_CONNECTION_INFO_T* connections, int count) {
    for (int i = 0; i < count; ++i) {
        if (connections[i].signal_strength < -120 || connections[i].signal_strength > -40) {
            fprintf(stderr, "Invalid signal strength: %d\n", connections[i].signal_strength);
            return 0;
        }
    }
    return 1;
}

void log_error(const char* message) {
    FILE* file = fopen("connection_errors.log", "a");
    if (file != NULL) {
        fprintf(file, "%s\n", message);
        fclose(file);
    } else {
        perror("Failed to open error log");
    }
}

int main() {
    int seed = time(NULL);
    WIFI_CONNECTION_INFO_T* connections = create_connection_list(seed, MAX_CONNECTIONS);

    if (connections == NULL) {
        return 1;
    }

    if (!validate_connections(connections, MAX_CONNECTIONS)) {
        log_error("Validation failed");
    }

    free(connections);
    return 0;
}
