// Define NFAPI_CRC_INDICATION_PDU_T structure and other necessary types here

#define MAX_LIST_SIZE 1200
#define DEFAULT_SEED time(NULL)

typedef struct {
    // Define fields for RX_UE_INFORMATION_TAG, RNTI, CRCFLAG, etc.
} NFAPI_CRC_INDICATION_PDU_T;

// Memory pool implementation
NFAPI_CRC_INDICATION_PDU_T* memory_pool[MAX_LIST_SIZE];
int pool_index = 0;
pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate memory from the pool
NFAPI_CRC_INDICATION_PDU_T* alloc_from_pool() {
    pthread_mutex_lock(&pool_mutex);
    if (pool_index < MAX_LIST_SIZE) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = memory_pool[pool_index++];
        pthread_mutex_unlock(&pool_mutex);
        return pdu;
    }
    pthread_mutex_unlock(&pool_mutex);
    return NULL; // Pool full
}

// Function to free memory back to the pool
void free_to_pool(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&pool_mutex);
    if (pool_index > 0 && pool_index < MAX_LIST_SIZE) {
        memory_pool[--pool_index] = pdu;
    }
    pthread_mutex_unlock(&pool_mutex);
}

// Function to create and populate the list
void create_and_populate_list(int N, unsigned int seed) {
    srand(seed);

    for (int i = 0; i < N && pool_index < MAX_LIST_SIZE; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = alloc_from_pool();
        if (!pdu) {
            // Handle pool full scenario
            break;
        }

        // Generate random RX_UE_INFORMATION_TAG and RNTI values
        pdu->RX_UE_INFORMATION_TAG = rand() % 1000; // Example range
        pdu->RNTI = rand() % 500; // Example range

        // Set CRCFLAG randomly
        pdu->CRCFLAG = rand() % 2;

        // Add validation step and logging to crc_indication_errors.log if invalid
        if (pdu->CRCFLAG != 0 && pdu->CRCFLAG != 1) {
            FILE* error_log = fopen("crc_indication_errors.log", "a");
            fprintf(error_log, "Invalid CRCFLAG: %d\n", pdu->CRCFLAG);
            fclose(error_log);
        }

        // Ensure unique RNTI values
        for (int j = 0; j < i; ++j) {
            if (memory_pool[j]->RNTI == pdu->RNTI) {
                free_to_pool(pdu);
                --i;
                break;
            }
        }
    }
}

// Function to export the list to a standardized binary format
