    if (file) {
        for (int i = 0; i < count; ++i) {
            fprintf(file, "RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n",
                    list[i]->RX_UE_INFORMATION_TAG,
