            fprintf(stderr, "Memory allocation failed for PHY RX stats.\n");
            continue;
        }
        // Initialize stats fields
        add_pdu_to_list(&pdu_list, &pdu_data, stats);
    }

    validate_pdu_list(&pdu_list);

    free_pdu_list(&pdu_list);
    return 0;
}
