void* resize_list(void* arg) {
    pthread_mutex_lock(&lock);
    if (size == capacity) {
        int new_capacity = capacity ? capacity * 2 : INITIAL_SIZE;
        list = realloc(list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (list == NULL) {
            perror("Failed to resize list");
