#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PACKETS 10000
#define PACKET_SIZE sizeof(PacketHeader)
#define CHUNK_SIZE 1024

typedef struct PacketHeader {
    char sourceIP[46]; // IPv6 max length: 39 (8 bytes per segment * 4 segments + 7 colons) + null terminator
    char destinationIP[46];
    int protocolType;
    int ttl;
    // Add other metadata fields as needed
} PacketHeader;

typedef struct QueueNode {
    PacketHeader data;
    struct QueueNode* next;
} QueueNode;

typedef struct Queue {
    QueueNode* front;
    QueueNode* rear;
    size_t size;
} Queue;

Queue* createQueue() {
    Queue* queue = (Queue*)malloc(sizeof(Queue));
    if (queue) {
        queue->front = NULL;
        queue->rear = NULL;
        queue->size = 0;
    }
    return queue;
}

void enqueue(Queue* queue, PacketHeader packet) {
    QueueNode* newNode = (QueueNode*)malloc(PACKET_SIZE);
    if (newNode) {
        memcpy(&newNode->data, &packet, PACKET_SIZE);
        newNode->next = NULL;

        if (!queue->rear) {
            queue->front = newNode;
            queue->rear = newNode;
        } else {
            queue->rear->next = newNode;
            queue->rear = newNode;
        }
        queue->size++;
    }
}

PacketHeader dequeue(Queue* queue) {
    PacketHeader packet;
    if (!queue || !queue->front) {
        memset(&packet, 0, PACKET_SIZE);
        return packet; // Return empty packet on error
    }

    QueueNode* temp = queue->front;
    memcpy(&packet, &temp->data, PACKET_SIZE);

    queue->front = queue->front->next;
    if (!queue->front) {
        queue->rear = NULL;
    }
    free(temp);
    queue->size--;

    return packet;
}

void destroyQueue(Queue* queue) {
    while (queue && queue->front) {
        QueueNode* temp = queue->front;
        queue->front = queue->front->next;
        free(temp);
    }
    free(queue);
}

int main() {
    Queue* queue = createQueue();
    if (!queue) {
        fprintf(stderr, "Failed to create queue\n");
        return 1;
    }

    // Example usage
    PacketHeader packet;
    strcpy(packet.sourceIP, "192.168.0.1");
    strcpy(packet.destinationIP, "10.0.0.1");
    packet.protocolType = 6; // TCP
    packet.ttl = 64;

    enqueue(queue, packet);

    PacketHeader dequeuedPacket = dequeue(queue);
    printf("Dequeued packet: Source IP - %s, Destination IP - %s, Protocol Type - %d, TTL - %d\n",
           dequeuedPacket.sourceIP, dequeuedPacket.destinationIP, dequeuedPacket.protocolType, dequeuedPacket.ttl);

    destroyQueue(queue);
    return 0;
}
