#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_PACKETS 1024
#define PAYLOAD_SIZE 1024

typedef struct HTTP_REQUEST {
    char REQUEST_METHOD[64];
    char URL[256];
    char PAYLOAD[PAYLOAD_SIZE];
} HTTP_REQUEST;

typedef struct PACKET_HEADER {
    char sourceIP[16];
    char destinationIP[16];
    int protocolType;
    int TTL;
    HTTP_REQUEST httpRequest;
} PACKET_HEADER;

typedef struct QUEUE_NODE {
    PACKET_HEADER packetHeader;
    struct QUEUE_NODE *next;
} QUEUE_NODE;

typedef struct QUEUE {
    QUEUE_NODE *front;
    QUEUE_NODE *rear;
    int size;
    pthread_mutex_t mutex;
} QUEUE;

QUEUE *createQueue(int maxPackets) {
    QUEUE *queue = (QUEUE *)malloc(sizeof(QUEUE));
    if (!queue) {
        perror("Failed to allocate memory for queue");
        return NULL;
    }
    queue->front = queue->rear = NULL;
    queue->size = 0;
    pthread_mutex_init(&queue->mutex, NULL);
    return queue;
}

void enqueue(QUEUE *queue, PACKET_HEADER packetHeader) {
    pthread_mutex_lock(&queue->mutex);
    QUEUE_NODE *newNode = (QUEUE_NODE *)malloc(sizeof(QUEUE_NODE));
    if (!newNode) {
        perror("Failed to allocate memory for new node");
        pthread_mutex_unlock(&queue->mutex);
        return;
    }
    newNode->packetHeader = packetHeader;
    newNode->next = NULL;

    if (queue->rear == NULL) {
        queue->front = queue->rear = newNode;
    } else {
        queue->rear->next = newNode;
        queue->rear = newNode;
    }

    queue->size++;
    pthread_mutex_unlock(&queue->mutex);
}

void dequeue(QUEUE *queue, PACKET_HEADER *packetHeader) {
    pthread_mutex_lock(&queue->mutex);
    if (queue->front == NULL) {
        pthread_mutex_unlock(&queue->mutex);
        return;
    }

    QUEUE_NODE *temp = queue->front;
    *packetHeader = temp->packetHeader;

    if (queue->front == queue->rear) {
        queue->front = queue->rear = NULL;
    } else {
        queue->front = queue->front->next;
    }

    free(temp);
    queue->size--;
    pthread_mutex_unlock(&queue->mutex);
}

void destroyQueue(QUEUE *queue) {
    pthread_mutex_lock(&queue->mutex);
    QUEUE_NODE *current = queue->front;
    while (current != NULL) {
        QUEUE_NODE *temp = current;
        current = current->next;
        free(temp);
    }
    queue->front = queue->rear = NULL;
    queue->size = 0;
    pthread_mutex_unlock(&queue->mutex);
    pthread_mutex_destroy(&queue->mutex);
    free(queue);
}
```

