#define MAX_LIST_SIZE 10000
#define CACHE_SIZE 1000
#define MIN_CPU_USAGE_THRESHOLD 80
#define CPU_USAGE_CHECK_INTERVAL 300
#define BUFFER_SIZE 4096

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
    // Other fields...
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *list[MAX_LIST_SIZE];
NFAPI_CRC_INDICATION_PDU_T cache[CACHE_SIZE];
int list_size = 0;
int cache_index = 0;
pthread_mutex_t mutex;
FILE *log_file;
char log_buffer[BUFFER_SIZE];
size_t log_buffer_pos;

void init() {
    pthread_mutex_init(&mutex, NULL);
    log_file = fopen("crc_indication_errors.log", "a");
}

void cleanup() {
    pthread_mutex_destroy(&mutex);
    fclose(log_file);
    for (int i = 0; i < list_size; ++i) {
        free(list[i]);
    }
}

NFAPI_CRC_INDICATION_PDU_T *get_from_cache() {
    pthread_mutex_lock(&mutex);
    if (cache_index == CACHE_SIZE) {
        cache_index = 0;
    }
    NFAPI_CRC_INDICATION_PDU_T *item = &cache[cache_index++];
    pthread_mutex_unlock(&mutex);
    return item;
}

void log_error(NFAPI_CRC_INDICATION_PDU_T *pdu, const char *message) {
    pthread_mutex_lock(&mutex);
    snprintf(log_buffer + log_buffer_pos, BUFFER_SIZE - log_buffer_pos, "Error: %s. RX_UE_INFORMATION_TAG=%d, RNTI=%d\n", message, pdu->RX_UE_INFORMATION_TAG, pdu->RNTI);
    log_buffer_pos += strlen(log_buffer + log_buffer_pos);
    if (log_buffer_pos >= BUFFER_SIZE) {
        fwrite(log_buffer, 1, log_buffer_pos, log_file);
        log_buffer_pos = 0;
    }
    pthread_mutex_unlock(&mutex);
}

NFAPI_CRC_INDICATION_PDU_T *create_pdu() {
    NFAPI_CRC_INDICATION_PDU_T *pdu = get_from_cache();
    if (pdu == NULL) {
        pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdu == NULL) {
            log_error(NULL, "Failed to allocate memory");
            return NULL;
        }
    }
    // Initialize fields...
    return pdu;
}

void add_to_list(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&mutex);
    if (list_size >= MAX_LIST_SIZE) {
        log_error(pdu, "List size exceeded");
        free(pdu);
        pthread_mutex_unlock(&mutex);
        return;
    }
    list[list_size++] = pdu;
    pthread_mutex_unlock(&mutex);
}

void *generate_crc_indications(void *arg) {
    int seed = *(int *)arg;
    srand(seed);
    for (int i = 0; i < 10000; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = create_pdu();
        if (pdu != NULL) {
            pdu->RX_UE_INFORMATION_TAG = rand() % 1000;
            pdu->RNTI = rand() % 50000;
            pdu->CRCFLAG = rand() % 2;
            add_to_list(pdu);
        }
    }
    return NULL;
}

int main() {
    init();
    pthread_t threads[4];
    int seeds[] = {1, 2, 3, 4};
    for (int i = 0; i < 4; ++i) {
        pthread_create(&threads[i], NULL, generate_crc_indications, &seeds[i]);
    }
    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }
    cleanup();
    return 0;
}
