void addOrUpdateEntry(int RNTI, bool CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&listMutex);
    ListEntry* current = head;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            current->data.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
            pthread_mutex_unlock(&listMutex);
            return;
        }
        current = current->next;
    }
    ListEntry* newEntry = malloc(sizeof(ListEntry));
    if (newEntry != NULL) {
        newEntry->data.RNTI = RNTI;
        newEntry->data.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
        newEntry->next = head;
        head = newEntry;
    }
    pthread_mutex_unlock(&listMutex);
}

void removeEntry(int RNTI) {
    pthread_mutex_lock(&listMutex);
    ListEntry* current = head;
    ListEntry* prev = NULL;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            if (prev != NULL) {
                prev->next = current->next;
            } else {
                head = current->next;
            }
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&listMutex);
}

int getTotalEntries() {
    int count = 0;
    ListEntry* current = head;
    while (current != NULL) {
        count++;
        current = current->next;
    }
    return count;
}

