typedef struct TCP_CONNECTION_RECORD {
    char ip[45]; // Assuming IPv6 format (max 45 characters including null terminator)
    int port;
    long timestamp;
} TCP_CONNECTION_RECORD;

typedef struct ConnectionList {
    TCP_CONNECTION_RECORD *records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock; // Mutex for thread safety
} ConnectionList;

void initConnectionList(ConnectionList *list) {
    list->records = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void freeConnectionList(ConnectionList *list) {
    pthread_mutex_lock(&list->lock);
    free(list->records);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int addRecord(ConnectionList *list, const TCP_CONNECTION_RECORD *record) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        size_t new_capacity = (list->capacity == 0) ? 1 : list->capacity * 2;
        TCP_CONNECTION_RECORD *new_records = realloc(list->records, new_capacity * sizeof(TCP_CONNECTION_RECORD));
        if (!new_records) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }
        list->records = new_records;
        list->capacity = new_capacity;
    }
    list->records[list->count++] = *record;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int removeRecord(ConnectionList *list, size_t index) {
    pthread_mutex_lock(&list->lock);
    if (index >= list->count) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Invalid index
    }
    for (size_t i = index; i < list->count - 1; ++i) {
        list->records[i] = list->records[i + 1];
    }
    --list->count;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

