#include <time.h>
#include <pthread.h>

#define MAX_LIST_SIZE 10000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *pool[MAX_LIST_SIZE];
int pool_index = 0;
pthread_mutex_t pool_mutex;

void init_pool() {
    pthread_mutex_init(&pool_mutex, NULL);
}

void* get_from_pool() {
    pthread_mutex_lock(&pool_mutex);
    if (pool_index == MAX_LIST_SIZE) {
        // Handle pool full scenario
        printf("Pool is full. Cannot allocate more memory.\n");
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T *item = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (item != NULL) {
        pool[pool_index++] = item;
    }
    pthread_mutex_unlock(&pool_mutex);
    return item;
}

void free_to_pool(void* item) {
    pthread_mutex_lock(&pool_mutex);
    for (int i = 0; i < pool_index; i++) {
        if (pool[i] == item) {
            pool[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&pool_mutex);
    free(item);
}

void validate_crc_indications(NFAPI_CRC_INDICATION_PDU_T *list, int size) {
    FILE *error_log = fopen("crc_indication_errors.log", "a");
    for (int i = 0; i < size; i++) {
        if (list[i].CRCFLAG != 0 && list[i].CRCFLAG != 1) {
            fprintf(error_log, "Invalid CRCFLAG at index %d: %d\n", i, list[i].CRCFLAG);
        }
    }
    fclose(error_log);
}

void* manage_crc_indications(int seed) {
    srand(seed);
    NFAPI_CRC_INDICATION_PDU_T *list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_LIST_SIZE);
    if (list == NULL) {
        printf("Failed to allocate memory for CRC indications.\n");
        return NULL;
    }

    // Populate the list with random values
    for (int i = 0; i < MAX_LIST_SIZE; i++) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 10000;
        list[i].RNTI = rand() % 4096; // Assuming a range of 0-4095
        list[i].CRCFLAG = rand() % 2;
    }

    validate_crc_indications(list, MAX_LIST_SIZE);

    // Free the allocated memory
    free(list);
    return NULL;
}

int main() {
    init_pool();
    manage_crc_indications(time(NULL));
    pthread_mutex_destroy(&pool_mutex);
    return 0;
}
