using System;
using System.Collections.Concurrent;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class StringHashProcessor
{
    private readonly HttpClient _httpClient;
    private readonly ConcurrentDictionary<string, string> _configCache;
    private readonly ILogger _logger;

    public StringHashProcessor(HttpClient httpClient, ILogger logger)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _configCache = new ConcurrentDictionary<string, string>();
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task ProcessBatchAsync(string[] strings)
    {
        var config = await FetchConfigAsync();
        foreach (var str in strings)
        {
            if (string.IsNullOrEmpty(str))
            {
                _logger.Log("Invalid input: String is null or empty", LogLevel.Warning);
                continue;
            }
            try
            {
                var hash = GenerateMd5Hash(str, config);
                _logger.Log($"Processed string '{str}' with hash {hash}", LogLevel.Information);
            }
            catch (Exception ex)
            {
                _logger.Log($"Failed to process string '{str}': {ex.Message}", LogLevel.Error);
            }
        }
    }

    private async Task<Config> FetchConfigAsync()
    {
        var cacheKey = "config";
        if (_configCache.TryGetValue(cacheKey, out var cachedConfig))
        {
            return JsonConvert.DeserializeObject<Config>(cachedConfig);
        }

        try
        {
            var response = await _httpClient.GetAsync("https://api.example.com/config");
            response.EnsureSuccessStatusCode();
            var configJson = await response.Content.ReadAsStringAsync();
            var config = JsonConvert.DeserializeObject<Config>(configJson);
            _configCache.TryAdd(cacheKey, configJson);
            return config;
        }
        catch (Exception ex)
        {
            _logger.Log($"Failed to fetch configuration: {ex.Message}", LogLevel.Error);
            return new Config(); // Fallback default configuration
        }
    }

    private string GenerateMd5Hash(string input, Config config)
    {
        using (var md5 = MD5.Create())
        {
            var inputBytes = Encoding.UTF8.GetBytes(input + config.Salt);
            var hashBytes = md5.ComputeHash(inputBytes);
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
        }
    }

    public class Config
    {
        public string Salt { get; set; } // Example configuration property
    }

    public enum LogLevel
    {
        Information,
        Warning,
        Error
    }

    public interface ILogger
    {
        void Log(string message, LogLevel level);
    }
}
