import org.springframework.stereotype.Service;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

@Service
public class MetricAggregator {

    private final ConcurrentHashMap<String, AtomicLong> sums = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, AtomicInteger> counts = new ConcurrentHashMap<>();

    public void updateMetrics(SensorReading reading) {
        String key = reading.getSensorId();
        sums.computeIfAbsent(key, k -> new AtomicLong()).addAndGet(reading.getValue());
        counts.computeIfAbsent(key, k -> new AtomicInteger()).incrementAndGet();
    }

    public SensorMetric getMetrics(String sensorId) {
        long sum = sums.getOrDefault(sensorId, 0L).get();
        int count = counts.getOrDefault(sensorId, 0).get();
        return new SensorMetric(sum, count);
    }

}
