public class SensorMetric {

    private double mean;
    private double variance;

    public SensorMetric(long sum, int count) {
        this.mean = (double) sum / count;
        double varianceSum = 0;
        for (int i = 1; i <= count; i++) {
            varianceSum += Math.pow(i - mean, 2);
        }
        this.variance = varianceSum / count;
    }

    // Getters and setters

}
