#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int TX_RRC_PDU;
    int TX_PDCP_PDU;
    int TX_MAC_PDU;
} NFAPI_L2_PDU_T;

typedef struct {
    int TX_POWER;
    int RSSI;
    float FEC纠错率;
} TX_STATS;

NFAPI_L2_PDU_T* createL2Pdu(int seed) {
    NFAPI_L2_PDU_T* pdu = (NFAPI_L2_PDU_T*)malloc(sizeof(NFAPI_L2_PDU_T));
    if (pdu == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }
    srand(seed);
    pdu->TX_RRC_PDU = rand() % 1000;
    pdu->TX_PDCP_PDU = rand() % 1000;
    pdu->TX_MAC_PDU = rand() % 1000;

    TX_STATS* stats = (TX_STATS*)malloc(sizeof(TX_STATS));
    if (stats == NULL) {
        perror("Memory allocation failed");
        free(pdu);
        return NULL;
    }
    stats->TX_POWER = rand() % 20;
    stats->RSSI = -100 + rand() % 30;
    stats->FEC纠错率 = ((float)(rand() % 10)) / 10.0f;

    pdu->stats = *stats;
    return pdu;
}

void freeL2Pdu(NFAPI_L2_PDU_T* pdu) {
    if (pdu != NULL) {
        free(pdu);
    }
}

int main(int argc, char** argv) {
    srand(time(NULL));
    int N = 5; // Example number of structures
    for (int i = 0; i < N; i++) {
        NFAPI_L2_PDU_T* pdu = createL2Pdu(i);
        if (pdu != NULL) {
            printf("Created L2 PDU with values: TX_RRC_PDU=%d, TX_PDCP_PDU=%d, TX_MAC_PDU=%d\n",
                   pdu->TX_RRC_PDU, pdu->TX_PDCP_PDU, pdu->TX_MAC_PDU);
            freeL2Pdu(pdu);
        }
    }
    return 0;
}
