#include <atomic>
#include <mutex>
#include <vector>
#include <thread>
#include <condition_variable>
#include <chrono>
#include <iostream>
#include <fstream>
#include <sstream>
#include <unordered_map>

struct DATA_STREAM_RECORD_T {
    int64_t TIMESTAMP;
    int32_t SOURCE_ID;
    uint32_t DATA_SIZE;
};

class DataStreamProcessor {
public:
    using DataStreamPtr = std::shared_ptr<DATA_STREAM_RECORD_T>;
    using DataStreamVector = std::vector<DataStreamPtr>;

private:
    mutable std::mutex mutex_;
    std::condition_variable cond_var_;
    std::atomic<bool> running_{true};
    std::vector<DataStreamPtr> data_streams_;
    std::unordered_map<int32_t, int> source_counts_;
    size_t batch_size_ = 100;
    enum class AggregationAlgorithm { Algorithm1, Algorithm2, Algorithm3 } current_algorithm_ = AggregationAlgorithm::Algorithm1;

public:
    ~DataStreamProcessor() {
        running_ = false;
        cond_var_.notify_all();
        for (auto& thread : threads_) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    void start(size_t num_threads) {
        threads_.reserve(num_threads);
        for (size_t i = 0; i < num_threads; ++i) {
            threads_.emplace_back(&DataStreamProcessor::processBatch, this);
        }
    }

    void stop() {
        running_ = false;
        cond_var_.notify_all();
    }

    void addStream(const DATA_STREAM_RECORD_T& record) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto stream = std::make_shared<DATA_STREAM_RECORD_T>(record);
        data_streams_.push_back(stream);
        source_counts_[record.SOURCE_ID]++;
        cond_var_.notify_one();
    }

    void setBatchSize(size_t size) {
        batch_size_ = size;
    }

    void setAggregationAlgorithm(AggregationAlgorithm algo) {
        current_algorithm_ = algo;
    }

private:
    void processBatch() {
        while (running_) {
            std::unique_lock<std::mutex> lock(mutex_);
            cond_var_.wait(lock, [this] { return !data_streams_.empty() || !running_; });
            if (!running_) break;

            DataStreamVector batch;
            for (size_t i = 0; i < batch_size_ && !data_streams_.empty(); ++i) {
                batch.push_back(data_streams_.back());
                data_streams_.pop_back();
                source_counts_[batch.back()->SOURCE_ID]--;
            }
            lock.unlock();

            if (!batch.empty()) {
                processBatchData(batch);
            }
        }
    }

    void processBatchData(const DataStreamVector& batch) {
        switch (current_algorithm_) {
            case AggregationAlgorithm::Algorithm1:
                processWithLowLatency(batch);
                break;
            case AggregationAlgorithm::Algorithm2:
                processMemoryEfficiently(batch);
                break;
            case AggregationAlgorithm::Algorithm3:
                processBalanced(batch);
                break;
        }
    }

    void processWithLowLatency(const DataStreamVector& batch) {
        // Algorithm 1 implementation
    }

    void processMemoryEfficiently(const DataStreamVector& batch) {
        // Algorithm 2 implementation
    }

    void processBalanced(const DataStreamVector& batch) {
        // Algorithm 3 implementation
    }
};

int main() {
    DataStreamProcessor processor;
    processor.start(4);
    std::this_thread::sleep_for(std::chrono::seconds(10));
    processor.stop();
    return 0;
}
