#define NFAPI_CRC_INDICATION_PDU_T struct { /* Define the structure as needed */ }

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_pdus(int N, int num_threads) {
    if (N <= 0 || num_threads <= 0) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        perror("Memory allocation failed");
        return NULL;
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    srand(time(NULL));

    void* thread_func(void* arg) {
        int start = *(int*)arg;
        int end = start + N / num_threads;

        for (int i = start; i < end; ++i) {
            // Populate pdus[i] with valid RX_UE_INFORMATION_TAG and RNTI
            pdus[i].RX_UE_INFORMATION_TAG = /* generate or assign a tag */;
            pdus[i].RNTI = /* generate or assign an RNTI */;

            // Set CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG
            pthread_mutex_lock(&lock);
            pdus[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2 == 0) ? 1 : 0;
            pthread_mutex_unlock(&lock);
        }

        return NULL;
    }

    int* thread_ids = malloc(num_threads * sizeof(int));
    if (!thread_ids) {
        perror("Memory allocation failed");
        free(pdus);
        return NULL;
    }

    for (int i = 0; i < num_threads; ++i) {
        thread_ids[i] = i * N / num_threads;
        pthread_create(&thread_ids[i], NULL, thread_func, &thread_ids[i]);
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(thread_ids[i], NULL);
    }

    free(thread_ids);
    return pdus;
}

void destroy_pdus(NFAPI_CRC_INDICATION_PDU_T* pdus, int N) {
    if (pdus) {
        free(pdus);
    }
}
