using System;
using System.IO;
using System.Security.Cryptography;

public class FileHashModifier
{
    public string GetMd5HashAndModifyExtension(string filename)
    {
        if (string.IsNullOrEmpty(filename))
            return null;

        // Generate MD5 hash
        using (MD5 md5 = MD5.Create())
        {
            byte[] inputBytes = System.Text.Encoding.ASCII.GetBytes(filename);
            byte[] hashBytes = md5.ComputeHash(inputBytes);

            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < hashBytes.Length; i++)
                sb.Append(hashBytes[i].ToString("x2"));

            string md5Hash = sb.ToString();

            // Modify file extension
            int dotIndex = filename.LastIndexOf('.');
            if (dotIndex == -1)
                dotIndex = filename.Length;

            string baseName = filename.Substring(0, dotIndex);
            string fileExtension = filename.Substring(dotIndex + 1);

            int numDigits = Math.Max(0, baseName.Length - fileExtension.Length - 3); // Adjust as needed
            string fileType = GetFileType(baseName);

            return $"{md5Hash}.{fileType:D{numDigits}}";
        }
    }

    private string GetFileType(string name)
    {
        if (name.Length < 3) return "unk";

        switch (name.Substring(0, 3).ToLower())
        {
            case "txt":
                return "txt";
            case "jpg":
                return "jpg";
            default:
                return "unk";
        }
    }
}
