    NetworkDeviceStatus *new_status = (NetworkDeviceStatus *)malloc(sizeof(NetworkDeviceStatus));
    new_status->status = status;
    strncpy(new_status->ip_address, ip_address, sizeof(new_status->ip_address) - 1);
    new_status->timestamp = time(NULL);
    new_status->next = NULL;
    return new_status;
}

void add_device_status(DeviceStatusList *list, NetworkDeviceStatus *new_status) {
    *list->last = new_status;
    list->last = &new_status->next;
    list->count++;
}

