    // Clear existing list
    while (list->head) {
        NetworkDeviceStatus *temp = list->head;
        list->head = temp->next;
        free(temp);
    }
    initialize_device_status_list(list);

    add_device_status(list, new_status1);
    add_device_status(list, new_status2);

    return 0; // Return success
}

void print_device_statuses(DeviceStatusList *list) {
    NetworkDeviceStatus *current = list->head;
    while (current) {
        printf("IP: %s, Status: %d, Timestamp: %ld\n", current->ip_address, current->status, current->timestamp);
        current = current->next;
    }
}

void clean_up_device_status_list(DeviceStatusList *list) {
    while (list->head) {
        NetworkDeviceStatus *temp = list->head;
        list->head = temp->next;
        free(temp);
    }
}
