#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_IP_LENGTH 15
#define MAX_TAG_LENGTH 10
#define BUFFER_SIZE 1024

typedef struct {
    char tag[MAX_TAG_LENGTH];
    char ip[MAX_IP_LENGTH];
    time_t timestamp;
} DeviceStatus;

typedef struct {
    DeviceStatus *statuses;
    int count;
    int capacity;
} DeviceList;

void initDeviceList(DeviceList *list) {
    list->statuses = NULL;
    list->count = 0;
    list->capacity = 0;
}

void freeDeviceList(DeviceList *list) {
    if (list->statuses != NULL) {
        free(list->statuses);
        list->statuses = NULL;
        list->count = 0;
        list->capacity = 0;
    }
}

int addDeviceStatus(DeviceList *list, const char *tag, const char *ip, time_t timestamp) {
    if (list->count >= list->capacity) {
        int new_capacity = (list->capacity == 0) ? BUFFER_SIZE : list->capacity * 2;
        DeviceStatus *new_statuses = realloc(list->statuses, new_capacity * sizeof(DeviceStatus));
        if (new_statuses == NULL) return -1;
        list->statuses = new_statuses;
        list->capacity = new_capacity;
    }
    strcpy(list->statuses[list->count].tag, tag);
    strcpy(list->statuses[list->count].ip, ip);
    list->statuses[list->count].timestamp = timestamp;
    list->count++;
    return 0;
}

void removeDeviceStatus(DeviceList *list, const char *tag) {
    for (int i = 0; i < list->count; i++) {
        if (strcmp(list->statuses[i].tag, tag) == 0) {
            for (int j = i; j < list->count - 1; j++) {
                list->statuses[j] = list->statuses[j + 1];
            }
            list->count--;
            return;
        }
    }
}

void updateDeviceStatus(DeviceList *list, const char *tag, time_t new_timestamp) {
    for (int i = 0; i < list->count; i++) {
        if (strcmp(list->statuses[i].tag, tag) == 0) {
            list->statuses[i].timestamp = new_timestamp;
            return;
        }
    }
}

int filterDeviceStatuses(DeviceList *list, DeviceList *filtered_list, const char *ip_prefix) {
    freeDeviceList(filtered_list);
    initDeviceList(filtered_list);
    for (int i = 0; i < list->count; i++) {
        if (strncmp(list->statuses[i].ip, ip_prefix, strlen(ip_prefix)) == 0) {
            addDeviceStatus(filtered_list, list->statuses[i].tag, list->statuses[i].ip, list->statuses[i].timestamp);
        }
    }
    return 0;
}

void *pollNetworkAPI(void *arg) {
    DeviceList *list = (DeviceList *)arg;
    while (1) {
        // Simulate fetching device statuses from an external API
        for (int i = 0; i < 5; i++) {
            addDeviceStatus(list, "tag1", "192.168.1." + i, time(NULL));
            sleep(1);
        }
        sleep(60); // Poll every minute
    }
    return NULL;
}

int main() {
    DeviceList list;
    initDeviceList(&list);

    pthread_t poll_thread;
    pthread_create(&poll_thread, NULL, pollNetworkAPI, &list);

    // Simulate filtering device statuses based on IP prefix
    DeviceList filtered_list;
    filterDeviceStatuses(&list, &filtered_list, "192.168.1.");

    freeDeviceList(&list);
    freeDeviceList(&filtered_list);

    return 0;
}
