#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_STATUS_SIZE 256

typedef enum {
    DEVICE_STATUS_TAG_UP,
    DEVICE_STATUS_TAG_DOWN,
    DEVICE_STATUS_TAG_UNKNOWN
} DEVICE_STATUS_TAG;

typedef struct {
    DEVICE_STATUS_TAG status;
    char ip_address[16];
    time_t timestamp;
} NetworkDeviceStatus;

typedef struct Node {
    NetworkDeviceStatus data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    int size;
    pthread_mutex_t lock;
} NetworkDeviceList;

NetworkDeviceList* network_device_list_create() {
    NetworkDeviceList* list = (NetworkDeviceList*)malloc(sizeof(NetworkDeviceList));
    if (list == NULL) return NULL;

    list->head = list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void network_device_list_destroy(NetworkDeviceList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void network_device_list_add(NetworkDeviceList* list, NetworkDeviceStatus status) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) return;

    new_node->data = status;
    new_node->next = NULL;

    if (list->tail != NULL) list->tail->next = new_node;
    list->tail = new_node;

    if (list->head == NULL) list->head = list->tail;

    list->size++;

    pthread_mutex_unlock(&list->lock);
}

